#[test]
fn partition_overrides_refuse_rebuild_recording_without_writing_ids() {
    let parent = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    for own in ["default: '7'", "nullable: false"] {
        let overridden = parent.replace(
            "  p1: {from: [0], to: [10]}",
            &format!("  p1:\n    from: [0]\n    to: [10]\n    columns:\n      k: {{{own}}}"),
        );
        for source_has_override in [false, true] {
            let d = Demo::new("rebuild2298-overrides");
            d.table(if source_has_override {
                &overridden
            } else {
                parent
            });
            succeeds(d.run(&["plan", "--no-dev"]));
            d.commit();
            d.table(&overridden.replace("partition_by: [k]", "partition_by: [bucket]"));
            let ids_path = d.dir.join("schema.ids.json");
            let before = std::fs::read(&ids_path).unwrap();
            let out = d.run(&[
                "rebuild-table",
                "app.p",
                "--max-rows",
                "20",
                "--reason",
                "maintenance",
            ]);
            assert_ne!(code(&out), 0, "{}{}", stdout(&out), stderr(&out));
            assert!(stderr(&out).contains("app.p1.k"), "{}", stderr(&out));
            assert!(
                stderr(&out).contains("partition column override"),
                "{}",
                stderr(&out)
            );
            assert_eq!(std::fs::read(&ids_path).unwrap(), before);
        }
    }
}

#[test]
fn rebuild_intent_is_a_convergent_git_record_and_never_an_executable_plan() {
    let d = Demo::new("rebuild2298");
    let before = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    d.table(before);
    succeeds(d.run(&["plan", "--no-dev"]));
    d.commit();
    let source = String::from_utf8(
        Command::new("git")
            .arg("-C")
            .arg(&d.dir)
            .args(["rev-parse", "HEAD"])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    d.table(&before.replace("partition_by: [k]", "partition_by: [bucket]"));
    let path = d.dir.join("schema.ids.json");
    let original = std::fs::read(&path).unwrap();
    for (target, cap, reason) in [
        ("app.p", "0", "x"),
        ("app.p", "1", "\u{3000}"),
        ("app.missing", "1", "x"),
        ("not-qualified", "1", "x"),
    ] {
        let out = d.run(&[
            "rebuild-table",
            target,
            "--max-rows",
            cap,
            "--reason",
            reason,
        ]);
        assert_ne!(code(&out), 0, "{}{}", stdout(&out), stderr(&out));
        assert_eq!(std::fs::read(&path).unwrap(), original);
    }
    assert_ne!(
        code(&d.run(&["plan", "--no-dev"])),
        0,
        "risk approval cannot invent intent"
    );
    let operator = "Maintainer with an unbounded audit name".repeat(10);
    d.git(&["config", "user.name", &operator]);
    let args = [
        "rebuild-table",
        "app.p",
        "--max-rows",
        "20",
        "--reason",
        " maintenance window ",
    ];
    let out = succeeds(d.run(&args));
    assert!(stdout(&out).contains("blocking rewrite"));
    let recorded = std::fs::read(&path).unwrap();
    let ids: pbps_model::IdsFile = serde_json::from_slice(&recorded).unwrap();
    let (_, intent) = ids
        .rebuild_into(ids.table_uid(&"app.p".parse().unwrap()).unwrap())
        .unwrap();
    assert_eq!(intent.operator, operator);
    assert_eq!(intent.reason.as_ref(), " maintenance window ");
    assert_eq!(intent.max_rows, 20);
    assert_eq!(intent.allowed_at.len(), 10);
    d.commit();
    succeeds(d.run(&args));
    assert_eq!(std::fs::read(&path).unwrap(), recorded);
    let committed = Command::new("git")
        .arg("-C")
        .arg(&d.dir)
        .args(["show", "HEAD:schema.ids.json"])
        .output()
        .unwrap();
    assert!(committed.status.success());
    assert_eq!(committed.stdout, recorded);
    // The committed approval is the baseline now: a database that holds it has
    // nothing to rebuild. One that still holds the source is refused.
    succeeds(d.run(&["plan", "--no-dev"]));
    let plan = d.run(&["plan", "--no-dev", "--since", source.trim()]);
    assert_ne!(code(&plan), 0);
    assert!(format!("{}{}", stdout(&plan), stderr(&plan)).contains("blocking rewrite"));
    assert_eq!(std::fs::read(&path).unwrap(), recorded);
    std::fs::write(d.dir.join("pbps.yml"), "dialect: mssql\n").unwrap();
    assert!(stderr(&d.run(&args)).contains("only supported for PostgreSQL"));
    assert_eq!(std::fs::read(&path).unwrap(), recorded);
}

#[test]
#[ignore = "needs live pg"]
fn recorded_rebuild_refuses_connected_plans_and_keeps_the_source_tree() {
    rebuild_members::live();
    let own = OwnDatabase::new(&server(), "rebuild2298");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA app; CREATE DOMAIN app.count AS integer; CREATE TABLE app.p(k integer, bucket integer, label varchar(20), spelled varchar(30), stamp timestamptz) PARTITION BY RANGE(k); CREATE TABLE app.p1 PARTITION OF app.p FOR VALUES FROM(0) TO(10); INSERT INTO app.p(k,bucket) VALUES(1,2)",
    );
    for (column, partition) in [(true, false), (false, true), (true, true)] {
        let d = Demo::new(&format!("rebuild2298-live-additions-{column}-{partition}"));
        succeeds(d.run(&["pull", "--db", connection]));
        let path = d.dir.join("schema/app.p.yml");
        std::fs::write(&path, REBUILD_ALIAS_SOURCE).unwrap();
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        check_rebuild_additions(&d, &path, column, partition, Some(connection));
    }
    let d = Demo::new("rebuild2298-live");
    succeeds(d.run(&["pull", "--db", connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.p.yml");
    check_rebuild_aliases(&d, &path, Some(connection));
    let artifact = d.dir.join("refused.json");
    std::fs::write(&artifact, b"keep existing artifact").unwrap();
    let out = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&out), 0, "{}{}", stdout(&out), stderr(&out));
    assert!(
        stderr(&out).contains("execution is not available yet"),
        "{}",
        stderr(&out)
    );
    assert_eq!(std::fs::read(&artifact).unwrap(), b"keep existing artifact");
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM app.p WHERE k=1 AND bucket=2"
        ),
        1
    );
    // Omitting any source member must also omit its pending permission from
    // each kind of ledger snapshot, while preserving the on-disk intent.
    let pending = std::fs::read(d.dir.join("schema.ids.json")).unwrap();
    on_server(connection, "DROP TABLE app.p1");
    for args in [
        vec!["snapshot", "--db", connection, "--force"],
        vec![
            "baseline",
            "--db",
            connection,
            "--reason",
            "accept missing leaf",
        ],
    ] {
        succeeds(d.run(&args));
        let snapshot = latest_snapshot(connection);
        snapshot.ids.validate().unwrap();
        assert!(snapshot.ids.rebuilds.is_empty());
        assert!(snapshot.ids.table_uid(&"app.p1".parse().unwrap()).is_none());
        assert!(snapshot.ids.table_uid(&"app.p".parse().unwrap()).is_some());
    }
    assert_eq!(
        std::fs::read(d.dir.join("schema.ids.json")).unwrap(),
        pending
    );
}

#[test]
fn identity_intents_after_an_approval_are_ordinary_and_a_withdrawal_restores_the_file() {
    let d = Demo::new("rebuild2298-intents");
    let parent = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    d.table(parent);
    succeeds(d.run(&["plan", "--no-dev"]));
    d.commit();
    let path = d.dir.join("schema.ids.json");
    let source_bytes = std::fs::read(&path).unwrap();
    let source = String::from_utf8(
        Command::new("git")
            .arg("-C")
            .arg(&d.dir)
            .args(["rev-parse", "HEAD"])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    let desired = parent.replace("partition_by: [k]", "partition_by: [bucket]");
    d.table(&desired);
    let approve = [
        "rebuild-table",
        "app.p",
        "--max-rows",
        "20",
        "--reason",
        "maintenance",
    ];
    succeeds(d.run(&approve));
    let approved_bytes = std::fs::read(&path).unwrap();
    let approved: pbps_model::IdsFile = serde_json::from_slice(&approved_bytes).unwrap();
    let leaf: pbps_model::TableName = "app.p1".parse().unwrap();
    let leaf_uid = approved.table_uid(&leaf).unwrap().clone();
    // No pending state freezes the approved members: a rename is an ordinary
    // intent on the replacement and keeps its uid.
    d.table(&desired.replace("p1:", "p2:"));
    succeeds(d.run(&["rename-table", "app.p1", "app.p2"]));
    let renamed: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    renamed.validate().unwrap();
    assert_eq!(
        renamed.table_uid(&"app.p2".parse().unwrap()),
        Some(&leaf_uid)
    );
    // The declarations moved on after the approval: refused by name, with the
    // command that re-approves.
    let stale = d.run(&["plan", "--no-dev", "--since", source.trim()]);
    assert_ne!(code(&stale), 0);
    assert!(
        stderr(&stale).contains("re-approve it with `pbps rebuild-table app.p --max-rows 20"),
        "{}",
        stderr(&stale)
    );
    succeeds(d.run(&approve));
    let plan = d.run(&["plan", "--no-dev", "--since", source.trim()]);
    assert!(
        stderr(&plan).contains("execution is not available yet"),
        "{}",
        stderr(&plan)
    );
    // `--withdraw` takes neither a cap nor a reason, and edits only the file.
    let both = d.run(&["rebuild-table", "app.p", "--withdraw", "--max-rows", "1"]);
    assert_ne!(code(&both), 0);
    assert_eq!(code(&d.run(&["rebuild-table", "app.p", "--withdraw"])), 0);
    let withdrawn: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    assert!(withdrawn.rebuilds.is_empty() && withdrawn.tombstones.is_empty());
    // The file is what it was before the approval, whatever happened since.
    let original: pbps_model::IdsFile = serde_json::from_slice(&source_bytes).unwrap();
    assert_eq!(
        (&withdrawn.tables, &withdrawn.columns),
        (&original.tables, &original.columns)
    );
    // Nothing is left to withdraw, and the refusal changes nothing.
    let before = std::fs::read(&path).unwrap();
    let again = d.run(&["rebuild-table", "app.p", "--withdraw"]);
    assert_ne!(code(&again), 0);
    assert!(
        stderr(&again).contains("no rebuild is recorded"),
        "{}",
        stderr(&again)
    );
    assert_eq!(std::fs::read(&path).unwrap(), before);
}

#[test]
fn renaming_the_replacement_after_the_approval_can_be_reapproved_and_withdrawn() {
    let d = Demo::new("rebuild2298-rename");
    let parent = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    d.table(parent);
    succeeds(d.run(&["plan", "--no-dev"]));
    d.commit();
    let path = d.dir.join("schema.ids.json");
    let original: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    let source = String::from_utf8(
        Command::new("git")
            .arg("-C")
            .arg(&d.dir)
            .args(["rev-parse", "HEAD"])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    let source = source.trim();
    let desired = parent.replace("partition_by: [k]", "partition_by: [bucket]");
    d.table(&desired);
    let approve = |table: &str| {
        d.run(&[
            "rebuild-table",
            table,
            "--max-rows",
            "20",
            "--reason",
            "maintenance",
        ])
    };
    succeeds(approve("app.p"));
    d.commit();
    // The ordinary rename of the live replacement, after the approval.
    d.table(&desired.replace("table: app.p\n", "table: app.q\n"));
    succeeds(d.run(&["rename-table", "app.p", "app.q"]));
    let stale = d.run(&["plan", "--no-dev", "--since", source]);
    assert!(
        stderr(&stale).contains("re-approve it with `pbps rebuild-table app.q --max-rows 20"),
        "{}",
        stderr(&stale)
    );
    // The command the plan printed works, and keeps the source it was cut from.
    let before: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    let refreshed = approve("app.q");
    assert_eq!(code(&refreshed), 0, "{}", stderr(&refreshed));
    let after: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    after.validate().unwrap();
    let (key, old) = before.rebuilds.iter().next().unwrap();
    assert_eq!(after.rebuilds[key].source, old.source);
    assert_eq!(after.rebuilds[key].continues, old.continues);
    // The environment at the source is told of the rename, not asked to re-approve.
    let plan = d.run(&["plan", "--no-dev", "--since", source]);
    assert!(
        stderr(&plan).contains("renamed after the approval")
            && !stderr(&plan).contains("re-approve"),
        "{}",
        stderr(&plan)
    );
    // Withdrawn under the name the file has now, the sources are back.
    assert_eq!(code(&d.run(&["rebuild-table", "app.q", "--withdraw"])), 0);
    let withdrawn: pbps_model::IdsFile =
        serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    assert!(withdrawn.rebuilds.is_empty() && withdrawn.tombstones.is_empty());
    assert_eq!(
        (&withdrawn.tables, &withdrawn.columns),
        (&original.tables, &original.columns)
    );
}

#[test]
fn a_chain_of_approvals_plans_as_one_composed_rebuild_from_any_older_revision() {
    let d = Demo::new("rebuild2298-chain");
    let parent = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    let rev = || {
        String::from_utf8(
            Command::new("git")
                .arg("-C")
                .arg(&d.dir)
                .args(["rev-parse", "HEAD"])
                .output()
                .unwrap()
                .stdout,
        )
        .unwrap()
        .trim()
        .to_owned()
    };
    d.table(parent);
    succeeds(d.run(&["plan", "--no-dev"]));
    d.commit();
    let source = rev();
    let approve = |cap: &str| {
        succeeds(d.run(&[
            "rebuild-table",
            "app.p",
            "--max-rows",
            cap,
            "--reason",
            "maintenance",
        ]));
        d.commit();
    };
    let second = parent.replace("partition_by: [k]", "partition_by: [bucket]");
    d.table(&second);
    approve("20");
    let middle = rev();
    d.table(&second.replace("bucket: {type: integer}", "bucket: {type: bigint}"));
    approve("30");
    // The files hold the last link; an environment at the first source is
    // rebuilt once, to it.
    let behind = d.run(&["plan", "--no-dev", "--since", &source]);
    assert_ne!(code(&behind), 0);
    assert!(
        stderr(&behind).contains("composed over 2 approved links"),
        "{}",
        stderr(&behind)
    );
    assert!(stderr(&behind).contains("execution is not available yet"));
    // One at the middle link is a single rebuild; one at the last has nothing to do.
    let current = d.run(&["plan", "--no-dev", "--since", &middle]);
    assert_ne!(code(&current), 0);
    assert!(
        !stderr(&current).contains("composed"),
        "{}",
        stderr(&current)
    );
    assert!(stderr(&current).contains("execution is not available yet"));
    succeeds(d.run(&["plan", "--no-dev"]));
}

#[test]
fn a_chain_that_returns_to_the_first_key_still_plans_as_one_composed_rebuild() {
    let d = Demo::new("rebuild2298-there-and-back");
    let parent = "table: app.p\ncolumns:\n  k: {type: integer}\n  bucket: {type: integer}\npartition_by: [k]\npartitions:\n  p1: {from: [0], to: [10]}\n";
    d.table(parent);
    succeeds(d.run(&["plan", "--no-dev"]));
    d.commit();
    let source = String::from_utf8(
        Command::new("git")
            .arg("-C")
            .arg(&d.dir)
            .args(["rev-parse", "HEAD"])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    let source = source.trim();
    let approve = |cap: &str| {
        succeeds(d.run(&[
            "rebuild-table",
            "app.p",
            "--max-rows",
            cap,
            "--reason",
            "maintenance",
        ]));
        d.commit();
    };
    d.table(&parent.replace("partition_by: [k]", "partition_by: [bucket]"));
    approve("20");
    // Back to the first key: the declarations are the first revision's again.
    d.table(parent);
    approve("30");
    let behind = d.run(&["plan", "--no-dev", "--since", source]);
    assert_ne!(code(&behind), 0);
    assert!(
        stderr(&behind).contains("composed over 2 approved links")
            && stderr(&behind).contains("execution is not available yet"),
        "{}",
        stderr(&behind)
    );
    succeeds(d.run(&["plan", "--no-dev"]));
}

