/// `doctor`'s runway reader parses a `timestamptz` bound as UTC text and reads
/// it in UTC whatever the database's own zone (DEC-1789.2, DEC-1916.1): on a
/// database in `Asia/Taipei` a weekly series that ends with its newest row is
/// still reported short, in `+00`, and never as a question it could not
/// answer. On 16 and 18.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_reads_a_runway_in_utc_on_a_database_in_another_zone() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        let own = OwnDatabase::new(server, &format!("runway_zone_1916_{k}"));
        let connection = own.connection();
        on_server(
            connection,
            &format!(
                "CREATE SCHEMA app; ALTER DATABASE \"{}\" SET timezone = 'Asia/Taipei'",
                own.name
            ),
        );
        let d = Demo::new(&format!("runway-zone-1916-{k}"));
        std::fs::write(
            d.dir.join("schema/app.tz.yml"),
            "table: app.tz\ncolumns:\n  id: {type: bigint, nullable: false}\n  \
             k: {type: timestamptz, nullable: false}\nprimary_key: [id, k]\n\
             partition_by: [k]\npartitions:\n  \
             tz_2026_12_28: {from: ['2026-12-28 00:00:00+00'], to: ['2027-01-04 00:00:00+00']}\n  \
             tz_2027_01_04: {from: ['2027-01-04 00:00:00+00'], to: ['2027-01-11 00:00:00+00']}\n",
        )
        .unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
        succeeds(d.run(&["bootstrap", "--db", connection]));
        on_server(
            connection,
            "INSERT INTO app.tz VALUES (1, '2027-01-05 10:00:00+00')",
        );
        assert_eq!(
            text_of(connection, "SELECT current_setting('TimeZone')"),
            "Asia/Taipei",
            "the scenario needs a session outside UTC"
        );

        let o = d.run(&["doctor", "--db", connection, "--format", "json"]);
        assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
        let json: serde_json::Value = serde_json::from_str(&stdout(&o)).unwrap();
        let findings = json["findings"].as_array().unwrap();
        let with = |id: &str| -> Vec<&serde_json::Value> {
            findings.iter().filter(|f| f["id"] == id).collect()
        };
        assert!(
            with("doctor.partition-runway-unknown").is_empty(),
            "a bound read in Taipei would be refused as not in UTC: {json}"
        );
        let short = with("doctor.partition-runway");
        assert_eq!(short.len(), 1, "{json}");
        let message = short[0]["message"].as_str().unwrap();
        assert!(
            message.contains("end at `2027-01-11 00:00:00+00`")
                && message.contains("to `2027-01-18 00:00:00+00` at least"),
            "{message}"
        );
    }
}

/// Bounds that carry fractions of a second are ordered, compared and printed
/// with them (#1923): `doctor` measures from the partition ending last inside
/// its second, and names the reach to the microsecond. On 16 and 18. The whole
/// scenario is `support/partition_runway.rs`'s.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_keeps_fractions_of_a_second_in_a_partition_runway() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        partition_runway::fractions(server, &format!("runway-frac-1923-{k}"));
    }
}

/// A default horizon above the largest value an integer key holds is a
/// question `doctor` cannot ask, and says so, while one landing exactly on the
/// largest value is asked (#2020). On 16 and 18. The whole scenario is
/// `support/partition_runway.rs`'s.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_does_not_call_a_series_short_of_a_value_past_the_integer_maximum() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        partition_runway::integer_ceiling(server, &format!("runway-int-2020-{k}"));
    }
}

/// A default horizon past the end of the key's axis is a question about the
/// declarations when they add a partition with no upper end: the finding says
/// a plan is missing, and not that `partition_runway` must change (#2036). A
/// series declared finite stays undetermined. On 16 and 18. The whole scenario
/// is `support/partition_runway.rs`'s.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_names_the_plan_when_declarations_with_no_upper_end_reach_a_horizon_past_the_axis() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        partition_runway::open_ended_declarations(server, &format!("runway-open-2036-{k}"));
    }
}

/// `doctor` does not read a partitioned table's occupancy through a parent
/// that row-level security filters for the account it runs as: the runway and
/// the DEFAULT's rows are each `…-unknown`, never "no row", while the owner, a
/// `BYPASSRLS` role and a table with a policy only on a partition are read as
/// before (#1925, DEC-1925.1). On 16 and 18.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_does_not_read_partition_occupancy_through_row_level_security() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        partition_runway::row_security(server, &format!("runway-rls-1925-{k}"));
    }
}

fn generated_series_flow(server: &str, slug: &str) {
    let own = OwnDatabase::new(server, slug);
    let conn = own.connection().to_owned();
    on_server(&conn, "CREATE SCHEMA app");
    let d = Demo::new(slug);
    let parent = |name: &str, key: &str, partitions: &str| {
        std::fs::write(
            d.dir.join(format!("schema/app.{name}.yml")),
            format!(
                "table: app.{name}\ncolumns:\n  id: {{type: bigint, nullable: false}}\n  \
                 k: {{type: {key}, nullable: false}}\nprimary_key: [id, k]\n\
                 partition_by: [k]\n{partitions}"
            ),
        )
        .unwrap();
    };
    parent(
        "d",
        "date",
        "partitions:\n  d_2026_11: {from: ['2026-11-01'], to: ['2026-12-01']}\n  d_rest: default\n",
    );
    parent(
        "t",
        "timestamptz",
        "partitions:\n  t_2026_12_28: {from: ['2026-12-28 00:00:00+00'], \
         to: ['2027-01-04 00:00:00+00']}\n",
    );
    parent(
        "s",
        "timestamp",
        "partitions:\n  s_2025: {from: ['2025-01-01 00:00:00'], to: ['2026-01-01 00:00:00']}\n",
    );
    parent("b", "bigint", "");
    succeeds(d.run(&["fmt"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &conn]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    // A row the DEFAULT holds, outside every range about to be added.
    on_server(&conn, "INSERT INTO app.d VALUES (9, '2030-01-01')");

    let extend = |args: &[&str]| {
        let mut all = vec!["partitions", "extend"];
        all.extend_from_slice(args);
        succeeds(d.run(&all))
    };
    let said = stdout(&extend(&[
        "app.d",
        "--every",
        "1month",
        "--until",
        "2027-03-01",
    ]));
    assert!(said.contains("Added 3 partition(s) to app.d"), "{said}");
    extend(&[
        "app.t",
        "--every",
        "1week",
        "--until",
        "2027-01-25 00:00:00+00",
    ]);
    extend(&[
        "app.s",
        "--every",
        "1year",
        "--until",
        "2028-01-01 00:00:00",
    ]);
    // From nothing: a parent that declares no range starts where --from says.
    extend(&["app.b", "--from", "0", "--every", "1000", "--until", "3000"]);
    succeeds(d.run(&["fmt", "--check"]));
    succeeds(d.run(&["validate"]));
    // Nothing is created by writing the declarations.
    assert_eq!(
        scalar(
            &conn,
            "SELECT count(*) FROM pg_class WHERE relname IN ('d_2026_12', 't_2027_01_04', \
             's_2026', 'b_0')"
        ),
        0
    );
    // The file now written is what a second run finds in place.
    let written = std::fs::read(d.dir.join("schema/app.d.yml")).unwrap();
    let again = succeeds(d.run(&[
        "partitions",
        "extend",
        "app.d",
        "--every",
        "1month",
        "--until",
        "2027-03-01",
    ]));
    assert!(
        stdout(&again).contains("nothing to add"),
        "{}",
        stdout(&again)
    );
    assert_eq!(
        std::fs::read(d.dir.join("schema/app.d.yml")).unwrap(),
        written
    );

    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("series.json");
    let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
    let planned = stdout(&o);
    for created in [
        "+ create table app.d_2026_12, a partition of app.d for rows from (\"2026-12-01\") to \
         (\"2027-01-01\")",
        "+ create table app.d_2027_02, a partition of app.d for rows from (\"2027-02-01\") to \
         (\"2027-03-01\")",
        "+ create table app.t_2027_01_18, a partition of app.t for rows from \
         (\"2027-01-18 00:00:00+00\") to (\"2027-01-25 00:00:00+00\")",
        "+ create table app.s_2027, a partition of app.s for rows from \
         (\"2027-01-01 00:00:00\") to (\"2028-01-01 00:00:00\")",
        "+ create table app.b_2000, a partition of app.b for rows from (\"2000\") to (\"3000\")",
    ] {
        assert!(planned.contains(created), "{created}\n{planned}");
    }
    succeeds(approved_apply(&d, &conn, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // The engine stores the text the generator wrote.
    let bound = |table: &str| {
        text_of(
            &conn,
            &format!(
                "SELECT pg_get_expr(relpartbound, oid) FROM pg_class WHERE oid = '{table}'::regclass"
            ),
        )
    };
    assert_eq!(
        bound("app.d_2027_01"),
        "FOR VALUES FROM ('2027-01-01') TO ('2027-02-01')"
    );
    assert_eq!(
        bound("app.t_2027_01_11"),
        "FOR VALUES FROM ('2027-01-11 00:00:00+00') TO ('2027-01-18 00:00:00+00')"
    );
    assert_eq!(
        bound("app.s_2026"),
        "FOR VALUES FROM ('2026-01-01 00:00:00') TO ('2027-01-01 00:00:00')"
    );
    assert_eq!(bound("app.b_1000"), "FOR VALUES FROM ('1000') TO ('2000')");

    // Rows land where their key says, the DEFAULT's row where it was.
    on_server(
        &conn,
        "INSERT INTO app.d VALUES (1, '2026-12-15'), (2, '2027-02-28'); \
         INSERT INTO app.t VALUES (1, '2027-01-04 00:00:00+00'), (2, '2027-01-24 23:59:59+00'); \
         INSERT INTO app.s VALUES (1, '2026-06-01 12:00:00'), (2, '2027-12-31 23:59:59'); \
         INSERT INTO app.b VALUES (1, 0), (2, 999), (3, 1000), (4, 2999)",
    );
    let routed = |table: &str| {
        text_of(
            &conn,
            &format!(
                "SELECT string_agg(replace(tableoid::regclass::text, 'app.', '') || ':' || id, \
                 ',' ORDER BY id) FROM {table}"
            ),
        )
    };
    assert_eq!(routed("app.d"), "d_2026_12:1,d_2027_02:2,d_rest:9");
    assert_eq!(routed("app.t"), "t_2027_01_04:1,t_2027_01_18:2");
    assert_eq!(routed("app.s"), "s_2026:1,s_2027:2");
    assert_eq!(routed("app.b"), "b_0:1,b_0:2,b_1000:3,b_2000:4");

    // A project pulled back from the target declares the same partitions,
    // byte for byte: the generator writes the spelling `pull` reads.
    let pulled = Demo::new(&format!("{slug}-pulled"));
    succeeds(pulled.run(&["pull", "--db", &conn]));
    for parent in ["d", "t", "s", "b"] {
        let partitions = |dir: &std::path::Path| {
            let text =
                std::fs::read_to_string(dir.join(format!("schema/app.{parent}.yml"))).unwrap();
            let at = text.find("\npartitions:\n").expect("a partitions block");
            text[at..].to_owned()
        };
        assert_eq!(partitions(&d.dir), partitions(&pulled.dir), "app.{parent}");
    }
}

/// A partition moved out of `partitions:` into a file of its own, of its
/// parent's shape under names of its own, is detached and kept through the
/// CLI (#1544): behind `--allow destructive`, its rows kept and gone from the
/// parent, after which `verify` is clean and nothing is left to plan. A
/// declaration of another shape is refused by name before a plan exists.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partition_is_detached_and_kept_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "detach-1544");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");
    let d = Demo::new("detach-1544");
    let columns = "columns:\n  id: {type: integer, nullable: false}\n  \
                   ts: {type: date, nullable: false}\n  n: {type: integer}\n";
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\n{columns}primary_key: [id, ts]\nindexes:\n  ev_n: {{columns: [n]}}\n\
                 checks:\n  ev_n_ck: n > 0\npartition_by: [ts]\npartitions:\n{partitions}"
            ),
        )
        .unwrap();
    };
    let p2025 = "  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n";
    let p2026 = "  ev_2026: {from: [\"2026-01-01\"], to: [\"2027-01-01\"]}\n";
    tree(&format!("{p2025}{p2026}"));
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &connection]));
    on_server(
        &connection,
        "INSERT INTO app.ev VALUES (1, '2025-06-01', 5), (2, '2026-06-01', 6)",
    );

    // Another shape: refused by name, before a plan exists.
    tree(p2026);
    let archived = d.dir.join("schema/app.ev_2025.yml");
    std::fs::write(
        &archived,
        format!("table: app.ev_2025\n{columns}primary_key: [id, ts]\n"),
    )
    .unwrap();
    // Refused offline, where the git baseline holds the standing partition
    // (#1737 review), before an identity file is written for the shape.
    let o = d.run(&["plan"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains("app.ev_2025 is detached from app.ev, and declared as other than")
            && said.contains("index `ev_n` is missing"),
        "{said}"
    );

    // Its parent's shape, its own names: detached behind its risk.
    std::fs::write(
        &archived,
        format!(
            "table: app.ev_2025\n{columns}primary_key:\n  name: arch_pk\n  columns: [id, ts]\n\
             indexes:\n  arch_n: {{columns: [n]}}\nchecks:\n  arch_n_ck: n > 0\n"
        ),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let o = succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    assert!(
        stdout(&o).contains("~ detach table app.ev_2025 from app.ev, keeping its rows"),
        "{}",
        stdout(&o)
    );
    let o = approved_apply(&d, &connection, &plan, &[]);
    assert_ne!(
        code(&o),
        0,
        "a detach needs its risk allowed: {}",
        stdout(&o)
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "destructive"],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(scalar(&connection, "SELECT count(*) FROM app.ev_2025"), 1);
    assert_eq!(scalar(&connection, "SELECT count(*) FROM app.ev"), 1);
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM pg_constraint WHERE conname IN ('arch_pk', 'arch_n_ck')"
        ),
        2
    );
}

/// Catalog names, not generated-name guesses, order clone handovers.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn detaches_follow_their_catalog_clone_name_handovers_on_both_servers() {
    for (k, server) in [old_server(), server()].iter().enumerate() {
        for scenario in ["pair", "chain", "exchange"] {
            let (own, d) = detach_clone_demo(server, &format!("{scenario}-{k}"));
            let connection = own.connection();
            declare_detach_parent(&d, false, scenario != "chain");
            let a = if scenario == "exchange" {
                (Some("a_unique"), "a_key", "z_index")
            } else {
                (Some("z_key"), "z_unique", "z_index")
            };
            declare_detached_clone(&d, "a", a.0, a.1, a.2);
            let z = if scenario == "chain" {
                ("c_key", "c_unique", "c_index")
            } else {
                ("released_key", "released_unique", "released_index")
            };
            declare_detached_clone(&d, "z", Some(z.0), z.1, z.2);
            if scenario == "chain" {
                declare_detached_clone(
                    &d,
                    "c",
                    Some("released_key"),
                    "released_unique",
                    "released_index",
                );
            }
            let (plan, script) = connected_plan(&d, connection);
            let at = |table: &str| {
                script
                    .find(&format!("DETACH PARTITION \"app\".\"{table}\""))
                    .unwrap_or_else(|| panic!("missing detach of {table}: {script}"))
            };
            assert!(at("z") < at("a"), "{script}");
            if scenario == "chain" {
                assert!(at("c") < at("z"), "{script}");
            }
            succeeds(approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "destructive"],
            ));
            for (table, value, key, unique, index) in
                [("a", 1, a.0.unwrap(), a.1, a.2), ("z", 11, z.0, z.1, z.2)]
            {
                assert_eq!(
                    scalar(connection, &format!("SELECT n::bigint FROM app.{table}")),
                    value
                );
                assert_eq!(
                    scalar(
                        connection,
                        &format!(
                            "SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid \
                     WHERE i.indrelid = 'app.{table}'::regclass AND c.relname IN ('{key}', '{unique}', '{index}')"
                        )
                    ),
                    3
                );
            }
            assert_eq!(
                scalar(connection, "SELECT count(*) FROM app.p"),
                if scenario == "chain" { 1 } else { 2 }
            );
            succeeds(d.run(&["verify", "--db", connection]));
            let next = succeeds(d.run(&["plan", "--db", connection]));
            assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        }
    }
}

#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn cyclic_or_retained_clone_claims_refuse_before_plan_publication_on_both_servers() {
    for (k, server) in [old_server(), server()].iter().enumerate() {
        for scenario in ["cycle", "retained", "unnamed"] {
            let (own, d) = detach_clone_demo(server, &format!("{scenario}-{k}"));
            let connection = own.connection();
            declare_detach_parent(&d, scenario == "retained", true);
            declare_detached_clone(
                &d,
                "a",
                Some("a_key"),
                "a_unique",
                if scenario == "unnamed" {
                    "z_key"
                } else {
                    "z_index"
                },
            );
            if scenario == "cycle" {
                declare_detached_clone(&d, "z", Some("z_key"), "z_unique", "a_index");
            } else if scenario == "unnamed" {
                declare_detached_clone(&d, "z", None, "z_unique", "z_index");
            }
            succeeds(d.run(&["plan"]));
            d.commit();
            let plan = d.dir.join("refused.json");
            let sql = d.dir.join("refused.sql");
            let output = d.run(&[
                "plan",
                "--db",
                connection,
                "--out",
                plan.to_str().unwrap(),
                "--sql",
                sql.to_str().unwrap(),
            ]);
            assert_ne!(code(&output), 0, "{}{}", stdout(&output), stderr(&output));
            let message = format!("{}{}", stdout(&output), stderr(&output));
            assert!(
                message.contains("app.a")
                    && message.contains("app.z")
                    && message.contains("plan of its own"),
                "{message}"
            );
            assert!(
                !plan.exists() && !sql.exists(),
                "a refusal publishes neither artifact"
            );
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*) FROM pg_inherits \
                WHERE inhparent = 'app.p'::regclass AND inhrelid IN ('app.a'::regclass, 'app.z'::regclass)"
                ),
                2
            );
            assert_eq!(scalar(connection, "SELECT count(*) FROM app.p"), 4);
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid \
                WHERE i.indrelid IN ('app.a'::regclass, 'app.z'::regclass) \
                AND c.relname IN ('a_key', 'a_unique', 'a_index', 'z_key', 'z_unique', 'z_index')"
                ),
                6
            );
        }
    }
}

#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_table_rename_follows_the_partition_releasing_its_target_name_on_both_servers() {
    for (k, server) in [old_server(), server()].iter().enumerate() {
        for dropped in [false, true] {
            check_clone_rename_applies(server, &format!("target-{k}-{dropped}"), false, dropped);
        }
    }
}

#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_schema_move_follows_the_partition_releasing_its_carried_index_name_on_both_servers() {
    for (k, server) in [old_server(), server()].iter().enumerate() {
        for dropped in [false, true] {
            check_clone_rename_applies(server, &format!("carried-{k}-{dropped}"), true, dropped);
        }
    }
}

fn check_clone_rename_applies(server: &str, slug: &str, carried: bool, dropped: bool) {
    let (own, d) = clone_rename_demo(server, slug, carried);
    let connection = own.connection();
    declare_detach_parent(&d, true, true);
    if dropped {
        succeeds(d.run(&["drop-table", "app.a", "--reason", "retired"]));
    } else {
        declare_detached_clone(&d, "a", Some("a_key"), "a_unique", "released_index");
    }
    declare_clone_rename(&d, carried);
    let (plan, script) = connected_plan(&d, connection);
    let detach = script.find("DETACH PARTITION \"app\".\"a\"").unwrap();
    let claim = script
        .find(if carried {
            "SET SCHEMA \"app\""
        } else {
            "RENAME TO \"a_index\""
        })
        .unwrap();
    assert!(detach < claim, "{script}");
    if dropped {
        let drop = script.find("DROP TABLE \"app\".\"a\"").unwrap();
        assert!(detach < drop && drop < claim, "{script}");
    }
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename", "--allow", "destructive"],
    ));
    let target = if carried { "source" } else { "a_index" };
    assert_eq!(
        scalar(connection, &format!("SELECT n::bigint FROM app.{target}")),
        41
    );
    assert_eq!(scalar(connection, "SELECT count(*) FROM app.p"), 3);
    if dropped {
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM pg_class WHERE oid = to_regclass('app.a')"
            ),
            0
        );
    } else {
        assert_eq!(scalar(connection, "SELECT n::bigint FROM app.a"), 1);
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid \
                 WHERE i.indrelid = 'app.a'::regclass AND c.relname = 'released_index'"
            ),
            1
        );
    }
    if carried {
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid \
                 JOIN pg_namespace n ON n.oid = c.relnamespace \
                 WHERE i.indrelid = 'app.source'::regclass AND n.nspname = 'app' AND c.relname = 'a_index'"
            ),
            1
        );
    }
    succeeds(d.run(&["verify", "--db", connection]));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn rename_claims_cannot_take_a_retained_partition_clone_name_on_both_servers() {
    for (k, server) in [old_server(), server()].iter().enumerate() {
        for carried in [false, true] {
            for detached in [false, true] {
                let (own, d) =
                    clone_rename_demo(server, &format!("kept-{k}-{carried}-{detached}"), carried);
                let connection = own.connection();
                if detached {
                    declare_detach_parent(&d, true, true);
                    declare_detached_clone(&d, "a", Some("a_key"), "a_unique", "a_index");
                }
                declare_clone_rename(&d, carried);
                succeeds(d.run(&["plan"]));
                d.commit();
                let plan = d.dir.join("refused.json");
                let sql = d.dir.join("refused.sql");
                let output = d.run(&[
                    "plan",
                    "--db",
                    connection,
                    "--out",
                    plan.to_str().unwrap(),
                    "--sql",
                    sql.to_str().unwrap(),
                ]);
                assert_ne!(code(&output), 0, "{}{}", stdout(&output), stderr(&output));
                let message = format!("{}{}", stdout(&output), stderr(&output));
                assert!(
                    message.contains("app.a_index")
                        && (message.contains("already is") || message.contains("both named")),
                    "{message}"
                );
                assert!(!plan.exists() && !sql.exists());
                assert_eq!(scalar(connection, "SELECT count(*) FROM app.p"), 4);
                let source = if carried { "src.source" } else { "app.source" };
                assert_eq!(
                    scalar(connection, &format!("SELECT n::bigint FROM {source}")),
                    41
                );
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_inherits \
                         WHERE inhparent = 'app.p'::regclass AND inhrelid = 'app.a'::regclass"
                    ),
                    1
                );
            }
        }
    }
}

fn clone_rename_demo(server: &str, slug: &str, carried: bool) -> (OwnDatabase, Demo) {
    let source = if carried { "src.source" } else { "app.source" };
    let index = if carried {
        "CREATE INDEX a_index ON src.source (v);"
    } else {
        ""
    };
    detach_clone_demo_beside(
        server,
        slug,
        &format!(
            "CREATE SCHEMA src; CREATE TABLE {source} (n integer NOT NULL, v integer NOT NULL); \
             INSERT INTO {source} VALUES (41, 8); {index}"
        ),
    )
}

fn declare_clone_rename(d: &Demo, carried: bool) {
    let source = if carried { "src.source" } else { "app.source" };
    let target = if carried { "app.source" } else { "app.a_index" };
    let index = if carried {
        "indexes:\n  a_index: {columns: [v]}\n"
    } else {
        ""
    };
    std::fs::remove_file(d.dir.join(format!("schema/{source}.yml"))).unwrap();
    std::fs::write(
        d.dir.join(format!("schema/{target}.yml")),
        format!(
            "table: {target}\nrenamed_from: {source}\ncolumns:\n  n: {{type: integer, nullable: false}}\n  v: {{type: integer, nullable: false}}\n{index}"
        ),
    )
    .unwrap();
}

fn detach_clone_demo(server: &str, slug: &str) -> (OwnDatabase, Demo) {
    detach_clone_demo_beside(server, slug, "")
}

fn detach_clone_demo_beside(server: &str, slug: &str, beside: &str) -> (OwnDatabase, Demo) {
    let own = OwnDatabase::new(server, &format!("detach-clones-{slug}"));
    on_server(
        own.connection(),
        r#"
        CREATE SCHEMA app;
        CREATE TABLE app.p (n integer NOT NULL, v integer NOT NULL,
            CONSTRAINT p_pk PRIMARY KEY (n), CONSTRAINT p_uq UNIQUE (n, v)) PARTITION BY RANGE (n);
        CREATE INDEX p_v ON app.p (v);
        CREATE TABLE app.a PARTITION OF app.p FOR VALUES FROM (0) TO (10);
        CREATE TABLE app.z PARTITION OF app.p FOR VALUES FROM (10) TO (20);
        CREATE TABLE app.c PARTITION OF app.p FOR VALUES FROM (20) TO (30);
        CREATE TABLE app.kept PARTITION OF app.p FOR VALUES FROM (30) TO (40);
        INSERT INTO app.p VALUES (1, 4), (11, 5), (21, 6), (31, 7);
        DO $rename$ DECLARE r record; BEGIN
            FOR r IN SELECT ci.relname AS was, t.relname AS owner,
                CASE pi.relname WHEN 'p_pk' THEN 'key' WHEN 'p_uq' THEN 'unique' ELSE 'index' END AS kind
                FROM pg_inherits h JOIN pg_class ci ON ci.oid = h.inhrelid
                JOIN pg_index i ON i.indexrelid = ci.oid JOIN pg_class t ON t.oid = i.indrelid
                JOIN pg_class pi ON pi.oid = h.inhparent
                JOIN pg_index x ON x.indexrelid = pi.oid
                WHERE x.indrelid = 'app.p'::regclass AND t.relname IN ('a', 'z', 'c')
            LOOP EXECUTE format('ALTER INDEX app.%I RENAME TO %I', r.was, r.owner || '_' || r.kind);
            END LOOP;
        END $rename$;
    "#,
    );
    if !beside.is_empty() {
        on_server(own.connection(), beside);
    }
    let d = Demo::new(&format!("detach-clones-{slug}"));
    succeeds(d.run(&["pull", "--db", own.connection()]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", own.connection(), "--reason", "adopt"]));
    (own, d)
}

fn declare_detach_parent(d: &Demo, keep_z: bool, keep_c: bool) {
    let mut partitions = "  kept: {from: [30], to: [40]}\n".to_owned();
    if keep_z {
        partitions.push_str("  z: {from: [10], to: [20]}\n");
    }
    if keep_c {
        partitions.push_str("  c: {from: [20], to: [30]}\n");
    }
    std::fs::write(d.dir.join("schema/app.p.yml"), format!(
        "table: app.p\ncolumns:\n  n: {{type: integer, nullable: false}}\n  v: {{type: integer, nullable: false}}\n\
         primary_key: {{name: p_pk, columns: [n]}}\nunique:\n  p_uq: [n, v]\n\
         indexes:\n  p_v: {{columns: [v]}}\npartition_by: [n]\npartitions:\n{partitions}"
    )).unwrap();
}

fn declare_detached_clone(d: &Demo, table: &str, key: Option<&str>, unique: &str, index: &str) {
    let key = key.map_or_else(
        || "primary_key: [n]\n".to_owned(),
        |name| format!("primary_key: {{name: {name}, columns: [n]}}\n"),
    );
    std::fs::write(d.dir.join(format!("schema/app.{table}.yml")), format!(
        "table: app.{table}\ncolumns:\n  n: {{type: integer, nullable: false}}\n  v: {{type: integer, nullable: false}}\n\
         {key}unique:\n  {unique}: [n, v]\nindexes:\n  {index}: {{columns: [v]}}\n"
    )).unwrap();
}

/// An ordinary managed table moved into its parent's `partitions:` is
/// attached through the CLI and keeps its rows (#1545): refused by name while
/// it holds a column its parent does not, then behind `--allow constraint`,
/// refused by the pre-flight while a row of it is outside its range or a row
/// of the DEFAULT partition is inside it, and nothing changed. Then attached:
/// its own index the declaration drops goes first, its matching index
/// becomes its parent's clone, its own check and NOT NULL stay, and the
/// parent's default comes back. Its rows answer through the parent, its
/// column uids are gone from the ids file, `verify` is clean, and nothing is
/// left to plan. A table already its parent's shape is one change, attached
/// in a staged apply as well.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_table_is_attached_as_a_partition_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "attach-1545");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");
    let d = Demo::new("attach-1545");
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 ts: {{type: date, nullable: false}}\n  n: {{type: integer, default: \"1\"}}\n\
                 primary_key: [id, ts]\nindexes:\n  ev_n: {{columns: [n]}}\n\
                 checks:\n  ev_n_ck: n > 0\npartition_by: [ts]\npartitions:\n{partitions}"
            ),
        )
        .unwrap();
    };
    let p2025 = "  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n";
    let rest = "  ev_rest: default\n";
    let ordinary = d.dir.join("schema/app.t.yml");
    let table = |extra: &str| {
        std::fs::write(
            &ordinary,
            format!(
                "table: app.t\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 ts: {{type: date, nullable: false}}\n  n: {{type: integer, nullable: false}}\n\
                 {extra}primary_key:\n  name: t_pk\n  columns: [id, ts]\n\
                 indexes:\n  t_n: {{columns: [n]}}\n  t_id: {{columns: [id]}}\n\
                 checks:\n  ev_n_ck: n > 0\n  t_small: n < 100\n"
            ),
        )
        .unwrap();
    };
    tree(&format!("{p2025}{rest}"));
    table("  extra: {type: text}\n");
    let staged = d.dir.join("schema/app.s.yml");
    std::fs::write(
        &staged,
        "table: app.s\ncolumns:\n  id: {type: integer, nullable: false}\n  \
         ts: {type: date, nullable: false}\n  n: {type: integer, default: \"1\"}\n\
         primary_key: [id, ts]\nchecks:\n  ev_n_ck: n>0\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &connection]));
    on_server(
        &connection,
        "INSERT INTO app.t VALUES (1, '2024-06-01', 5, 'a'), (2, '2023-06-01', 6, 'b'); \
         INSERT INTO app.ev VALUES (9, '2024-07-07', 7); \
         INSERT INTO app.s VALUES (5, '2022-03-03', 1)",
    );
    // The ids file's columns on `app.t`, by name.
    let columns_of_t = || -> Vec<String> {
        let text = std::fs::read_to_string(d.dir.join("schema.ids.json")).unwrap();
        let ids: serde_json::Value = serde_json::from_str(&text).unwrap();
        let mut names: Vec<String> = ids["columns"]
            .as_object()
            .unwrap()
            .values()
            .filter_map(|v| v.as_str()?.strip_prefix("app.t.").map(str::to_owned))
            .collect();
        names.sort();
        names
    };
    assert_eq!(columns_of_t(), ["extra", "id", "n", "ts"]);

    // A column its parent does not have: refused by name, and the ids file
    // keeps the table's columns.
    std::fs::remove_file(&ordinary).unwrap();
    let attached = "  t:\n    from: [\"2024-01-01\"]\n    to: [\"2025-01-01\"]\n    \
                    checks:\n      t_small: n < 100\n    columns:\n      n: {nullable: false}\n";
    tree(&format!("{p2025}{attached}{rest}"));
    let o = d.run(&["plan"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains(
            "app.t is attached to app.ev as a partition, but its columns are \
                       (id, ts, n, extra), and its parent's are (id, ts, n)"
        ),
        "{said}"
    );
    assert_eq!(columns_of_t(), ["extra", "id", "n", "ts"]);

    // The column dropped in a plan of its own.
    tree(&format!("{p2025}{rest}"));
    table("");
    succeeds(d.run(&["drop", "app.t.extra", "--reason", "not the parent's"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("drop.json");
    succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "destructive"],
    ));

    // Attached: planned behind its risk.
    std::fs::remove_file(&ordinary).unwrap();
    tree(&format!("{p2025}{attached}{rest}"));
    succeeds(d.run(&["plan"]));
    d.commit();
    assert!(columns_of_t().is_empty(), "{:?}", columns_of_t());
    let plan = d.dir.join("attach.json");
    let o = succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    assert!(
        stdout(&o).contains("~ attach table app.t to app.ev as a partition, keeping its rows"),
        "{}",
        stdout(&o)
    );
    let o = approved_apply(&d, &connection, &plan, &[]);
    assert_ne!(
        code(&o),
        0,
        "an attach needs its risk allowed: {}",
        stdout(&o)
    );
    // Refused by the pre-flight, by name, and nothing changed. An unmanaged
    // trigger named as a row trigger of the parent, which the engine refuses
    // to attach over (#1632), and a column grant, which it attaches over, are
    // counted from the catalog (#1642 review); a trigger under another name
    // is the partition's own once attached, and not counted.
    on_server(
        &connection,
        "CREATE FUNCTION app.noop() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NEW; END';
         CREATE TRIGGER noop BEFORE INSERT ON app.ev FOR EACH ROW EXECUTE FUNCTION app.noop();
         CREATE TRIGGER noop BEFORE INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.noop();
         CREATE TRIGGER other BEFORE INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.noop();
         GRANT SELECT (n) ON app.t TO PUBLIC",
    );
    let o = approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "destructive,constraint"],
    );
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains("1 rows of app.t outside the range it takes under app.ev")
            && said.contains("1 rows of app.ev inside the range of its new partition app.t")
            && said.contains("1 triggers on app.t named as a row trigger of app.ev")
            && said.contains("1 columns of app.t with grants of their own")
            && said.contains("nothing has been changed"),
        "{said}"
    );
    let holds = |sql: &str| scalar(&connection, &format!("SELECT ({sql})::int::int8"));
    assert_eq!(
        holds("SELECT relispartition FROM pg_class WHERE oid = 'app.t'::regclass"),
        0
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 't_id'"),
        1
    );

    // Out of the way: attached.
    on_server(
        &connection,
        "DELETE FROM app.t WHERE id = 2; DELETE FROM app.ev WHERE id = 9;
         DROP TRIGGER noop ON app.t; DROP TRIGGER other ON app.t;
         DROP TRIGGER noop ON app.ev; DROP FUNCTION app.noop();
         REVOKE SELECT (n) ON app.t FROM PUBLIC",
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "destructive,constraint"],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        holds("SELECT tableoid = 'app.t'::regclass FROM app.ev WHERE id = 1"),
        1
    );
    // The parent's default, given back: a row written straight to the table
    // takes it, as one through the parent does.
    on_server(
        &connection,
        "INSERT INTO app.t (id, ts) VALUES (3, '2024-08-01'); \
         INSERT INTO app.ev (id, ts) VALUES (4, '2024-09-01')",
    );
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM app.t WHERE id IN (3, 4) AND n = 1"
        ),
        2
    );
    // Its matching index its parent's clone, the other one gone, its own
    // check still its own.
    assert_eq!(
        holds("SELECT relispartition FROM pg_class WHERE relname = 't_n'"),
        1
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 't_id'"),
        0
    );
    assert_eq!(
        holds(
            "SELECT conislocal AND coninhcount = 0 FROM pg_constraint \
              WHERE conrelid = 'app.t'::regclass AND conname = 't_small'"
        ),
        1
    );

    // Already its parent's shape: the attach alone, staged. Its check is
    // spelled `n>0` beside its parent's `n > 0`, which the engine reads as
    // one, and so does the connected plan (#1642 review).
    std::fs::remove_file(&staged).unwrap();
    tree(&format!(
        "{p2025}{attached}  s: {{from: [\"2022-01-01\"], to: [\"2023-01-01\"]}}\n{rest}"
    ));
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("staged.json");
    let o = succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--staged",
        "--out",
        plan.to_str().unwrap(),
    ]));
    assert!(
        stdout(&o).contains("~ attach table app.s to app.ev as a partition, keeping its rows"),
        "{}",
        stdout(&o)
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--allow", "constraint"],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        holds("SELECT tableoid = 'app.s'::regclass FROM app.ev WHERE id = 5"),
        1
    );
}

/// An ordinary table declared as its parent's DEFAULT partition is attached
/// with its rows (#1639, DEC-1639.1). A row another partition takes is
/// refused by name before any statement and nothing changes; once it is
/// gone the attach runs, a row no range takes and a NULL key route to it
/// through the parent, `verify` is clean and nothing is left to plan. The
/// staged form keeps the single statement, which no CHECK can spare a scan.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_table_is_attached_as_the_default_partition_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "attach-1639");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");
    let d = Demo::new("attach-1639");
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 k: {{type: integer}}\npartition_by: [k]\npartitions:\n\
                 \x20 ev_a: {{from: [0], to: [10]}}\n  ev_b: {{from: [10], to: [20]}}\n{partitions}"
            ),
        )
        .unwrap();
    };
    let ordinary = d.dir.join("schema/app.t.yml");
    tree("");
    std::fs::write(
        &ordinary,
        "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\n  k: {type: integer}\n",
    )
    .unwrap();
    let other = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.f.yml"),
            format!(
                "table: app.f\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 k: {{type: integer}}\npartition_by: [k]\npartitions:\n\
                 \x20 f_a: {{from: [0], to: [10]}}\n{partitions}"
            ),
        )
        .unwrap();
    };
    other("");
    let staged = d.dir.join("schema/app.s.yml");
    std::fs::write(
        &staged,
        "table: app.s\ncolumns:\n  id: {type: integer, nullable: false}\n  k: {type: integer}\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &connection]));
    on_server(
        &connection,
        "INSERT INTO app.t VALUES (1, 25), (2, NULL), (3, -5), (4, 5); \
         INSERT INTO app.ev VALUES (9, 15)",
    );

    std::fs::remove_file(&ordinary).unwrap();
    tree("  t: default\n");
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("attach.json");
    let o = succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    assert!(
        stdout(&o)
            .contains("~ attach table app.t to app.ev as its default partition, keeping its rows"),
        "{}",
        stdout(&o)
    );
    // The row of ev_a's range: refused by name, and nothing changed.
    let o = approved_apply(&d, &connection, &plan, &["--allow", "constraint"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains("1 rows of app.t that another partition of app.ev takes")
            && said.contains("nothing has been changed")
            && !said.contains("violated by some row"),
        "{said}"
    );
    let holds = |sql: &str| scalar(&connection, &format!("SELECT ({sql})::int::int8"));
    assert_eq!(
        holds("SELECT relispartition FROM pg_class WHERE oid = 'app.t'::regclass"),
        0
    );

    // Out of the way: attached, and routed to through the parent.
    on_server(&connection, "DELETE FROM app.t WHERE id = 4");
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "constraint"],
    ));
    assert_eq!(
        holds(
            "SELECT partdefid = 'app.t'::regclass FROM pg_partitioned_table \
              WHERE partrelid = 'app.ev'::regclass"
        ),
        1
    );
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    on_server(
        &connection,
        "INSERT INTO app.ev VALUES (5, 500), (6, NULL), (7, 3)",
    );
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM app.ev WHERE tableoid = 'app.t'::regclass"
        ),
        5
    );
    assert_eq!(
        holds("SELECT tableoid = 'app.ev_a'::regclass FROM app.ev WHERE id = 7"),
        1
    );

    // Staged: the single statement, with no temporary CHECK, which no
    // bound of a DEFAULT can spare a scan.
    on_server(&connection, "INSERT INTO app.s VALUES (1, 50), (2, NULL)");
    std::fs::remove_file(&staged).unwrap();
    other("  s: default\n");
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("staged.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--staged",
        "--out",
        plan.to_str().unwrap(),
    ]));
    let o = succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--allow", "constraint"],
    ));
    assert!(!stdout(&o).contains("pbps_attach_"), "{}", stdout(&o));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM app.f WHERE tableoid = 'app.s'::regclass"
        ),
        2
    );
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_staged_attach_uses_a_plain_attach_only_for_its_own_occupied_constraint_name() {
    for case in [
        "p",
        "u",
        "f",
        "different",
        "other_constraint",
        "table",
        "index",
        "sequence",
        "own_index",
    ] {
        let own = OwnDatabase::new(&server(), &format!("attach2126_{case}"));
        let connection = own.connection();
        on_server(connection, "CREATE SCHEMA app");
        let d = Demo::new(&format!("attach2126-{case}"));
        let columns = "columns:\n  id: {type: integer, nullable: false}\n  v: {type: integer, nullable: false}\n";
        std::fs::write(
            d.dir.join("schema/app.ref.yml"),
            "table: app.ref\ncolumns:\n  v: {type: integer, nullable: false}\nprimary_key: [v]\n",
        )
        .unwrap();
        let constraints = |prefix: &str| {
            format!(
                "primary_key: {{name: {prefix}_pk, columns: [id]}}\nunique:\n  {prefix}_uq: [id, v]\n\
             foreign_keys:\n  {prefix}_fk:\n    columns: [v]\n    references: app.ref(v)\n"
            )
        };
        let parent = format!(
            "table: app.ev\n{columns}{}partition_by: [id]\n",
            constraints("ev")
        );
        std::fs::write(d.dir.join("schema/app.ev.yml"), &parent).unwrap();
        d.table(&format!("table: app.t\n{columns}{}", constraints("t")));
        succeeds(d.run(&["plan"]));
        d.commit();
        succeeds(d.run(&["bootstrap", "--db", connection]));
        let ids: pbps_model::IdsFile =
            serde_json::from_slice(&std::fs::read(d.dir.join("schema.ids.json")).unwrap()).unwrap();
        let uid = ids
            .tables
            .iter()
            .find(|(_, name)| name.schema.as_str() == "app" && name.name.as_str() == "t")
            .unwrap()
            .0;
        let scratch = format!("pbps_attach_{uid}");
        let occupied = matches!(case, "p" | "u" | "f");
        let setup = match case {
            "p" => format!("ALTER TABLE app.t RENAME CONSTRAINT t_pk TO {scratch}"),
            "u" => format!("ALTER TABLE app.t RENAME CONSTRAINT t_uq TO {scratch}"),
            "f" => format!("ALTER TABLE app.t RENAME CONSTRAINT t_fk TO {scratch}"),
            "different" => format!("ALTER TABLE app.t RENAME CONSTRAINT t_pk TO {scratch}_other"),
            "other_constraint" => {
                format!("CREATE TABLE app.other (v int CONSTRAINT {scratch} PRIMARY KEY)")
            }
            "table" => format!("CREATE TABLE app.{scratch} (v int)"),
            "index" => {
                format!("CREATE TABLE app.other (v int); CREATE INDEX {scratch} ON app.other(v)")
            }
            "sequence" => format!("CREATE SEQUENCE app.{scratch}"),
            "own_index" => format!("CREATE INDEX {scratch} ON app.t(v)"),
            _ => unreachable!(),
        };
        on_server(connection, &setup);
        if case == "own_index" {
            // Keep this independent index across the attach, rather than
            // planning its removal as a second logical change.
            d.table(&format!(
                "table: app.t\n{columns}{}indexes:\n  {scratch}: {{columns: [v]}}\n",
                constraints("t")
            ));
            succeeds(d.run(&["plan"]));
            d.commit();
        }
        succeeds(d.run(&[
            "baseline",
            "--db",
            connection,
            "--reason",
            "adopt live constraint names",
        ]));
        on_server(
            connection,
            "INSERT INTO app.ref VALUES (1); INSERT INTO app.t VALUES (1, 1)",
        );
        std::fs::remove_file(d.dir.join("schema/app.t.yml")).unwrap();
        let own_index = if case == "own_index" {
            format!("    indexes:\n      {scratch}: {{columns: [v]}}\n")
        } else {
            String::new()
        };
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!("{parent}partitions:\n  t:\n    from: [0]\n    to: [10]\n{own_index}"),
        )
        .unwrap();
        let path = connected_artifact(&d, connection, true);
        let plan: pbps_model::SavedPlan =
            serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        assert_eq!(plan.changes.changes.len(), 1, "{case}");
        let change = &plan.changes.changes[0];
        let sql = pbps_pg::Postgres::new()
            .fixture_emit_staged(&change.change, change.strategy)
            .unwrap();
        assert_eq!(sql.len(), if occupied { 1 } else { 4 }, "{case}: {sql:?}");
        assert_eq!(
            sql.iter()
                .filter(|s| s.sql.contains("ATTACH PARTITION"))
                .count(),
            1
        );
        if occupied {
            assert!(
                sql.iter().all(|s| s.scan_check.is_none()),
                "{case}: {sql:?}"
            );
        }
        succeeds(approved_apply(
            &d,
            connection,
            &path,
            &["--staged", "--allow", "constraint"],
        ));
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM app.ev WHERE tableoid = 'app.t'::regclass"
            ),
            1,
            "{case}"
        );
        if occupied {
            assert_eq!(
                scalar(
                    connection,
                    &format!(
                        "SELECT count(*) FROM pg_constraint WHERE conrelid = 'app.t'::regclass AND conname = '{scratch}'"
                    )
                ),
                1,
                "{case}"
            );
        }
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(
            stdout(&next).contains("No changes"),
            "{case}: {}",
            stdout(&next)
        );
    }
}

/// A staged attach skips its scan through a CHECK it validates first, and
/// what a stopped run leaves of that CHECK is pbps's to take out (#1638,
/// DEC-1638.1). A `VALIDATE` that fails takes it out itself, with no
/// checkpoint to resume from. An attach that fails after its checkpoint
/// leaves it validated: `baseline` takes it out by its exact name before it
/// records, as it does one a run that died before any checkpoint left, and
/// `--resume` drops it as the run's last statement. Measured
/// by `seq_scan`, the staged attach scans its table no more often than a
/// transactional one does, which reads the table once more for the attach.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_staged_attach_skips_its_scan_and_leaves_its_check_to_nobody() {
    staged_attach_recovery(&server(), false);
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn staged_attach_type_pins_preserve_check_recovery_on_postgres_18() {
    staged_attach_recovery(&server(), true);
}

#[test]
#[ignore = "needs a live PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn staged_attach_type_pins_preserve_check_recovery_on_postgres_16() {
    staged_attach_recovery(
        &std::env::var("PBPS_TEST_PG_OLD_DB").expect("set PBPS_TEST_PG_OLD_DB"),
        true,
    );
}

fn staged_attach_recovery(server: &str, referenced: bool) {
    let own = OwnDatabase::new(server, "attach-1638");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");
    if referenced {
        on_server(&connection, "CREATE TYPE app.tag AS ENUM ('x')");
    }
    let extra_column = if referenced {
        "  tag: {type: app.tag}\n"
    } else {
        ""
    };
    let d = Demo::new("attach-1638");
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 ts: {{type: date, nullable: false}}\n{extra_column}primary_key: [id, ts]\n\
                 partition_by: [ts]\npartitions:\n  \
                 ev_2025: {{from: [\"2025-01-01\"], to: [\"2026-01-01\"]}}\n{partitions}"
            ),
        )
        .unwrap();
    };
    let ordinary = |name: &str| {
        std::fs::write(
            d.dir.join(format!("schema/app.{name}.yml")),
            format!(
                "table: app.{name}\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 ts: {{type: date, nullable: false}}\n{extra_column}primary_key: [id, ts]\n"
            ),
        )
        .unwrap();
    };
    tree("");
    for name in ["t", "u_st", "u_tx"] {
        ordinary(name);
    }
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &connection]));
    on_server(
        &connection,
        "INSERT INTO app.t (id, ts) SELECT g, DATE '2024-01-01' + g % 300 FROM generate_series(1, 1000) g; \
         INSERT INTO app.u_st (id, ts) SELECT g, DATE '2023-01-01' + g % 300 FROM generate_series(1, 1000) g; \
         INSERT INTO app.u_tx (id, ts) SELECT g, DATE '2022-01-01' + g % 300 FROM generate_series(1, 1000) g",
    );
    let temporaries = || {
        scalar(
            &connection,
            "SELECT count(*) FROM pg_constraint WHERE conname LIKE 'pbps_attach_%'",
        )
    };
    let attached = |name: &str| {
        scalar(
            &connection,
            &format!("SELECT count(*) FROM pg_inherits WHERE inhrelid = 'app.{name}'::regclass"),
        )
    };
    let stop = |name: &str, when: &str| {
        on_server(
            &connection,
            &format!(
                "CREATE FUNCTION public.{name}() RETURNS event_trigger LANGUAGE plpgsql AS $$ \
                 BEGIN IF {when} THEN RAISE EXCEPTION '{name}'; END IF; END $$; \
                 CREATE EVENT TRIGGER {name} ON ddl_command_end WHEN TAG IN ('ALTER TABLE') \
                 EXECUTE FUNCTION public.{name}()"
            ),
        );
    };
    let unstop = |name: &str| {
        on_server(
            &connection,
            &format!("DROP EVENT TRIGGER {name}; DROP FUNCTION public.{name}()"),
        );
    };
    let t_range = "  t: {from: [\"2024-01-01\"], to: [\"2025-01-01\"]}\n";
    std::fs::remove_file(d.dir.join("schema/app.t.yml")).unwrap();
    tree(t_range);
    let plan = connected_artifact(&d, &connection, true);
    let shown = std::fs::read_to_string(&plan).unwrap();
    assert!(
        shown.contains("\"key\": [\n"),
        "the plan carries the key: {shown}"
    );

    // A: the VALIDATE fails. Its CHECK is taken out, and the run starts again
    // without `--resume`.
    stop(
        "stop_validate",
        "EXISTS (SELECT FROM pg_constraint WHERE conname LIKE 'pbps_attach_%' AND convalidated)",
    );
    let o = approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--allow", "constraint"],
    );
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert_eq!((temporaries(), attached("t")), (0, 0), "{said}");
    assert!(
        code(&o) != 0
            && said.contains("statement 1 of 4 done (checkpointed with the next)")
            && said.contains("was removed; the database is as the last checkpoint recorded it")
            && said.contains("start this plan again with `pbps apply --staged` without `--resume`"),
        "{said}"
    );
    unstop("stop_validate");

    // B: the attach fails after the VALIDATE's checkpoint. `baseline` takes
    // the validated CHECK out by its name and says so in the record.
    stop(
        "stop_attach",
        "EXISTS (SELECT FROM pg_inherits WHERE inhrelid = 'app.t'::regclass)",
    );
    let o = approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--allow", "constraint"],
    );
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        code(&o) != 0 && said.contains("statement 2 of 4 done (checkpoint #"),
        "{said}"
    );
    assert_eq!((temporaries(), attached("t")), (1, 0), "{said}");
    // A baseline that refuses leaves the CHECK where the staged checkpoint
    // recorded it: its removal is in the same transaction as the record
    // (#2127). An undeclared partition of the managed parent makes it refuse.
    let entries = || scalar(&connection, "SELECT count(*) FROM public.__pbps_state");
    let before = entries();
    on_server(
        &connection,
        "CREATE TABLE app.ev_2030 PARTITION OF app.ev \
             FOR VALUES FROM ('2030-01-01') TO ('2031-01-01')",
    );
    let o = d.run(&["baseline", "--db", &connection, "--reason", "refused"]);
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        code(&o) != 0
            && said.contains("app.ev_2030 is a partition of the managed table app.ev")
            && !said.contains("Removed the staged attach's"),
        "{said}"
    );
    assert_eq!((temporaries(), entries()), (1, before), "{said}");
    on_server(&connection, "DROP TABLE app.ev_2030");
    let o = succeeds(d.run(&[
        "baseline",
        "--db",
        &connection,
        "--reason",
        "the attach is given up",
    ]));
    assert!(
        stdout(&o).contains("Removed the staged attach's temporary CHECK `pbps_attach_t_"),
        "{}",
        stdout(&o)
    );
    assert_eq!(temporaries(), 0);
    let reason = latest_snapshot(&connection)
        .reason
        .map(pbps_model::Text::into_raw)
        .unwrap_or_default();
    assert!(
        reason.starts_with("the attach is given up (first removed the staged attach's"),
        "{reason}"
    );

    // B': a run that dies after the `ADD` commits and before the `VALIDATE`'s
    // checkpoint records nothing: the newest entry is the baseline above.
    // `baseline` still takes the CHECK out, which no declaration can name.
    let removed = stdout(&o);
    let name = removed
        .split("CHECK `")
        .nth(1)
        .and_then(|rest| rest.split('`').next())
        .expect("the removed CHECK is named");
    on_server(
        &connection,
        &format!(
            "ALTER TABLE app.t ADD CONSTRAINT \"{name}\" \
             CHECK (ts >= DATE '2024-01-01') NOT VALID"
        ),
    );
    // A reason the column holds only on its own keeps its own text: the
    // note is left out rather than overflowing the record.
    let full = format!("the run died{}", ".".repeat(988));
    let o = succeeds(d.run(&["baseline", "--db", &connection, "--reason", &full]));
    assert!(
        stdout(&o).contains(&format!(
            "Removed the staged attach's temporary CHECK `{name}`"
        )),
        "{}",
        stdout(&o)
    );
    assert_eq!(temporaries(), 0);
    assert_eq!(
        latest_snapshot(&connection)
            .reason
            .map(pbps_model::Text::into_raw)
            .unwrap_or_default(),
        full
    );

    // B'': the same, under a newest entry this build cannot read. `baseline`
    // is that entry's remedy (DECISIONS 203), so the CHECK is found by the
    // project's identities, not the ledger's.
    on_server(
        &connection,
        &format!(
            "ALTER TABLE app.t ADD CONSTRAINT \"{name}\" \
             CHECK (ts >= DATE '2024-01-01') NOT VALID; \
             UPDATE public.__pbps_state \
             SET state_json = jsonb_set(state_json::jsonb, '{{version}}', '5')::text \
             WHERE id = (SELECT max(id) FROM public.__pbps_state)"
        ),
    );
    let o = d.run(&["verify", "--db", &connection]);
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        code(&o) != 0 && said.contains("this is a version 5 state"),
        "{said}"
    );
    let o = succeeds(d.run(&["baseline", "--db", &connection, "--reason", "an old ledger"]));
    assert!(
        stdout(&o).contains(&format!(
            "Removed the staged attach's temporary CHECK `{name}`"
        )),
        "{}",
        stdout(&o)
    );
    assert_eq!(temporaries(), 0);
    let reason = latest_snapshot(&connection)
        .reason
        .map(pbps_model::Text::into_raw)
        .unwrap_or_default();
    assert_eq!(
        reason,
        format!(
            "an old ledger (first removed the staged attach's temporary CHECK `{name}` on \
             `app.t`)"
        )
    );

    // C: stopped there again, and resumed: the run drops the CHECK itself.
    let plan = connected_artifact(&d, &connection, true);
    let o = approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--allow", "constraint"],
    );
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    unstop("stop_attach");
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--staged", "--resume", "--allow", "constraint"],
    ));
    assert_eq!((temporaries(), attached("t")), (0, 1));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // D: as many scans of its table as a transactional attach makes, which
    // scans it once more for the attach itself.
    let scans = |name: &str| {
        scalar(
            &connection,
            &format!(
                "SELECT seq_scan FROM pg_stat_user_tables WHERE relid = 'app.{name}'::regclass"
            ),
        )
    };
    let mut deltas = Vec::new();
    for (name, from, staged) in [("u_st", "2023", true), ("u_tx", "2022", false)] {
        std::fs::remove_file(d.dir.join(format!("schema/app.{name}.yml"))).unwrap();
        let ranges = std::fs::read_to_string(d.dir.join("schema/app.ev.yml")).unwrap();
        let next = format!(
            "  {name}: {{from: [\"{from}-01-01\"], to: [\"{}-01-01\"]}}\n",
            from.parse::<i32>().unwrap() + 1
        );
        std::fs::write(d.dir.join("schema/app.ev.yml"), format!("{ranges}{next}")).unwrap();
        let plan = connected_artifact(&d, &connection, staged);
        let before = scans(name);
        let flags: &[&str] = if staged {
            &["--staged", "--allow", "constraint"]
        } else {
            &["--allow", "constraint"]
        };
        succeeds(approved_apply(&d, &connection, &plan, flags));
        deltas.push(scans(name) - before);
        assert_eq!((temporaries(), attached(name)), (0, 1), "{name}");
    }
    assert_eq!(
        deltas[0], deltas[1],
        "staged and transactional scans: {deltas:?}"
    );
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// Index storage parameters go the whole way through the CLI (#1442):
/// pulled with the index, changed in place by one `ALTER INDEX` that
/// applies and verifies, after which the next plan is empty.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn index_storage_parameters_change_in_place_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "index-params-1442");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY, k integer); \
         CREATE INDEX t_k ON app.t (k) WITH (fillfactor = 70); \
         INSERT INTO app.t VALUES (1, 10)",
    );
    let d = Demo::new("index-params-1442");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.t.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let pulled = "    storage_parameters: {fillfactor: 70}\n";
    assert!(text.contains(pulled), "{text}");
    std::fs::write(
        &path,
        text.replace(
            pulled,
            "    storage_parameters: {deduplicate_items: false, fillfactor: 80}\n",
        ),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    assert!(
        script.contains(
            "ALTER INDEX \"app\".\"t_k\" SET (deduplicate_items = 'false', fillfactor = '80');"
        ),
        "{script}"
    );
    assert!(!script.contains("DROP INDEX"), "{script}");
    succeeds(approved_apply(&d, &connection, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// Storage parameters go the whole way through the CLI (#1441): pulled in
/// canonical spelling, changed (set, changed and reset) by one typed plan that
/// applies, after which the next plan is empty. A parameter reset by hand is
/// drift, and one the model cannot declare is reported by the next command,
/// never overwritten.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn storage_parameters_change_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "storage-params-1441");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY, body text) \
           WITH (fillfactor = 70, autovacuum_enabled = off); \
         INSERT INTO app.t VALUES (1, 'a')",
    );
    let d = Demo::new("storage-params-1441");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.t.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let pulled = "storage_parameters:\n  autovacuum_enabled: false\n  fillfactor: 70\n";
    assert!(text.contains(pulled), "{text}");
    std::fs::write(
        &path,
        text.replace(
            pulled,
            "storage_parameters:\n  fillfactor: 80\n  parallel_workers: 2\n",
        ),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    assert!(
        script.contains(
            "SET (fillfactor = '80', parallel_workers = '2'), RESET (autovacuum_enabled);"
        ),
        "{script}"
    );
    succeeds(approved_apply(&d, &connection, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Reset by hand: drift, named by `verify`.
    on_server(&connection, "ALTER TABLE app.t RESET (fillfactor)");
    let drifted = d.run(&["plan", "--db", &connection]);
    assert_ne!(code(&drifted), 0, "{}", stdout(&drifted));
    let verified = d.run(&["verify", "--db", &connection]);
    assert_ne!(code(&verified), 0, "{}", stdout(&verified));
    let said = format!("{}{}", stdout(&verified), stderr(&verified));
    assert!(said.contains("app.t"), "{said}");

    // A parameter the model cannot declare: reported, and nothing planned
    // over it.
    on_server(
        &connection,
        "ALTER TABLE app.t SET (fillfactor = 80, toast.autovacuum_enabled = false)",
    );
    let refused = d.run(&["plan", "--db", &connection]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    let said = format!("{}{}", stdout(&refused), stderr(&refused));
    assert!(said.contains("toast.autovacuum_enabled"), "{said}");
}

/// A replica identity goes the whole way through the CLI (#1444). Pulled as
/// declared, moved to an index the same plan creates, after it, while its
/// old index is dropped, applied and verified. Then reset by hand on the
/// server, which is drift the next plan names rather than a change it
/// quietly restates.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_replica_identity_moves_to_a_new_index_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "replica-identity-1444");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY, code integer NOT NULL, v integer); \
         CREATE UNIQUE INDEX t_code ON app.t (code); \
         ALTER TABLE app.t REPLICA IDENTITY USING INDEX t_code; \
         INSERT INTO app.t VALUES (1, 10, NULL), (2, 20, 5)",
    );
    let d = Demo::new("replica-identity-1444");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.t.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let pulled = "indexes:\n  t_code:\n    columns: [code]\n    unique: true\n\nreplica_identity: {index: t_code}\n";
    assert!(text.contains(pulled), "{text}");
    std::fs::write(
        &path,
        text.replace(
            pulled,
            "indexes:\n  t_id_code:\n    columns: [id, code]\n    unique: true\n\nreplica_identity: {index: t_id_code}\n",
        ),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("CREATE UNIQUE INDEX \"t_id_code\"") < at("REPLICA IDENTITY USING INDEX \"t_id_code\""),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "destructive", "--allow", "constraint"],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Reset by someone else: drift, named, not restated.
    on_server(&connection, "ALTER TABLE app.t REPLICA IDENTITY DEFAULT");
    let drifted = d.run(&["plan", "--db", &connection]);
    assert_ne!(code(&drifted), 0, "{}", stdout(&drifted));
    assert!(
        stderr(&drifted).contains("has drifted"),
        "{}",
        stderr(&drifted)
    );
    let verified = d.run(&["verify", "--db", &connection]);
    assert_ne!(code(&verified), 0, "{}", stdout(&verified));
    let said = format!("{}{}", stdout(&verified), stderr(&verified));
    assert!(said.contains("app.t"), "{said}");
}

/// Two functions dropped together, `g` calling `f`, each released from a
/// generated column by an expression change, and `f`'s release ordered first:
/// `g` is still dropped before `f`. Each drop moves after its own release and
/// after the drops of what depends on it (DEC-1168.1).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn dropped_functions_keep_their_order_after_their_releases() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-release-chain");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
         CREATE FUNCTION app.g(x integer) RETURNS integer LANGUAGE sql IMMUTABLE \
           BEGIN ATOMIC SELECT app.f(x); END; \
         CREATE TABLE app.a (id integer PRIMARY KEY, v integer, \
                             c integer GENERATED ALWAYS AS (app.f(v)) STORED); \
         CREATE TABLE app.z (id integer PRIMARY KEY, v integer, \
                             c integer GENERATED ALWAYS AS (app.g(v)) STORED); \
         INSERT INTO app.a (id, v) VALUES (1, 5); INSERT INTO app.z (id, v) VALUES (1, 5)",
    );
    let d = Demo::new("generated-release-chain");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    for f in ["f", "g"] {
        std::fs::remove_file(
            d.dir
                .join(format!("schema/app.{f}%28integer%29.function.yml")),
        )
        .unwrap();
    }
    for table in ["a", "z"] {
        let path = d.dir.join(format!("schema/app.{table}.yml"));
        let text = std::fs::read_to_string(&path).unwrap();
        let edited: String = text
            .lines()
            .map(|l| {
                if l.trim_start().starts_with("generated:") {
                    "    generated: {expression: 'v * 2', stored: true}".to_owned()
                } else {
                    l.to_owned()
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\n";
        assert_ne!(
            edited, text,
            "app.{table}'s generated column is where this test expects it"
        );
        std::fs::write(&path, edited).unwrap();
    }
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("DROP FUNCTION \"app\".\"g\"") < at("DROP FUNCTION \"app\".\"f\""),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &[
            "--allow",
            "narrowing",
            "--allow",
            "destructive",
            "--allow",
            "revoke",
        ],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// The drop of a function generated columns call follows what releases them,
/// wherever the differ put that (DEC-1168.1): an expression change that reads
/// a column the same revision adds, after that addition, and the drop of a
/// generated column, in the column-drop class. Moving either up to the
/// function's drop ran it ahead of what it needs, or was refused outright.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_dropped_function_follows_what_releases_its_generated_columns() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-release-later");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.f1(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
         CREATE FUNCTION app.f2(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
         CREATE TABLE app.t1 (id integer PRIMARY KEY, a integer, \
                              g1 integer GENERATED ALWAYS AS (app.f1(a)) STORED); \
         CREATE TABLE app.t2 (id integer PRIMARY KEY, a integer, \
                              g2 integer GENERATED ALWAYS AS (app.f2(a)) STORED); \
         INSERT INTO app.t1 (id, a) VALUES (1, 5); INSERT INTO app.t2 (id, a) VALUES (1, 5)",
    );
    let d = Demo::new("generated-release-later");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    for f in ["f1", "f2"] {
        std::fs::remove_file(
            d.dir
                .join(format!("schema/app.{f}%28integer%29.function.yml")),
        )
        .unwrap();
    }
    // `t1.g1` reads a new column `b` instead of calling `f1`.
    let t1 = d.dir.join("schema/app.t1.yml");
    let text = std::fs::read_to_string(&t1).unwrap();
    let edited: String = text
        .lines()
        .flat_map(|l| {
            if l == "  g1:" {
                vec![
                    "  b:".to_owned(),
                    "    type: integer".to_owned(),
                    l.to_owned(),
                ]
            } else if l.trim_start().starts_with("generated:") {
                vec!["    generated: {expression: 'b * 3', stored: true}".to_owned()]
            } else {
                vec![l.to_owned()]
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert!(
        edited.contains("  b:\n    type: integer\n  g1:"),
        "{edited}"
    );
    std::fs::write(&t1, edited).unwrap();
    // `t2.g2` goes, with the function it calls.
    let t2 = d.dir.join("schema/app.t2.yml");
    let text = std::fs::read_to_string(&t2).unwrap();
    let mut in_g2 = false;
    let edited: String = text
        .lines()
        .filter(|l| {
            if !l.starts_with("   ") {
                in_g2 = *l == "  g2:";
            }
            !in_g2
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert!(!edited.contains("g2"), "{edited}");
    std::fs::write(&t2, edited).unwrap();
    succeeds(d.run(&["drop", "app.t2.g2", "--reason", "computed elsewhere now"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("ADD COLUMN \"b\"") < at("SET EXPRESSION")
            && at("SET EXPRESSION") < at("DROP FUNCTION \"app\".\"f1\""),
        "{script}"
    );
    assert!(
        at("DROP COLUMN \"g2\"") < at("DROP FUNCTION \"app\".\"f2\""),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &[
            "--allow",
            "narrowing",
            "--allow",
            "destructive",
            "--allow",
            "revoke",
        ],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// A function a generated column calls, dropped for good in the revision that
/// changes the column's expression to stop calling it: the expression change
/// releases the dependency, so it runs before `DROP FUNCTION` and the plan
/// applies. The same drop without the expression change is still refused by
/// name, since nothing else can take the expression off (DEC-1168.1).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_expression_change_releases_a_generated_column_from_a_dropped_function() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-release");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x * 2 $$; \
         CREATE TABLE app.t (id integer PRIMARY KEY, a integer, \
                             g integer NOT NULL GENERATED ALWAYS AS (app.f(a)) STORED); \
         INSERT INTO app.t (id, a) VALUES (1, 5)",
    );
    let d = Demo::new("generated-release");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    std::fs::remove_file(d.dir.join("schema/app.f%28integer%29.function.yml")).unwrap();

    // The drop alone: refused, naming the generated column.
    succeeds(d.run(&["plan"]));
    d.commit();
    let o = d.run(&["plan", "--db", &connection]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("a generated column") && stderr(&o).contains("releases it"),
        "{}",
        stderr(&o)
    );

    // With the expression changed off the function, to one that yields a
    // NULL, and the column made nullable: the relaxation goes ahead of the
    // drop with the expression change, or `SET EXPRESSION` is refused under
    // the old NOT NULL.
    let path = d.dir.join("schema/app.t.yml");
    let table = std::fs::read_to_string(&path).unwrap();
    let mut in_g = false;
    let released: String = table
        .lines()
        .filter_map(|l| {
            if l.starts_with("  ") && !l.starts_with("   ") {
                in_g = l == "  g:";
            }
            if in_g && l.trim() == "nullable: false" {
                None
            } else if l.trim_start().starts_with("generated:") {
                Some("    generated: {expression: 'nullif(a, 5) * 3', stored: true}".to_owned())
            } else {
                Some(l.to_owned())
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert_ne!(
        released, table,
        "the fixture's `g` is where this test expects it"
    );
    std::fs::write(&path, released).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(at("SET EXPRESSION") < at("DROP FUNCTION"), "{script}");
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &[
            "--allow",
            "narrowing",
            "--allow",
            "destructive",
            "--allow",
            "revoke",
        ],
    ));
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*)::int8 FROM app.t WHERE id = 1 AND g IS NULL"
        ),
        1
    );
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// A generated column's new expression calls a function the same plan
/// creates, so its release of `a` runs after the plan's rows, and `a`'s drop
/// waits behind it, past a row inserted into the table (#1397). A nullable
/// input lets that row in, and the plan applies end to end. A `NOT NULL`
/// input with no default instead delays its insert and the insert's consumers
/// until the release and drop have run (#2174). This exact flow needs PG17+.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_released_input_dropped_past_an_inserted_row_carries_its_consumers() {
    let server = server();
    let own = OwnDatabase::new(&server, "released-drop-insert");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.opt (id integer PRIMARY KEY, a integer, b integer, \
                               g integer GENERATED ALWAYS AS (a * 2) STORED); \
         CREATE TABLE app.req (id integer PRIMARY KEY, a integer NOT NULL, b integer, \
                               g integer GENERATED ALWAYS AS (a * 2) STORED); \
         CREATE TABLE app.child (id integer PRIMARY KEY, pid integer NOT NULL REFERENCES app.req(id))",
    );
    let d = Demo::new("released-drop-insert");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    // One revision of a table: `a` gone, `g` computed by `function` from
    // `b`, which the same revision creates, and a row inserted without `a`.
    let revise = |table: &str, function: &str| {
        std::fs::write(
            d.dir
                .join(format!("schema/app.{function}%28integer%29.function.yml")),
            format!(
                "function: app.{function}(integer)\npublic_execute: true\n\ndefinition: |-\n  \
                 (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x * 3 $$\n"
            ),
        )
        .unwrap();
        let path = d.dir.join(format!("schema/app.{table}.yml"));
        let text = std::fs::read_to_string(&path).unwrap();
        let mut in_a = false;
        let edited: String = text
            .lines()
            .filter_map(|l| {
                if !l.starts_with("   ") {
                    in_a = l == "  a:";
                }
                if in_a {
                    None
                } else if l.trim_start().starts_with("generated:") {
                    Some(format!(
                        "    generated: {{expression: 'app.{function}(b)', stored: true}}"
                    ))
                } else {
                    Some(l.to_owned())
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\ndata:\n  mode: exact\n  rows:\n    1: {b: 3}\n";
        assert!(!edited.contains("  a:\n"), "{edited}");
        std::fs::write(&path, edited).unwrap();
        succeeds(d.run(&[
            "drop",
            &format!("app.{table}.a"),
            "--reason",
            "computed from b now",
        ]));
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    revise("opt", "f");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    // The row before the release, the drop after it.
    assert!(
        at("INSERT INTO \"app\".\"opt\"")
            < at("ALTER TABLE \"app\".\"opt\" ALTER COLUMN \"g\" SET EXPRESSION")
            && at("ALTER TABLE \"app\".\"opt\" ALTER COLUMN \"g\" SET EXPRESSION")
                < at("ALTER TABLE \"app\".\"opt\" DROP COLUMN \"a\""),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "narrowing", "--allow", "destructive"],
    ));
    assert_eq!(
        scalar(&connection, "SELECT g::int8 FROM app.opt WHERE id = 1"),
        9
    );
    succeeds(d.run(&["verify", "--db", &connection]));

    assert!(stdout(&succeeds(d.run(&["plan", "--db", &connection]))).contains("No changes"));
    revise("req", "h");
    let path = d.dir.join("schema/app.req.yml");
    let text = std::fs::read_to_string(&path)
        .unwrap()
        .replace("    1: {b: 3}", "    1: {b: 3}\n    2: {b: 4}")
        + "\nunique:\n  req_b_unique: [b]\n";
    std::fs::write(path, text).unwrap();
    let path = d.dir.join("schema/app.child.yml");
    let text = std::fs::read_to_string(&path).unwrap()
        + "\ndata:\n  mode: exact\n  rows:\n    1: {pid: 1}\n";
    std::fs::write(path, text).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let saved: pbps_model::SavedPlan =
        serde_json::from_slice(&std::fs::read(&plan).unwrap()).unwrap();
    let at = |predicate: &dyn Fn(&pbps_model::Change) -> bool| {
        saved
            .changes
            .changes
            .iter()
            .position(|p| predicate(&p.change))
            .unwrap()
    };
    use pbps_model::Change;
    let release = at(
        &|c| matches!(c,Change::AlterColumnExpression { column,.. } if column.table.raw().to_string()=="app.req"),
    );
    let dropped = at(
        &|c| matches!(c,Change::DropColumn { column,.. } if column.table.raw().to_string()=="app.req" && column.name.raw()=="a"),
    );
    let parent = at(
        &|c| matches!(c,Change::InsertRow { table,key,.. } if table.raw().to_string()=="app.req" && *key==pbps_model::RowKey::from("1")),
    );
    let later = at(
        &|c| matches!(c,Change::InsertRow { table,key,.. } if table.raw().to_string()=="app.req" && *key==pbps_model::RowKey::from("2")),
    );
    let child =
        at(&|c| matches!(c,Change::InsertRow { table,.. } if table.raw().to_string()=="app.child"));
    let key =
        at(&|c| matches!(c,Change::AddUnique { table,.. } if table.raw().to_string()=="app.req"));
    assert!(
        release < dropped && dropped < parent && parent < later && parent < child && later < key,
        "{:?}",
        saved.changes
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &[
            "--allow",
            "narrowing",
            "--allow",
            "destructive",
            "--allow",
            "constraint",
        ],
    ));
    assert_eq!(scalar(&connection, "SELECT sum(g)::int8 FROM app.req"), 21);
    assert_eq!(
        scalar(&connection, "SELECT count(*) FROM app.child WHERE pid=1"),
        1
    );
    succeeds(d.run(&["verify", "--db", &connection]));
    assert!(stdout(&succeeds(d.run(&["plan", "--db", &connection]))).contains("No changes"));
}

/// A defaulted input's release must preserve the Default effect edge in the
/// debug final check (#2291). PG16 reaches its existing capability refusal
/// and uses the supported drop/re-add SQL control instead.
#[test]
#[ignore = "needs live PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_defaulted_generated_input_is_released_before_its_insert() {
    for (label, server, modern) in [
        ("pg18", server(), true),
        (
            "pg16",
            std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB is not set"),
            false,
        ),
    ] {
        let own = OwnDatabase::new(&server, &format!("defaulted_release_{label}"));
        let connection = own.connection();
        on_server(
            connection,
            "CREATE SCHEMA app; \
             CREATE TABLE app.t (id integer PRIMARY KEY, a integer NOT NULL DEFAULT 7, \
                                 b integer, g integer GENERATED ALWAYS AS (a * 2) STORED)",
        );
        let d = Demo::new(&format!("defaulted-release-{label}"));
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let path = d.dir.join("schema/app.t.yml");
        let mut text = std::fs::read_to_string(&path).unwrap();
        let start = text.find("  a:\n").unwrap();
        let end = text.find("  b:\n").unwrap();
        text.replace_range(start..end, "");
        let mut desired = text
            .lines()
            .map(|line| {
                if line.trim_start().starts_with("generated:") {
                    "    generated: {expression: 'app.f(b)', stored: true}"
                } else {
                    line
                }
            })
            .collect::<Vec<_>>()
            .join("\n");
        desired.push_str("\ndata:\n  mode: exact\n  rows:\n    1: {b: 3}\n");
        std::fs::write(path, desired).unwrap();
        std::fs::write(
            d.dir.join("schema/app.f%28integer%29.function.yml"),
            "function: app.f(integer)\npublic_execute: true\n\ndefinition: |-\n  \
             (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x * 3 $$\n",
        )
        .unwrap();
        succeeds(d.run(&["drop", "app.t.a", "--reason", "release generated input"]));
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join("plan.json");
        let planned = d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]);
        if modern {
            succeeds(planned);
            let saved: pbps_model::SavedPlan =
                serde_json::from_slice(&std::fs::read(&plan).unwrap()).unwrap();
            use pbps_model::Change;
            let at = |predicate: fn(&Change) -> bool| {
                saved
                    .changes
                    .changes
                    .iter()
                    .position(|p| predicate(&p.change))
                    .unwrap()
            };
            let function = at(|c| matches!(c, Change::CreateModule { .. }));
            let release = at(|c| matches!(c, Change::AlterColumnExpression { .. }));
            let drop = at(|c| matches!(c, Change::DropColumn { .. }));
            let insert = at(|c| matches!(c, Change::InsertRow { .. }));
            assert!(
                function < release && release < drop && drop < insert,
                "{:?}",
                saved.changes
            );
            succeeds(approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "narrowing", "--allow", "destructive"],
            ));
            succeeds(d.run(&["verify", "--db", connection]));
            let next = succeeds(d.run(&["plan", "--db", connection]));
            assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        } else {
            assert!(!planned.status.success());
            let error = stderr(&planned);
            assert!(
                error.contains("generation_support")
                    && error.contains(
                        "changing a generated column's expression needs PostgreSQL 17 or later"
                    )
                    && !error.contains("effects contradict this order"),
                "{error}"
            );
            assert!(!plan.exists());
            assert_eq!(scalar(connection, "SELECT count(*) FROM app.t"), 0);
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*) FROM pg_catalog.pg_attribute \
                    WHERE attrelid='app.t'::regclass AND attname='a' AND NOT attisdropped"
                ),
                1
            );
            // This is the supported PG16 SQL shape, not admission of an
            // AlterColumnExpression that the server cannot execute.
            on_server(
                connection,
                "CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE \
                 AS $$ SELECT x * 3 $$; \
                 ALTER TABLE app.t DROP COLUMN g; \
                 ALTER TABLE app.t ADD COLUMN g integer GENERATED ALWAYS AS (app.f(b)) STORED; \
                 ALTER TABLE app.t DROP COLUMN a; \
                 INSERT INTO app.t(id,b) VALUES(1,3)",
            );
        }
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM app.t WHERE id=1 AND b=3 AND g=9"
            ),
            1
        );
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM pg_catalog.pg_attribute \
                WHERE attrelid='app.t'::regclass AND attname='a' AND NOT attisdropped"
            ),
            0
        );
    }
}

/// The same plan as above, on a `NOT NULL` input a `BEFORE INSERT` trigger
/// fills (#2178). The trigger kept, the row is let in and the plan applies.
/// The trigger dropped by the same plan, the one that would fill `a` may be
/// gone when the row is written, so its row must follow the released input's
/// drop, just as for an input nothing fills (#2174).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_released_input_a_trigger_fills_is_required_once_the_plan_drops_the_trigger() {
    let server = server();
    let own = OwnDatabase::new(&server, "released-drop-trigger");
    let connection = own.connection().to_owned();
    let table = |name: &str| {
        format!(
            "CREATE TABLE app.{name} (id integer PRIMARY KEY, a integer NOT NULL, b integer, \
                                     g integer GENERATED ALWAYS AS (a * 2) STORED); \
             CREATE FUNCTION app.fill_{name}() RETURNS trigger LANGUAGE plpgsql AS \
               $$ BEGIN NEW.a := 0; RETURN NEW; END $$; \
             CREATE TRIGGER fill BEFORE INSERT ON app.{name} \
               FOR EACH ROW EXECUTE FUNCTION app.fill_{name}();"
        )
    };
    on_server(
        &connection,
        &format!("CREATE SCHEMA app; {} {}", table("kept"), table("gone")),
    );
    let d = Demo::new("released-drop-trigger");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    // As above: `a` gone, `g` computed by `function` from `b`, created by the
    // same revision, and a row inserted without `a`.
    let revise = |table: &str, function: &str| {
        std::fs::write(
            d.dir
                .join(format!("schema/app.{function}%28integer%29.function.yml")),
            format!(
                "function: app.{function}(integer)\npublic_execute: true\n\ndefinition: |-\n  \
                 (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x * 3 $$\n"
            ),
        )
        .unwrap();
        let path = d.dir.join(format!("schema/app.{table}.yml"));
        let text = std::fs::read_to_string(&path).unwrap();
        let mut in_a = false;
        let edited: String = text
            .lines()
            .filter_map(|l| {
                if !l.starts_with("   ") {
                    in_a = l == "  a:";
                }
                if in_a {
                    None
                } else if l.trim_start().starts_with("generated:") {
                    Some(format!(
                        "    generated: {{expression: 'app.{function}(b)', stored: true}}"
                    ))
                } else {
                    Some(l.to_owned())
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\ndata:\n  mode: exact\n  rows:\n    1: {b: 3}\n";
        assert!(!edited.contains("  a:\n"), "{edited}");
        std::fs::write(&path, edited).unwrap();
        succeeds(d.run(&[
            "drop",
            &format!("app.{table}.a"),
            "--reason",
            "computed from b now",
        ]));
    };
    let plan = d.dir.join("plan.json");
    revise("kept", "f");
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "narrowing", "--allow", "destructive"],
    ));
    assert_eq!(
        scalar(&connection, "SELECT g::int8 FROM app.kept WHERE id = 1"),
        9
    );

    // The trigger on `gone` and its function dropped by the same revision.
    revise("gone", "h");
    let mut removed = Vec::new();
    for entry in std::fs::read_dir(d.dir.join("schema")).unwrap() {
        let path = entry.unwrap().path();
        let text = std::fs::read_to_string(&path).unwrap_or_default();
        if text.contains("fill_gone") {
            removed.push(path.file_name().unwrap().to_string_lossy().into_owned());
            std::fs::remove_file(path).unwrap();
        }
    }
    // The trigger, and the function only it calls.
    assert_eq!(removed.len(), 2, "{removed:?}");
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "narrowing", "--allow", "destructive"],
    ));
    assert_eq!(
        scalar(&connection, "SELECT g::int8 FROM app.gone WHERE id=1"),
        9
    );
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM pg_trigger WHERE tgrelid='app.gone'::regclass AND NOT tgisinternal"
        ),
        0
    );
    succeeds(d.run(&["verify", "--db", &connection]));
    assert!(stdout(&succeeds(d.run(&["plan", "--db", &connection]))).contains("No changes"));
}

/// PG16 cannot SET EXPRESSION. Removing the generated reader is its supported
/// sibling; this tests real plan/apply/empty-replan, not the PG17+ expression flip.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_dropped_generated_reader_releases_its_required_input_before_inserted_rows() {
    for (version, server) in [(16, old_server()), (18, server())] {
        let own = OwnDatabase::new(&server, &format!("released-reader-{version}"));
        let connection = own.connection();
        on_server(
            connection,
            "CREATE SCHEMA app; CREATE TABLE app.p (id integer PRIMARY KEY,a integer NOT NULL,b integer,g integer GENERATED ALWAYS AS (a*2) STORED); CREATE TABLE app.c (id integer PRIMARY KEY,pid integer NOT NULL REFERENCES app.p(id))",
        );
        let d = Demo::new(&format!("released-reader-{version}"));
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let path = d.dir.join("schema/app.p.yml");
        let text = std::fs::read_to_string(&path).unwrap();
        let mut removed = false;
        let edited = text
            .lines()
            .filter(|line| {
                if !line.starts_with("   ") {
                    removed = *line == "  a:" || *line == "  g:";
                }
                !removed
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\nunique:\n  p_b_unique: [b]\ndata:\n  mode: exact\n  rows:\n    1: {b: 3}\n    2: {b: 4}\n";
        std::fs::write(path, edited).unwrap();
        let path = d.dir.join("schema/app.c.yml");
        let text = std::fs::read_to_string(&path).unwrap()
            + "\ndata:\n  mode: exact\n  rows:\n    1: {pid: 1}\n";
        std::fs::write(path, text).unwrap();
        succeeds(d.run(&[
            "intent",
            "--drop",
            "app.p.a",
            "reader and old input removed",
            "--drop",
            "app.p.g",
            "reader and old input removed",
        ]));
        succeeds(d.run(&["plan"]));
        d.commit();
        let path = d.dir.join("plan.json");
        succeeds(d.run(&["plan", "--db", connection, "--out", path.to_str().unwrap()]));
        let saved: pbps_model::SavedPlan =
            serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
        let drop_at = |name: &str| {
            saved.changes.changes.iter().position(|p| matches!(&p.change,pbps_model::Change::DropColumn { column,.. } if column.table.raw().to_string()=="app.p" && column.name.raw()==name)).unwrap()
        };
        let insert=saved.changes.changes.iter().position(|p| matches!(&p.change,pbps_model::Change::InsertRow { table,.. } if table.raw().to_string()=="app.p")).unwrap();
        assert!(
            drop_at("g") < drop_at("a") && drop_at("a") < insert,
            "PG{version}: {:?}",
            saved.changes
        );
        succeeds(approved_apply(
            &d,
            connection,
            &path,
            &[
                "--allow",
                "destructive",
                "--allow",
                "narrowing",
                "--allow",
                "constraint",
            ],
        ));
        assert_eq!(scalar(connection, "SELECT sum(b)::int8 FROM app.p"), 7);
        assert_eq!(
            scalar(connection, "SELECT count(*) FROM app.c WHERE pid=1"),
            1
        );
        succeeds(d.run(&["verify", "--db", connection]));
        assert!(
            stdout(&succeeds(d.run(&["plan", "--db", connection]))).contains("No changes"),
            "PG{version}"
        );
    }
}

/// One revision changes a generated column's expression to stop reading `a`
/// and drops or retypes `a`: the expression change runs first, releasing `a`,
/// and the plan applies (DEC-1316.1). A view over the generated column stays:
/// `SET EXPRESSION` leaves the column it reads in place. An expression that still names `a` is
/// still refused by name, before anything runs.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_expression_change_releases_its_old_input_in_the_same_plan() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-input-release");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t1 (id integer PRIMARY KEY, a integer, b integer, \
                              g integer GENERATED ALWAYS AS (a * 2) STORED); \
         CREATE TABLE app.t2 (id integer PRIMARY KEY, a integer, b integer, \
                              g integer GENERATED ALWAYS AS (a * 2) STORED); \
         CREATE TABLE app.t3 (id integer PRIMARY KEY, a integer, b integer, \
                              g integer GENERATED ALWAYS AS (a * 2) STORED); \
         CREATE VIEW app.v1 AS SELECT id, g FROM app.t1; \
         INSERT INTO app.t1 (id, a, b) VALUES (1, 5, 7); \
         INSERT INTO app.t2 (id, a, b) VALUES (1, 5, 7); \
         INSERT INTO app.t3 (id, a, b) VALUES (1, 5, 7)",
    );
    let d = Demo::new("generated-input-release");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    // Rewrites one table's declaration: `g`'s expression, and `a` dropped
    // (`None`) or retyped.
    let edit = |table: &str, expression: &str, a_type: Option<&str>| {
        let path = d.dir.join(format!("schema/app.{table}.yml"));
        let text = std::fs::read_to_string(&path).unwrap();
        let mut in_a = false;
        let edited: String = text
            .lines()
            .filter_map(|l| {
                if !l.starts_with("   ") {
                    in_a = l == "  a:";
                }
                if in_a {
                    return match a_type {
                        None => None,
                        Some(ty) if l.trim_start().starts_with("type:") => {
                            Some(format!("    type: {ty}"))
                        }
                        Some(_) => Some(l.to_owned()),
                    };
                }
                if l.trim_start().starts_with("generated:") {
                    Some(format!(
                        "    generated: {{expression: '{expression}', stored: true}}"
                    ))
                } else {
                    Some(l.to_owned())
                }
            })
            .collect::<Vec<_>>()
            .join("\n")
            + "\n";
        assert_ne!(edited, text, "app.{table} is where this test expects it");
        std::fs::write(&path, edited).unwrap();
    };
    edit("t1", "b * 2", None);
    edit("t2", "b * 2", Some("text"));
    // And a default written for the new type, which the old one refuses
    // (`invalid input syntax for type integer`, measured on 18.6): it has to
    // follow the retype wherever the retype goes.
    let t2 = d.dir.join("schema/app.t2.yml");
    let text = std::fs::read_to_string(&t2).unwrap();
    let defaulted = text.replacen(
        "  a:\n    type: text\n",
        "  a:\n    type: text\n    default: \"'abc'\"\n",
        1,
    );
    assert_ne!(
        defaulted, text,
        "app.t2's `a` is where this test expects it"
    );
    std::fs::write(&t2, defaulted).unwrap();
    succeeds(d.run(&["drop", "app.t1.a", "--reason", "computed from b now"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("ALTER TABLE \"app\".\"t1\" ALTER COLUMN \"g\" SET EXPRESSION")
            < at("ALTER TABLE \"app\".\"t1\" DROP COLUMN \"a\""),
        "{script}"
    );
    assert!(
        at("ALTER TABLE \"app\".\"t2\" ALTER COLUMN \"g\" SET EXPRESSION")
            < at("ALTER TABLE \"app\".\"t2\" ALTER COLUMN \"a\" TYPE"),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "narrowing", "--allow", "destructive"],
    ));
    assert_eq!(
        scalar(&connection, "SELECT g::int8 FROM app.t1 WHERE id = 1"),
        14
    );
    assert_eq!(
        scalar(&connection, "SELECT g::int8 FROM app.t2 WHERE id = 1"),
        14
    );
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Negative: the new expression still names `a`, so it may still read it,
    // and the retype is refused by name before anything runs.
    edit("t3", "a + b", Some("bigint"));
    succeeds(d.run(&["plan"]));
    d.commit();
    let o = d.run(&["plan", "--db", &connection]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("generation_support") && stderr(&o).contains("does not name `a`"),
        "{}",
        stderr(&o)
    );
}

/// #1391: a revision that drops `a` while another generated column's new
/// expression starts reading it has no order. Once `h` reads `a`, the drop is
/// refused, and before that its expression names a column that is gone. So
/// `plan --db` refuses it by name, before anything runs (DEC-1391.1).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_new_reader_of_a_dropped_input_is_refused_before_anything_runs() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-new-reader");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY, a integer, b integer, \
                             g integer GENERATED ALWAYS AS (a * 2) STORED, \
                             h integer GENERATED ALWAYS AS (b * 3) STORED)",
    );
    let d = Demo::new("generated-new-reader");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.t.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let mut column = String::new();
    let edited: String = text
        .lines()
        .filter_map(|l| {
            if !l.starts_with("   ") {
                column = l.trim().trim_end_matches(':').to_owned();
            }
            match (column.as_str(), l.trim_start().starts_with("generated:")) {
                ("a", _) => None,
                ("g", true) => Some("    generated: {expression: 'b * 2', stored: true}".into()),
                ("h", true) => Some("    generated: {expression: 'a + 1', stored: true}".into()),
                _ => Some(l.to_owned()),
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
        + "\n";
    assert!(
        edited.contains("'a + 1'") && edited.contains("'b * 2'") && !edited.contains("\n  a:"),
        "app.t is where this test expects it:\n{text}"
    );
    std::fs::write(&path, edited).unwrap();
    succeeds(d.run(&["drop", "app.t.a", "--reason", "gone"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let o = d.run(&["plan", "--db", &connection]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("new expression of app.t.h"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*)::int8 FROM information_schema.columns \
              WHERE table_schema = 'app' AND table_name = 't' AND column_name = 'a'"
        ),
        1
    );
}

/// #1425: the same with a generated column the revision adds rather than one
/// it changes. The differ drops `a` before it adds `h`, and the `ADD COLUMN`
/// would fail with `a` gone, so `plan --db` refuses it by name first.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_new_generated_column_reading_a_dropped_input_is_refused_before_anything_runs() {
    let server = server();
    let own = OwnDatabase::new(&server, "generated-added-reader");
    let connection = own.connection().to_owned();
    on_server(
        &connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY, a integer, b integer)",
    );
    let d = Demo::new("generated-added-reader");
    succeeds(d.run(&["pull", "--db", &connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &connection, "--reason", "adopt"]));
    let path = d.dir.join("schema/app.t.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let mut column = String::new();
    let mut edited: Vec<String> = Vec::new();
    for l in text.lines() {
        if !l.starts_with("   ") {
            column = l.trim().trim_end_matches(':').to_owned();
        }
        if column == "a" {
            continue;
        }
        edited.push(l.to_owned());
        if l == "columns:" {
            edited.push("  h:".into());
            edited.push("    type: integer".into());
            edited.push("    generated: {expression: 'a + 1', stored: true}".into());
        }
    }
    let edited = edited.join("\n") + "\n";
    assert!(
        edited.contains("'a + 1'") && !edited.contains("\n  a:"),
        "app.t is where this test expects it:\n{text}"
    );
    std::fs::write(&path, edited).unwrap();
    succeeds(d.run(&["drop", "app.t.a", "--reason", "gone"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let o = d.run(&["plan", "--db", &connection]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("the expression of the new app.t.h"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*)::int8 FROM information_schema.columns \
              WHERE table_schema = 'app' AND table_name = 't' AND column_name = 'a'"
        ),
        1
    );
}

/// A NOT NULL tightening runs after the plan's rows on its table, which may
/// be what fills or removes its NULLs: an `ensure` update that gives the NULL
/// a value, and an `exact` table that deletes the row holding it. Both apply,
/// and the next plan is empty. A NULL row the plan leaves alone is still
/// counted, and the plan is refused before anything runs (#1367).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_tightening_follows_the_rows_that_fill_or_remove_its_nulls() {
    let server = server();
    let own = OwnDatabase::new(&server, "tighten-after-rows");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");
    let d = Demo::new("tighten-after-rows");
    let table = |name: &str, nullable: bool, data: &str| {
        let c = if nullable {
            "{type: integer}"
        } else {
            "{type: integer, nullable: false}"
        };
        std::fs::write(
            d.dir.join(format!("schema/app.{name}.yml")),
            format!(
                "table: app.{name}\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 c: {c}\nprimary_key: {{name: pk_{name}, columns: [id]}}\n{data}"
            ),
        )
        .unwrap();
    };
    // `filled` holds a NULL an update fills, `removed` one an exact delete
    // takes away, and `kept` one nothing touches.
    table(
        "filled",
        true,
        "data:\n  mode: ensure\n  rows:\n    1: {}\n",
    );
    table(
        "removed",
        true,
        "data:\n  mode: exact\n  rows:\n    1: {c: 5}\n    2: {}\n",
    );
    table(
        "kept",
        true,
        "data:\n  mode: ensure\n  rows:\n    1: {}\n    2: {}\n",
    );
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &connection]));
    assert_eq!(
        scalar(
            &connection,
            "SELECT count(*) FROM (SELECT c FROM app.filled UNION ALL SELECT c FROM app.removed) r \
             WHERE c IS NULL"
        ),
        2
    );

    table(
        "filled",
        false,
        "data:\n  mode: ensure\n  rows:\n    1: {c: 5}\n",
    );
    table(
        "removed",
        false,
        "data:\n  mode: exact\n  rows:\n    1: {c: 5}\n",
    );
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        &connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("UPDATE \"app\".\"filled\"")
            < at("ALTER TABLE \"app\".\"filled\" ALTER COLUMN \"c\" SET NOT NULL"),
        "{script}"
    );
    assert!(
        at("DELETE FROM \"app\".\"removed\"")
            < at("ALTER TABLE \"app\".\"removed\" ALTER COLUMN \"c\" SET NOT NULL"),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        &connection,
        &plan,
        &[
            "--allow",
            "not-null",
            "--allow",
            "data-update",
            "--allow",
            "data-delete",
        ],
    ));
    succeeds(d.run(&["verify", "--db", &connection]));
    let next = succeeds(d.run(&["plan", "--db", &connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Negative: row 1 is filled, and row 2, which an `ensure` table no longer
    // declaring it leaves alone, still holds its NULL. Counted over the rows
    // the plan leaves, and refused before anything runs.
    table(
        "kept",
        false,
        "data:\n  mode: ensure\n  rows:\n    1: {c: 5}\n",
    );
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]));
    let refused = approved_apply(
        &d,
        &connection,
        &plan,
        &["--allow", "not-null", "--allow", "data-update"],
    );
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    assert!(
        stderr(&refused).contains("1 existing NULLs in app.kept.c"),
        "{}",
        stderr(&refused)
    );
    assert_eq!(
        scalar(&connection, "SELECT count(*) FROM app.kept WHERE c IS NULL"),
        2,
        "nothing ran"
    );
}

#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn the_deployment_loop_reads_constraints_before_postgres_18() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 180000 THEN RAISE EXCEPTION 'this regression needs a pre-18 server'; END IF; END $$",
    );
    deployment_loop(&server, "old-loop");
}

fn deployment_loop(server: &str, slug: &str) {
    let own = OwnDatabase::new(server, slug);
    let connection = own.connection().to_owned();
    // The tool never creates a schema (`doctor` says so); the environment has
    // to bring it, exactly as on the other engine.
    on_server(&connection, "CREATE SCHEMA app");

    let d = Demo::new(slug);
    d.table(ONE_COLUMN);
    let o = d.run(&["plan"]);
    assert_eq!(code(&o), 0, "{}", stderr(&o));
    d.commit();

    let o = d.run(&["bootstrap", "--db", &connection]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let o = d.run(&["verify", "--db", &connection]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(stdout(&o).contains("No drift"), "{}", stdout(&o));

    // One revision, planned against the database and applied through the
    // gate: a column added, and the plan's `--out` artifact is what `apply`
    // takes, checksum-pinned.
    d.table(TWO_COLUMNS);
    assert_eq!(code(&d.run(&["plan"])), 0);
    d.commit();
    let plan = d.dir.join("plan.json");
    let o = d.run(&["plan", "--db", &connection, "--out", plan.to_str().unwrap()]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(stdout(&o).contains("label"), "{}", stdout(&o));
    let o = d.run(&[
        "apply",
        "--db",
        &connection,
        "--plan",
        plan.to_str().unwrap(),
        "--checksum",
        &plan_checksum(&plan),
    ]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));

    let o = d.run(&["verify", "--db", &connection]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let o = d.run(&["plan", "--db", &connection]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(stdout(&o).contains("No changes"), "{}", stdout(&o));

    // The ledger, read back: the bootstrap and the apply, newest first.
    let o = d.run(&["state", "list", "--db", &connection, "--format", "json"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let v: serde_json::Value = serde_json::from_str(&stdout(&o))
        .unwrap_or_else(|e| panic!("stdout was not JSON ({e}): {}", stdout(&o)));
    let entries = v["data"]["entries"]
        .as_array()
        .unwrap_or_else(|| panic!("{}", stdout(&o)));
    assert_eq!(entries.len(), 2, "{v}");
    assert_eq!(entries[0]["kind"], "apply", "{v}");
    assert_eq!(entries[1]["kind"], "bootstrap", "{v}");
    // Older servers lack the new flags, not constraints themselves. The
    // fallback must still observe an independently added ordinary CHECK.
    on_server(
        &connection,
        "ALTER TABLE app.t ADD CONSTRAINT positive_id CHECK (id > 0)",
    );
    let drift = d.run(&["verify", "--db", &connection]);
    assert_ne!(code(&drift), 0, "{}{}", stdout(&drift), stderr(&drift));
    assert!(
        stdout(&drift).contains("positive_id"),
        "{}{}",
        stdout(&drift),
        stderr(&drift)
    );
}

/// Drift is drift on this engine too: a column added by hand is reported,
/// with the exit code a scheduled drift-watch keys on (DECISIONS 25), and a
/// `pull` reads the same database back into declarations that validate.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB (see scripts/live-tests-pg.sh)"]
fn drift_and_pull_are_read_from_the_postgres_catalog() {
    let server = server();
    let own = OwnDatabase::new(&server, "drift");
    let connection = own.connection().to_owned();
    on_server(&connection, "CREATE SCHEMA app");

    let d = Demo::new("drift");
    d.table(ONE_COLUMN);
    assert_eq!(code(&d.run(&["plan"])), 0);
    d.commit();
    let o = d.run(&["bootstrap", "--db", &connection]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));

    on_server(&connection, "ALTER TABLE app.t ADD COLUMN stray integer");
    let o = d.run(&["verify", "--db", &connection, "--format", "json"]);
    assert_eq!(code(&o), 2, "{}{}", stdout(&o), stderr(&o));
    let v: serde_json::Value = serde_json::from_str(&stdout(&o))
        .unwrap_or_else(|e| panic!("stdout was not JSON ({e}): {}", stdout(&o)));
    assert_eq!(v["result"], "findings", "{v}");
    assert!(stdout(&o).contains("stray"), "{}", stdout(&o));

    // `pull --force` overwrites the declarations with what the catalog holds,
    // and what it writes must validate under the same dialect.
    let o = d.run(&["pull", "--db", &connection, "--force"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let pulled = std::fs::read_to_string(d.dir.join("schema/app.t.yml")).unwrap();
    assert!(pulled.contains("stray"), "{pulled}");
    let o = d.run(&["validate"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
}

/// `doctor` examines a PostgreSQL environment through the seam: the version
/// is read, the engine has one edition so none is reported, the ledger is
/// found, and a schema the declarations use but the database lacks is the
/// error it is on the other engine — with the remedy quoted this engine's
/// way.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB (see scripts/live-tests-pg.sh)"]
fn doctor_examines_a_postgres_environment() {
    let server = server();
    let own = OwnDatabase::new(&server, "doctor");
    let connection = own.connection().to_owned();

    let d = Demo::new("doctor");
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nenvironments:\n  dev:\n    url_env: PBPS_FLOW_PG_DEV\n",
    )
    .unwrap();
    d.table(ONE_COLUMN);
    assert_eq!(code(&d.run(&["plan"])), 0);
    d.commit();

    let o = d.run_with_env(
        &["doctor", "--format", "json"],
        &[("PBPS_FLOW_PG_DEV", connection.as_str())],
    );
    let v: serde_json::Value = serde_json::from_str(&stdout(&o))
        .unwrap_or_else(|e| panic!("stdout was not JSON ({e}): {}", stdout(&o)));
    let env = &v["data"]["environments"][0];
    assert_eq!(env["state"], "uninitialized", "{v}");
    assert!(
        env["server_version"]
            .as_str()
            .is_some_and(|s| !s.is_empty()),
        "{v}"
    );
    assert!(env["edition"].is_null(), "one edition, no line: {v}");
    let ids: Vec<&str> = v["findings"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|f| f["id"].as_str())
        .collect();
    assert!(ids.contains(&"schema.absent"), "{v}");
    let absent = v["findings"]
        .as_array()
        .unwrap()
        .iter()
        .find(|f| f["id"] == "schema.absent")
        .unwrap();
    assert_eq!(absent["remedy"], "CREATE SCHEMA \"app\";", "{v}");
    assert_eq!(code(&o), 2, "{}{}", stdout(&o), stderr(&o));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB (see scripts/live-tests-pg.sh)"]
fn ledger_migration_guidance_keeps_the_explicit_or_configured_target() {
    struct Role(String, String);
    impl Drop for Role {
        fn drop(&mut self) {
            let _ = try_on_server(&self.0, &format!("DROP ROLE {}", self.1));
        }
    }
    let server = server();
    let role = Role(
        server.clone(),
        format!("pbps_target444_{}", std::process::id()),
    );
    let password = "pbpsTarget444!1";
    let own = OwnDatabase::new(&server, "migration_target444");
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    rt.block_on(async {
        let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, own.connection()).await.unwrap();
        pbps_pg::state::ensure_tables(&mut conn).await.unwrap();
        conn.execute("ALTER TABLE public.__pbps_state DROP COLUMN state_version, DROP COLUMN tables_count, DROP COLUMN modules_count, DROP COLUMN staged_completed, DROP COLUMN staged_total").await.unwrap();
    });
    on_server(
        own.connection(),
        &format!(
            "CREATE ROLE {0} LOGIN PASSWORD '{password}'; GRANT USAGE ON SCHEMA public TO {0}; GRANT SELECT, INSERT, DELETE ON public.__pbps_state, public.__pbps_lock TO {0};",
            role.1
        ),
    );
    let connection = format!(
        "{} user={} password={password}",
        own.connection()
            .split_whitespace()
            .filter(|w| !w.starts_with("user=") && !w.starts_with("password="))
            .collect::<Vec<_>>()
            .join(" "),
        role.1
    );
    let d = Demo::new("migration-target444");
    succeeds(d.run(&["plan"]));
    d.commit();
    // The first refusal has no configured environment that bare doctor could inspect.
    for configured in [false, true] {
        let output = if configured {
            std::fs::write(d.dir.join("pbps.yml"), "dialect: postgres\nenvironments:\n  target:\n    url_env: PBPS_MIGRATION_TARGET444\n").unwrap();
            d.commit();
            d.run_with_env(
                &["bootstrap", "--env", "target"],
                &[("PBPS_MIGRATION_TARGET444", &connection)],
            )
        } else {
            d.run(&["bootstrap", "--db", &connection])
        };
        let message = format!("{}{}", stdout(&output), stderr(&output));
        assert_eq!(code(&output), 1, "{message}");
        assert!(
            message.contains("public.__pbps_state is missing the timeline columns"),
            "{message}"
        );
        assert!(
            message.contains("state_version") && message.contains("staged_total"),
            "{message}"
        );
        assert!(
            message.contains("needs ownership of public.__pbps_state"),
            "{message}"
        );
        // Before issue #167 this seam rendered the ownership refusal as the
        // literal `db error`; the server's own sentence is what a reader
        // needs beside the guidance the assertion above already checks.
        assert!(
            message.contains("this role could not add them.")
                && message.contains("must be owner of table __pbps_state"),
            "{message}"
        );
        assert!(
            message.contains(
                "Run `pbps doctor` with the same `--db` or `--env` target as the failed command"
            ),
            "{message}"
        );
        assert!(
            !message.contains(password) && !message.contains(&connection),
            "credentials must stay out of guidance"
        );
    }
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn doctor_reports_data_and_role_grant_gaps_from_the_declarations() {
    struct Roles(String, Vec<String>);
    impl Drop for Roles {
        fn drop(&mut self) {
            for role in &self.1 {
                let _ = try_on_server(&self.0, &format!("DROP ROLE IF EXISTS {role}"));
            }
        }
    }
    let server = server();
    let roles = Roles(
        server.clone(),
        vec![
            format!("pbps_doctor_deployer_{}", std::process::id()),
            format!("pbps_doctor_reader_{}", std::process::id()),
        ],
    );
    let deployer = &roles.1[0];
    let reader = &roles.1[1];
    let own = OwnDatabase::new(&server, "doctor-demand");
    let connection = own.connection();
    on_server(
        connection,
        &format!(
            "CREATE ROLE {deployer} LOGIN PASSWORD 'doctor-test'; CREATE ROLE {reader}; \
         CREATE SCHEMA app AUTHORIZATION {deployer}; \
         CREATE TABLE app.t (id bigint NOT NULL PRIMARY KEY); \
         ALTER TABLE app.t OWNER TO {deployer}; \
         REVOKE INSERT ON app.t FROM {deployer}; \
         CREATE SCHEMA shared; CREATE VIEW shared.v AS SELECT 1 AS id; \
         CREATE FUNCTION shared.f(integer) RETURNS integer LANGUAGE sql AS 'SELECT $1'; \
         CREATE FUNCTION shared.f(text) RETURNS text LANGUAGE sql AS 'SELECT $1'; \
         GRANT USAGE ON SCHEMA shared TO {deployer}; \
         GRANT SELECT ON shared.v TO {deployer}; \
         GRANT EXECUTE ON FUNCTION shared.f(text) TO {deployer} WITH GRANT OPTION; \
         GRANT CREATE ON SCHEMA public TO {deployer}"
        ),
    );
    let login = format!(
        "{} user={deployer} password=doctor-test",
        connection
            .split_whitespace()
            .filter(|word| !word.starts_with("user=") && !word.starts_with("password="))
            .collect::<Vec<_>>()
            .join(" ")
    );
    let d = Demo::new("doctor-demand");
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nenvironments:\n  dev:\n    url_env: PBPS_FLOW_PG_DEV\n",
    )
    .unwrap();
    d.table(&format!(
        "{ONE_COLUMN}data:\n  mode: ensure\n  rows:\n    1: {{}}\n"
    ));
    std::fs::write(d.dir.join("schema/reader.yml"), format!(
        "role: {reader}\ngrants:\n  schema::shared: [usage]\n  shared.v: [select]\n  shared.f(integer): [execute]\n"
    )).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let diagnose = || {
        let output = d.run_with_env(
            &["doctor", "--format", "json"],
            &[("PBPS_FLOW_PG_DEV", login.as_str())],
        );
        let json: serde_json::Value = serde_json::from_str(&stdout(&output)).unwrap();
        (output, json)
    };
    let (output, json) = diagnose();
    assert_eq!(code(&output), 2, "{json}");
    let gaps = json["data"]["environments"][0]["missing_permissions"]
        .as_array()
        .unwrap();
    for expected in [
        "INSERT on TABLE \"app\".\"t\"",
        "USAGE WITH GRANT OPTION on SCHEMA \"shared\"",
        "SELECT WITH GRANT OPTION on TABLE \"shared\".\"v\"",
        "EXECUTE WITH GRANT OPTION on ROUTINE \"shared\".\"f\"(integer)",
    ] {
        assert!(
            gaps.iter()
                .any(|g| g.as_str().unwrap().starts_with(expected)),
            "missing {expected}: {json}"
        );
    }
    assert!(
        !gaps
            .iter()
            .any(|g| g.as_str().unwrap().starts_with("DELETE")
                || g.as_str().unwrap().starts_with("UPDATE")),
        "a key-only ensure block never updates or deletes: {json}"
    );
    on_server(
        connection,
        &format!(
            "GRANT INSERT (id) ON app.t TO {deployer}; \
         GRANT USAGE ON SCHEMA shared TO {deployer} WITH GRANT OPTION; \
         GRANT SELECT ON shared.v TO {deployer} WITH GRANT OPTION; \
         GRANT EXECUTE ON FUNCTION shared.f(integer) TO {deployer} WITH GRANT OPTION"
        ),
    );
    let (_, json) = diagnose();
    assert_eq!(
        json["data"]["environments"][0]["missing_permissions"],
        serde_json::json!([]),
        "the named remedies remove every permission gap: {json}"
    );
}

/// #820. Once a project has recorded identities, `doctor`'s permission read
/// starts by reading the last recorded state, so a deploying role that may not
/// `SELECT` from `public.__pbps_state` gets `permission.unknown` even though
/// the catalogs it was sent to are readable. The remedy has to name the ledger.
///
/// One project, one restricted login, three fresh observations: the read
/// works, the table's `SELECT` alone is taken away, and it is given back. Each
/// is checked by the login's own read of the table and by the server's
/// effective-privilege answer, so the finding is tied to that one grant and
/// not to a connection, a missing table or the lock.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn doctor_names_the_recorded_state_read_when_its_select_is_denied() {
    struct Role(String, String);
    impl Drop for Role {
        fn drop(&mut self) {
            let _ = try_on_server(&self.0, &format!("DROP ROLE IF EXISTS {}", self.1));
        }
    }
    let server = server();
    let role = Role(
        server.clone(),
        format!("pbps_doctor_ledger_{}", std::process::id()),
    );
    let deployer = role.1.as_str();
    let own = OwnDatabase::new(&server, "doctor-ledger-read");
    let connection = own.connection();
    on_server(
        connection,
        &format!(
            "CREATE ROLE {deployer} LOGIN NOSUPERUSER PASSWORD 'ledger-820-secret'; CREATE SCHEMA app"
        ),
    );
    let login = format!(
        "{} user={deployer} password=ledger-820-secret",
        connection
            .split_whitespace()
            .filter(|word| !word.starts_with("user=") && !word.starts_with("password="))
            .collect::<Vec<_>>()
            .join(" ")
    );
    let d = Demo::new("doctor-ledger-read");
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nenvironments:\n  dev:\n    url_env: PBPS_FLOW_PG_DEV\n",
    )
    .unwrap();
    d.table(ONE_COLUMN);
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    let ids = std::fs::read_to_string(d.dir.join("schema.ids.json")).unwrap();
    assert!(
        ids.contains("app.t"),
        "the project has recorded identities: {ids}"
    );
    assert_eq!(
        scalar(connection, "SELECT count(*) FROM public.__pbps_state"),
        1,
        "bootstrap recorded one state"
    );
    // Everything a read of this project needs, the ledger's included, so the
    // only thing the middle observation changes is the one grant.
    on_server(
        connection,
        &format!(
            "GRANT USAGE ON SCHEMA public, app TO {deployer}; \
             GRANT SELECT ON public.__pbps_state, public.__pbps_lock, app.t TO {deployer}"
        ),
    );
    let can_select = || {
        scalar(
            connection,
            &format!(
                "SELECT has_table_privilege('{deployer}', 'public.__pbps_state', 'SELECT')::int::bigint"
            ),
        ) == 1
    };
    let reads_it = || try_on_server(&login, "SELECT count(*) FROM public.__pbps_state");
    let diagnose = || {
        let output = d.run_with_env(
            &["doctor", "--format", "json"],
            &[("PBPS_FLOW_PG_DEV", login.as_str())],
        );
        let json: serde_json::Value = serde_json::from_str(&stdout(&output))
            .unwrap_or_else(|e| panic!("{e}: {}", stdout(&output)));
        assert!(
            !stdout(&output).contains("ledger-820-secret")
                && !stderr(&output).contains("ledger-820-secret"),
            "the password is never printed"
        );
        (output, json)
    };
    let unknown = |json: &serde_json::Value| -> Vec<serde_json::Value> {
        json["findings"]
            .as_array()
            .unwrap_or_else(|| panic!("{json}"))
            .iter()
            .filter(|f| f["id"] == "permission.unknown")
            .cloned()
            .collect()
    };
    let identities = || std::fs::read_to_string(d.dir.join("schema.ids.json")).unwrap();
    let ledger = || scalar(connection, "SELECT count(*) FROM public.__pbps_state");

    // Readable: the permission read answers.
    assert!(can_select());
    reads_it().expect("the login reads the recorded state");
    let (_, json) = diagnose();
    assert!(unknown(&json).is_empty(), "{json}");
    // Serialized only when set.
    assert_ne!(
        json["data"]["environments"][0]["permissions_unknown"], true,
        "{json}"
    );

    // That one grant taken away, and nothing else granting it.
    on_server(
        connection,
        &format!("REVOKE SELECT ON public.__pbps_state FROM {deployer}"),
    );
    assert!(
        !can_select(),
        "no other grant lets the login read the table"
    );
    let denied = reads_it().expect_err("the login can no longer read the recorded state");
    assert!(
        denied.contains("permission denied for table __pbps_state"),
        "{denied}"
    );
    try_on_server(&login, "SELECT count(*) FROM public.__pbps_lock")
        .expect("the lock is still readable");
    try_on_server(&login, "SELECT count(*) FROM pg_catalog.pg_class")
        .expect("the catalogs are still readable");
    let (output, json) = diagnose();
    assert_ne!(code(&output), 0, "{json}");
    let found = unknown(&json);
    assert_eq!(found.len(), 1, "{json}");
    assert_eq!(found[0]["severity"], "error", "{json}");
    // Since #822 the finding's message carries the advice, and its remedy is
    // the command that checks again: which read failed is not known there.
    let advice = found[0]["message"]
        .as_str()
        .unwrap_or_else(|| panic!("{json}"));
    assert!(advice.contains("SELECT on public.__pbps_state"), "{advice}");
    assert!(advice.contains("USAGE on schema public"), "{advice}");
    assert_eq!(found[0]["remedy"], "pbps doctor --env dev", "{json}");
    let environment = &json["data"]["environments"][0];
    assert_eq!(environment["permissions_unknown"], true, "{json}");
    let detail = environment["detail"]
        .as_str()
        .unwrap_or_else(|| panic!("{json}"));
    assert!(detail.contains("recorded identities"), "{detail}");
    // Read-only: doctor changed neither the declarations nor the ledger.
    assert_eq!(identities(), ids);
    assert_eq!(ledger(), 1);

    // Given back, by the same login in a fresh session: the finding goes.
    on_server(
        connection,
        &format!("GRANT SELECT ON public.__pbps_state TO {deployer}"),
    );
    assert!(can_select());
    reads_it().expect("the login reads the recorded state again");
    let (_, json) = diagnose();
    assert!(unknown(&json).is_empty(), "{json}");
    assert_eq!(identities(), ids);
    assert_eq!(ledger(), 1);

    // The database goes before the cluster-wide role, which it holds grants for.
    drop(own);
}

/// #566: doctor keys a declared routine the way the dialect spells it, as
/// the planner does. A managed `app.f(integer)` whose ACL grants `EXECUTE` to
/// a declared role, granted by somebody this deployer cannot act for, needs
/// the grant option to be managed. Declared as `app.f(int)`, the file's
/// spelling matched nothing the catalog reads back, the adopted ACL was set
/// aside as unmanaged, and doctor reported no gap at all. Both spellings now
/// report the same one.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn doctor_reports_an_adopted_routine_grant_whatever_the_argument_spelling() {
    for spelling in ["int", "integer"] {
        let server = server();
        let deployer = format!("pbps_d566_dep_{}_{spelling}", std::process::id());
        let reader = format!("pbps_d566_read_{}_{spelling}", std::process::id());
        let _roles = ClusterRoles {
            server: server.clone(),
            names: vec![deployer.clone(), reader.clone()],
        };
        let own = OwnDatabase::new(&server, &format!("doctor-566-{spelling}"));
        let connection = own.connection();
        on_server(
            connection,
            &format!(
                "CREATE ROLE {deployer} LOGIN PASSWORD 'doctor-test'; CREATE ROLE {reader}; \
                 CREATE SCHEMA app AUTHORIZATION {deployer}; \
                 GRANT CREATE ON SCHEMA public TO {deployer}; \
                 CREATE FUNCTION app.f(integer) RETURNS integer LANGUAGE sql AS 'SELECT $1'; \
                 GRANT EXECUTE ON FUNCTION app.f(integer) TO {reader}"
            ),
        );
        let login = format!(
            "{} user={deployer} password=doctor-test",
            connection
                .split_whitespace()
                .filter(|word| !word.starts_with("user=") && !word.starts_with("password="))
                .collect::<Vec<_>>()
                .join(" ")
        );
        let d = Demo::new(&format!("doctor-566-{spelling}"));
        std::fs::write(
            d.dir.join("pbps.yml"),
            "dialect: postgres\nenvironments:\n  dev:\n    url_env: PBPS_FLOW_PG_DEV\n",
        )
        .unwrap();
        std::fs::write(
            d.dir.join("schema/f.yml"),
            format!(
                "function: app.f({spelling})\n\
                 definition: (n {spelling}) RETURNS integer LANGUAGE sql AS 'SELECT n'\n"
            ),
        )
        .unwrap();
        std::fs::write(d.dir.join("schema/reader.yml"), format!("role: {reader}\n")).unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
        let output = d.run_with_env(
            &["doctor", "--format", "json"],
            &[("PBPS_FLOW_PG_DEV", login.as_str())],
        );
        let json: serde_json::Value = serde_json::from_str(&stdout(&output)).unwrap();
        assert_eq!(code(&output), 2, "{spelling}: {json}");
        let gaps = json["data"]["environments"][0]["missing_permissions"]
            .as_array()
            .unwrap();
        assert!(
            gaps.iter().any(|g| g
                .as_str()
                .unwrap()
                .starts_with("EXECUTE WITH GRANT OPTION on ROUTINE \"app\".\"f\"(integer)")),
            "{spelling}: {json}"
        );
    }
}

/// #2249: adopted sequence ACLs need the same original-grantor authority
/// doctor already checks for relations and routines. The physical sequence
/// name is deliberately unrelated to the column address used by the plan.
#[test]
#[ignore = "needs live PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn doctor_predicts_the_adopted_serial_sequence_grant_the_plan_cannot_revoke() {
    let mut failed_versions = Vec::new();
    for (version, server) in [
        (16, std::env::var("PBPS_TEST_PG_OLD_DB").unwrap()),
        (18, server()),
    ] {
        // Exercise both engines even when a mutation breaks the first one.
        let result = std::panic::catch_unwind(|| {
            let deployer = format!("pbps_d2249_dep_{version}_{}", std::process::id());
            let grantor = format!("pbps_d2249_grant_{version}_{}", std::process::id());
            let reader = format!("pbps_d2249_read_{version}_{}", std::process::id());
            let _roles = ClusterRoles {
                server: server.clone(),
                names: vec![reader.clone(), grantor.clone(), deployer.clone()],
            };
            let own = OwnDatabase::new(&server, &format!("doctor-sequence2249-{version}"));
            let connection = own.connection();
            assert_eq!(
                scalar(
                    connection,
                    "SELECT current_setting('server_version_num')::bigint / 10000"
                ),
                version
            );
            on_server(
                connection,
                &format!(
                    "CREATE ROLE {deployer} LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE PASSWORD 'trigger-test'; \
                 CREATE ROLE {grantor} NOSUPERUSER; CREATE ROLE {reader} NOSUPERUSER; \
                 CREATE SCHEMA app AUTHORIZATION {deployer}; \
                 GRANT CREATE ON SCHEMA public TO {deployer}"
                ),
            );
            let login = as_role(connection, &deployer);
            on_server(
                &login,
                "CREATE TABLE app.t (id serial PRIMARY KEY); ALTER SEQUENCE app.t_id_seq RENAME TO custom2249",
            );
            let d = Demo::new(&format!("doctor-sequence2249-{version}"));
            std::fs::write(
                d.dir.join("pbps.yml"),
                "dialect: postgres\nenvironments:\n  dev:\n    url_env: PBPS_FLOW_PG_DEV\n",
            )
            .unwrap();
            d.table("table: app.t\ncolumns:\n  id: {type: serial, sequence: {name: custom2249}}\nprimary_key: {name: t_pkey, columns: [id]}\n");
            succeeds(d.run(&["plan"]));
            d.commit();
            succeeds(d.run(&[
                "baseline",
                "--db",
                &login,
                "--reason",
                "existing serial table",
            ]));

            // The table is recorded before the recipient is managed. Neither
            // declarations nor ledger contain this ACL; adoption of the newly
            // managed role must reach the planner's revocability check.
            on_server(
                &login,
                &format!(
                    "GRANT USAGE ON SCHEMA app TO {grantor}; \
                 GRANT USAGE ON SEQUENCE app.custom2249 TO {grantor} WITH GRANT OPTION"
                ),
            );
            on_server(
                connection,
                &format!(
                    "SET ROLE {grantor}; GRANT USAGE ON SEQUENCE app.custom2249 TO {reader}; RESET ROLE"
                ),
            );
            std::fs::write(d.dir.join("schema/reader.yml"), format!("role: {reader}\n")).unwrap();
            succeeds(d.run(&["plan"]));
            d.commit();
            let target: pbps_model::GrantTarget = "sequence::app.t.id".parse().unwrap();
            let unrevocable = tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap()
                .block_on(async {
                    let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, &login)
                        .await
                        .unwrap();
                    pbps_pg::catalog::introspect(&mut conn)
                        .await
                        .unwrap()
                        .unrevocable
                });
            assert!(
                unrevocable.iter().any(|g| g.role.raw() == reader
                    && g.target == target
                    && g.permission == pbps_model::Permission::Usage),
                "{unrevocable:?}"
            );
            let diagnose = || {
                let output = d.run_with_env(
                    &["doctor", "--format", "json"],
                    &[("PBPS_FLOW_PG_DEV", login.as_str())],
                );
                let json: serde_json::Value = serde_json::from_str(&stdout(&output)).unwrap();
                (output, json)
            };
            let (diagnosis, json) = diagnose();
            let plan = d.dir.join("plan.json");
            let planning = ["plan", "--db", &login, "--out", plan.to_str().unwrap()];
            let refused = d.run(&planning);
            assert_eq!(
                code(&refused),
                1,
                "{}{}",
                stdout(&refused),
                stderr(&refused)
            );
            let why = stderr(&refused);
            for needle in ["unrevocable_grants", "app.custom2249", grantor.as_str()] {
                assert!(why.contains(needle), "{needle}: {why}");
            }
            assert!(!plan.exists(), "a refused plan must not be saved");
            eprintln!("PG {version}: plan refuses the original-grantor ACL on sequence::app.t.id");
            let gap = "USAGE WITH GRANT OPTION on SEQUENCE owned by app.t.id";
            assert_eq!(code(&diagnosis), 2, "PG {version}: {json}");
            let gaps = json["data"]["environments"][0]["missing_permissions"]
                .as_array()
                .unwrap();
            assert!(
                gaps.iter().any(|g| {
                    let g = g.as_str().unwrap();
                    g.starts_with(gap) && g.contains(&grantor)
                }),
                "PG {version}: {json}"
            );
            eprintln!("PG {version}: doctor reports the same owning-column authority gap");

            // Only the original grantor changes. The owner's otherwise
            // identical ACL is revocable and must produce no doctor gap.
            on_server(
                connection,
                &format!(
                    "SET ROLE {grantor}; REVOKE USAGE ON SEQUENCE app.custom2249 FROM {reader}; RESET ROLE"
                ),
            );
            on_server(
                &login,
                &format!("GRANT USAGE ON SEQUENCE app.custom2249 TO {reader}"),
            );
            let (_, json) = diagnose();
            let gaps = json["data"]["environments"][0]["missing_permissions"]
                .as_array()
                .unwrap();
            assert!(gaps.is_empty(), "PG {version}: {json}");
            assert_ne!(
                json["data"]["environments"][0]["permissions_unknown"], true,
                "{json}"
            );
            succeeds(d.run(&planning));
            let saved: pbps_model::SavedPlan =
                serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
            assert!(saved.changes.changes.iter().any(|p| matches!(&p.change,
                pbps_model::Change::Revoke { role, target: found, permissions }
                    if role.raw() == reader && found == &target && permissions.contains(&pbps_model::Permission::Usage)
            )), "{:?}", saved.changes);
            eprintln!(
                "PG {version}: the revocable control has no gap and plans the same sequence target"
            );
        });
        if result.is_err() {
            failed_versions.push(version);
        }
    }
    assert!(
        failed_versions.is_empty(),
        "failed PostgreSQL versions: {failed_versions:?}"
    );
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn arriving_overloads_rebind_unchanged_callers_in_the_approved_plan() {
    let server = server();
    let own = OwnDatabase::new(&server, "overload-rebind");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("overload-rebind");
    std::fs::write(d.dir.join("schema/f-bigint.yml"),
        "function: app.f(bigint)\ndefinition: (n bigint) RETURNS text LANGUAGE sql AS $$ SELECT 'old' $$\n").unwrap();
    std::fs::write(d.dir.join("schema/caller.yml"),
        "function: app.caller()\ndefinition: () RETURNS text LANGUAGE sql BEGIN ATOMIC SELECT f(1); END\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    on_server(
        connection,
        "DO $$ BEGIN IF app.caller() <> 'old' THEN RAISE EXCEPTION 'wrong initial binding'; END IF; END $$",
    );

    std::fs::write(d.dir.join("schema/f-integer.yml"),
        "function: app.f(integer)\ndefinition: (n integer) RETURNS text LANGUAGE sql AS $$ SELECT 'new' $$\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let planning = ["plan", "--db", connection, "--out", plan.to_str().unwrap()];
    succeeds(d.run(&planning));
    // Run the real plan before inspecting its shape: an omitted rebuild must
    // fail on the engine's observed binding, not merely a mirrored assertion.
    //
    // `--allow revoke` because the synthesized rebuild of `app.caller()` is a
    // drop and a create on this engine, and the create restores the default
    // `EXECUTE` to `PUBLIC` that the plan then takes away again (issue #318):
    // the routine was there before, so the gate is asked.
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "revoke"],
    ));
    on_server(
        connection,
        "DO $$ BEGIN IF app.caller() <> 'new' THEN RAISE EXCEPTION 'successful apply retained the old overload binding'; END IF; END $$",
    );
    let saved: pbps_model::SavedPlan =
        serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    let rebuilt: Vec<_> = saved
        .changes
        .changes
        .iter()
        .filter_map(|p| {
            if let pbps_model::Change::AlterModule { id, .. } = &p.change {
                Some(id.raw().to_string())
            } else {
                None
            }
        })
        .collect();
    assert_eq!(rebuilt, ["app.caller()"]);
    succeeds(d.run(&["verify", "--db", connection]));
    let next = succeeds(d.run(&planning));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // A second new signature still reaches the ordinary carried-state guard.
    // The scanner is intentionally conservative about overload applicability.
    std::fs::write(d.dir.join("schema/f-smallint.yml"),
        "function: app.f(smallint)\ndefinition: (n smallint) RETURNS text LANGUAGE sql AS $$ SELECT 'small' $$\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    on_server(connection, "COMMENT ON FUNCTION app.caller() IS 'keep me'");
    let refused = d.run(&planning);
    assert_eq!(
        code(&refused),
        1,
        "{}{}",
        stdout(&refused),
        stderr(&refused)
    );
    assert!(stderr(&refused).contains("comment"), "{}", stderr(&refused));
    on_server(connection, "COMMENT ON FUNCTION app.caller() IS NULL");
    succeeds(d.run(&planning));
    let staged = d.run(&[
        "plan",
        "--db",
        connection,
        "--staged",
        "--out",
        plan.to_str().unwrap(),
    ]);
    assert_eq!(code(&staged), 1, "{}{}", stdout(&staged), stderr(&staged));
    assert!(
        stderr(&staged).contains("require a transaction"),
        "{}",
        stderr(&staged)
    );
    on_server(
        connection,
        "COMMENT ON FUNCTION app.caller() IS 'arrived after planning'",
    );
    // Approved, so that the refusal under test is the comment and not the
    // rebuild's own `revoke` risk (issue #318) — an unapproved plan stops at
    // the gate before it ever asks the catalog.
    let refused = approved_apply(&d, connection, &plan, &["--allow", "revoke"]);
    assert_eq!(
        code(&refused),
        1,
        "{}{}",
        stdout(&refused),
        stderr(&refused)
    );
    assert!(stderr(&refused).contains("comment"), "{}", stderr(&refused));
    on_server(
        connection,
        "DO $$ BEGIN IF to_regprocedure('app.f(smallint)') IS NOT NULL OR app.caller() <> 'new' THEN RAISE EXCEPTION 'refused rebuild changed the database'; END IF; END $$",
    );
}

fn omission_policy(d: &Demo, policy: &str) {
    std::fs::write(
        d.dir.join("pbps.yml"),
        format!("dialect: postgres\nunmanaged: {policy}\nenvironments:\n  dev:\n    url_env: PBPS_OMISSION_DB\n"),
    )
    .unwrap();
    d.commit();
}

fn omission_report(d: &Demo, connection: &str, command: &str) -> serde_json::Value {
    let args = if command == "verify" {
        vec!["verify", "--db", connection, "--format", "json"]
    } else {
        vec!["status", "--format", "json"]
    };
    let result = d.run_with_env(&args, &[("PBPS_OMISSION_DB", connection)]);
    let report: serde_json::Value = serde_json::from_str(&stdout(&result)).unwrap();
    assert_eq!(
        code(&result),
        if command == "verify" { 2 } else { 0 },
        "{report}: {}",
        stderr(&result)
    );
    if command == "verify" {
        let facts = report["findings"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|f| f["id"] == "state.drift-unexpressible")
            .collect::<Vec<_>>();
        assert_eq!(facts.len(), 1, "{report}");
        let remedy = facts[0]["remedy"]
            .as_str()
            .expect("existing optional remedy");
        for command in [
            "`pbps pull`",
            "`pbps plan --db`",
            "`pbps baseline --reason …`",
        ] {
            assert!(remedy.contains(command), "{report}");
        }
        assert!(
            facts[0]["message"]
                .as_str()
                .unwrap()
                .contains("which this model does not hold"),
            "{report}"
        );
    } else {
        let row = &report["data"][0];
        assert_eq!(row["state"], "drift", "{report}");
        let detail = row["detail"].as_str().unwrap();
        assert!(
            detail.contains("1 fact(s) inside the managed set"),
            "{report}"
        );
        let managed = detail
            .split(" — ")
            .find(|part| part.contains("fact(s) inside the managed set"))
            .unwrap();
        assert_eq!(
            managed.matches("which this model does not hold").count(),
            1,
            "{report}"
        );
    }
    report
}

fn omitted_state_cannot_be_recorded(d: &Demo, connection: &str) {
    // Ignore unrelated cluster roles here so only the managed omission can
    // explain the refusal. No command may replace the previous good snapshot.
    omission_policy(d, "ignore");
    let before = scalar(connection, "SELECT count(*) FROM public.__pbps_state");
    for args in [
        vec!["plan", "--db", connection],
        vec![
            "baseline",
            "--db",
            connection,
            "--reason",
            "must refuse omission",
        ],
        vec!["snapshot", "--db", connection, "--force"],
    ] {
        let result = d.run(&args);
        assert_eq!(code(&result), 1, "{}{}", stdout(&result), stderr(&result));
        assert!(
            stderr(&result).contains("1 fact(s) inside the managed set cannot be represented"),
            "{}",
            stderr(&result)
        );
        assert_eq!(
            scalar(connection, "SELECT count(*) FROM public.__pbps_state"),
            before
        );
    }
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn managed_omission_reports_each_catalog_fact_once_and_keeps_recording_refusals() {
    let own = OwnDatabase::new(&server(), "omission-facts");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("omission-facts");
    d.table(ONE_COLUMN);
    std::fs::write(d.dir.join("schema/f.yml"), "function: app.f(integer)\ndefinition: (n integer) RETURNS integer LANGUAGE sql AS $$ SELECT n $$\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    succeeds(d.run(&["verify", "--db", connection]));
    on_server(
        connection,
        "DROP FUNCTION app.f(integer); CREATE AGGREGATE app.f(integer) (SFUNC = int4pl, STYPE = integer, INITCOND = '0')",
    );
    for policy in ["warn", "error"] {
        omission_policy(&d, policy);
        for command in ["verify", "status"] {
            let report = omission_report(&d, connection, command);
            assert!(
                !report.to_string().contains("aggregate app.f(integer) ("),
                "{report}"
            );
        }
    }
    omitted_state_cannot_be_recorded(&d, connection);
    on_server(
        connection,
        "DROP AGGREGATE app.f(integer); CREATE FUNCTION app.f(n integer) RETURNS integer LANGUAGE sql AS $$ SELECT n $$",
    );
    succeeds(d.run(&["verify", "--db", connection]));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn managed_omission_relations_stay_out_of_unmanaged_policy_with_absent_tables() {
    let own = OwnDatabase::new(&server(), "omission-relations");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("omission-relations");
    d.table(ONE_COLUMN);
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    succeeds(d.run(&["verify", "--db", connection]));
    on_server(
        connection,
        "DROP TABLE app.t; CREATE MATERIALIZED VIEW app.t AS SELECT 1::bigint AS id",
    );
    for has_unmanaged in [false, true] {
        if has_unmanaged {
            on_server(
                connection,
                "CREATE MATERIALIZED VIEW app.other AS SELECT 1 AS id; CREATE AGGREGATE app.t(integer) (SFUNC = int4pl, STYPE = integer, INITCOND = '0')",
            );
        }
        for policy in ["warn", "error"] {
            omission_policy(&d, policy);
            for command in ["verify", "status"] {
                let report = omission_report(&d, connection, command);
                let rendered = report.to_string();
                assert!(!rendered.contains("materialized view app.t ("), "{report}");
                // Table identity must not hide an unrelated relation or the
                // same-named routine, even when their kind is also omitted.
                for name in [
                    "materialized view app.other (",
                    "aggregate app.t(integer) (",
                ] {
                    assert_eq!(rendered.contains(name), has_unmanaged, "{report}");
                }
            }
        }
    }
    omitted_state_cannot_be_recorded(&d, connection);
    on_server(
        connection,
        "DROP MATERIALIZED VIEW app.t; DROP MATERIALIZED VIEW app.other; DROP AGGREGATE app.t(integer); CREATE TABLE app.t (id bigint NOT NULL, CONSTRAINT pk_t PRIMARY KEY (id))",
    );
    succeeds(d.run(&["verify", "--db", connection]));
}

/// A plan approved on 16 and carried to 18 with its database is refused on
/// 18, before any of its DDL runs (issue #571). 18 reads `json_scalar` as a
/// keyword: the view keeps its old binding through a dump and restore, but its
/// canonical text gains quotes, so the restored database no longer matches the
/// recorded baseline (SPEC §§7.3 and 8.2). Planned again there, the bare
/// declaration would bind to the SQL/JSON constructor instead, which is why
/// the refusal matters. A dump and restore rather than `pg_upgrade`: the test
/// needs the old server's own ledger rows and parsed view on the new server,
/// and both servers' clients are already in their containers.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB, PBPS_TEST_PG_OLD_DB, PBPS_TEST_PG_CONTAINER and PBPS_TEST_PG_OLD_CONTAINER"]
fn a_plan_saved_before_a_grammar_upgrade_is_refused_after_the_transfer() {
    use std::io::Write;
    use std::process::Stdio;

    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    let old_container =
        std::env::var("PBPS_TEST_PG_OLD_CONTAINER").expect("PBPS_TEST_PG_OLD_CONTAINER");
    let new_container = std::env::var("PBPS_TEST_PG_CONTAINER").expect("PBPS_TEST_PG_CONTAINER");
    let new_server = server();
    on_server(
        &old_server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'needs pre-17'; END IF; END $$",
    );
    on_server(
        &new_server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer < 170000 THEN RAISE EXCEPTION 'needs 17+'; END IF; END $$",
    );
    let old = OwnDatabase::new(&old_server, "grammar_upgrade");
    let new = OwnDatabase::new(&new_server, "grammar_upgrade");
    on_server(old.connection(), "CREATE SCHEMA app");
    let d = Demo::new("grammar-upgrade");
    std::fs::write(
        d.dir.join("schema/scalar-bigint.yml"),
        "function: app.json_scalar(bigint)\n\
         definition: (n bigint) RETURNS integer LANGUAGE sql AS $$ SELECT 42 $$\n",
    )
    .unwrap();
    std::fs::write(
        d.dir.join("schema/v.yml"),
        "view: app.v\ndefinition: SELECT json_scalar(7) AS value\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", old.connection()]));
    succeeds(d.run(&["verify", "--db", old.connection()]));
    let value = "SELECT value::bigint FROM app.v";
    assert_eq!(scalar(old.connection(), value), 42);

    // The arriving overload is the only edit; the view's rebuild is the one
    // the planner adds for an unchanged caller (DECISIONS 420).
    std::fs::write(
        d.dir.join("schema/scalar-integer.yml"),
        "function: app.json_scalar(integer)\n\
         definition: (n integer) RETURNS integer LANGUAGE sql AS $$ SELECT 99 $$\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        old.connection(),
        "--out",
        plan.to_str().unwrap(),
    ]));
    let saved: pbps_model::SavedPlan =
        serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    let modules: Vec<_> = saved
        .changes
        .changes
        .iter()
        .filter_map(|p| {
            if let pbps_model::Change::CreateModule { id, .. } = &p.change {
                Some(format!("create {id}", id = id.shown()))
            } else if let pbps_model::Change::AlterModule { id, .. } = &p.change {
                Some(format!("alter {id}", id = id.shown()))
            } else {
                None
            }
        })
        .collect();
    assert_eq!(modules, ["create app.json_scalar(integer)", "alter app.v"]);
    succeeds(d.run(&["verify", "--db", old.connection()]));
    // No staged artifact can carry the rebuild at all.
    let staged = d.run(&["plan", "--db", old.connection(), "--staged"]);
    assert_eq!(code(&staged), 1, "{}{}", stdout(&staged), stderr(&staged));
    assert!(
        stderr(&staged).contains("require a transaction"),
        "{}",
        stderr(&staged)
    );

    // Schema, ledger, ownership and ACLs, as the old server's own client
    // writes them; nothing is recorded again on the new server.
    let dump = Command::new("docker")
        .args([
            "exec",
            &old_container,
            "pg_dump",
            "-U",
            "postgres",
            "-d",
            &old.name,
        ])
        .output()
        .unwrap();
    assert!(
        dump.status.success(),
        "{}",
        String::from_utf8_lossy(&dump.stderr)
    );
    let mut restore = Command::new("docker")
        .args([
            "exec",
            "-i",
            &new_container,
            "psql",
            "-U",
            "postgres",
            "-d",
            &new.name,
        ])
        .args(["-X", "-q", "--set=ON_ERROR_STOP=1"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    // Fed from a thread while `wait_with_output` reads, so psql's own output
    // cannot fill a pipe nobody is reading yet (#1485).
    let mut stdin = restore.stdin.take().unwrap();
    let dumped = dump.stdout.clone();
    let feeder = std::thread::spawn(move || stdin.write_all(&dumped));
    let restored = restore.wait_with_output().unwrap();
    fed(feeder.join().unwrap());
    assert!(
        restored.status.success(),
        "{}",
        String::from_utf8_lossy(&restored.stderr)
    );
    let definition = "SELECT pg_get_viewdef('app.v'::regclass)";
    assert_eq!(
        text_of(new.connection(), definition),
        " SELECT app.\"json_scalar\"((7)::bigint) AS value;"
    );
    let unchanged = || {
        assert_eq!(
            scalar(new.connection(), value),
            42,
            "the old binding was lost"
        );
        assert_eq!(
            scalar(
                new.connection(),
                "SELECT count(*) FROM pg_proc WHERE proname = 'json_scalar' \
                 AND pronamespace = 'app'::regnamespace"
            ),
            1,
            "the arriving overload was created"
        );
    };
    unchanged();

    // The only difference is the view's restated text.
    let drift = |o: Output| {
        assert_eq!(code(&o), 2, "{}{}", stdout(&o), stderr(&o));
        let report = json_output(o);
        let changes = report["data"]["changes"]["changes"].as_array().unwrap();
        assert_eq!(changes.len(), 1, "{report}");
        assert_eq!(changes[0]["op"], "alter_module", "{report}");
        assert_eq!(changes[0]["id"], "app.v", "{report}");
        report["data"]["live_checksum"].clone()
    };
    let before = drift(d.run(&["verify", "--db", new.connection(), "--format", "json"]));

    let refused = approved_apply(&d, new.connection(), &plan, &[]);
    assert_eq!(
        code(&refused),
        1,
        "{}{}",
        stdout(&refused),
        stderr(&refused)
    );
    assert!(
        stderr(&refused).contains("is no longer the database this plan was computed against"),
        "{}",
        stderr(&refused)
    );
    unchanged();
    let refused = approved_apply(&d, new.connection(), &plan, &["--staged"]);
    assert_eq!(
        code(&refused),
        1,
        "{}{}",
        stdout(&refused),
        stderr(&refused)
    );
    assert!(
        stderr(&refused).contains("is a transactional plan and `--staged` was given"),
        "{}",
        stderr(&refused)
    );
    unchanged();
    let after = drift(d.run(&["verify", "--db", new.connection(), "--format", "json"]));
    assert_eq!(before, after, "a refused apply changed the schema");

    // The same artifact still applies where it was planned, so the refusal
    // above is the transfer's and not the artifact's.
    succeeds(approved_apply(&d, old.connection(), &plan, &[]));
    assert_eq!(scalar(old.connection(), value), 99);

    // And what the bare declaration means on 18.
    let fresh = OwnDatabase::new(&new_server, "grammar_fresh");
    on_server(
        fresh.connection(),
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.json_scalar(bigint) RETURNS integer LANGUAGE sql AS 'SELECT 42'; \
         SET search_path = app; \
         CREATE VIEW app.v AS SELECT json_scalar(7) AS value",
    );
    assert_eq!(
        text_of(
            fresh.connection(),
            "SELECT pg_typeof(value)::text || ' ' || value::text FROM app.v"
        ),
        "json 7"
    );
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn unrelated_routine_limitations_do_not_refuse_a_managed_table_or_overload() {
    let own = OwnDatabase::new(&server(), "limitation-scope");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("limitation-scope");
    d.table(ONE_COLUMN);
    std::fs::write(d.dir.join("schema/f.yml"), "function: app.t(integer)\ndefinition: (n integer) RETURNS integer LANGUAGE sql AS $$ SELECT n $$\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    on_server(
        connection,
        "CREATE AGGREGATE app.t(bigint) (SFUNC = int8pl, STYPE = bigint, INITCOND = '0')",
    );
    succeeds(d.run(&["plan", "--db", connection]));
    succeeds(d.run(&["snapshot", "--db", connection, "--force"]));
    succeeds(d.run(&[
        "baseline",
        "--db",
        connection,
        "--reason",
        "accept managed state",
    ]));
    succeeds(d.run(&["verify", "--db", connection]));

    // A real table limitation still refuses the same managed scope. RLS is
    // adopted now; an INSERT rewrite rule remains unrepresentable.
    on_server(
        connection,
        "CREATE RULE swallow_insert AS ON INSERT TO app.t DO INSTEAD NOTHING",
    );
    let refused = d.run(&["plan", "--db", connection]);
    assert_ne!(code(&refused), 0);
    assert!(
        stderr(&refused).contains("rewrite rules"),
        "{}",
        stderr(&refused)
    );
    on_server(connection, "DROP RULE swallow_insert ON app.t");

    // The exact managed signature becoming unsupported is also a limitation.
    on_server(
        connection,
        "DROP FUNCTION app.t(integer); CREATE AGGREGATE app.t(integer) (SFUNC = int4pl, STYPE = integer, INITCOND = '0')",
    );
    let refused = d.run(&["baseline", "--db", connection, "--reason", "must refuse"]);
    assert_ne!(code(&refused), 0);
    assert!(
        stderr(&refused).contains("aggregate"),
        "{}",
        stderr(&refused)
    );
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn omitted_modules_obey_unmanaged_policy_even_beside_a_managed_overload() {
    struct Role(String, String);
    impl Drop for Role {
        fn drop(&mut self) {
            let _ = try_on_server(&self.0, &format!("DROP ROLE IF EXISTS {}", self.1));
        }
    }
    let assert_omitted_modules = |result: &Output, present: bool| {
        let message = stderr(result);
        for object in ["aggregate app.t(bigint)", "view app.bad(int)"] {
            assert_eq!(message.contains(object), present, "{message}");
        }
        assert!(!message.contains("function app.t(integer)"), "{message}");
        // An unrelated cluster role may independently refuse the plan, but
        // connection, snapshot, or planning errors must never count as clean.
        if message.contains("`unmanaged: error`") {
            assert_ne!(code(result), 0, "{message}");
        } else {
            assert_eq!(code(result), 0, "{message}");
        }
    };
    let own = OwnDatabase::new(&server(), "unmanaged-modules");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("unmanaged-modules");
    d.table(ONE_COLUMN);
    std::fs::write(d.dir.join("schema/f.yml"), "function: app.t(integer)\ndefinition: (n integer) RETURNS integer LANGUAGE sql AS $$ SELECT n $$\n").unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    // Roles are cluster-wide, so compare only this test's objects rather than
    // assuming an own database means a stable unmanaged inventory.
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nunmanaged: error\n",
    )
    .unwrap();
    d.commit();
    let control = d.run(&["plan", "--db", connection]);
    assert_omitted_modules(&control, false);
    let role = Role(
        connection.to_owned(),
        format!("pbps_unmanaged_churn_{}", std::process::id()),
    );
    on_server(connection, &format!("CREATE ROLE {}", role.1));

    on_server(
        connection,
        "CREATE AGGREGATE app.t(bigint) (SFUNC = int8pl, STYPE = bigint, INITCOND = '0'); CREATE VIEW app.\"bad(int)\" AS SELECT id FROM app.t",
    );

    for policy in ["ignore", "warn", "error"] {
        std::fs::write(
            d.dir.join("pbps.yml"),
            format!("dialect: postgres\nunmanaged: {policy}\n"),
        )
        .unwrap();
        d.commit();
        let result = d.run(&["plan", "--db", connection]);
        if policy == "error" {
            assert_omitted_modules(&result, true);
            assert_ne!(code(&result), 0, "{}", stdout(&result));
            let message = stderr(&result);
            assert!(message.contains("`unmanaged: error`"), "{message}");
            assert!(message.contains("aggregate app.t(bigint)"), "{message}");
            assert!(message.contains("view app.bad(int)"), "{message}");
            let verified = d.run(&["verify", "--db", connection, "--format", "json"]);
            let report: serde_json::Value = serde_json::from_str(&stdout(&verified)).unwrap();
            assert_eq!(code(&verified), 2, "{report}: {}", stderr(&verified));
            assert!(
                report["findings"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|finding| {
                        finding["id"] == "state.unmanaged-refused"
                            && finding["message"].as_str().is_some_and(|message| {
                                message.contains("aggregate app.t(bigint)")
                                    && message.contains("view app.bad(int)")
                            })
                    }),
                "{report}"
            );
        } else {
            let message = stderr(&result);
            assert_eq!(
                message.contains("are not declared and are left alone"),
                policy == "warn",
                "{message}"
            );
            succeeds(result);
        }
    }
    // Removing only our omitted modules restores the original policy answer;
    // the same-name managed function must not become an unmanaged object.
    on_server(
        connection,
        "DROP AGGREGATE app.t(bigint); DROP VIEW app.\"bad(int)\"",
    );
    let restored = d.run(&["plan", "--db", connection]);
    assert!(stderr(&restored).contains(&role.1), "{}", stderr(&restored));
    assert_omitted_modules(&restored, false);
    let role_name = role.1.clone();
    drop(role);
    let after_role_drop = d.run(&["plan", "--db", connection]);
    assert!(
        !stderr(&after_role_drop).contains(&role_name),
        "{}",
        stderr(&after_role_drop)
    );
    assert_omitted_modules(&after_role_drop, false);
}

/// #1723: each relation-namespace occupant follows its table through the
/// plan's renames in the plan's order. `s2.b` moves to `s3.c` and its
/// index `n_ix` is rebuilt there, then `s1.a`, with an `n_ix` of its own,
/// moves to `s2.b`. Each table's index goes where its table goes, so the
/// rebuilt index's name in `s3` is free, and the plan applies.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_index_follows_its_table_through_a_chain_of_moves() {
    let own = OwnDatabase::new(&server(), "chain1723");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA s1; CREATE SCHEMA s2; CREATE SCHEMA s3",
    );
    let d = Demo::new("chain1723");
    let declare = |name: &str, body: Option<&str>| {
        let path = d.dir.join(format!("schema/{name}.yml"));
        match body {
            Some(body) => std::fs::write(path, format!("table: {name}\n{body}")).unwrap(),
            None => std::fs::remove_file(path).unwrap(),
        }
    };
    let table = |key: &str, column: &str, index: &str| {
        format!(
            "columns:\n  id: {{type: bigint, nullable: false}}\n  {column}: {{type: bigint}}\n\
             primary_key: {{name: {key}, columns: [id]}}\n\
             indexes:\n  n_ix: {{columns: [{index}]}}\n"
        )
    };
    let step = |d: &Demo| {
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    declare("s1.a", Some(&table("pk_a", "v", "v")));
    declare("s2.b", Some(&table("pk_b", "w", "w")));
    step(&d);
    succeeds(d.run(&["bootstrap", "--db", connection]));

    declare("s2.b", None);
    declare("s3.c", Some(&table("pk_b", "w", "w, id")));
    succeeds(d.run(&["rename-table", "s2.b", "s3.c"]));
    step(&d);
    declare("s1.a", None);
    declare("s2.b", Some(&table("pk_a", "v", "v")));
    succeeds(d.run(&["rename-table", "s1.a", "s2.b"]));
    step(&d);

    let plan = d.dir.join("plan.json");
    let o = d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]);
    assert_eq!(code(&o), 0, "{}", stderr(&o));
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename", "--allow", "destructive"],
    ));
    let at = |schema: &str| {
        scalar(
            connection,
            &format!(
                "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace \
                 WHERE c.relname = 'n_ix' AND n.nspname = '{schema}'"
            ),
        )
    };
    assert_eq!((at("s1"), at("s2"), at("s3")), (0, 1, 1));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// #1738: a constraint trigger's `pg_constraint` row holds `n_pkey`, and the
/// plan drops the trigger before it creates `app.n`, whose unnamed key then
/// takes `n_pkey` (measured on 16 and 18). A default of `app.n` naming
/// `app.n_pkey` names the key's index before it exists: the plan is refused,
/// writing no artifact. Without that default it applies, and the key's
/// index is `n_pkey`.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_dropped_constraint_trigger_frees_its_name_for_a_key() {
    let own = OwnDatabase::new(&server(), "trigger_holder");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer PRIMARY KEY); \
         CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$; \
         CREATE CONSTRAINT TRIGGER n_pkey AFTER INSERT ON app.t \
             FOR EACH ROW EXECUTE FUNCTION app.f()",
    );
    let d = Demo::new("trigger-holder");
    succeeds(d.run(&["pull", "--db", connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
    let trigger = std::fs::read_dir(d.dir.join("schema"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| {
            std::fs::read_to_string(p)
                .unwrap()
                .lines()
                .any(|l| l.starts_with("trigger:") && l.contains("n_pkey"))
        })
        .expect("the constraint trigger is pulled");
    std::fs::remove_file(trigger).unwrap();
    let new_table = |default: &str| {
        format!(
            "table: app.n\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
             label: {{type: text, default: \"{default}\"}}\nprimary_key: [id]\n"
        )
    };
    let declared = d.dir.join("schema/app.n.yml");
    std::fs::write(&declared, new_table("('app.n_pkey'::regclass)::text")).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let artifact = d.dir.join("refused-plan.json");
    let out = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&out), 0, "{}", stdout(&out));
    assert!(
        stderr(&out).contains("names app.n_pkey"),
        "{}",
        stderr(&out)
    );
    assert!(!artifact.exists(), "a refused plan writes no artifact");

    std::fs::write(&declared, new_table("''")).unwrap();
    let plan = connected_artifact(&d, connection, false);
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "destructive"],
    ));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_index WHERE indisprimary \
             AND indexrelid = 'app.n_pkey'::regclass"
        ),
        1
    );
}

/// #2101: the key's schema sees the clone, independently of its parent's schema.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn constraint_trigger_clones_predict_the_key_name_after_a_drop_or_attach() {
    for attach in [false, true] {
        let slug = format!("clone-key-2101-{attach}");
        let own = OwnDatabase::new(&server(), &slug);
        let connection = own.connection();
        on_server(connection, &format!(
            "CREATE SCHEMA app; CREATE SCHEMA parts;
             CREATE TABLE app.p(id integer) PARTITION BY RANGE(id);
             CREATE TABLE parts.n(id integer NOT NULL, label text);
             CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;
             CREATE CONSTRAINT TRIGGER n_pkey AFTER INSERT ON app.p FOR EACH ROW EXECUTE FUNCTION app.f();
             {}",
            if attach { "CREATE TABLE parts.p1(id integer)" }
            else { "CREATE TABLE parts.p1 PARTITION OF app.p FOR VALUES FROM (0) TO (10)" }
        ));
        let d = Demo::new(&slug);
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        if attach {
            std::fs::remove_file(d.dir.join("schema/parts.p1.yml")).unwrap();
            std::fs::write(d.dir.join("schema/app.p.yml"),
                "table: app.p\ncolumns:\n  id: {type: integer}\npartition_by: [id]\npartitions:\n  parts.p1: {from: ['0'], to: ['10']}\n").unwrap();
        } else {
            std::fs::remove_file(d.dir.join("schema/app.p%2En_pkey.trigger.yml")).unwrap();
        }
        let expected = if attach { "n_pkey1" } else { "n_pkey" };
        let table = |expression: &str| {
            format!(
                "table: parts.n\ncolumns:\n  id: {{type: integer, nullable: false}}\n  label: {{type: text, default: \"{expression}\"}}\nprimary_key: [id]\n"
            )
        };
        let path = d.dir.join("schema/parts.n.yml");
        std::fs::write(
            &path,
            table(&format!("('parts.{expected}'::regclass)::text")),
        )
        .unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
        let refused = d.dir.join("refused.json");
        let output = d.run(&[
            "plan",
            "--db",
            connection,
            "--out",
            refused.to_str().unwrap(),
        ]);
        assert_ne!(code(&output), 0, "{}", stdout(&output));
        assert!(
            stderr(&output).contains(&format!("names parts.{expected}")),
            "{}",
            stderr(&output)
        );
        assert!(!refused.exists());
        std::fs::write(&path, table("''")).unwrap();
        let plan = connected_artifact(&d, connection, false);
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "destructive,constraint"],
        ));
        assert_eq!(
            text_of(
                connection,
                "SELECT c.relname::text FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid='parts.n'::regclass AND i.indisprimary"
            ),
            expected
        );
        succeeds(d.run(&["verify", "--db", connection]));
    }
}

/// #2276: unmanaged parent triggers still produce schema-wide key-name holders.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn unmanaged_constraint_trigger_clones_predict_the_later_key_name_on_both_servers() {
    for (version, server) in [(16, old_server()), (18, server())] {
        for constraint in [true, false] {
            for attach in [true, false] {
                let slug = format!("unmanaged-clone-2276-{version}-{constraint}-{attach}");
                let own = OwnDatabase::new(&server, &slug);
                let connection = own.connection();
                on_server(connection, &format!(
                    "CREATE SCHEMA app; CREATE SCHEMA parts;
                     CREATE TABLE app.p(id integer) PARTITION BY RANGE(id);
                     CREATE TABLE parts.n(id integer NOT NULL, label text);
                     CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;
                     {}",
                    if attach { "CREATE TABLE parts.p1(id integer)" } else { "" }
                ));
                let d = Demo::new(&slug);
                std::fs::write(
                    d.dir.join("pbps.yml"),
                    "dialect: postgres\nunmanaged: ignore\n",
                )
                .unwrap();
                succeeds(d.run(&["pull", "--db", connection]));
                d.commit();
                succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
                // Install after recording the baseline, so neither declared
                // snapshot contains the producer that the catalog must supply.
                on_server(connection, &format!(
                    "CREATE {}TRIGGER old_name AFTER INSERT ON app.p FOR EACH ROW EXECUTE FUNCTION app.f();
                     ALTER TRIGGER old_name ON app.p RENAME TO n_pkey",
                    if constraint { "CONSTRAINT " } else { "" }
                ));
                let statement_constraint = try_on_server(connection,
                    "CREATE CONSTRAINT TRIGGER impossible AFTER INSERT ON app.p FOR EACH STATEMENT EXECUTE FUNCTION app.f()"
                ).unwrap_err();
                assert!(
                    statement_constraint.contains("syntax error"),
                    "{statement_constraint}"
                );
                if attach {
                    std::fs::remove_file(d.dir.join("schema/parts.p1.yml")).unwrap();
                }
                std::fs::write(d.dir.join("schema/app.p.yml"),
                    "table: app.p\ncolumns:\n  id: {type: integer}\npartition_by: [id]\npartitions:\n  parts.p1: {from: ['0'], to: ['10']}\n"
                ).unwrap();
                let expected = if constraint { "n_pkey1" } else { "n_pkey" };
                let table = |expression: &str| {
                    format!(
                        "table: parts.n\ncolumns:\n  id: {{type: integer, nullable: false}}\n  label: {{type: text, default: \"{expression}\"}}\nprimary_key: [id]\n"
                    )
                };
                let path = d.dir.join("schema/parts.n.yml");
                std::fs::write(
                    &path,
                    table(&format!("('parts.{expected}'::regclass)::text")),
                )
                .unwrap();
                succeeds(d.run(&["plan"]));
                d.commit();
                let refused = d.dir.join("refused.json");
                let output = d.run(&[
                    "plan",
                    "--db",
                    connection,
                    "--out",
                    refused.to_str().unwrap(),
                ]);
                assert_ne!(code(&output), 0, "{}{}", stdout(&output), stderr(&output));
                assert!(
                    stderr(&output).contains(&format!("names parts.{expected}")),
                    "{}",
                    stderr(&output)
                );
                assert!(!refused.exists());
                // The reference resolves before the key exists. Removing it
                // lets apply measure the name independently of the prediction.
                std::fs::write(&path, table("''")).unwrap();
                let plan = connected_artifact(&d, connection, false);
                succeeds(approved_apply(
                    &d,
                    connection,
                    &plan,
                    &["--allow", "destructive,constraint"],
                ));
                assert_eq!(
                    text_of(
                        connection,
                        "SELECT c.relname::text FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid='parts.n'::regclass AND i.indisprimary"
                    ),
                    expected
                );
                assert_eq!(scalar(connection,
                    "SELECT count(*) FROM pg_trigger clone JOIN pg_trigger parent ON parent.oid=clone.tgparentid
                     WHERE clone.tgrelid='parts.p1'::regclass AND parent.tgrelid='app.p'::regclass
                       AND clone.tgname='n_pkey' AND (clone.tgtype & 1) <> 0"
                ), 1);
                assert_eq!(scalar(connection,
                    "SELECT count(*) FROM pg_trigger clone JOIN pg_constraint con ON con.oid=clone.tgconstraint
                     WHERE clone.tgrelid='parts.p1'::regclass AND clone.tgname='n_pkey'
                       AND con.conname='n_pkey' AND con.conparentid=0 AND clone.tgparentid<>0"
                ), i64::from(constraint));
                println!(
                    "PostgreSQL {}: constraint={constraint}, attach={attach}, key={expected}; row clone verified",
                    text_of(connection, "SHOW server_version")
                );
                succeeds(d.run(&["verify", "--db", connection]));
            }
        }
    }
}

/// #2102: pre-flight must reserve future clones before the attach's first statement.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_attach_refuses_unmanaged_names_of_planned_parent_row_triggers() {
    for row in [true, false] {
        for rebuilt in [true, false] {
            let slug = format!("attach-trigger-2102-{row}-{rebuilt}");
            let own = OwnDatabase::new(&server(), &slug);
            let connection = own.connection();
            on_server(connection,
                "CREATE SCHEMA app; CREATE TABLE app.p(id integer) PARTITION BY RANGE(id);
                 CREATE TABLE app.p1(id integer);
                 CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;");
            if rebuilt {
                on_server(
                    connection,
                    &format!(
                        "CREATE TRIGGER x AFTER INSERT ON app.p FOR EACH {} EXECUTE FUNCTION app.f()",
                        if row { "ROW" } else { "STATEMENT" }
                    ),
                );
            }
            let d = Demo::new(&slug);
            succeeds(d.run(&["pull", "--db", connection]));
            d.commit();
            succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
            on_server(
                connection,
                "CREATE TRIGGER x AFTER INSERT ON app.p1 FOR EACH ROW EXECUTE FUNCTION app.f()",
            );
            std::fs::remove_file(d.dir.join("schema/app.p1.yml")).unwrap();
            std::fs::write(d.dir.join("schema/app.p.yml"),
                "table: app.p\ncolumns:\n  id: {type: integer}\npartition_by: [id]\npartitions:\n  p1: {from: ['0'], to: ['10']}\n").unwrap();
            std::fs::write(d.dir.join("schema/app.p%2Ex.trigger.yml"), format!(
                "trigger: app.x\non: app.p\ndefinition: AFTER INSERT OR UPDATE ON app.p FOR EACH {} EXECUTE FUNCTION app.f()\n", if row { "ROW" } else { "STATEMENT" }
            )).unwrap();
            std::fs::write(
                d.dir.join("schema/app.a_marker.yml"),
                "table: app.a_marker\ncolumns:\n  id: {type: integer}\n",
            )
            .unwrap();
            let plan = connected_artifact(&d, connection, false);
            let output = approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "destructive,constraint"],
            );
            if row {
                assert_ne!(code(&output), 0, "{}", stdout(&output));
                let message = format!("{}{}", stdout(&output), stderr(&output));
                assert!(
                    message.contains("planned row triggers: x") && message.contains("app.p1"),
                    "{message}"
                );
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_class WHERE oid=to_regclass('app.a_marker')"
                    ),
                    0
                );
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_inherits WHERE inhrelid='app.p1'::regclass"
                    ),
                    0
                );
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_trigger WHERE tgrelid='app.p'::regclass AND tgname='x'"
                    ),
                    i64::from(rebuilt)
                );
            } else {
                succeeds(output);
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_inherits WHERE inhrelid='app.p1'::regclass"
                    ),
                    1
                );
                assert_eq!(
                    scalar(
                        connection,
                        "SELECT count(*) FROM pg_trigger WHERE tgrelid='app.p1'::regclass AND tgname='x' AND tgparentid=0"
                    ),
                    1
                );
            }
        }
    }
}

/// #2107: a parent or ordinary trigger's own companion is lost with its routine rebuild.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_routine_rebuild_refuses_its_constraint_triggers_own_comment() {
    for partitioned in [false, true] {
        let slug = format!("trigger-comment-2107-{partitioned}");
        let own = OwnDatabase::new(&server(), &slug);
        let connection = own.connection();
        on_server(connection, &format!(
            "CREATE SCHEMA app; CREATE TABLE app.t(id integer){};
             {}CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;
             CREATE CONSTRAINT TRIGGER audit AFTER INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.f();
             COMMENT ON CONSTRAINT audit ON app.t IS 'keep the audit constraint comment';",
            if partitioned { " PARTITION BY RANGE(id)" } else { "" },
            if partitioned { "CREATE TABLE app.p1 PARTITION OF app.t FOR VALUES FROM (0) TO (10);" } else { "" }
        ));
        let d = Demo::new(&slug);
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let routine = d.dir.join("schema/app.f%28%29.function.yml");
        let original = std::fs::read_to_string(&routine).unwrap();
        let changed = original.replace("RETURN NULL", "RETURN NEW");
        assert_ne!(changed, original);
        std::fs::write(routine, changed).unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
        let artifact = d.dir.join("refused.json");
        let output = d.run(&[
            "plan",
            "--db",
            connection,
            "--out",
            artifact.to_str().unwrap(),
        ]);
        assert_ne!(code(&output), 0, "{}", stdout(&output));
        let why = stderr(&output);
        assert!(
            why.contains("comment")
                && why.contains("keep the audit constraint comment")
                && why.contains("audit"),
            "{why}"
        );
        assert!(!artifact.exists());
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*) FROM pg_constraint c JOIN pg_description d ON d.objoid=c.oid AND d.classoid='pg_constraint'::regclass WHERE c.conrelid='app.t'::regclass AND c.conname='audit' AND d.description='keep the audit constraint comment'"
            ),
            1
        );
        // With no attached state, the same rebuild is valid and applies.
        on_server(connection, "COMMENT ON CONSTRAINT audit ON app.t IS NULL");
        let plan = d.dir.join("unadorned.json");
        succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "destructive"],
        ));
        succeeds(d.run(&["verify", "--db", connection]));
    }
}

/// A constraint trigger and its partition clones release their companion
/// constraint names before a check or foreign key takes them (#2100).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_constraint_trigger_rebuild_frees_its_name_before_a_check_or_foreign_key() {
    for partition in [false, true] {
        for foreign_key in [false, true] {
            let slug = format!("trigger-slot-{}-{}", partition, foreign_key);
            let own = OwnDatabase::new(&server(), &slug);
            let connection = own.connection();
            let create = if partition {
                "CREATE TABLE app.t (id integer) PARTITION BY RANGE (id);
                 CREATE TABLE app.p0 PARTITION OF app.t FOR VALUES FROM (0) TO (10);"
            } else {
                "CREATE TABLE app.t (id integer PRIMARY KEY);"
            };
            on_server(connection, &format!(
                "CREATE SCHEMA app;
                 CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
                 CREATE TABLE app.r (id integer PRIMARY KEY); INSERT INTO app.r VALUES (1);
                 {create}
                 CREATE CONSTRAINT TRIGGER audit AFTER INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.f();
                 INSERT INTO app.t VALUES (1);"));
            let d = Demo::new(&slug);
            succeeds(d.run(&["pull", "--db", connection]));
            d.commit();
            succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
            let target = if partition { "app.p0" } else { "app.t" };
            // Without releasing the trigger, the name is still occupied.
            // Measure the engine's refusal rather than adding a new intake
            // rule for an invalid final declaration to this ordering fix.
            let kept = try_on_server(
                connection,
                &format!("ALTER TABLE {target} ADD CONSTRAINT audit CHECK (id >= 0)"),
            )
            .unwrap_err();
            assert!(
                kept.contains("audit") && kept.contains("already exists"),
                "{kept}"
            );
            let part = if foreign_key {
                "foreign_keys:\n  audit:\n    columns: [id]\n    references: app.r(id)\n"
            } else {
                "checks:\n  audit: id >= 0\n"
            };
            let table = d.dir.join("schema/app.t.yml");
            if partition {
                let indented: String = part.lines().map(|line| format!("    {line}\n")).collect();
                std::fs::write(&table, format!(
                    "table: app.t\ncolumns:\n  id: {{type: integer}}\npartition_by: [id]\npartitions:\n  p0:\n    from: ['0']\n    to: ['10']\n{indented}"
                )).unwrap();
            } else {
                let original = std::fs::read_to_string(&table).unwrap();
                std::fs::write(&table, format!("{original}{part}")).unwrap();
            }
            let trigger = d.dir.join("schema/app.t%2Eaudit.trigger.yml");
            let original = std::fs::read_to_string(&trigger).unwrap();
            let ordinary = original
                .replace("CONSTRAINT AFTER", "AFTER")
                .replace(" NOT DEFERRABLE INITIALLY IMMEDIATE", "");
            assert_ne!(ordinary, original);
            std::fs::write(&trigger, ordinary).unwrap();
            let (plan, script) = connected_plan(&d, connection);
            assert!(
                script.find("DROP TRIGGER \"audit\"").unwrap()
                    < script.find("ADD CONSTRAINT \"audit\"").unwrap(),
                "{script}"
            );
            succeeds(approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "destructive,constraint"],
            ));
            succeeds(d.run(&["verify", "--db", connection]));
            let next = succeeds(d.run(&["plan", "--db", connection]));
            assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
            assert_eq!(
                scalar(connection, "SELECT count(*)::bigint FROM app.t WHERE id=1"),
                1
            );
            assert_eq!(
                scalar(
                    connection,
                    &format!(
                        "SELECT count(*)::bigint FROM pg_constraint WHERE conrelid='{target}'::regclass AND conname='audit' AND contype='{}'",
                        if foreign_key { "f" } else { "c" }
                    )
                ),
                1
            );
        }
    }
}

/// A key delayed by a constraint-trigger handover keeps the foreign keys
/// that need it, without carrying keys that reference another standing key.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_deferred_unique_or_primary_key_keeps_its_referencing_foreign_key_after_it() {
    for kind in ["unique", "primary", "check"] {
        let slug = format!("trigger-slot-key-readers-{kind}");
        let own = OwnDatabase::new(&server(), &slug);
        let connection = own.connection();
        on_server(connection, "CREATE SCHEMA app;
            CREATE TABLE app.t (id integer NOT NULL);
            CREATE TABLE app.c (id integer);
            CREATE TABLE app.r (id integer PRIMARY KEY);
            CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
            CREATE CONSTRAINT TRIGGER audit AFTER INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.f();");
        let d = Demo::new(&slug);
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let table = d.dir.join("schema/app.t.yml");
        let original = std::fs::read_to_string(&table).unwrap();
        let claimer = match kind {
            "unique" => "unique:\n  audit: [id]\nreplica_identity: {unique: audit}\n",
            "primary" => {
                "primary_key: {name: audit, columns: [id]}\nreplica_identity: primary_key\n"
            }
            _ => "checks:\n  audit: id >= 0\n",
        };
        std::fs::write(table, format!("{original}{claimer}")).unwrap();
        let child = d.dir.join("schema/app.c.yml");
        let original = std::fs::read_to_string(&child).unwrap();
        let target = if kind == "check" { "r" } else { "t" };
        std::fs::write(child, format!("{original}foreign_keys:\n  dependent:\n    columns: [id]\n    references: app.{target}(id)\n  unrelated:\n    columns: [id]\n    references: app.r(id)\n")).unwrap();
        let trigger = d.dir.join("schema/app.t%2Eaudit.trigger.yml");
        let original = std::fs::read_to_string(&trigger).unwrap();
        let ordinary = original
            .replace("CONSTRAINT AFTER", "AFTER")
            .replace(" NOT DEFERRABLE INITIALLY IMMEDIATE", "");
        assert_ne!(ordinary, original);
        std::fs::write(trigger, ordinary).unwrap();
        let (plan, script) = connected_plan(&d, connection);
        let release = script.find("DROP TRIGGER \"audit\"").unwrap();
        let claim = script.find("ADD CONSTRAINT \"audit\"").unwrap();
        let dependent = script.find("ADD CONSTRAINT \"dependent\"").unwrap();
        let unrelated = script.find("ADD CONSTRAINT \"unrelated\"").unwrap();
        assert!(release < claim, "{script}");
        assert!(unrelated < release, "{script}");
        assert_eq!(claim < dependent, kind != "check", "{script}");
        if kind != "check" {
            assert!(
                claim < script.find("REPLICA IDENTITY USING INDEX").unwrap(),
                "{script}"
            );
        }
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        on_server(
            connection,
            "INSERT INTO app.r VALUES (1); INSERT INTO app.t VALUES (1); INSERT INTO app.c VALUES (1)",
        );
        assert_eq!(scalar(connection, "SELECT count(*)::bigint FROM app.c"), 1);
    }
}

fn a_partition_takes_a_released_constraint_trigger_name(attach: bool) {
    for was_constraint in [true, false] {
        let slug = format!("partition-trigger-slot-{attach}-{was_constraint}");
        let own = OwnDatabase::new(&server(), &slug);
        let connection = own.connection();
        on_server(connection, &format!(
            "CREATE SCHEMA app;
             CREATE TABLE app.t (id integer) PARTITION BY RANGE (id);
             CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$;
             CREATE {}TRIGGER audit AFTER INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.f();{}",
            if was_constraint { "CONSTRAINT " } else { "" },
            if attach {
                "CREATE TABLE app.p0 (id integer CONSTRAINT audit CHECK (id >= 0)); INSERT INTO app.p0 VALUES (1);"
            } else { "" }
        ));
        let d = Demo::new(&slug);
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let check = if attach {
            let path = d.dir.join("schema/app.p0.yml");
            let table = std::fs::read_to_string(&path).unwrap();
            std::fs::remove_file(path).unwrap();
            table.split_once("checks:\n").unwrap().1.to_owned()
        } else {
            "  audit: id >= 0\n".into()
        };
        let check: String = check.lines().map(|line| format!("    {line}\n")).collect();
        std::fs::write(d.dir.join("schema/app.t.yml"), format!(
            "table: app.t\ncolumns:\n  id: {{type: integer}}\npartition_by: [id]\npartitions:\n  p0:\n    from: ['0']\n    to: ['10']\n    checks:\n{check}"
        )).unwrap();
        if was_constraint {
            // A kept constraint trigger still makes this final shape invalid.
            // Keep the connected plan's named refusal: changing the order
            // cannot make two final holders of the same name valid.
            succeeds(d.run(&["plan"]));
            d.commit();
            let kept = d.dir.join("kept.json");
            let result = d.run(&["plan", "--db", connection, "--out", kept.to_str().unwrap()]);
            assert_ne!(code(&result), 0, "{}", stdout(&result));
            let why = stderr(&result);
            assert!(
                why.contains("audit")
                    && why.contains("app.p0")
                    && why.contains("constraint trigger"),
                "{why}"
            );
            assert!(!kept.exists(), "a refused plan writes no artifact");
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*)::bigint FROM pg_class WHERE relnamespace='app'::regnamespace AND relname='p0' AND relispartition"
                ),
                0
            );
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*)::bigint FROM pg_constraint WHERE conrelid='app.t'::regclass AND conname='audit' AND contype='t'"
                ),
                1
            );
        }
        let trigger = d.dir.join("schema/app.t%2Eaudit.trigger.yml");
        let original = std::fs::read_to_string(&trigger).unwrap();
        let ordinary = original
            .replace("CONSTRAINT AFTER", "AFTER")
            .replace(" NOT DEFERRABLE INITIALLY IMMEDIATE", "")
            .replace("AFTER INSERT", "AFTER INSERT OR UPDATE");
        assert_ne!(ordinary, original);
        std::fs::write(trigger, ordinary).unwrap();
        let (plan, script) = connected_plan(&d, connection);
        let partition = script
            .find(if attach {
                "ATTACH PARTITION"
            } else {
                "CREATE TABLE \"app\".\"p0\""
            })
            .unwrap();
        let release = script.find("DROP TRIGGER \"audit\"").unwrap();
        assert_eq!(release < partition, was_constraint, "{script}");
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        on_server(connection, "INSERT INTO app.t VALUES (2)");
        assert_eq!(
            scalar(connection, "SELECT count(*)::bigint FROM app.t"),
            if attach { 2 } else { 1 }
        );
        assert_eq!(
            scalar(
                connection,
                "SELECT count(*)::bigint FROM pg_constraint WHERE conrelid='app.p0'::regclass AND conname='audit' AND contype='c'"
            ),
            1
        );
    }
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_created_partition_takes_a_constraint_trigger_name_after_its_release() {
    a_partition_takes_a_released_constraint_trigger_name(false);
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_attached_partition_keeps_its_check_after_a_constraint_trigger_releases_its_name() {
    a_partition_takes_a_released_constraint_trigger_name(true);
}

/// #1749: `ALTER TABLE ... SET SCHEMA` takes a table's indexes along under
/// their names, and refuses one whose name a relation of the destination
/// holds (measured on 16 and 18). An unmanaged sequence `s2.n` and a table
/// moved from `s1` to `s2` with an index `n`: the plan is refused before it
/// is written, naming both. Without the sequence the move applies.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_move_onto_a_name_the_destination_holds_is_refused() {
    let own = OwnDatabase::new(&server(), "landing1749");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA s1; CREATE SCHEMA s2; CREATE SEQUENCE s2.n",
    );
    let d = Demo::new("landing1749");
    let body = "columns:\n  id: {type: bigint, nullable: false}\n\
                primary_key: {name: pk_t, columns: [id]}\n\
                indexes:\n  n: {columns: [id]}\n";
    std::fs::write(
        d.dir.join("schema/s1.t.yml"),
        format!("table: s1.t\n{body}"),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    std::fs::remove_file(d.dir.join("schema/s1.t.yml")).unwrap();
    std::fs::write(
        d.dir.join("schema/s2.t.yml"),
        format!("table: s2.t\n{body}"),
    )
    .unwrap();
    succeeds(d.run(&["rename-table", "s1.t", "s2.t"]));
    succeeds(d.run(&["plan"]));
    d.commit();

    let artifact = d.dir.join("refused-plan.json");
    let out = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&out), 0, "{}", stdout(&out));
    assert!(
        stderr(&out).contains(
            "`s2.n`: this plan moves index `s1.n` on `s1.t` there, with the rename of `s1.t` \
             to `s2.t`, where sequence `s2.n` already is"
        ),
        "{}",
        stderr(&out)
    );
    assert!(!artifact.exists(), "a refused plan writes no artifact");

    on_server(connection, "DROP SEQUENCE s2.n");
    let plan = d.dir.join("plan.json");
    succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename"],
    ));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 's2' AND c.relname = 'n'"
        ),
        1
    );
}

/// #1765: a table or a view outside the recorded scope holds its name in the
/// destination schema, and `SET SCHEMA` refuses to carry an index onto it
/// (measured on 18). Each is refused before the plan is written, naming the
/// holder; once it is gone the move applies.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_move_onto_an_unmanaged_table_or_view_is_refused() {
    let own = OwnDatabase::new(&server(), "landing1765");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA s1; CREATE SCHEMA s2");
    let d = Demo::new("landing1765");
    let body = "columns:\n  id: {type: bigint, nullable: false}\n\
                primary_key: {name: pk_t, columns: [id]}\n\
                indexes:\n  n: {columns: [id]}\n";
    std::fs::write(
        d.dir.join("schema/s1.t.yml"),
        format!("table: s1.t\n{body}"),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    std::fs::remove_file(d.dir.join("schema/s1.t.yml")).unwrap();
    std::fs::write(
        d.dir.join("schema/s2.t.yml"),
        format!("table: s2.t\n{body}"),
    )
    .unwrap();
    succeeds(d.run(&["rename-table", "s1.t", "s2.t"]));
    succeeds(d.run(&["plan"]));
    d.commit();

    let artifact = d.dir.join("refused-plan.json");
    for (holder, what) in [
        ("CREATE TABLE s2.n (x integer)", "table"),
        ("DROP TABLE s2.n; CREATE VIEW s2.n AS SELECT 1 AS x", "view"),
    ] {
        on_server(connection, holder);
        let out = d.run(&[
            "plan",
            "--db",
            connection,
            "--out",
            artifact.to_str().unwrap(),
        ]);
        assert_ne!(code(&out), 0, "{}", stdout(&out));
        assert!(
            stderr(&out).contains(&format!(
                "`s2.n`: this plan moves index `s1.n` on `s1.t` there, with the rename of \
                 `s1.t` to `s2.t`, where {what} `s2.n` already is"
            )),
            "{}",
            stderr(&out)
        );
        assert!(!artifact.exists(), "a refused plan writes no artifact");
    }

    on_server(connection, "DROP VIEW s2.n");
    let plan = d.dir.join("plan.json");
    succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename"],
    ));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace \
             WHERE n.nspname = 's2' AND c.relname = 'n' AND c.relkind = 'i'"
        ),
        1
    );
}

/// #1765: what a cross-schema rename carries keeps its catalog name, so a
/// managed table holding it is no declaration conflict: `s1.old`'s unnamed
/// key's index is `old_pkey`, moved to `s2` beside a managed `s2.old_pkey`,
/// while the declarations name the key `new_pkey`. The plan is refused
/// before it is written, naming both, where it used to fail at `SET SCHEMA`;
/// renaming the holder away in the same plan frees the name first.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_move_onto_a_managed_table_holding_its_carried_name_is_refused() {
    let own = OwnDatabase::new(&server(), "managed1765");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA s1; CREATE SCHEMA s2");
    let d = Demo::new("managed1765");
    let keyed = "columns:\n  id: {type: bigint, nullable: false}\nprimary_key: {columns: [id]}\n";
    let holder = "columns:\n  x: {type: integer}\n";
    std::fs::write(
        d.dir.join("schema/s1.old.yml"),
        format!("table: s1.old\n{keyed}"),
    )
    .unwrap();
    std::fs::write(
        d.dir.join("schema/s2.old_pkey.yml"),
        format!("table: s2.old_pkey\n{holder}"),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    std::fs::remove_file(d.dir.join("schema/s1.old.yml")).unwrap();
    std::fs::write(
        d.dir.join("schema/s2.new.yml"),
        format!("table: s2.new\n{keyed}"),
    )
    .unwrap();
    succeeds(d.run(&["rename-table", "s1.old", "s2.new"]));
    succeeds(d.run(&["plan"]));
    d.commit();

    let artifact = d.dir.join("refused-plan.json");
    let out = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&out), 0, "{}", stdout(&out));
    assert!(
        stderr(&out).contains(
            "`s2.old_pkey`: this plan moves index `s1.old_pkey` on `s1.old` there, with the \
             rename of `s1.old` to `s2.new`, where table `s2.old_pkey` already is"
        ),
        "{}",
        stderr(&out)
    );
    assert!(!artifact.exists(), "a refused plan writes no artifact");

    std::fs::remove_file(d.dir.join("schema/s2.old_pkey.yml")).unwrap();
    std::fs::write(
        d.dir.join("schema/s2.kept.yml"),
        format!("table: s2.kept\n{holder}"),
    )
    .unwrap();
    succeeds(d.run(&["rename-table", "s2.old_pkey", "s2.kept"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    let out = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]);
    succeeds(out);
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename"],
    ));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_class WHERE oid = to_regclass('s2.old_pkey') AND relkind = 'i'"
        ),
        1
    );
}

/// #1767: `s2.b` was `s2.a` once, so its identity sequence is still
/// `s2.a_id_seq`, and `s1.a` moving to `s2.a` carries `s1.a_id_seq` onto that
/// name. The differ puts that move first; `s2.b`'s own move to `s3` frees the
/// name, so connected planning runs the move after it (DEC-1767.1,
/// DEC-1957.2). The plan is written in that order and applies, on 16 and on
/// 18.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_rename_that_moves_a_carried_names_holder_away_runs_first_on_both_servers() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        let own = OwnDatabase::new(server, "hoist1767");
        let connection = own.connection();
        on_server(
            connection,
            "CREATE SCHEMA s1; CREATE SCHEMA s2; CREATE SCHEMA s3; \
             CREATE TABLE s1.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
             CREATE TABLE s2.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
             ALTER TABLE s2.a RENAME TO b; ALTER INDEX s2.a_pkey RENAME TO b_pkey",
        );
        let d = Demo::new(&format!("hoist1767-{k}"));
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let moved = |from: &str, to: &str| {
            let path = d.dir.join(format!("schema/{from}.yml"));
            let text = std::fs::read_to_string(&path).unwrap();
            std::fs::remove_file(&path).unwrap();
            std::fs::write(
                d.dir.join(format!("schema/{to}.yml")),
                text.replace(&format!("table: {from}"), &format!("table: {to}")),
            )
            .unwrap();
            succeeds(d.run(&["rename-table", from, to]));
        };
        moved("s2.b", "s3.b");
        moved("s1.a", "s2.a");
        succeeds(d.run(&["plan"]));
        d.commit();

        let plan = d.dir.join("plan.json");
        let sql = d.dir.join("plan.sql");
        succeeds(d.run(&[
            "plan",
            "--db",
            connection,
            "--out",
            plan.to_str().unwrap(),
            "--sql",
            sql.to_str().unwrap(),
        ]));
        let script = std::fs::read_to_string(&sql).unwrap();
        let at = |needle: &str| {
            script
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
        };
        assert!(
            at("ALTER TABLE \"s2\".\"b\" SET SCHEMA \"s3\"")
                < at("ALTER TABLE \"s1\".\"a\" SET SCHEMA \"s2\""),
            "{script}"
        );
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "rename"],
        ));
        for sequence in ["s2.a_id_seq", "s3.a_id_seq"] {
            assert_eq!(
                scalar(
                    connection,
                    &format!(
                        "SELECT count(*) FROM pg_class WHERE oid = to_regclass('{sequence}') \
                         AND relkind = 'S'"
                    )
                ),
                1,
                "{sequence}"
            );
        }
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    }
}

/// #1957: a chain the one hoist of DEC-1767.1 refused. `s1.a`'s move to
/// `s2` carries `s1.a_id_seq` onto `s2.a_id_seq`, which `s2.b`'s sequence
/// holds until `s2.b` moves to `s3.c`, a name only `s3.c`'s rename to `s3.d`
/// frees. The handovers order all three (DEC-1957.2): the plan is written in
/// that order and applies, on 16 and on 18.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_chain_of_carried_name_handovers_is_ordered_on_both_servers() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        let own = OwnDatabase::new(server, "chain1957");
        let connection = own.connection();
        on_server(
            connection,
            "CREATE SCHEMA s1; CREATE SCHEMA s2; CREATE SCHEMA s3; \
             CREATE TABLE s1.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
             CREATE TABLE s2.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
             ALTER TABLE s2.a RENAME TO b; ALTER INDEX s2.a_pkey RENAME TO b_pkey; \
             CREATE TABLE s3.c (n int)",
        );
        let d = Demo::new(&format!("chain1957-{k}"));
        succeeds(d.run(&["pull", "--db", connection]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        let moved = |from: &str, to: &str| {
            let path = d.dir.join(format!("schema/{from}.yml"));
            let text = std::fs::read_to_string(&path).unwrap();
            std::fs::remove_file(&path).unwrap();
            std::fs::write(
                d.dir.join(format!("schema/{to}.yml")),
                text.replace(&format!("table: {from}"), &format!("table: {to}")),
            )
            .unwrap();
            succeeds(d.run(&["rename-table", from, to]));
        };
        moved("s3.c", "s3.d");
        moved("s2.b", "s3.c");
        moved("s1.a", "s2.a");
        succeeds(d.run(&["plan"]));
        d.commit();

        let plan = d.dir.join("plan.json");
        let sql = d.dir.join("plan.sql");
        succeeds(d.run(&[
            "plan",
            "--db",
            connection,
            "--out",
            plan.to_str().unwrap(),
            "--sql",
            sql.to_str().unwrap(),
        ]));
        let script = std::fs::read_to_string(&sql).unwrap();
        let at = |needle: &str| {
            script
                .find(needle)
                .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
        };
        assert!(
            at("ALTER TABLE \"s3\".\"c\" RENAME TO \"d\"")
                < at("ALTER TABLE \"s2\".\"b\" SET SCHEMA \"s3\""),
            "{script}"
        );
        assert!(
            at("ALTER TABLE \"s2\".\"b\" SET SCHEMA \"s3\"")
                < at("ALTER TABLE \"s1\".\"a\" SET SCHEMA \"s2\""),
            "{script}"
        );
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "rename"],
        ));
        for sequence in ["s2.a_id_seq", "s3.a_id_seq"] {
            assert_eq!(
                scalar(
                    connection,
                    &format!(
                        "SELECT count(*) FROM pg_class WHERE oid = to_regclass('{sequence}') \
                         AND relkind = 'S'"
                    )
                ),
                1,
                "{sequence}"
            );
        }
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    }
}

/// #1767 review: a view the plan changes, with a dependent view the
/// declarations leave alone, makes the module passes plan the revision again
/// in the differ's order (`rediff`), which undid the hoist. The plan
/// written still runs `s2.b`'s move first, and applies.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_hoisted_rename_stays_ahead_when_a_view_rebuild_plans_again() {
    let own = OwnDatabase::new(&server(), "rediff1767");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA s1; CREATE SCHEMA s2; CREATE SCHEMA s3; CREATE SCHEMA app; \
         CREATE TABLE s1.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
         CREATE TABLE s2.a (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY); \
         ALTER TABLE s2.a RENAME TO b; ALTER INDEX s2.a_pkey RENAME TO b_pkey; \
         CREATE VIEW app.v1 AS SELECT 1 AS x; \
         CREATE VIEW app.v2 AS SELECT x FROM app.v1",
    );
    let d = Demo::new("rediff1767");
    succeeds(d.run(&["pull", "--db", connection]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
    let view = std::fs::read_dir(d.dir.join("schema"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| {
            p.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with("app.v1.")
        })
        .expect("the pull writes `app.v1`");
    let text = std::fs::read_to_string(&view).unwrap();
    assert!(text.contains("1 AS x"), "{text}");
    std::fs::write(&view, text.replace("1 AS x", "2 AS x")).unwrap();
    let moved = |from: &str, to: &str| {
        let path = d.dir.join(format!("schema/{from}.yml"));
        let text = std::fs::read_to_string(&path).unwrap();
        std::fs::remove_file(&path).unwrap();
        std::fs::write(
            d.dir.join(format!("schema/{to}.yml")),
            text.replace(&format!("table: {from}"), &format!("table: {to}")),
        )
        .unwrap();
        succeeds(d.run(&["rename-table", from, to]));
    };
    moved("s2.b", "s3.b");
    moved("s1.a", "s2.a");
    succeeds(d.run(&["plan"]));
    d.commit();

    let plan = d.dir.join("plan.json");
    let sql = d.dir.join("plan.sql");
    succeeds(d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        plan.to_str().unwrap(),
        "--sql",
        sql.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    assert!(
        at("DROP VIEW") < at("CREATE VIEW"),
        "the views are rebuilt:\n{script}"
    );
    assert!(
        at("ALTER TABLE \"s2\".\"b\" SET SCHEMA \"s3\"")
            < at("ALTER TABLE \"s1\".\"a\" SET SCHEMA \"s2\""),
        "{script}"
    );
    succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "rename", "--allow", "destructive"],
    ));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// #1633: a foreign key's `RESTRICT` is pulled as `restrict` on delete and
/// on update, bootstrapped into an empty database, and pulled back the same,
/// with nothing left to plan. Changing an action between `restrict` and
/// `no_action` plans, applies, and leaves nothing to plan, and the catalog
/// then holds the action declared. On 16 and 18 (DEC-1633.1).
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_restrict_foreign_key_round_trips_and_its_actions_change_on_both_servers() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        let source = OwnDatabase::new(server, "restrict_source");
        on_server(
            source.connection(),
            "CREATE SCHEMA app; \
             CREATE TABLE app.p (id integer PRIMARY KEY); \
             CREATE TABLE app.c (id integer PRIMARY KEY, p integer CONSTRAINT c_p_fk \
                 REFERENCES app.p ON DELETE RESTRICT ON UPDATE RESTRICT)",
        );
        let d = Demo::new(&format!("restrict-{k}"));
        let pulled = succeeds(d.run(&["pull", "--db", source.connection()]));
        assert!(!stderr(&pulled).contains("RESTRICT"), "{}", stderr(&pulled));
        let file = d.dir.join("schema/app.c.yml");
        let declared = std::fs::read_to_string(&file).unwrap();
        assert!(declared.contains("on_delete: restrict"), "{declared}");
        assert!(declared.contains("on_update: restrict"), "{declared}");
        succeeds(d.run(&["plan"]));
        d.commit();

        let target = OwnDatabase::new(server, "restrict_target");
        let connection = target.connection();
        on_server(connection, "CREATE SCHEMA app");
        succeeds(d.run(&["bootstrap", "--db", connection]));
        // Tens for delete, units for update: 1 where the action is `r`,
        // RESTRICT, and 2 where it is `a`, NO ACTION.
        let actions = || {
            scalar(
                connection,
                "SELECT ((CASE confdeltype WHEN 'r' THEN 10 WHEN 'a' THEN 20 END) \
                      + (CASE confupdtype WHEN 'r' THEN 1 WHEN 'a' THEN 2 END))::bigint \
                 FROM pg_constraint WHERE conname = 'c_p_fk'",
            )
        };
        assert_eq!(actions(), 11);
        let again = Demo::new(&format!("restrict-again-{k}"));
        succeeds(again.run(&["pull", "--db", connection]));
        assert_eq!(
            std::fs::read_to_string(again.dir.join("schema/app.c.yml")).unwrap(),
            declared
        );
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

        // Each side changed in turn, then back.
        for (on_delete, on_update, wanted) in [
            ("no_action", "restrict", 21),
            ("restrict", "no_action", 12),
            ("restrict", "restrict", 11),
        ] {
            let text = declared
                .replace("on_delete: restrict", &format!("on_delete: {on_delete}"))
                .replace("on_update: restrict", &format!("on_update: {on_update}"));
            std::fs::write(&file, text).unwrap();
            let plan = connected_artifact(&d, connection, false);
            succeeds(approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "constraint"],
            ));
            assert_eq!(actions(), wanted, "{on_delete} {on_update}");
            let next = succeeds(d.run(&["plan", "--db", connection]));
            assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        }
    }
}

#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn permission_versions_are_checked_before_planning_bootstrap_apply_and_resume() {
    struct Roles(Vec<(String, String)>);
    impl Drop for Roles {
        fn drop(&mut self) {
            for (server, name) in &self.0 {
                let _ = try_on_server(server, &format!("DROP ROLE IF EXISTS {name}"));
            }
        }
    }
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    let new_server = server();
    let role = format!("pbps_version_{}", std::process::id());
    let _roles = Roles(vec![
        (old_server.clone(), role.clone()),
        (new_server.clone(), role.clone()),
    ]);
    for server in [&old_server, &new_server] {
        on_server(server, &format!("CREATE ROLE {role}"));
    }
    on_server(
        &old_server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'needs pre-17'; END IF; END $$",
    );
    on_server(
        &new_server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer < 170000 THEN RAISE EXCEPTION 'needs 17+'; END IF; END $$",
    );
    let old = OwnDatabase::new(&old_server, "permission_version");
    let new = OwnDatabase::new(&new_server, "permission_version");
    let bootstrap_target = OwnDatabase::new(&old_server, "permission_bootstrap");
    for db in [&old, &new, &bootstrap_target] {
        on_server(db.connection(), "CREATE SCHEMA app");
    }
    let d = Demo::new("permission-version");
    d.table(ONE_COLUMN);
    let role_file = d.dir.join("schema/reader.yml");
    let declare = |permissions: &str| {
        std::fs::write(
            &role_file,
            format!("role: {role}\ngrants:\n  app.t: [{permissions}]\n  schema::app: [usage]\n"),
        )
        .unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    declare("select");
    for db in [&old, &new] {
        succeeds(d.run(&["bootstrap", "--db", db.connection()]));
    }
    declare("select, maintain");
    let refuses_version = |o: Output| {
        assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
        assert!(
            stderr(&o).contains("permission_support (PostgreSQL)"),
            "{}",
            stderr(&o)
        );
        assert!(
            stderr(&o).contains("PostgreSQL 17 or later"),
            "{}",
            stderr(&o)
        );
    };
    refuses_version(d.run(&["bootstrap", "--db", bootstrap_target.connection()]));
    on_server(
        bootstrap_target.connection(),
        "DO $$ BEGIN IF to_regclass('app.t') IS NOT NULL OR to_regclass('public.__pbps_state') IS NOT NULL THEN RAISE EXCEPTION 'bootstrap wrote before refusing'; END IF; END $$",
    );

    let plan = d.dir.join("version-plan.json");
    let o = d.run(&[
        "plan",
        "--db",
        old.connection(),
        "--out",
        plan.to_str().unwrap(),
        "--format",
        "json",
    ]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    let report: serde_json::Value = serde_json::from_str(&stdout(&o)).unwrap();
    assert_eq!(report["result"], "unanswerable", "{report}");
    assert!(
        report["findings"][0]["message"]
            .as_str()
            .unwrap()
            .contains("permission_support (PostgreSQL)"),
        "{report}"
    );
    assert!(
        !plan.exists(),
        "refused planning must not write an artifact"
    );
    let o = succeeds(d.run(&[
        "plan",
        "--db",
        new.connection(),
        "--out",
        plan.to_str().unwrap(),
        "--format",
        "json",
    ]));
    let report: serde_json::Value = serde_json::from_str(&stdout(&o)).unwrap();
    assert_eq!(
        report["data"]["connected_checks"][0]["name"],
        "permission_support"
    );
    assert_eq!(report["data"]["connected_checks"][0]["status"], "passed");
    assert_eq!(
        report["data"]["connected_checks"][0]["engine"],
        "PostgreSQL"
    );
    refuses_version(apply_plan(&d, old.connection(), &plan, false));
    let staged = d.dir.join("version-staged.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        new.connection(),
        "--out",
        staged.to_str().unwrap(),
        "--staged",
        "--format",
        "json",
    ]));
    refuses_version(apply_plan(&d, old.connection(), &staged, true));
    refuses_version(d.run(&[
        "apply",
        "--db",
        old.connection(),
        "--plan",
        staged.to_str().unwrap(),
        "--checksum",
        &plan_checksum(&staged),
        "--staged",
        "--resume",
    ]));
    let listing = succeeds(d.run(&[
        "state",
        "list",
        "--db",
        old.connection(),
        "--format",
        "json",
    ]));
    let listing: serde_json::Value = serde_json::from_str(&stdout(&listing)).unwrap();
    assert_eq!(
        listing["data"]["entries"].as_array().unwrap().len(),
        1,
        "a capability refusal must not write a ledger entry: {listing}"
    );
    succeeds(apply_plan(&d, new.connection(), &plan, false));
    on_server(
        new.connection(),
        &format!(
            "DO $$ BEGIN IF NOT has_table_privilege('{role}', 'app.t', 'MAINTAIN') THEN RAISE EXCEPTION 'grant missing'; END IF; END $$"
        ),
    );

    // Reference-data adoption also remains a single JSON document, carrying
    // the notice that the human plan prints before its summary.
    d.table(&format!(
        "{ONE_COLUMN}data:\n  mode: ensure\n  rows:\n    1: {{}}\n"
    ));
    succeeds(d.run(&["plan"]));
    d.commit();
    let adoption = succeeds(d.run(&["plan", "--db", new.connection(), "--format", "json"]));
    let adoption: serde_json::Value = serde_json::from_str(&stdout(&adoption)).unwrap();
    assert!(
        adoption["findings"]
            .as_array()
            .unwrap()
            .iter()
            .any(|f| f["id"] == "data.adoption"),
        "{adoption}"
    );
    d.table(ONE_COLUMN);

    // A revoke-only plan still works on the old server. The guard is about
    // permissions the plan grants, not permissions mentioned in a declaration.
    std::fs::write(&role_file, format!("role: {role}\n")).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&[
        "plan",
        "--db",
        old.connection(),
        "--out",
        plan.to_str().unwrap(),
        "--format",
        "json",
    ]));
    let saved: pbps_model::SavedPlan =
        serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    assert!(
        saved
            .changes
            .changes
            .iter()
            .all(|p| matches!(p.change, pbps_model::Change::Revoke { .. }))
    );
    succeeds(d.run(&[
        "apply",
        "--db",
        old.connection(),
        "--plan",
        plan.to_str().unwrap(),
        "--checksum",
        &plan_checksum(&plan),
        "--allow",
        "revoke",
    ]));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn drop_blockers_are_named_in_planning_and_rechecked_before_apply_writes() {
    for (target, slug) in [("app.t.label", "drop_column"), ("app.t", "drop_table")] {
        let db = OwnDatabase::new(&server(), slug);
        let connection = db.connection();
        on_server(connection, "CREATE SCHEMA app");
        let d = Demo::new(slug);
        d.table(TWO_COLUMNS);
        succeeds(d.run(&["plan"]));
        d.commit();
        succeeds(d.run(&["bootstrap", "--db", connection]));
        if target == "app.t" {
            std::fs::remove_file(d.dir.join("schema/app.t.yml")).unwrap();
        } else {
            d.table(ONE_COLUMN);
        }
        let command = if target == "app.t" {
            "drop-table"
        } else {
            "drop"
        };
        succeeds(d.run(&[command, target, "--reason", "no longer retained"]));
        d.commit();
        on_server(
            connection,
            "CREATE VIEW app.external_v AS SELECT label FROM app.t",
        );
        let plan = d.dir.join("drop.json");
        let out = d.run(&[
            "plan",
            "--db",
            connection,
            "--format",
            "json",
            "--out",
            plan.to_str().unwrap(),
        ]);
        assert_eq!(code(&out), 1, "{}{}", stdout(&out), stderr(&out));
        let report: serde_json::Value = serde_json::from_str(&stdout(&out)).unwrap();
        assert_eq!(report["result"], "unanswerable", "{report}");
        let message = report["findings"][0]["message"].as_str().unwrap();
        assert!(
            message.contains("drop_blockers (PostgreSQL)") && message.contains("external_v"),
            "{report}"
        );
        assert!(!plan.exists(), "refused plans must not be saved");
        on_server(connection, "DROP VIEW app.external_v");
        let out = succeeds(d.run(&[
            "plan",
            "--db",
            connection,
            "--format",
            "json",
            "--out",
            plan.to_str().unwrap(),
        ]));
        let report: serde_json::Value = serde_json::from_str(&stdout(&out)).unwrap();
        let checks = report["data"]["connected_checks"].as_array().unwrap();
        assert!(
            checks
                .iter()
                .any(|c| c["name"] == "drop_blockers" && c["status"] == "passed"),
            "{report}"
        );
        let human = stdout(&succeeds(d.run(&["plan", "--db", connection])));
        assert!(
            human.contains("drop_blockers") && human.contains("catalog dependencies"),
            "{human}"
        );
        let staged = d.dir.join("drop-staged.json");
        succeeds(d.run(&[
            "plan",
            "--db",
            connection,
            "--staged",
            "--out",
            staged.to_str().unwrap(),
        ]));
        on_server(
            connection,
            "CREATE VIEW app.external_v AS SELECT label FROM app.t",
        );
        for (artifact, is_staged) in [(&plan, false), (&staged, true)] {
            let checksum = plan_checksum(artifact);
            let mut args = vec![
                "apply",
                "--db",
                connection,
                "--plan",
                artifact.to_str().unwrap(),
                "--checksum",
                &checksum,
                "--allow",
                "destructive",
            ];
            if is_staged {
                args.push("--staged");
            }
            let out = d.run(&args);
            assert_eq!(code(&out), 1, "{}{}", stdout(&out), stderr(&out));
            assert!(
                stderr(&out).contains("drop_blockers (PostgreSQL)")
                    && stderr(&out).contains("external_v"),
                "{}",
                stderr(&out)
            );
            let listing =
                succeeds(d.run(&["state", "list", "--db", connection, "--format", "json"]));
            let listing: serde_json::Value = serde_json::from_str(&stdout(&listing)).unwrap();
            let entries = listing["data"]["entries"].as_array().unwrap();
            assert_eq!(
                entries.iter().filter(|e| e["kind"] != "failed").count(),
                1,
                "{listing}"
            );
            assert_eq!(
                entries[0]["kind"], "failed",
                "failed attempts retain their audit entry"
            );
            on_server(connection, "SELECT label FROM app.t");
        }
        on_server(connection, "DROP VIEW app.external_v");
        succeeds(d.run(&[
            "apply",
            "--db",
            connection,
            "--plan",
            plan.to_str().unwrap(),
            "--checksum",
            &plan_checksum(&plan),
            "--allow",
            "destructive",
        ]));
        succeeds(d.run(&["verify", "--db", connection]));
    }
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn drop_blockers_do_not_refuse_a_closing_resume_after_the_drop_completed() {
    let db = OwnDatabase::new(&server(), "drop_resume");
    let connection = db.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("drop-resume");
    d.table(TWO_COLUMNS);
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", connection]));
    d.table(ONE_COLUMN);
    succeeds(d.run(&["drop", "app.t.label", "--reason", "no longer retained"]));
    d.commit();
    let artifact = d.dir.join("staged.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        connection,
        "--staged",
        "--out",
        artifact.to_str().unwrap(),
    ]));
    let plan: pbps_model::SavedPlan =
        serde_json::from_str(&std::fs::read_to_string(&artifact).unwrap()).unwrap();
    assert_eq!(plan.changes.changes.len(), 1);
    let pg = pbps_pg::Postgres::new();
    let p = &plan.changes.changes[0];
    let statements = pg.fixture_emit(&p.change, p.strategy).unwrap();
    assert_eq!(
        statements.len(),
        1,
        "a pending DROP cannot follow a prior statement of this change"
    );
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    rt.block_on(async {
        let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, connection)
            .await
            .unwrap();
        let mut checkpoint = pbps_pg::state::latest(&mut conn)
            .await
            .unwrap()
            .unwrap()
            .snapshot;
        conn.execute(&statements[0].sql).await.unwrap();
        checkpoint
            .schema
            .tables
            .get_mut(&pbps_model::TableName::new("app", "t"))
            .unwrap()
            .columns
            .shift_remove("label");
        checkpoint.ids = plan.ids.clone();
        checkpoint.kind = pbps_model::StateKind::Staged;
        checkpoint.plan_checksum = Some(plan.wire_fingerprint());
        checkpoint.staged = Some(pbps_model::StagedProgress {
            completed: 1,
            total: 1,
            last_statement: statements[0].sql.clone(),
        });
        pbps_pg::state::record(&mut conn, &checkpoint)
            .await
            .unwrap();
    });
    succeeds(d.run(&[
        "apply",
        "--db",
        connection,
        "--plan",
        artifact.to_str().unwrap(),
        "--checksum",
        &plan.wire_fingerprint(),
        "--allow",
        "destructive",
        "--staged",
        "--resume",
    ]));
    succeeds(d.run(&["verify", "--db", connection]));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn the_cli_ledger_preserves_history_and_distinguishes_absent_empty_and_unreadable() {
    let own = OwnDatabase::new(&server(), "invariant_ledger");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("invariant-ledger");
    d.table(ONE_COLUMN);
    succeeds(d.run(&["plan"]));
    d.commit();
    let history = || {
        json_output(succeeds(
            d.run(&["state", "list", "--db", connection, "--format", "json"]),
        ))
    };
    let absent = history();
    assert_eq!(absent["data"]["initialized"], false, "{absent}");
    assert_eq!(absent["data"]["entries"], serde_json::json!([]));
    succeeds(d.run(&[
        "baseline",
        "--db",
        connection,
        "--reason",
        "adopting an empty schema",
    ]));
    let recorded = latest_snapshot(connection);
    assert!(recorded.schema.tables.is_empty());
    assert_eq!(
        latest_snapshot(connection),
        recorded,
        "separate connections read the same snapshot"
    );
    succeeds(d.run(&["bootstrap", "--db", connection]));
    let v = history();
    let entries = v["data"]["entries"].as_array().unwrap();
    assert_eq!(entries.len(), 2, "{v}");
    assert_eq!(entries[0]["kind"], "bootstrap");
    assert_eq!(entries[0]["tables"], 1);
    assert_eq!(entries[1]["kind"], "baseline");
    assert_eq!(entries[1]["tables"], 0);
    assert_eq!(entries[1]["reason"], "adopting an empty schema");
    assert!(entries[0]["id"].as_i64().unwrap() > entries[1]["id"].as_i64().unwrap());
    let limited = json_output(succeeds(d.run(&[
        "state", "list", "--db", connection, "--format", "json", "--limit", "1",
    ])));
    assert_eq!(limited["data"]["entries"], serde_json::json!([entries[0]]));
    // Missing query columns are unreadable, never an empty successful history.
    on_server(
        connection,
        "ALTER TABLE public.__pbps_state RENAME COLUMN kind TO hidden_kind",
    );
    let broken = d.run(&["state", "list", "--db", connection, "--format", "json"]);
    assert_eq!(code(&broken), 1, "{}", stderr(&broken));
    let broken = json_output(broken);
    assert_eq!(broken["result"], "unanswerable");
    assert!(broken.get("data").is_none(), "{broken}");
    on_server(
        connection,
        "ALTER TABLE public.__pbps_state RENAME COLUMN hidden_kind TO kind; DELETE FROM public.__pbps_state",
    );
    let empty = history();
    assert_eq!(empty["data"]["initialized"], true);
    assert_eq!(empty["data"]["entries"], serde_json::json!([]));
}

/// #1205: the operator (git `user.name`) went into the ledger's
/// `varchar(128)` unbounded, so a long one was refused at the ledger write —
/// on `apply`, after the statements had run. It is recorded, cut to the
/// column in this engine's unit, characters: 100 emoji fit whole here, where
/// SQL Server's UTF-16 count would have kept 64.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_operator_wider_than_the_ledger_column_is_recorded_cut_to_it() {
    let own = OwnDatabase::new(&server(), "operator_width");
    let connection = own.connection();
    let d = bootstrapped_demo(connection, "operator-width", ONE_COLUMN);
    for (name, recorded) in [
        ("a".repeat(300), "a".repeat(128)),
        ("\u{1F600}".repeat(100), "\u{1F600}".repeat(100)),
        ("\u{1F600}".repeat(200), "\u{1F600}".repeat(128)),
    ] {
        d.git(&["config", "user.name", &name]);
        succeeds(d.run(&["baseline", "--db", connection, "--reason", "wide operator"]));
        assert_eq!(latest_snapshot(connection).operator, recorded);
        // The column projection and `state_json` agree on what was recorded.
        let listed = json_output(succeeds(
            d.run(&["state", "list", "--db", connection, "--format", "json"]),
        ));
        assert_eq!(listed["data"]["entries"][0]["operator"], recorded.as_str());
    }
}

/// #1188: the lock row named a person, not a process, and pbps set no
/// application name, so "is the holder gone?" had nothing to check before
/// `pbps unlock`. The row now names the host, pid, CI job and the application
/// name the holder's sessions carry, and the refusal and `unlock` both print
/// the query that finds those sessions.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_lock_names_its_holders_process_and_says_how_to_find_its_session() {
    let own = OwnDatabase::new(&server(), "lock_holder");
    let connection = own.connection();
    let d = bootstrapped_demo(connection, "lock-holder", ONE_COLUMN);

    // What the CLI records while it holds the lock, read from inside its own
    // apply: a DDL event trigger runs in that session, beside the lock row.
    on_server(
        connection,
        r#"
        CREATE SCHEMA witness;
        CREATE TABLE witness.held (locked_by text, session_name text);
        CREATE FUNCTION witness.copy_lock() RETURNS event_trigger LANGUAGE plpgsql AS $$
        BEGIN
          INSERT INTO witness.held
            SELECT locked_by, current_setting('application_name') FROM public.__pbps_lock;
        END $$;
        CREATE EVENT TRIGGER copy_lock ON ddl_command_end WHEN TAG IN ('ALTER TABLE')
          EXECUTE FUNCTION witness.copy_lock();
    "#,
    );
    d.table(TWO_COLUMNS);
    let plan = connected_artifact(&d, connection, false);
    let checksum = plan_checksum(&plan);
    succeeds(d.run_with_env(
        &[
            "apply",
            "--db",
            connection,
            "--plan",
            plan.to_str().unwrap(),
            "--checksum",
            &checksum,
        ],
        &[("GITHUB_RUN_ID", "4242"), ("GITHUB_RUN_ATTEMPT", "2")],
    ));
    on_server(connection, "DROP EVENT TRIGGER copy_lock");
    let recorded = text_of(connection, "SELECT locked_by FROM witness.held LIMIT 1");
    let session = text_of(connection, "SELECT session_name FROM witness.held LIMIT 1");
    assert!(session.starts_with("pbps/"), "{session}");
    assert!(
        recorded.ends_with(&format!(
            ", CI job GitHub Actions run 4242 attempt 2, application_name \"{session}\"]"
        )),
        "{recorded}"
    );
    assert!(recorded.contains(", pid "), "{recorded}");
    assert_eq!(
        pbps_db::holder_application_name(&recorded).as_deref(),
        Some(session.as_str())
    );

    // A holder that is still connected: this test's own session, taking the
    // lock the way the CLI does.
    let rt = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();
    let (mut held, name, holder) = rt.block_on(async {
        let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, connection)
            .await
            .unwrap();
        let name = pbps_pg::state::session_application_name(&mut conn)
            .await
            .unwrap();
        let holder = pbps_db::LockHolder {
            operator: "holder-1188",
            host: Some("host-1188"),
            pid: std::process::id(),
            ci_job: None,
            application_name: &name,
        }
        .render();
        pbps_pg::state::lock(&mut conn, &holder).await.unwrap();
        (conn, name, holder)
    });
    // Found from another session by the name the row recorded. That session
    // is this process's too, so it carries the same name and is left out.
    let lookup = format!("FROM pg_stat_activity WHERE application_name = '{name}'");
    assert_eq!(
        scalar(
            connection,
            &format!("SELECT count(*) {lookup} AND pid <> pg_backend_pid()")
        ),
        1,
        "{holder}"
    );

    let denied = d.run(&["baseline", "--db", connection, "--reason", "second holder"]);
    assert_eq!(code(&denied), 1, "{}{}", stdout(&denied), stderr(&denied));
    for expected in [holder.as_str(), lookup.as_str()] {
        assert!(stderr(&denied).contains(expected), "{}", stderr(&denied));
    }
    let released = succeeds(d.run(&["unlock", "--db", connection]));
    for expected in [holder.as_str(), lookup.as_str()] {
        assert!(
            stdout(&released).contains(expected),
            "{}",
            stdout(&released)
        );
    }
    rt.block_on(async { held.execute("SELECT 1").await.unwrap() });
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn the_cli_refuses_the_second_lock_holder_and_unlock_releases_only_the_gate() {
    let own = OwnDatabase::new(&server(), "invariant_lock");
    let connection = own.connection();
    let d = bootstrapped_demo(connection, "invariant-lock", ONE_COLUMN);
    on_server(
        connection,
        "INSERT INTO public.__pbps_lock (id, locked_by) VALUES (1, 'invariant-first-holder')",
    );
    let before = latest_snapshot(connection);
    for args in [
        vec!["baseline", "--db", connection, "--reason", "second holder"],
        vec!["snapshot", "--db", connection],
    ] {
        let denied = d.run(&args);
        assert_eq!(code(&denied), 1, "{}{}", stdout(&denied), stderr(&denied));
        assert!(
            stderr(&denied).contains("invariant-first-holder"),
            "{}",
            stderr(&denied)
        );
    }
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM public.__pbps_lock WHERE locked_by = 'invariant-first-holder'"
        ),
        1
    );
    assert_eq!(latest_snapshot(connection), before);
    let diagnosis = d.run(&["doctor", "--db", connection, "--format", "json"]);
    assert_eq!(code(&diagnosis), 2);
    let diagnosis = json_output(diagnosis);
    assert!(
        diagnosis["findings"]
            .as_array()
            .unwrap()
            .iter()
            .any(|f| f["id"] == "state.locked")
    );
    succeeds(d.run(&["unlock", "--db", connection]));
    assert_eq!(
        scalar(connection, "SELECT count(*) FROM public.__pbps_lock"),
        0
    );
    assert_eq!(latest_snapshot(connection), before);
    succeeds(d.run(&["unlock", "--db", connection]));
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "after unlock"]));
    assert_eq!(
        latest_snapshot(connection)
            .reason
            .as_ref()
            .map(pbps_model::Text::raw),
        Some("after unlock")
    );
}

/// A trigger's own `RAISE EXCEPTION` naming a value nobody declared to this
/// tool keeps that value on the operator's own screen and off the ledger.
///
/// The ready-phase finding on PR #464 named two shapes that can put row data
/// into `db.message()` rather than the enrichment fields DECISIONS 454
/// already strips: an engine conversion error, and a "PL/pgSQL/check/trigger
/// exception whose primary MESSAGE contains row data." The first was tried
/// here first and **measured** not to be reachable through this tool's own
/// emitted DDL: `ALTER COLUMN ... TYPE` without an explicit `USING` — which is
/// all pbps ever emits (ADR-0012 §5 refuses a retype no automatic cast
/// covers) — fails a real out-of-range or over-length row with a *generic*
/// message (`integer out of range`, `value too long for type character
/// varying(10)`, `numeric field overflow`), none of which named the value on
/// 18.6; only a bare `CAST('text' AS type)` from an untyped literal does that,
/// and this tool never emits one against existing data. The second shape,
/// below, is reachable exactly as the finding named it, through a data
/// trigger this tool's own guard (`crates/pbps-pg/src/data_triggers.rs`)
/// already treats as approved because it exists in the very first recorded
/// state.
///
/// The secret lives in a table this plan never declares and this trigger
/// reads on its own — not in the row the plan writes. A first draft of this
/// fixture put the literal in the *declared* row instead, and its failure was
/// the useful measurement: pbps's own emitted `INSERT` necessarily restates
/// what was declared, so a secret placed there also appears in this tool's
/// own `.context()` framing around the statement, which is not the driver
/// frame and is not supposed to be redacted (it is the plan's own checksummed
/// text, already in git — DECISIONS 455). Reading a genuinely undeclared
/// value out of a side table, the way `unapproved_data_triggers_
/// cannot_use_the_deployers_privileges` above already reads `public.secret`,
/// isolates the one frame this test means to pin: the driver's.
///
/// The trigger is adopted the way an operator's own would be — pulled after
/// it exists live, declared from that pulled text, and folded into a fresh
/// `baseline` — rather than written by hand, for the same reason the
/// `trigger:`-pulling tests elsewhere in this file give: only a pulled
/// definition is the engine's own deparsed text, and this is what makes the
/// reference-data write below a *recorded managed* use of the trigger, not
/// the refusal `unapproved_data_triggers_cannot_use_the_deployers_privileges`
/// covers.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_triggers_own_exception_keeps_the_row_value_off_the_ledger_but_not_off_the_operator() {
    let own = OwnDatabase::new(&server(), "invariant_trigger_message");
    let connection = own.connection();
    let declared = "table: app.t\ncolumns:\n  code: {type: varchar(20), nullable: false}\n  \
         label: {type: text, nullable: false}\nprimary_key: {name: pk_t, columns: [code]}\n";
    let d = bootstrapped_demo(connection, "invariant-trigger-message", declared);
    on_server(
        connection,
        "CREATE TABLE public.secret(value text); \
         INSERT INTO public.secret VALUES ('super-secret-value-167'); \
         CREATE FUNCTION app.reject() RETURNS trigger LANGUAGE plpgsql AS \
         $$DECLARE v text; BEGIN SELECT value INTO v FROM public.secret; \
           RAISE EXCEPTION 'rejected: %', v; END$$; \
         CREATE TRIGGER reject BEFORE INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.reject()",
    );
    let puller = Demo::new("invariant-trigger-message-pull");
    succeeds(puller.run(&["pull", "--db", connection]));
    let module = std::fs::read_dir(puller.dir.join("schema"))
        .unwrap()
        .filter_map(|entry| {
            let path = entry.unwrap().path();
            let body = std::fs::read_to_string(&path).ok()?;
            body.lines()
                .any(|line| line.starts_with("trigger:"))
                .then_some(body)
        })
        .next()
        .expect("the engine's own spelling of the trigger");
    std::fs::write(d.dir.join("schema/reject.yml"), module).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&[
        "baseline",
        "--db",
        connection,
        "--reason",
        "adopt the reject trigger",
    ]));
    succeeds(d.run(&["verify", "--db", connection]));
    d.table(&format!(
        "{declared}data:\n  mode: exact\n  rows:\n    x: {{label: New}}\n"
    ));
    let plan = connected_artifact(&d, connection, false);
    let failed = approved_apply(&d, connection, &plan, &[]);
    assert_eq!(code(&failed), 1, "{}{}", stdout(&failed), stderr(&failed));
    assert!(
        stderr(&failed).contains("super-secret-value-167"),
        "the operator, who already holds credentials to this database, still \
         gets the server's own sentence: {}",
        stderr(&failed)
    );
    assert!(stderr(&failed).contains("rejected:"), "{}", stderr(&failed));

    let after = latest_snapshot(connection);
    assert_eq!(after.kind, pbps_model::StateKind::Failed);
    let reason = after
        .reason
        .as_ref()
        .map(|r| r.raw().to_owned())
        .unwrap_or_default();
    assert!(
        !reason.contains("super-secret-value-167"),
        "a value nobody declared to this tool must never reach the durable \
         ledger: {reason}"
    );
    assert!(
        reason.contains("P0001"),
        "the SQLSTATE for a bare RAISE EXCEPTION is not data and should still \
         help an operator reading the ledger later: {reason}"
    );
    assert!(
        reason.contains("the database rejected this statement"),
        "this tool's own framing is not data either, and should survive \
         beside the redacted driver frame: {reason}"
    );
    assert!(
        reason.contains("New"),
        "the plan's own declared value is not the driver's data and must \
         survive in this tool's own emitted-statement text: {reason}"
    );
}

/// A tool-composed refusal — this tool's own guard naming an unapproved
/// trigger, never a server value — keeps naming the trigger in the durable
/// ledger, unlike the driver's own sentence the test above pins.
///
/// A second ready-phase round on PR #464 found `ledger_safe_reason` treating
/// this refusal the same way as a real driver frame: `data_triggers.rs`'s
/// `refused()` used to build a `DbError::Driver` with no code, exactly the
/// shape `ledger_safe_reason` could not tell apart from a server's, and it
/// redacted the one thing an operator reading the ledger later needs — which
/// trigger to remove. `DbError::Refused` (DECISIONS 455) makes this
/// unrepresentable as `Driver`: this test pins that the redaction can never
/// happen again, whatever call site builds the refusal.
///
/// The trigger is created live *after* the plan is computed against the
/// clean baseline, so `plan` never sees it and only `apply`'s own re-check
/// (`crate::engine::prepare_data_writes`, run fresh inside the transaction)
/// catches it — the same shape a trigger installed between approval and
/// deployment would take outside a test.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_unapproved_triggers_own_refusal_keeps_naming_it_on_the_ledger() {
    let own = OwnDatabase::new(&server(), "invariant_refused_trigger");
    let connection = own.connection();
    let declared = "table: app.t\ncolumns:\n  code: {type: varchar(20), nullable: false}\n  \
         label: {type: text, nullable: false}\nprimary_key: {name: pk_t, columns: [code]}\n";
    let d = bootstrapped_demo(connection, "invariant-refused-trigger", declared);
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nunmanaged: ignore\n",
    )
    .unwrap();
    d.table(&format!(
        "{declared}data:\n  mode: exact\n  rows:\n    x: {{label: New}}\n"
    ));
    let plan = connected_artifact(&d, connection, false);
    on_server(
        connection,
        "CREATE FUNCTION app.audit() RETURNS trigger LANGUAGE plpgsql AS \
         $$BEGIN RETURN NEW; END$$; \
         CREATE TRIGGER audit BEFORE INSERT ON app.t FOR EACH ROW EXECUTE FUNCTION app.audit()",
    );
    let failed = approved_apply(&d, connection, &plan, &[]);
    assert_eq!(code(&failed), 1, "{}{}", stdout(&failed), stderr(&failed));
    assert!(
        stderr(&failed).contains("unsafe data trigger") && stderr(&failed).contains("audit"),
        "{}",
        stderr(&failed)
    );

    let after = latest_snapshot(connection);
    assert_eq!(after.kind, pbps_model::StateKind::Failed);
    let reason = after
        .reason
        .as_ref()
        .map(|r| r.raw().to_owned())
        .unwrap_or_default();
    assert!(
        reason.contains("unsafe data trigger") && reason.contains("audit"),
        "a tool-composed refusal names its own trigger, and must survive on \
         the ledger unredacted: {reason}"
    );
    assert!(
        !reason.contains("its message is not recorded here"),
        "this is not a driver frame, and must never be run through the \
         driver-only redaction marker: {reason}"
    );
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_second_statement_failure_rolls_back_the_first_and_records_only_a_failed_attempt() {
    let own = OwnDatabase::new(&server(), "invariant_atomic");
    let connection = own.connection();
    let d = bootstrapped_demo(connection, "invariant-atomic", ONE_COLUMN);
    d.table(&ONE_COLUMN.replace(
        "  id:",
        "  first: {type: text}\n  second: {type: text}\n  id:",
    ));
    let plan = connected_artifact(&d, connection, false);
    let saved: pbps_model::SavedPlan =
        serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    assert_eq!(saved.changes.changes.len(), 2);
    // An event trigger fails the second DDL after the first really executed.
    // Sequence increments survive rollback, so this cannot pass by refusing
    // in preflight before either statement ran.
    on_server(
        connection,
        r#"
        CREATE SCHEMA witness;
        CREATE SEQUENCE witness.executed;
        CREATE FUNCTION witness.fail_second() RETURNS event_trigger LANGUAGE plpgsql AS $$
        BEGIN
          IF EXISTS (SELECT FROM pg_attribute WHERE attrelid = 'app.t'::regclass AND attname IN ('first', 'second') AND NOT attisdropped) THEN
            PERFORM nextval('witness.executed');
          END IF;
          IF (SELECT count(*) FROM pg_attribute WHERE attrelid = 'app.t'::regclass AND attname IN ('first', 'second') AND NOT attisdropped) = 2 THEN
            RAISE EXCEPTION 'invariant second statement failed';
          END IF;
        END $$;
        CREATE EVENT TRIGGER fail_second ON ddl_command_end WHEN TAG IN ('ALTER TABLE') EXECUTE FUNCTION witness.fail_second();
    "#,
    );
    let failed = approved_apply(&d, connection, &plan, &[]);
    assert_eq!(code(&failed), 1, "{}{}", stdout(&failed), stderr(&failed));
    assert_eq!(
        scalar(
            connection,
            "SELECT CASE WHEN is_called THEN last_value ELSE 0 END FROM witness.executed"
        ),
        2,
        "{}{}",
        stdout(&failed),
        stderr(&failed)
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_attribute WHERE attrelid = 'app.t'::regclass AND attname IN ('first', 'second') AND NOT attisdropped"
        ),
        0
    );
    let after = latest_snapshot(connection);
    assert_eq!(after.kind, pbps_model::StateKind::Failed);
    assert_eq!(
        after.plan_checksum.as_deref(),
        Some(plan_checksum(&plan).as_str())
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM public.__pbps_state WHERE kind = 'apply'"
        ),
        0
    );
    succeeds(d.run(&["verify", "--db", connection]));
    on_server(connection, "DROP EVENT TRIGGER fail_second");
    succeeds(approved_apply(&d, connection, &plan, &[]));
    assert_eq!(
        latest_snapshot(connection).kind,
        pbps_model::StateKind::Apply
    );
    succeeds(d.run(&["verify", "--db", connection]));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn the_cli_probe_counts_real_null_rows_before_any_statement_and_then_accepts_clean_data() {
    let own = OwnDatabase::new(&server(), "invariant_probe");
    let connection = own.connection();
    let d = bootstrapped_demo(connection, "invariant-probe", TWO_COLUMNS);
    on_server(
        connection,
        "INSERT INTO app.t (id, label) VALUES (1, NULL), (2, NULL), (3, 'present')",
    );
    d.table(&TWO_COLUMNS.replace(
        "label: {type: varchar(50)}",
        "label: {type: varchar(50), nullable: false}",
    ));
    let plan = connected_artifact(&d, connection, false);
    let refused = approved_apply(&d, connection, &plan, &["--allow", "not-null"]);
    assert_eq!(code(&refused), 1);
    assert!(
        stderr(&refused).contains("2 existing NULLs in"),
        "{}",
        stderr(&refused)
    );
    assert!(
        stderr(&refused).contains("nothing has been changed"),
        "{}",
        stderr(&refused)
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_attribute WHERE attrelid = 'app.t'::regclass AND attname = 'label' AND attnotnull"
        ),
        0
    );
    assert_eq!(
        scalar(connection, "SELECT count(*) FROM app.t WHERE label IS NULL"),
        2
    );
    on_server(
        connection,
        "UPDATE app.t SET label = 'filled' WHERE label IS NULL",
    );
    let applied = succeeds(approved_apply(
        &d,
        connection,
        &plan,
        &["--allow", "not-null"],
    ));
    assert!(
        stdout(&applied).contains("probe(s) passed"),
        "{}",
        stdout(&applied)
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_attribute WHERE attrelid = 'app.t'::regclass AND attname = 'label' AND attnotnull"
        ),
        1
    );
    succeeds(d.run(&["verify", "--db", connection]));
}

#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn constraint_triggers_pull_bootstrap_and_plan_without_duplicate_constraints() {
    use pbps_model::{Change, ModuleKind, SavedPlan};
    let own = OwnDatabase::new(&server(), "constraint_trigger229");
    let connection = own.connection();
    on_server(
        connection,
        "CREATE SCHEMA app;
        CREATE TABLE app.t (id integer PRIMARY KEY);
        CREATE TABLE app.child (id integer REFERENCES app.t(id));
        CREATE TABLE app.calls (id integer);
        CREATE FUNCTION app.fire() RETURNS trigger LANGUAGE plpgsql AS
            $$BEGIN INSERT INTO app.calls VALUES (NEW.id); RETURN NEW; END$$;
        CREATE CONSTRAINT TRIGGER \"constraint name\" AFTER INSERT ON app.t
            DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.fire()",
    );
    let d = Demo::new("constraint-trigger229-pull");
    succeeds(d.run(&["pull", "--db", connection]));
    let loaded = pbps_load::load_schema_dir(&d.dir.join("schema")).unwrap();
    let trigger = "app.t.constraint name".parse().unwrap();
    assert_eq!(
        loaded.schema.modules.len(),
        2,
        "{:?}",
        loaded.schema.modules
    );
    let module = &loaded.schema.modules[&trigger];
    assert_eq!(module.kind, ModuleKind::Trigger);
    assert!(
        module
            .definition
            .starts_with("CONSTRAINT AFTER INSERT ON app.t ")
    );
    assert!(module.definition.contains("DEFERRABLE INITIALLY DEFERRED"));
    // The four internal RI triggers stay out while their FK stays represented.
    assert_eq!(
        loaded.schema.tables[&"app.child".parse().unwrap()]
            .foreign_keys
            .len(),
        1
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_trigger WHERE tgisinternal
        AND tgrelid IN ('app.t'::regclass, 'app.child'::regclass)"
        ),
        4
    );
    tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(async {
            let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, connection)
                .await
                .unwrap();
            let pulled = pbps_pg::catalog::introspect(&mut conn).await.unwrap();
            assert!(pulled.limitations.is_empty(), "{:?}", pulled.limitations);
        });
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&[
        "baseline",
        "--db",
        connection,
        "--reason",
        "adopt a user constraint trigger",
    ]));
    let plan = d.dir.join("adoption-plan.json");
    succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    let saved: SavedPlan = serde_json::from_str(&std::fs::read_to_string(plan).unwrap()).unwrap();
    assert!(saved.changes.is_empty(), "{:?}", saved.changes);

    // Bootstrap the actual serialized pull, then measure the promised timing.
    let rebuilt = OwnDatabase::new(&server(), "constraint_trigger229_rebuilt");
    let rebuilt = rebuilt.connection();
    on_server(rebuilt, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", rebuilt]));
    assert_eq!(
        latest_snapshot(rebuilt).schema.modules,
        loaded.schema.modules
    );
    assert_eq!(
        scalar(
            rebuilt,
            "SELECT count(*) FROM pg_trigger WHERE tgname='constraint name'
        AND NOT tgisinternal AND tgconstraint <> 0 AND tgdeferrable AND tginitdeferred"
        ),
        1
    );
    on_server(
        rebuilt,
        "BEGIN; INSERT INTO app.t VALUES (1);
        DO $$BEGIN ASSERT (SELECT count(*) FROM app.calls) = 0; END$$;
        SET CONSTRAINTS ALL IMMEDIATE;
        DO $$BEGIN ASSERT (SELECT count(*) FROM app.calls) = 1; END$$; ROLLBACK",
    );
    assert!(try_on_server(rebuilt, "INSERT INTO app.child VALUES (99)").is_err());

    // An edit takes the ordinary module drop/create path and retains CONSTRAINT.
    let mut paths = vec![d.dir.join("schema")];
    let path = loop {
        let path = paths.pop().expect("the pulled trigger declaration");
        if path.is_dir() {
            paths.extend(std::fs::read_dir(path).unwrap().map(|e| e.unwrap().path()));
        } else if std::fs::read_to_string(&path)
            .unwrap()
            .lines()
            .any(|l| l.starts_with("trigger:"))
        {
            break path;
        }
    };
    let text = std::fs::read_to_string(&path).unwrap();
    std::fs::write(
        path,
        text.replace("INITIALLY DEFERRED", "INITIALLY IMMEDIATE"),
    )
    .unwrap();
    let plan = connected_artifact(&d, rebuilt, false);
    let saved: SavedPlan = serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    assert_eq!(saved.changes.changes.len(), 1, "{:?}", saved.changes);
    assert!(
        matches!(&saved.changes.changes[0].change, Change::AlterModule { id, .. } if id == &trigger)
    );
    succeeds(approved_apply(&d, rebuilt, &plan, &[]));
    assert_eq!(
        scalar(
            rebuilt,
            "SELECT count(*) FROM pg_trigger WHERE tgname='constraint name'
        AND tgconstraint <> 0 AND tgdeferrable AND NOT tginitdeferred"
        ),
        1
    );
    succeeds(d.run(&["verify", "--db", rebuilt]));
}

const CONSTRAINT_TRIGGER_TABLE: &str = "table: app.t\ncolumns:\n  code: {type: varchar(20), nullable: false}\n  label: {type: text, nullable: false}\nprimary_key: {name: pk_t, columns: [code]}\n";

fn adopted_constraint_trigger(connection: &str, slug: &str, function_body: &str) -> Demo {
    let d = bootstrapped_demo(connection, slug, CONSTRAINT_TRIGGER_TABLE);
    on_server(
        connection,
        &format!(
            "CREATE FUNCTION app.late() RETURNS trigger LANGUAGE plpgsql AS $$ {function_body} $$;
        CREATE CONSTRAINT TRIGGER late AFTER INSERT ON app.t
            DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION app.late()"
        ),
    );
    adopt_constraint_trigger_modules(connection, &d);
    d
}

fn adopt_constraint_trigger_modules(connection: &str, d: &Demo) {
    let modules = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
        .unwrap()
        .block_on(async {
            let mut conn = pbps_db::Conn::connect(pbps_db::Driver::Postgres, connection)
                .await
                .unwrap();
            pbps_pg::catalog::introspect(&mut conn)
                .await
                .unwrap()
                .schema
                .modules
        });
    for (index, (id, module)) in modules.into_iter().enumerate() {
        let body = module
            .definition
            .lines()
            .map(|line| format!("  {line}\n"))
            .collect::<String>();
        let kind = module.kind.as_str();
        let identity = match &id {
            pbps_model::ModuleId::Trigger { on, name } => {
                format!("{}.{name}\non: {on}", on.schema, on = on.raw())
            }
            pbps_model::ModuleId::Named(_) | pbps_model::ModuleId::Routine(_) => {
                id.raw().to_string()
            }
        };
        std::fs::write(
            d.dir.join(format!("schema/adopted-{index}.yml")),
            format!("{kind}: {identity}\ndefinition: |-\n{body}"),
        )
        .unwrap();
    }
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&[
        "baseline",
        "--db",
        connection,
        "--reason",
        "adopt a deferred trigger",
    ]));
}

