/// #1619: an unnamed key's index is `<table>_pkey`, built at the end of the
/// `CREATE TABLE`, after the defaults. A connected plan whose new table's
/// default names it is refused, writing no artifact; two plans deploy it.
/// While an unmanaged relation holds that name, the engine numbers the key's
/// index instead and the literal names what holds it, so the plan is not
/// refused and applies.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_default_naming_an_unnamed_keys_index_is_refused_unless_the_name_is_held() {
    let own = OwnDatabase::new(&server(), "names_generated_key");
    let connection = own.connection();
    let d = bootstrapped_demo(
        connection,
        "names_generated_key",
        "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\nprimary_key: [id]\n",
    );
    let new_table = |table: &str, default: &str| {
        std::fs::write(
            d.dir.join(format!("schema/app.{table}.yml")),
            format!(
                "table: app.{table}\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 label: {{type: text, default: \"{default}\"}}\nprimary_key: [id]\n"
            ),
        )
        .unwrap();
    };
    let names = |what: &str| format!("('app.{what}'::regclass)::text");

    new_table("n", &names("n_pkey"));
    succeeds(d.run(&["plan"]));
    d.commit();
    let artifact = d.dir.join("refused-plan.json");
    let refused = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    let why = stderr(&refused);
    assert!(
        why.contains("app.n.label's default or expression names app.n_pkey"),
        "{why}"
    );
    assert!(!artifact.exists(), "a refused plan writes no artifact");

    // The remedy: the table without the default first, then the default.
    new_table("n", "''");
    let first = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &first, &[]));
    new_table("n", &names("n_pkey"));
    let second = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &second, &[]));

    // Negative: `app.m_pkey` is held, so the key's index is `m_pkey1`, and
    // the default names the table that holds the name.
    on_server(connection, "CREATE TABLE app.m_pkey (x integer)");
    new_table("m", &names("m_pkey"));
    let held = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &held, &[]));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_index WHERE indrelid = 'app.m'::regclass \
             AND indisprimary AND indexrelid = 'app.m_pkey1'::regclass"
        ),
        1
    );
}

/// #1645: a connected plan reads what holds an unnamed key's candidate names
/// now, and walks the plan to the key, so the key's index arrives under the
/// name the engine will choose. Each case below was approved before and
/// failed its apply; each is refused, writing no artifact. With `--staged`
/// it is refused the same way, ahead of that mode's own refusal of a plan of
/// more than one change, which the last case is not:
/// - a second key cutting to the first's name, whose index is `_pkey1`;
/// - a key whose name an index the plan drops first holds now;
/// - an unnamed key replaced, with a default set between its drop and its
///   add naming its index;
/// - a key numbered past a check constraint's name in its schema.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_key_named_by_what_holds_its_candidates_when_it_is_created_is_refused() {
    let names = |what: &str| format!("('app.{what}'::regclass)::text");
    let new_table = |table: &str, default: &str| {
        format!(
            "table: app.{table}\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
             label: {{type: text, default: \"{default}\"}}\nprimary_key: [id]\n"
        )
    };
    let t = |label: &str, key: &str, rest: &str| {
        format!(
            "table: app.t\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
             k: {{type: integer, nullable: false}}\n  label: {label}\n\
             primary_key: {key}\n{rest}"
        )
    };
    let kept = "indexes:\n  n_pkey: {columns: [k]}\nchecks:\n  q_pkey: k > 0\n";
    let numbered = format!("{}_pkey1", "s".repeat(57));
    let long = |last: char| format!("{}{last}", "s".repeat(61));
    let cases = [
        // Two tables cutting to one name: the second key's index is `_pkey1`.
        (
            "two_keys",
            vec![
                (long('a'), new_table(&long('a'), "''")),
                (long('b'), new_table(&long('b'), &names(&numbered))),
            ],
            numbered.clone(),
        ),
        // `app.t`'s index `n_pkey` dropped first frees the name for
        // `app.n`'s key.
        (
            "freed_holder",
            vec![
                (
                    "t".to_owned(),
                    t("{type: text}", "[id]", "checks:\n  q_pkey: k > 0\n"),
                ),
                ("n".to_owned(), new_table("n", &names("n_pkey"))),
            ],
            "n_pkey".to_owned(),
        ),
        // `app.t`'s key replaced, and a default naming its index set
        // between its drop and its add.
        (
            "replaced_key",
            vec![(
                "t".to_owned(),
                t(
                    &format!("{{type: text, default: \"{}\"}}", names("t_pkey")),
                    "[id, k]",
                    kept,
                ),
            )],
            "t_pkey".to_owned(),
        ),
        // The check `q_pkey` on `app.t` numbers `app.q`'s key.
        (
            "constraint_holder",
            vec![("q".to_owned(), new_table("q", &names("q_pkey1")))],
            "q_pkey1".to_owned(),
        ),
    ];
    for (case, files, named) in cases {
        let slug = format!("key_holders_{case}");
        let own = OwnDatabase::new(&server(), &slug);
        let connection = own.connection();
        let d = bootstrapped_demo(connection, &slug, &t("{type: text}", "[id]", kept));
        for (table, body) in &files {
            std::fs::write(d.dir.join(format!("schema/app.{table}.yml")), body).unwrap();
        }
        succeeds(d.run(&["plan"]));
        d.commit();
        for staged in [false, true] {
            let artifact = d.dir.join("refused-plan.json");
            let mut args = vec![
                "plan",
                "--db",
                connection,
                "--out",
                artifact.to_str().unwrap(),
            ];
            if staged {
                args.push("--staged");
            }
            let out = d.run(&args);
            assert_ne!(code(&out), 0, "{case}, staged {staged}: {}", stdout(&out));
            let why = stderr(&out);
            assert!(why.contains(&format!("names app.{named}")), "{case}: {why}");
            assert!(
                !artifact.exists(),
                "{case}: a refused plan writes no artifact"
            );
        }
        if case == "constraint_holder" {
            // Negative: without the default the plan applies, and the key
            // is numbered where the engine puts it.
            std::fs::write(d.dir.join("schema/app.q.yml"), new_table("q", "''")).unwrap();
            let plan = connected_artifact(&d, connection, false);
            succeeds(approved_apply(&d, connection, &plan, &[]));
            assert_eq!(
                scalar(
                    connection,
                    "SELECT count(*) FROM pg_index WHERE indisprimary \
                     AND indexrelid = 'app.q_pkey1'::regclass"
                ),
                1
            );
        }
    }
}

/// #1593: `regclass` input cuts a name part to 63 bytes, silently, so a
/// default naming 64 `a`s names the 63-`a` index the plan creates later. The
/// connected plan is refused, writing no artifact, though the two spellings
/// differ.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_default_naming_a_later_index_past_the_identifier_limit_is_refused() {
    let own = OwnDatabase::new(&server(), "names_long_index");
    let connection = own.connection();
    let columns = "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\n";
    let label = |default: &str| format!("  label: {{type: text, default: \"{default}\"}}\n");
    let index = format!("indexes:\n  {}:\n    columns: [id]\n", "a".repeat(63));
    let d = bootstrapped_demo(
        connection,
        "names_long_index",
        &format!("{columns}{}primary_key: [id]\n", label("''")),
    );
    let named = format!("('app.{}'::regclass)::text", "a".repeat(64));
    d.table(&format!(
        "{columns}{}primary_key: [id]\n{index}",
        label(&named)
    ));
    succeeds(d.run(&["plan"]));
    d.commit();
    let artifact = d.dir.join("refused-plan.json");
    let refused = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    let why = stderr(&refused);
    assert!(
        why.contains(&format!("names app.{}", "a".repeat(63))),
        "{why}"
    );
    assert!(!artifact.exists(), "a refused plan writes no artifact");
}

/// #1629: pbps's own statement text is ASCII, so a database in an encoding
/// that cannot hold `—` or `…` (measured: `LATIN1`, `EUC_JP` and others) is
/// bootstrapped, and a plan whose script writes declared rows applies there.
/// That script carries the row checks' `RAISE` text, which pbps writes.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_database_in_a_non_utf8_encoding_is_bootstrapped_and_deployed() {
    for encoding in ["LATIN1", "EUC_JP"] {
        let slug = format!("encoded_{}", encoding.to_lowercase());
        let own = OwnDatabase::encoded(&server(), &slug, encoding);
        let connection = own.connection();
        let d = bootstrapped_demo(
            connection,
            &slug,
            "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\nprimary_key: [id]\n",
        );
        d.table(
            "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\n  \
             label: {type: text}\nprimary_key: [id]\n\
             data:\n  mode: ensure\n  rows:\n    1: {label: one}\n",
        );
        let plan = connected_artifact(&d, connection, false);
        succeeds(approved_apply(&d, connection, &plan, &[]));
        assert_eq!(
            scalar(connection, "SELECT count(*) FROM app.t WHERE label = 'one'"),
            1,
            "{encoding}"
        );
    }
}

/// #1627 review: `regclass` input cuts a name to 63 bytes of the database's
/// encoding. In a single-byte database, 62 `a`s and `é` are 63 bytes, so a
/// default naming that unmanaged table names it whole. It is not the 62-`a`
/// index the plan creates later, which a cut by UTF-8 bytes would read it as.
/// The plan writes its artifact and applies.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_literal_cut_differs_by_encoding_so_a_single_byte_name_is_not_refused() {
    let own = OwnDatabase::encoded(&server(), "single_byte_literal", "LATIN1");
    let connection = own.connection();
    let columns = "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\n";
    let label = |default: &str| format!("  label: {{type: text, default: \"{default}\"}}\n");
    let d = bootstrapped_demo(
        connection,
        "single_byte_literal",
        &format!("{columns}{}primary_key: [id]\n", label("''")),
    );
    let external = format!("{}é", "a".repeat(62));
    on_server(
        connection,
        &format!("CREATE TABLE app.\"{external}\" (id integer)"),
    );
    // YAML's double quotes take `\"` for the identifier's quotes.
    d.table(&format!(
        "{columns}{}primary_key: [id]\nindexes:\n  {}:\n    columns: [id]\n",
        label(&format!("('app.\\\"{external}\\\"'::regclass)::text")),
        "a".repeat(62)
    ));
    let plan = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &plan, &[]));
    assert_eq!(
        scalar(
            connection,
            &format!(
                "SELECT count(*) FROM pg_class WHERE relname = '{}' \
                 AND relnamespace = 'app'::regnamespace AND relkind = 'i'",
                "a".repeat(62)
            )
        ),
        1
    );
}

/// #1576: PostgreSQL resolves `'app.ix_new'::regclass` when the default is
/// set, and the differ sets a default before it creates an index. A connected
/// plan that does both is refused, writing no artifact, with a two-plan
/// remedy; the two plans then deploy it.
#[test]
#[ignore = "needs a live PostgreSQL; see scripts/live-tests-pg.sh"]
fn a_default_naming_an_index_the_plan_creates_later_is_refused_and_two_plans_deploy_it() {
    let own = OwnDatabase::new(&server(), "names_later_index");
    let connection = own.connection();
    let columns = "table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\n";
    let label = |default: &str| format!("  label: {{type: text, default: \"{default}\"}}\n");
    let index = "indexes:\n  ix_new:\n    columns: [id]\n";
    let named = "('app.ix_new'::regclass)::text";
    let d = bootstrapped_demo(
        connection,
        "names_later_index",
        &format!("{columns}{}primary_key: [id]\n", label("''")),
    );

    d.table(&format!(
        "{columns}{}primary_key: [id]\n{index}",
        label(named)
    ));
    succeeds(d.run(&["plan"]));
    d.commit();
    let artifact = d.dir.join("refused-plan.json");
    let refused = d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        artifact.to_str().unwrap(),
    ]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    let why = stderr(&refused);
    assert!(
        why.contains("app.t.label's default names app.ix_new"),
        "{why}"
    );
    assert!(why.contains("second plan"), "{why}");
    assert!(!artifact.exists(), "a refused plan writes no artifact");

    // The remedy: the index alone first, then the default.
    d.table(&format!(
        "{columns}{}primary_key: [id]\n{index}",
        label("''")
    ));
    let first = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &first, &[]));
    d.table(&format!(
        "{columns}{}primary_key: [id]\n{index}",
        label(named)
    ));
    let second = connected_artifact(&d, connection, false);
    succeeds(approved_apply(&d, connection, &second, &[]));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_attrdef WHERE adrelid = 'app.t'::regclass \
             AND pg_get_expr(adbin, adrelid) LIKE '%ix_new%'"
        ),
        1
    );
}

/// A bootstrap creates a new table's prefix before the functions its
/// expressions call, then adds the generated suffix and sets the default
/// after those functions, as `plan --db` does (DEC-1503.1). Both expressions
/// bootstrap an empty database, verify and replan empty. The negative: a
/// table that calls nothing stays before the functions. A partition waits
/// for its parent's completed columns, including when a built-in shares a
/// declared function's name, through bootstrap and `plan --db` alike.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_bootstrap_creates_what_a_new_table_calls_before_it() {
    let server = server();
    let source = OwnDatabase::new(&server, "boot-1585");
    let target = OwnDatabase::new(&server, "boot-1585-target");
    let planned = OwnDatabase::new(&server, "boot-1585-planned");
    let (src, tgt) = (
        source.connection().to_owned(),
        target.connection().to_owned(),
    );
    on_server(
        &src,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.zz() RETURNS text LANGUAGE sql IMMUTABLE RETURN 'x'; \
         CREATE FUNCTION app.zz_double(i integer) RETURNS integer \
             LANGUAGE sql IMMUTABLE RETURN i * 2; \
         CREATE TABLE app.t (id integer, note text DEFAULT app.zz(), \
             g integer GENERATED ALWAYS AS (app.zz_double(id)) STORED); \
         CREATE TABLE app.a_plain (id integer); \
         CREATE TABLE app.ev (k integer NOT NULL, \
             g integer GENERATED ALWAYS AS (app.zz_double(k)) STORED) PARTITION BY RANGE (k); \
         CREATE TABLE app.ev_1 PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
         CREATE FUNCTION app.abs() RETURNS integer LANGUAGE sql IMMUTABLE RETURN 1; \
         CREATE TABLE app.ab (k integer NOT NULL, \
             g integer GENERATED ALWAYS AS (abs(k)) STORED) PARTITION BY RANGE (k); \
         CREATE TABLE app.ab_1 PARTITION OF app.ab FOR VALUES FROM (0) TO (10)",
    );
    let d = Demo::new("boot-1585");
    succeeds(d.run(&["pull", "--db", &src]));
    d.commit();

    // Relation names precede the functions; only the expressions wait.
    let sql = d.dir.join("boot.sql");
    succeeds(d.run(&["bootstrap", "--sql", sql.to_str().unwrap()]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("{needle} is not in:\n{script}"))
    };
    let table = at("CREATE TABLE \"app\".\"t\"");
    let zz = at("CREATE FUNCTION \"app\".\"zz\"\n");
    let double = at("CREATE FUNCTION \"app\".\"zz_double\"");
    let generated = at("ALTER TABLE \"app\".\"t\" ADD COLUMN \"g\"");
    assert!(table < double && double < generated, "{script}");
    assert!(
        table < zz && zz < at("ALTER TABLE \"app\".\"t\" ALTER COLUMN \"note\" SET DEFAULT"),
        "{script}"
    );
    let prefix = &script[table..script[table..].find(") USING heap;").unwrap() + table];
    assert!(
        prefix.contains("\"id\" integer") && prefix.contains("\"note\" text"),
        "{script}"
    );
    assert!(!prefix.contains("GENERATED ALWAYS"), "{script}");
    assert!(
        at("CREATE TABLE \"app\".\"a_plain\"") < at("CREATE FUNCTION \"app\".\"zz\"\n"),
        "{script}"
    );
    // Each partition follows the last column its parent adds (#1586).
    assert!(
        at("ALTER TABLE \"app\".\"ev\" ADD COLUMN \"g\"") < at("CREATE TABLE \"app\".\"ev_1\""),
        "{script}"
    );
    assert!(
        at("ALTER TABLE \"app\".\"ab\" ADD COLUMN \"g\"") < at("CREATE TABLE \"app\".\"ab_1\""),
        "{script}"
    );

    on_server(&tgt, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", &tgt]));
    succeeds(d.run(&["verify", "--db", &tgt]));
    let next = succeeds(d.run(&["plan", "--db", &tgt]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    on_server(&tgt, "INSERT INTO app.t (id) VALUES (3)");
    assert_eq!(
        scalar(
            &tgt,
            "SELECT count(*) FROM app.t WHERE note = 'x' AND g = 6"
        ),
        1
    );
    on_server(&tgt, "INSERT INTO app.ev (k) VALUES (4)");
    assert_eq!(scalar(&tgt, "SELECT count(*) FROM app.ev_1 WHERE g = 8"), 1);

    // The same tables and functions through `plan --db` and `apply`
    // (#1586): a project declaring only the unrelated table bootstraps the
    // database, then gains the rest, which one plan creates. Its own ids
    // file, minted for what it declares: a bootstrap records every uid it is
    // given, built or not (#1600).
    let pln = planned.connection().to_owned();
    on_server(&pln, "CREATE SCHEMA app");
    let d = {
        let later = Demo::new("boot-1585-planned");
        std::fs::copy(
            d.dir.join("schema/app.a_plain.yml"),
            later.dir.join("schema/app.a_plain.yml"),
        )
        .unwrap();
        succeeds(later.run(&["plan"]));
        later.commit();
        succeeds(later.run(&["bootstrap", "--db", &pln]));
        for entry in std::fs::read_dir(d.dir.join("schema")).unwrap() {
            let path = entry.unwrap().path();
            std::fs::copy(
                &path,
                later.dir.join("schema").join(path.file_name().unwrap()),
            )
            .unwrap();
        }
        succeeds(later.run(&["plan"]));
        later.commit();
        later
    };
    let plan = d.dir.join("first.json");
    succeeds(d.run(&["plan", "--db", &pln, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(&d, &pln, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &pln]));
    let next = succeeds(d.run(&["plan", "--db", &pln]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// The offline `plan` uses the same creation parts as `plan --db`
/// (DEC-1503.1): a new table creates its prefix before the function its
/// generated suffix calls, then adds that suffix after the function.
/// A default calling a declared function is set after it too. Negative: a
/// table that calls nothing keeps its place ahead of the functions. The
/// script is the one `--out` records, so the preview and its artifact agree.
#[test]
fn an_offline_plan_creates_what_a_new_table_calls_before_it() {
    let d = Demo::new("preview-1598");
    let schema = d.dir.join("schema");
    std::fs::write(
        schema.join("app.zz%28%29.function.yml"),
        "function: app.zz()\ndefinition: |-\n  () RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT 'x' $$\n",
    )
    .unwrap();
    std::fs::write(
        schema.join("app.zz_double%28integer%29.function.yml"),
        "function: app.zz_double(integer)\ndefinition: |-\n  (i integer) RETURNS integer \
         LANGUAGE sql IMMUTABLE AS $$ SELECT i * 2 $$\n",
    )
    .unwrap();
    std::fs::write(
        schema.join("app.gen.yml"),
        "table: app.gen\ncolumns:\n  id: {type: integer, nullable: false}\n  \
         g: {type: integer, generated: {expression: 'app.zz_double(id)', stored: true}}\n",
    )
    .unwrap();
    std::fs::write(
        schema.join("app.dflt.yml"),
        "table: app.dflt\ncolumns:\n  id: {type: integer, nullable: false}\n  \
         note: {type: text, default: 'app.zz()'}\n",
    )
    .unwrap();
    std::fs::write(
        schema.join("app.a_plain.yml"),
        "table: app.a_plain\ncolumns:\n  id: {type: integer, nullable: false}\n",
    )
    .unwrap();
    // Mints the identities, which the preview needs to split a default out.
    succeeds(d.run(&["plan"]));
    let sql = d.dir.join("preview.sql");
    let plan = d.dir.join("preview.json");
    succeeds(d.run(&[
        "plan",
        "--sql",
        sql.to_str().unwrap(),
        "--out",
        plan.to_str().unwrap(),
    ]));
    let script = std::fs::read_to_string(&sql).unwrap();
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("{needle} is not in:\n{script}"))
    };
    let zz = at("CREATE FUNCTION \"app\".\"zz\"\n");
    let double = at("CREATE FUNCTION \"app\".\"zz_double\"");
    // Keeping the prefix early exposes the relation before the generation binds.
    let prefix = at("CREATE TABLE \"app\".\"gen\" (\n    \"id\" integer NOT NULL\n) USING heap;");
    let generated = at("ALTER TABLE \"app\".\"gen\" ADD COLUMN \"g\"");
    assert!(prefix < double && double < generated, "{script}");
    // A default is split out of its table and set after the function.
    assert!(
        at("CREATE TABLE \"app\".\"dflt\"") < zz && zz < at("SET DEFAULT"),
        "{script}"
    );
    // Nothing about the table that calls nothing moves it.
    assert!(at("CREATE TABLE \"app\".\"a_plain\"") < zz, "{script}");
}

/// An offline preview that drops a module cannot read what depends on it, so
/// the dependents pass is skipped and said so: in human output as a line, and
/// in JSON as a note with a stable id (SPEC §9.8, #1982 review), never as
/// silence a consumer would read as "no dependents". Negative: a preview that
/// drops no module carries no such note.
#[test]
fn an_offline_plan_names_the_catalog_fact_it_could_not_read_in_json_too() {
    let d = Demo::new("preview-skip-notes");
    let function = d.dir.join("schema/app.zz%28%29.function.yml");
    std::fs::write(
        &function,
        "function: app.zz()\ndefinition: |-\n  () RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT 'x' $$\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let notes = |report: &serde_json::Value| {
        report["findings"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|f| f["id"] == "plan.module-dependents-unread")
            .map(|f| f["severity"].as_str().unwrap().to_owned())
            .collect::<Vec<_>>()
    };
    let unchanged = json_output(succeeds(d.run(&["plan", "--format", "json"])));
    assert!(notes(&unchanged).is_empty(), "{unchanged}");

    std::fs::remove_file(&function).unwrap();
    let dropped = json_output(succeeds(d.run(&["plan", "--check", "--format", "json"])));
    assert_eq!(notes(&dropped), ["note"], "{dropped}");
    let human = succeeds(d.run(&["plan", "--check"]));
    assert!(
        stdout(&human).contains("What depends on a dropped or rebuilt module"),
        "{}",
        stdout(&human)
    );
}

/// A bootstrap whose reordering moves a relation after an expression naming
/// it in a literal is refused by name before any script or DDL, as `plan
/// --db` refuses it (DEC-1576.1, #1599 review): an expression index on
/// `abs(k)` beside a declared `app.abs()` follows the function, and a
/// default reading `'app.ix_a'::regclass` would otherwise roll the bootstrap
/// back. So would a function whose body reads it, through its own
/// `search_path` from another schema too. The database stays empty,
/// and the refusal's two-plan remedy deploys it. An unqualified name, which
/// only the target can settle, is refused before `--sql` writes a script
/// beside `--db`. Negative: without the literals the same declarations
/// bootstrap.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_bootstrap_naming_a_relation_its_reordering_moves_later_is_refused() {
    let server = server();
    let source = OwnDatabase::new(&server, "boot-later");
    let target = OwnDatabase::new(&server, "boot-later-target");
    let plain = OwnDatabase::new(&server, "boot-later-plain");
    let both = OwnDatabase::new(&server, "boot-later-both");
    let (src, tgt) = (
        source.connection().to_owned(),
        target.connection().to_owned(),
    );
    on_server(
        &src,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.abs() RETURNS integer LANGUAGE sql IMMUTABLE RETURN 1; \
         CREATE TABLE app.a (k integer); \
         CREATE INDEX ix_a ON app.a (abs(k)); \
         CREATE TABLE app.z (r text DEFAULT ('app.ix_a'::regclass)::text); \
         CREATE FUNCTION app.reader() RETURNS integer LANGUAGE sql \
             RETURN ('app.ix_a'::regclass)::oid::integer; \
         CREATE SCHEMA other; \
         CREATE FUNCTION other.across() RETURNS integer LANGUAGE sql \
             SET search_path = app, pg_temp \
             AS $$ SELECT ('ix_a'::regclass)::oid::integer $$",
    );
    let d = Demo::new("boot-later");
    succeeds(d.run(&["pull", "--db", &src]));
    d.commit();
    let z = d.dir.join("schema/app.z.yml");
    let declared = std::fs::read_to_string(&z).unwrap();
    let reader = d.dir.join("schema/app.reader%28%29.function.yml");
    let reads = std::fs::read_to_string(&reader).unwrap();
    let across = d.dir.join("schema/other.across%28%29.function.yml");
    let reads_across = std::fs::read_to_string(&across).unwrap();

    let sql = d.dir.join("boot.sql");
    for args in [
        vec!["bootstrap", "--sql", sql.to_str().unwrap()],
        vec!["bootstrap", "--db", &tgt],
    ] {
        let o = d.run(&args);
        assert_ne!(code(&o), 0, "{args:?}: {}", stdout(&o));
        assert!(
            stderr(&o).contains("names a relation this plan creates later")
                && stderr(&o).contains("app.z.r's default or expression names app.ix_a")
                && stderr(&o).contains("app.reader() names app.ix_a")
                && stderr(&o).contains("other.across() names app.ix_a"),
            "{args:?}: {}",
            stderr(&o)
        );
    }
    assert!(!sql.exists(), "no script is written");
    assert_eq!(
        scalar(
            &tgt,
            "SELECT count(*) FROM pg_namespace WHERE nspname = 'app'"
        ),
        0,
        "nothing was built"
    );

    // The remedy: the expressions in a second plan, once the index stands.
    std::fs::write(&z, "table: app.z\ncolumns:\n  r: {type: text}\n").unwrap();
    std::fs::remove_file(&reader).unwrap();
    std::fs::remove_file(&across).unwrap();
    d.commit();
    on_server(&tgt, "CREATE SCHEMA app; CREATE SCHEMA other");
    succeeds(d.run(&["bootstrap", "--db", &tgt]));
    std::fs::write(&z, &declared).unwrap();
    std::fs::write(&reader, &reads).unwrap();
    std::fs::write(&across, &reads_across).unwrap();
    d.commit();
    let plan = d.dir.join("second.json");
    succeeds(d.run(&["plan", "--db", &tgt, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(&d, &tgt, &plan, &[]));
    let next = succeeds(d.run(&["plan", "--db", &tgt]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Unqualified, the name may be `pg_catalog`'s: asked of the target,
    // and refused before `--sql` writes a script beside `--db`.
    std::fs::remove_file(&reader).unwrap();
    std::fs::remove_file(&across).unwrap();
    std::fs::write(
        &z,
        declared.replace("'app.ix_a'::regclass", "'ix_a'::regclass"),
    )
    .unwrap();
    d.commit();
    let b = both.connection().to_owned();
    on_server(&b, "CREATE SCHEMA app");
    let script = d.dir.join("both.sql");
    let o = d.run(&["bootstrap", "--sql", script.to_str().unwrap(), "--db", &b]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("app.z.r's default or expression names app.ix_a"),
        "{}",
        stderr(&o)
    );
    assert!(!script.exists(), "no script is written");

    // Negative: no literal, nothing refused.
    let p = plain.connection().to_owned();
    std::fs::write(
        &z,
        "table: app.z\ncolumns:\n  r: {type: text, default: \"'x'\"}\n",
    )
    .unwrap();
    d.commit();
    on_server(&p, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", &p]));
}
/// #1604: a routine's own `SET search_path`, in the form `pull` declares
/// (`SET search_path TO 'other', 'pg_temp'`), is where its string body's
/// unqualified name is looked up. `app.reads()` names `'k'`, which is
/// `other.k`; the bootstrap's reordering moves an index `app.k` after it,
/// which the routine never names, so the plan is not refused and deploys.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_bootstrap_reads_a_routines_own_search_path_as_pulled() {
    let server = server();
    let source = OwnDatabase::new(&server, "boot-own-path");
    let target = OwnDatabase::new(&server, "boot-own-path-target");
    let (src, tgt) = (
        source.connection().to_owned(),
        target.connection().to_owned(),
    );
    on_server(
        &src,
        "CREATE SCHEMA other; \
         CREATE TABLE other.k (id integer); \
         CREATE SCHEMA app; \
         CREATE FUNCTION app.abs() RETURNS integer LANGUAGE sql IMMUTABLE RETURN 1; \
         CREATE TABLE app.a (k integer); \
         CREATE INDEX k ON app.a (abs(k)); \
         CREATE FUNCTION app.reads() RETURNS integer LANGUAGE sql \
             SET search_path = other, pg_temp \
             AS $$ SELECT ('k'::regclass)::oid::integer $$",
    );
    let d = Demo::new("boot-own-path");
    succeeds(d.run(&["pull", "--db", &src]));
    d.commit();
    let declared =
        std::fs::read_to_string(d.dir.join("schema/app.reads%28%29.function.yml")).unwrap();
    assert!(
        declared.contains("SET search_path TO 'other', 'pg_temp'"),
        "{declared}"
    );
    on_server(&tgt, "CREATE SCHEMA app; CREATE SCHEMA other");
    succeeds(d.run(&["bootstrap", "--db", &tgt]));
    assert_eq!(
        scalar(
            &tgt,
            "SELECT count(*) FROM (SELECT 1) AS one \
             WHERE app.reads() = 'other.k'::regclass::oid::integer"
        ),
        1,
        "the body reads other.k"
    );
}

/// #1600: a bootstrap records only the uids of what it built. Declarations
/// without `app.t` bootstrap a database whose ids file names `app.t` too;
/// once `app.t` is declared again, the next `plan --db` creates it, `apply`
/// builds it, and verify and a replan are clean. The same holds for a
/// `baseline` or a forced `snapshot` taken while a declared table is
/// missing: the next plan creates it. Negative: a bootstrap of the full declarations still records
/// every uid, so its replan is clean.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_table_bootstrap_did_not_build_is_created_by_the_next_plan() {
    let server = server();
    let source = OwnDatabase::new(&server, "boot-ids");
    let partial = OwnDatabase::new(&server, "boot-ids-partial");
    let full = OwnDatabase::new(&server, "boot-ids-full");
    let (src, part, whole) = (
        source.connection().to_owned(),
        partial.connection().to_owned(),
        full.connection().to_owned(),
    );
    on_server(
        &src,
        "CREATE SCHEMA app; \
         CREATE TABLE app.t (id integer, note text DEFAULT 'z'); \
         CREATE TABLE app.a_plain (id integer)",
    );
    let d = Demo::new("boot-ids");
    succeeds(d.run(&["pull", "--db", &src]));
    d.commit();
    let schema = d.dir.join("schema");
    let aside = d.dir.join("aside");
    std::fs::create_dir_all(&aside).unwrap();
    let held_back = ["app.t.yml"];

    // Without `app.t`: a bootstrap of `a_plain` alone.
    for file in held_back {
        std::fs::rename(schema.join(file), aside.join(file)).unwrap();
    }
    d.commit();
    on_server(&part, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", &part]));
    for file in held_back {
        std::fs::rename(aside.join(file), schema.join(file)).unwrap();
    }
    d.commit();

    // Declared again, it is created by the next plan.
    let plan = d.dir.join("rest.json");
    let o = succeeds(d.run(&["plan", "--db", &part, "--out", plan.to_str().unwrap()]));
    assert!(stdout(&o).contains("app.t"), "{}", stdout(&o));
    succeeds(approved_apply(&d, &part, &plan, &[]));
    assert_eq!(
        scalar(
            &part,
            "SELECT count(*) FROM pg_class WHERE oid = to_regclass('app.t')"
        ),
        1,
        "app.t is built"
    );
    succeeds(d.run(&["verify", "--db", &part]));
    let next = succeeds(d.run(&["plan", "--db", &part]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // A baseline taken while a declared table is missing records it as
    // missing, not held: the next plan creates it.
    on_server(&part, "DROP TABLE app.a_plain");
    succeeds(d.run(&[
        "baseline",
        "--db",
        &part,
        "--reason",
        "a_plain dropped by hand",
    ]));
    let again = d.dir.join("again.json");
    let o = succeeds(d.run(&["plan", "--db", &part, "--out", again.to_str().unwrap()]));
    assert!(stdout(&o).contains("app.a_plain"), "{}", stdout(&o));
    succeeds(approved_apply(&d, &part, &again, &[]));
    succeeds(d.run(&["verify", "--db", &part]));
    let next = succeeds(d.run(&["plan", "--db", &part]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // And a forced snapshot, the same way.
    on_server(&part, "DROP TABLE app.a_plain");
    succeeds(d.run(&["snapshot", "--db", &part, "--force"]));
    let third = d.dir.join("third.json");
    let o = succeeds(d.run(&["plan", "--db", &part, "--out", third.to_str().unwrap()]));
    assert!(stdout(&o).contains("app.a_plain"), "{}", stdout(&o));
    succeeds(approved_apply(&d, &part, &third, &[]));
    succeeds(d.run(&["verify", "--db", &part]));

    // Negative: the full declarations, every uid recorded.
    on_server(&whole, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", &whole]));
    succeeds(d.run(&["verify", "--db", &whole]));
    let next = succeeds(d.run(&["plan", "--db", &whole]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
}

/// A standing range-partitioned parent's columns change through the CLI
/// (#1687), on a tree holding rows: a range partition with its own default,
/// one with its own NOT NULL, and a table attached with a NOT NULL of its
/// own. A column is added, retyped, renamed with the key column, its default
/// changed and its NOT NULL dropped and set, then dropped; each saved plan
/// applies, verifies and replans empty, the engine recursing each into every
/// partition, and the partitions keep their own. The cost estimate names the
/// recursion. A key column's retype and drop are refused by name, and
/// nothing changes.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitioned_parents_columns_change_through_the_cli() {
    parent_columns_flow(&server(), "parent-columns-1687");
}

/// [`a_partitioned_parents_columns_change_through_the_cli`] on a pre-17
/// server, where a parent's NOT NULL drop takes a partition's own with it.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_partitioned_parents_columns_change_through_the_cli_before_postgres_17() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    parent_columns_flow(&server, "parent-columns-1687-old");
}

/// A partitioned parent's column changes meet its partitions' own entries
/// through the CLI (#1699), on a tree holding rows. Each combination the
/// interim plan refused by name (#1692) is planned, applies, verifies and
/// replans empty: a partition's own check and unique index on a column the
/// parent retypes; a name passing hands on the parent, a partition's own
/// default and index on the column following it; a function rebuilt under a
/// partition's own default while the parent renames its column; the parent's
/// default released while the function its partitions' copies call is
/// rebuilt; and a name renamed away and added again, with a partition's own
/// NOT NULL on the new column.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitioned_parents_column_changes_reach_its_partitions_own_through_the_cli() {
    partition_inheritance_flow(&server(), "partition-inheritance-1699");
}

/// [`a_partitioned_parents_column_changes_reach_its_partitions_own_through_the_cli`]
/// on a pre-17 server.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_partitioned_parents_column_changes_reach_its_partitions_own_through_the_cli_before_postgres_17()
 {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    partition_inheritance_flow(&server, "partition-inheritance-1699-old");
}

fn partition_inheritance_flow(server: &str, slug: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(&conn, SETUP_1699);
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    let function = d.dir.join("schema/app.f%28integer%29.function.yml");
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let edit = |path: &std::path::Path, from: &str, to: &str| {
        let text = std::fs::read_to_string(path).unwrap();
        assert!(text.contains(from), "{from:?} in {text}");
        std::fs::write(path, text.replacen(from, to, 1)).unwrap();
    };
    let applied = |name: &str| {
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let planned = stdout(&o);
        succeeds(approved_apply(
            &d,
            &conn,
            &plan,
            &["--allow", "rename,not-null,destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        planned
    };
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let default_of = |table: &str, column: &str| {
        text_of(
            &conn,
            &format!(
                "SELECT coalesce(pg_get_expr(d.adbin, d.adrelid), '-') FROM pg_attribute a \
                 LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum \
                 WHERE a.attrelid = '{table}'::regclass AND a.attname = '{column}'"
            ),
        )
    };
    let rebuild_f = |body: &str| {
        std::fs::write(
            &function,
            format!(
                "function: app.f(integer)\npublic_execute: true\n\ndefinition: |-\n  \
                 (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ {body} $$\n"
            ),
        )
        .unwrap();
    };

    // A partition's own check and unique index on the column its parent
    // retypes: the parent's retype first, each probe over the converted rows.
    edit(
        &path,
        "  k:\n    type: integer\n",
        "  k:\n    type: bigint\n",
    );
    edit(
        &path,
        "    columns:\n      m: {default: app.f(7)}\n",
        "    columns:\n      m: {default: app.f(7)}\n    checks:\n      ev_2024_k: k > 0\n    \
         indexes:\n      ev_2024_k:\n        columns: [k]\n        unique: true\n",
    );
    applied("retype.json");
    assert_eq!(
        holds(
            "SELECT format_type(atttypid, atttypmod) = 'bigint' FROM pg_attribute \
             WHERE attrelid = 'app.ev_2024'::regclass AND attname = 'k'"
        ),
        1
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_constraint WHERE conname = 'ev_2024_k'"),
        1
    );
    assert_eq!(
        holds("SELECT indisunique::int FROM pg_index WHERE indexrelid = 'app.ev_2024_k'::regclass"),
        1
    );

    // A name passing hands: `n` dropped and `m` renamed into it. The
    // partitions' own default and index on `m` follow it to `n`.
    edit(&path, "  \"n\":\n    type: integer\n", "");
    succeeds(d.run(&["drop", "app.ev.n", "--reason", "gone"]));
    edit(
        &path,
        "  m:\n    type: integer\n",
        "  \"n\":\n    type: integer\n",
    );
    edit(
        &path,
        "      m: {default: app.f(7)}",
        "      \"n\": {default: app.f(7)}",
    );
    edit(&path, "        columns: [m]", "        columns: [\"n\"]");
    succeeds(d.run(&["rename", "app.ev.m", "n"]));
    applied("hands.json");
    assert_eq!(default_of("app.ev_2024", "n"), "app.f(7)");
    assert_eq!(default_of("app.ev_2025", "n"), "-");
    assert_eq!(
        holds("SELECT pg_get_indexdef('app.ev_2025_m'::regclass) LIKE '%(n)'"),
        1
    );
    assert_eq!(holds("SELECT sum(n) FROM app.ev"), 6, "the old `m` values");

    // `f` rebuilt under `ev_2024`'s own default while the parent renames the
    // column it is on: taken off under `n`, put back under `n2`.
    rebuild_f("SELECT x + 0");
    edit(
        &path,
        "  \"n\":\n    type: integer\n",
        "  n2:\n    type: integer\n",
    );
    edit(
        &path,
        "      \"n\": {default: app.f(7)}",
        "      n2: {default: app.f(7)}",
    );
    edit(&path, "        columns: [\"n\"]", "        columns: [n2]");
    succeeds(d.run(&["rename", "app.ev.n", "n2"]));
    applied("rebuild-rename.json");
    assert_eq!(default_of("app.ev_2024", "n2"), "app.f(7)");
    assert_eq!(
        holds(
            "SELECT prosrc LIKE '%x + 0%' FROM pg_proc WHERE oid = 'app.f(integer)'::regprocedure"
        ),
        1
    );

    // The parent's default on `g` released while `f`, which every
    // partition's copy calls, is rebuilt: the parent's `DROP DEFAULT` takes
    // the copies first.
    rebuild_f("SELECT x + 1");
    edit(
        &path,
        "  g:\n    type: integer\n    default: app.f(1)\n",
        "  g:\n    type: integer\n",
    );
    applied("rebuild-release.json");
    for t in ["app.ev", "app.ev_2024", "app.ev_2025"] {
        assert_eq!(default_of(t, "g"), "-", "{t}");
    }

    // `z` renamed away and added again, `ev_2025` holding its own NOT NULL
    // on the new one, which every row takes at its default. The old `z` is
    // NULL in `ev_2025`'s row, so a probe reading it under the name it
    // leaves refused the plan the engine takes.
    edit(
        &path,
        "  z:\n    type: integer\n",
        "  z_old:\n    type: integer\n",
    );
    succeeds(d.run(&["rename", "app.ev.z", "z_old"]));
    edit(
        &path,
        "  z_old:\n    type: integer\n",
        "  z_old:\n    type: integer\n  z:\n    type: integer\n    default: \"5\"\n",
    );
    edit(
        &path,
        "    indexes:\n      ev_2025_m:",
        "    columns:\n      z: {nullable: false}\n    indexes:\n      ev_2025_m:",
    );
    applied("readd.json");
    assert_eq!(holds("SELECT count(*) FROM app.ev WHERE z = 5"), 3);
    assert_eq!(holds("SELECT count(*) FROM app.ev WHERE z_old IS NULL"), 1);
    assert_eq!(
        holds(
            "SELECT attnotnull::int FROM pg_attribute WHERE attrelid = 'app.ev_2025'::regclass \
             AND attname = 'z'"
        ),
        1
    );
}

/// A standing range-partitioned parent's keys, checks and foreign keys
/// change through the CLI (#1689), on a tree holding rows: a primary key, a
/// unique constraint, a check and a foreign key added together, each
/// reaching every partition as the engine's clone; a foreign key from
/// another table referencing the parent; then the parent's own dropped. Each
/// verifies and replans empty. A check the rows of one partition violate is
/// refused by the pre-flight before any DDL, and at plan time, by name: a
/// key without the partition key column, and a check under a name a
/// partition holds as its own.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitioned_parents_keys_checks_and_foreign_keys_change_through_the_cli() {
    parent_keys_flow(&server(), "parent-keys-1689");
}

/// [`a_partitioned_parents_keys_checks_and_foreign_keys_change_through_the_cli`]
/// on a pre-17 server.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_partitioned_parents_keys_checks_and_foreign_keys_change_through_the_cli_before_postgres_17() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    parent_keys_flow(&server, "parent-keys-1689-old");
}

fn parent_keys_flow(server: &str, slug: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE \
             AS $$ SELECT x $$; \
         CREATE TABLE app.ref (id integer PRIMARY KEY); \
         INSERT INTO app.ref VALUES (1), (2), (500); \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, r integer) \
             PARTITION BY RANGE (ts); \
         CREATE TABLE app.ev_2024 PARTITION OF app.ev \
             FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
         CREATE TABLE app.ev_2025 PARTITION OF app.ev \
             FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
         ALTER TABLE app.ev_2025 ADD CONSTRAINT ev_2025_ck CHECK (r > 0); \
         INSERT INTO app.ev VALUES (1, '2024-06-01', 1), (2, '2025-06-01', 2); \
         CREATE TABLE app.child (id integer NOT NULL, ts date NOT NULL); \
         INSERT INTO app.child VALUES (1, '2024-06-01')",
    );
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    let child = d.dir.join("schema/app.child.yml");
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let edit = |file: &std::path::Path, from: &str, to: &str| {
        let text = std::fs::read_to_string(file).unwrap();
        assert!(text.contains(from), "{from:?} in {text}");
        std::fs::write(file, text.replacen(from, to, 1)).unwrap();
    };
    let applied = |name: &str| {
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let planned = stdout(&o);
        succeeds(approved_apply(
            &d,
            &conn,
            &plan,
            &["--allow", "destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        planned
    };
    let refused = |what: &str| {
        let o = d.run(&["plan"]);
        assert_ne!(code(&o), 0, "{}", stdout(&o));
        assert!(stderr(&o).contains(what), "{}", stderr(&o));
    };
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    // The partitions' constraints of a kind that are the parent's clones.
    let clones = |kind: &str| {
        holds(&format!(
            "SELECT count(*) FROM pg_constraint WHERE contype = '{kind}' \
             AND conrelid IN ('app.ev_2024'::regclass, 'app.ev_2025'::regclass) \
             AND (conparentid <> 0 OR NOT conislocal)"
        ))
    };

    // Added together: each reaches both partitions.
    edit(
        &path,
        "\npartition_by:",
        "\nprimary_key: [id, ts]\nunique:\n  ev_u: [id, r, ts]\nchecks:\n  ev_r_ck: r > 0\n\
         foreign_keys:\n  ev_r_fk:\n    columns: [r]\n    references: app.ref(id)\n\npartition_by:",
    );
    let planned = applied("add.json");
    assert!(
        planned.contains("recurses into its 2 partition(s)"),
        "{planned}"
    );
    for kind in ["p", "u", "c", "f"] {
        assert_eq!(clones(kind), 2, "{kind}");
    }
    // A foreign key from another table referencing the parent.
    edit(
        &child,
        "\n",
        "\nforeign_keys:\n  child_ev_fk:\n    columns: [id, ts]\n    references: app.ev(id, ts)\n",
    );
    applied("referenced.json");
    assert_eq!(
        holds("SELECT count(*) FROM pg_constraint WHERE conname = 'child_ev_fk'"),
        1
    );

    // A check one partition's rows violate: refused by the pre-flight, nothing
    // changed.
    on_server(&conn, "INSERT INTO app.ev VALUES (3, '2025-07-01', 500)");
    edit(
        &path,
        "  ev_r_ck: r > 0\n",
        "  ev_r_ck: r > 0\n  ev_r_max: r < 100\n",
    );
    succeeds(d.run(&["plan"]));
    d.commit();
    let violates = d.dir.join("violates.json");
    succeeds(d.run(&["plan", "--db", &conn, "--out", violates.to_str().unwrap()]));
    let o = approved_apply(&d, &conn, &violates, &["--allow", "destructive,constraint"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("violate the new check ev_r_max"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_constraint WHERE conname = 'ev_r_max'"),
        0
    );
    on_server(&conn, "DELETE FROM app.ev WHERE id = 3");
    applied("checked.json");
    assert_eq!(clones("c"), 4);

    // A function the parent's check and index call, rebuilt: each is taken
    // down and put back around it on the parent, which takes its clones on
    // every partition with it (#1745 review).
    edit(
        &path,
        "\npartition_by:",
        "\nindexes:\n  ev_f:\n    keys:\n      - expression: app.f(r)\n\npartition_by:",
    );
    edit(
        &path,
        "  ev_r_max: r < 100\n",
        "  ev_r_max: r < 100\n  ev_f_ck: app.f(r) > 0\n",
    );
    applied("function-backed.json");
    assert_eq!(clones("c"), 6);
    // Rebuilt, in the plan that gives `ev_2024` its own index of the
    // parent's shape, named to sort after it: the parent's is taken down and
    // put back around the rebuild, and the own index must be built after it,
    // or the parent's takes it (#1745 review).
    std::fs::write(
        d.dir.join("schema/app.f%28integer%29.function.yml"),
        "function: app.f(integer)\npublic_execute: true\n\ndefinition: |-\n  \
         (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x + 0 $$\n",
    )
    .unwrap();
    edit(
        &path,
        "  ev_2024: {from: [\"2024-01-01\"], to: [\"2025-01-01\"]}\n",
        "  ev_2024:\n    from: [\"2024-01-01\"]\n    to: [\"2025-01-01\"]\n    indexes:\n      \
         zz_own:\n        keys:\n          - expression: app.f(r)\n",
    );
    let own_is_own =
        || holds("SELECT count(*) FROM pg_inherits WHERE inhrelid = 'app.zz_own'::regclass");
    applied("rebuilt.json");
    assert_eq!(
        holds(
            "SELECT prosrc LIKE '%x + 0%' FROM pg_proc WHERE oid = 'app.f(integer)'::regprocedure"
        ),
        1
    );
    assert_eq!(clones("c"), 6);
    assert_eq!(
        own_is_own(),
        0,
        "the partition's own index is still its own"
    );
    edit(
        &path,
        "    indexes:\n      zz_own:\n        keys:\n          - expression: app.f(r)\n",
        "",
    );
    edit(
        &path,
        "\nindexes:\n  ev_f:\n    keys:\n      - expression: app.f(r)\n",
        "\n",
    );
    edit(&path, "  ev_f_ck: app.f(r) > 0\n", "");
    // Removed in the plan that rebuilds the function again: the parent's
    // drops release the clones too.
    std::fs::write(
        d.dir.join("schema/app.f%28integer%29.function.yml"),
        "function: app.f(integer)\npublic_execute: true\n\ndefinition: |-\n  \
         (x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x + 1 $$\n",
    )
    .unwrap();
    applied("unbacked.json");
    assert_eq!(clones("c"), 4);

    // Dropped: the parent's unique, checks and foreign key, with their clones.
    edit(
        &path,
        "unique:\n  ev_u: [id, r, ts]\nchecks:\n  ev_r_ck: r > 0\n  ev_r_max: r < 100\n\
         foreign_keys:\n  ev_r_fk:\n    columns: [r]\n    references: app.ref(id)\n",
        "",
    );
    applied("drop.json");
    for kind in ["u", "c", "f"] {
        assert_eq!(clones(kind), 0, "{kind}");
    }
    assert_eq!(clones("p"), 2, "the key the child references stays");
    // The partition's own check is still its own.
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_constraint WHERE conname = 'ev_2025_ck' AND conislocal \
             AND coninhcount = 0"
        ),
        1
    );

    // Refused by name, before any DDL: a key without the partition key
    // column, and a check under the name of a partition's own.
    edit(
        &path,
        "\npartition_by:",
        "\nunique:\n  ev_id: [id]\n\npartition_by:",
    );
    refused("without the partition key column `ts`");
    edit(
        &path,
        "\nunique:\n  ev_id: [id]\n",
        "\nchecks:\n  ev_2025_ck: r > 0\n",
    );
    refused("a name app.ev_2025 holds as its own check");
}

/// #1547: a range partition added beside a standing DEFAULT partition takes
/// the DEFAULT's rows of its range through the CLI. A first plan whose
/// partition's own check refuses a moved row rolls back whole: no partition,
/// every row where it was, the DEFAULT still attached. Without that check the
/// plan applies: each row ends in the partition its key belongs to, none lost
/// or doubled, the parent's index cloned onto the new partition, `verify` is
/// clean and the next plan is empty, applied staged, outside a transaction. A move whose rows a foreign key with a
/// delete action references is refused, before
/// any statement runs and with the referencing row kept, the parent renamed in
/// the same plan or not.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_range_beside_a_default_takes_its_rows_through_the_cli() {
    default_move_flow(&server(), "default-move-1547", "PBPS_TEST_PG_CONTAINER");
}

/// [`a_range_beside_a_default_takes_its_rows_through_the_cli`] on a pre-17
/// server.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_range_beside_a_default_takes_its_rows_through_the_cli_before_postgres_17() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE \
         EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    default_move_flow(
        &server,
        "default-move-1547-old",
        "PBPS_TEST_PG_OLD_CONTAINER",
    );
}

fn default_move_flow(server: &str, slug: &str, container: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, r integer DEFAULT 7, \
             note text, PRIMARY KEY (id, ts), CONSTRAINT ev_r_ck CHECK (r > 0)) \
             PARTITION BY RANGE (ts); \
         CREATE INDEX ev_r ON app.ev (r); \
         ALTER TABLE app.ev ALTER COLUMN note SET STORAGE EXTERNAL; \
         CREATE TABLE app.ev_2024 PARTITION OF app.ev \
             FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
         CREATE TABLE app.ev_rest PARTITION OF app.ev DEFAULT; \
         INSERT INTO app.ev VALUES (1, '2024-06-01', 1, 'a'), (2, '2025-03-01', 2, 'b'), \
             (3, '2025-12-31', 3, 'c'), (4, '2026-01-01', 4, 'd'), (5, '2030-01-01', 5, 'e')",
    );
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let ids_in = |partition: &str| -> String {
        text_of(
            &conn,
            &format!(
                "SELECT coalesce(string_agg(id::text, ',' ORDER BY id), '-') FROM {partition}"
            ),
        )
    };
    let path = d.dir.join("schema/app.ev.yml");
    let pulled = std::fs::read_to_string(&path).unwrap();
    assert!(pulled.contains("\npartitions:\n"), "{pulled}");
    let with = |entries: &str| {
        std::fs::write(
            &path,
            pulled.replacen("\npartitions:\n", &format!("\npartitions:\n{entries}"), 1),
        )
        .unwrap();
    };
    let plan = d.dir.join("move.json");
    let connected = |d: &Demo| {
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
        stdout(&o)
    };
    let planned = |d: &Demo| {
        let o = d.run(&["plan"]);
        assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
        d.commit();
        connected(d)
    };
    let kept = |why: &str| {
        assert_eq!(
            holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_2025'"),
            0,
            "{why}: no partition"
        );
        assert_eq!(ids_in("ONLY app.ev_rest"), "2,3,4,5", "{why}: no row moved");
    };

    // #1788: nobody allowed the move, so its rows are refused by name before
    // any statement runs, with the command that allows it and the move
    // written out to run by hand. `plan --db` lists the logical slots that
    // would decode the move: none, a physical slot being none of them.
    let physical = format!("pbps_{}", slug.replace('-', "_"));
    let drop_slot = format!(
        "SELECT pg_drop_replication_slot(slot_name) FROM pg_replication_slots \
         WHERE slot_name = '{physical}'"
    );
    on_server(&conn, &drop_slot);
    on_server(
        &conn,
        &format!("SELECT pg_create_physical_replication_slot('{physical}')"),
    );
    with("  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n");
    let shown = planned(&d);
    on_server(&conn, &drop_slot);
    assert!(
        shown.contains("app.ev_rest, none allowed: the apply refuses any it holds"),
        "{shown}"
    );
    assert!(
        shown.contains(
            "logical_slots: no logical replication slot on this database would decode the rows \
             moved from app.ev_rest into app.ev_2025"
        ),
        "{shown}"
    );
    let o = approved_apply(&d, &conn, &plan, &[]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let refused = stderr(&o);
    for said in [
        "the data will not accept this plan",
        "2 rows of app.ev_rest are inside the range of app.ev_2025",
        "no move of them was allowed",
        "pbps move-rows app.ev_2025 --max-rows <N> --reason \"\"",
        "LOCK TABLE ONLY \"app\".\"ev_rest\" IN SHARE MODE;",
    ] {
        assert!(refused.contains(said), "{said}: {refused}");
    }
    kept("refused before the apply");
    // The moving statement refuses too, run where no pre-flight asks: the
    // `plan --sql` script, read by psql.
    let script = d.dir.join("unallowed.sql");
    succeeds(d.run(&["plan", "--db", &conn, "--sql", script.to_str().unwrap()]));
    let o = psql_script_in(container, &db, &std::fs::read_to_string(&script).unwrap());
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("2 rows of app.ev_rest are inside the range of app.ev_2025")
            && stderr(&o).contains("no move of them was allowed"),
        "{}",
        stderr(&o)
    );
    kept("refused by the moving statement");

    // Negative: a move for a table no rows can move into is refused, and
    // records nothing; and a bound must allow a row.
    let ids_file = d.dir.join("schema.ids.json");
    let before = std::fs::read_to_string(&ids_file).unwrap();
    let o = d.run(&["move-rows", "app.ev", "--max-rows", "5", "--reason", "x"]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        format!("{}{}", stdout(&o), stderr(&o))
            .contains("app.ev is not a range or list partition whose parent declares a DEFAULT"),
        "{}{}",
        stdout(&o),
        stderr(&o)
    );
    let o = d.run(&[
        "move-rows",
        "app.ev_2025",
        "--max-rows",
        "0",
        "--reason",
        "x",
    ]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert_eq!(std::fs::read_to_string(&ids_file).unwrap(), before);

    // Allowed, but for fewer rows than the range holds: refused, by the
    // pre-flight and by the moving statement alike, with nothing moved.
    succeeds(d.run(&[
        "move-rows",
        "app.ev_2025",
        "--max-rows",
        "1",
        "--reason",
        "no CDC reads app.ev",
    ]));
    planned(&d);
    let o = approved_apply(&d, &conn, &plan, &[]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("2 rows of app.ev_rest are inside the range of app.ev_2025, more than the 1 its allowed move may take")
            && stderr(&o).contains("a batch at a time"),
        "{}",
        stderr(&o)
    );
    kept("past the bound allowed");
    succeeds(d.run(&["plan", "--db", &conn, "--sql", script.to_str().unwrap()]));
    let o = psql_script_in(container, &db, &std::fs::read_to_string(&script).unwrap());
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("more than the 1 its allowed move may take"),
        "{}",
        stderr(&o)
    );
    kept("past the bound, by the moving statement");

    // Allowed for as many rows as it holds: the rows move below. Allowing
    // the same again changes nothing, `plan --check` finds the identity file
    // current, and the plan carries the bound.
    succeeds(d.run(&[
        "move-rows",
        "app.ev_2025",
        "--max-rows",
        "2",
        "--reason",
        "no CDC reads app.ev",
    ]));
    d.commit();
    let again = succeeds(d.run(&[
        "move-rows",
        "app.ev_2025",
        "--max-rows",
        "2",
        "--reason",
        "no CDC reads app.ev",
    ]));
    assert!(
        stdout(&again).contains("The identity file is unchanged"),
        "{}",
        stdout(&again)
    );
    succeeds(d.run(&["plan", "--check"]));
    let shown = connected(&d);
    assert!(
        shown.contains(
            "moving those rows out of the default partition app.ev_rest, at most 2 as allowed"
        ),
        "{shown}"
    );

    // Its own check refuses row 3, moved in before the check is added: the
    // whole plan rolls back.
    with(
        "  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n    checks:\n      \
         ev_2025_ck: ts < '2025-12-01'\n",
    );
    let shown = planned(&d);
    assert!(
        shown.contains(
            "+ create table app.ev_2025, a partition of app.ev for rows from (\"2025-01-01\") to \
             (\"2026-01-01\"), moving those rows out of the default partition app.ev_rest"
        ),
        "{shown}"
    );
    // Its own check faces the moved rows, which is the gate's to approve.
    let o = approved_apply(&d, &conn, &plan, &[]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(stderr(&o).contains("--allow constraint"), "{}", stderr(&o));
    let o = approved_apply(&d, &conn, &plan, &["--allow", "constraint"]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o).contains("check constraint \"ev_2025_ck\" of relation \"ev_2025\" is violated"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_2025'"),
        0,
        "the partition is rolled back"
    );
    assert_eq!(ids_in("ONLY app.ev_rest"), "2,3,4,5");
    assert_eq!(ids_in("ONLY app.ev_2024"), "1");
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_inherits WHERE inhparent = 'app.ev'::regclass \
             AND inhrelid = 'app.ev_rest'::regclass"
        ),
        1,
        "the DEFAULT is still attached"
    );

    with("  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n");
    let o = d.run(&["plan"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    d.commit();

    // Without the check, the rows move, and staged too: the lock, the table,
    // the move and the attach are one statement, which the engine runs as one
    // transaction outside an explicit one.
    let o = d.run(&[
        "plan",
        "--db",
        &conn,
        "--staged",
        "--out",
        plan.to_str().unwrap(),
    ]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(stdout(&o).contains("app.ev_2025"), "{}", stdout(&o));
    succeeds(approved_apply(&d, &conn, &plan, &["--staged"]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(ids_in("ONLY app.ev_2024"), "1");
    assert_eq!(ids_in("ONLY app.ev_2025"), "2,3");
    assert_eq!(ids_in("ONLY app.ev_rest"), "4,5");
    assert_eq!(ids_in("app.ev"), "1,2,3,4,5", "no row lost or doubled");
    assert_eq!(
        holds("SELECT count(*) FROM app.ev_2025 WHERE id = 2 AND r = 2 AND note = 'b'"),
        1
    );
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_inherits i JOIN pg_class c ON c.oid = i.inhrelid \
             WHERE i.inhparent = 'app.ev_r'::regclass AND c.relname LIKE 'ev_2025%'"
        ),
        1,
        "the parent's index is cloned onto the new partition"
    );
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_attribute WHERE attrelid = 'app.ev_2025'::regclass \
             AND attname = 'note' AND attstorage = 'e'"
        ),
        1,
        "a column's storage is its parent's, as `PARTITION OF` gives it"
    );

    // A key with a delete action references a row the next range would
    // move: refused by name before the first statement, the row kept.
    on_server(
        &conn,
        "CREATE SCHEMA ext; \
         CREATE TABLE ext.child (id integer, ts date, \
             FOREIGN KEY (id, ts) REFERENCES app.ev ON DELETE CASCADE); \
         INSERT INTO ext.child VALUES (4, '2026-01-01')",
    );
    let now = std::fs::read_to_string(&path).unwrap();
    std::fs::write(
        &path,
        now.replacen(
            "\npartitions:\n",
            "\npartitions:\n  ev_2026:\n    from: [\"2026-01-01\"]\n    to: [\"2027-01-01\"]\n",
            1,
        ),
    )
    .unwrap();
    succeeds(d.run(&[
        "move-rows",
        "app.ev_2026",
        "--max-rows",
        "1",
        "--reason",
        "no CDC reads app.ev",
    ]));
    planned(&d);
    let o = approved_apply(&d, &conn, &plan, &[]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o)
            .contains("rows that reference rows of app.ev_rest inside the range of app.ev_2026"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_2026'"),
        0
    );
    assert_eq!(
        holds("SELECT count(*) FROM ext.child"),
        1,
        "the referencing row is kept"
    );
    assert_eq!(ids_in("ONLY app.ev_rest"), "4,5");

    // The same, with the parent renamed in the plan: the pre-flight reads it
    // under the name it has before the rename, and still refuses.
    let now = std::fs::read_to_string(&path).unwrap();
    assert!(now.starts_with("table: app.ev\n"), "{now}");
    std::fs::write(
        d.dir.join("schema/app.events.yml"),
        now.replacen(
            "table: app.ev\n",
            "table: app.events\nrenamed_from: app.ev\n",
            1,
        ),
    )
    .unwrap();
    std::fs::remove_file(&path).unwrap();
    planned(&d);
    let o = approved_apply(&d, &conn, &plan, &["--allow", "rename"]);
    assert_ne!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    assert!(
        stderr(&o)
            .contains("rows that reference rows of app.ev_rest inside the range of app.ev_2026"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT count(*) FROM ext.child"),
        1,
        "the referencing row is kept"
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'events'"),
        0,
        "nothing ran"
    );

    // The same plan, with nothing referencing the row, as the `plan --sql`
    // script psql reads one command at a time (SPEC 7.3): the lock, the table,
    // the move and the attach are one `DO` block there too, so the lock is
    // taken and the row moves. As a batch of four, psql ran `LOCK` alone,
    // outside a transaction, and refused it (#1763 review).
    on_server(&conn, "DELETE FROM ext.child");
    let script = d.dir.join("move.sql");
    succeeds(d.run(&["plan", "--db", &conn, "--sql", script.to_str().unwrap()]));
    let generated = std::fs::read_to_string(&script).unwrap();
    assert!(generated.contains("LOCK TABLE ONLY"), "{generated}");
    succeeds(psql_script_in(container, &db, &generated));
    assert_eq!(ids_in("ONLY app.ev_2026"), "4");
    assert_eq!(ids_in("ONLY app.ev_rest"), "5");
    assert_eq!(ids_in("app.events"), "1,2,3,4,5", "no row lost or doubled");
}

/// #1690: a standing range-partitioned parent is renamed as any table is, a
/// plain `ALTER TABLE ... RENAME`. Its partitions follow it without that
/// being a change of their partitioning, its clones stay its own, and a
/// foreign key referencing it follows it as it follows any table.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitioned_parent_is_renamed_through_the_cli() {
    parent_rename_flow(&server(), "parent-rename-1690");
}

/// [`a_partitioned_parent_is_renamed_through_the_cli`] on a pre-17 server.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_partitioned_parent_is_renamed_through_the_cli_before_postgres_17() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE \
         EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    parent_rename_flow(&server, "parent-rename-1690-old");
}

fn parent_rename_flow(server: &str, slug: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, r integer, note text, \
             v numeric(10,2), \
             PRIMARY KEY (id, ts), CONSTRAINT ev_r_ck CHECK (r > 0)) \
             PARTITION BY RANGE (ts); \
         CREATE INDEX ev_r ON app.ev (r); \
         CREATE TABLE app.ev_2024 PARTITION OF app.ev \
             FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
         CREATE TABLE app.ev_2025 PARTITION OF app.ev \
             FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
         CREATE INDEX ev_2024_own ON app.ev_2024 (id, r); \
         ALTER TABLE app.ev_2024 ALTER COLUMN note SET DEFAULT 'x'; \
         INSERT INTO app.ev VALUES (1, '2024-06-01', 1, NULL, 1.50), \
             (2, '2025-06-01', 2, NULL, 2.00); \
         CREATE TABLE app.child (id integer NOT NULL, ts date NOT NULL, \
             CONSTRAINT child_ev_fk FOREIGN KEY (id, ts) REFERENCES app.ev (id, ts)); \
         INSERT INTO app.child VALUES (1, '2024-06-01')",
    );
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let rows = || holds("SELECT count(*) FROM app.events");

    let from = d.dir.join("schema/app.ev.yml");
    let text = std::fs::read_to_string(&from).unwrap();
    assert!(text.starts_with("table: app.ev\n"), "{text}");
    std::fs::write(
        d.dir.join("schema/app.events.yml"),
        text.replacen(
            "table: app.ev\n",
            "table: app.events\nrenamed_from: app.ev\n",
            1,
        ),
    )
    .unwrap();
    std::fs::remove_file(&from).unwrap();
    let child = d.dir.join("schema/app.child.yml");
    let text = std::fs::read_to_string(&child).unwrap();
    assert!(text.contains("app.ev(id, ts)"), "{text}");
    std::fs::write(&child, text.replace("app.ev(id, ts)", "app.events(id, ts)")).unwrap();

    let o = d.run(&["plan"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    d.commit();
    let plan = d.dir.join("rename.json");
    let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    let planned = stdout(&o);
    assert!(planned.contains("app.events"), "{planned}");
    succeeds(approved_apply(&d, &conn, &plan, &["--allow", "rename"]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    assert_eq!(rows(), 2, "the rows stay with the parent");
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_inherits WHERE inhparent = 'app.events'::regclass \
             AND inhrelid IN ('app.ev_2024'::regclass, 'app.ev_2025'::regclass)"
        ),
        2,
        "both partitions are the renamed parent's"
    );
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_class WHERE relname = 'ev' AND relnamespace = 'app'::regnamespace"
        ),
        0
    );
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_constraint WHERE conname = 'child_ev_fk' \
             AND confrelid = 'app.events'::regclass"
        ),
        1,
        "the referencing key follows the parent"
    );
    // The partition's own index is still its own, the parent's still its
    // clone on each partition.
    assert_eq!(
        holds("SELECT count(*) FROM pg_inherits WHERE inhrelid = 'app.ev_2024_own'::regclass"),
        0
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_inherits WHERE inhparent = 'app.ev_r'::regclass"),
        2
    );

    let text_before = std::fs::read_to_string(d.dir.join("schema/app.events.yml")).unwrap();
    assert!(
        text_before.contains("  v:\n    type: \"numeric(10, 2)\"\n"),
        "{text_before}"
    );
    // Renamed again, in the plan that also renames a column, drops one a
    // partition holds its own default on, and adds an index: the parent's
    // changes name it as declared, and each reaches the partitions under the
    // new name. The drop takes the partition's own default with it, which
    // the apply's read-back expects under the parent's new name (#1751
    // review).
    let from = d.dir.join("schema/app.events.yml");
    let text = std::fs::read_to_string(&from).unwrap();
    let head = "table: app.events\nrenamed_from: app.ev\n";
    assert!(text.starts_with(head), "{text}");
    assert!(text.contains("\n  r:\n    type: integer\n"), "{text}");
    let text = text
        .replacen(head, "table: app.ev2\nrenamed_from: app.events\n", 1)
        .replacen(
            "\n  r:\n    type: integer\n",
            "\n  r2:\n    type: integer\n    renamed_from: r\n",
            1,
        )
        .replacen(
            "\nindexes:\n",
            "\nindexes:\n  ev2_id:\n    columns: [id]\n",
            1,
        )
        .replace("columns: [r]", "columns: [r2]")
        .replace("columns: [id, r]", "columns: [id, r2]")
        .replace("r > 0", "r2 > 0")
        .replacen("  note:\n    type: text\n", "", 1)
        .replacen(
            "    columns:\n      note: {default: \"'x'::text\"}\n",
            "",
            1,
        )
        // A retype the pre-flight probes through the partitions under the
        // parent's new name: `1.50` is `2` once converted, which the
        // partition's new check takes (#1751 review).
        .replacen(
            "  v:\n    type: \"numeric(10, 2)\"\n",
            "  v:\n    type: \"numeric(10, 0)\"\n",
            1,
        )
        .replacen(
            "    indexes:\n      ev_2024_own:",
            "    checks:\n      ev_2024_v: v = round(v)\n    indexes:\n      ev_2024_own:",
            1,
        );
    std::fs::write(d.dir.join("schema/app.ev2.yml"), text).unwrap();
    std::fs::remove_file(&from).unwrap();
    let text = std::fs::read_to_string(&child).unwrap();
    std::fs::write(
        &child,
        text.replace("app.events(id, ts)", "app.ev2(id, ts)"),
    )
    .unwrap();
    succeeds(d.run(&["drop", "app.ev2.note", "--reason", "unused"]));
    let o = d.run(&["plan"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    d.commit();
    let plan = d.dir.join("again.json");
    let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    // The check's text names the renamed column, so it is taken down and
    // put back, as on any table.
    succeeds(approved_apply(
        &d,
        &conn,
        &plan,
        &["--allow", "rename,constraint,destructive,narrowing"],
    ));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        holds("SELECT count(*) FROM pg_inherits WHERE inhparent = 'app.ev2_id'::regclass"),
        2,
        "the new index reaches both partitions"
    );
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_attribute WHERE attname = 'r2' AND attrelid IN \
             ('app.ev2'::regclass, 'app.ev_2024'::regclass, 'app.ev_2025'::regclass)"
        ),
        3
    );
    assert_eq!(holds("SELECT count(*) FROM app.ev2"), 2);
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_attribute WHERE attname = 'note' AND NOT attisdropped \
             AND attrelid IN ('app.ev2'::regclass, 'app.ev_2024'::regclass)"
        ),
        0
    );

    // Outside the declarations, a permanent table's key to the parent. A
    // plan renaming the parent and adding an unlogged partition under the
    // new name is refused by name: the catalog is read under the name the
    // parent has now (#1613).
    on_server(
        &conn,
        "CREATE SCHEMA ext; \
         CREATE TABLE ext.r (id integer, ts date, \
             CONSTRAINT r_ev_fk FOREIGN KEY (id, ts) REFERENCES app.ev2 (id, ts))",
    );
    let from = d.dir.join("schema/app.ev2.yml");
    let text = std::fs::read_to_string(&from).unwrap();
    let head = "table: app.ev2\nrenamed_from: app.events\n";
    assert!(text.starts_with(head), "{text}");
    std::fs::write(
        d.dir.join("schema/app.ev3.yml"),
        format!(
            "{}  ev_2026:\n    from: [\"2026-01-01\"]\n    to: [\"2027-01-01\"]\n    unlogged: true\n",
            text.replacen(head, "table: app.ev3\nrenamed_from: app.ev2\n", 1)
        ),
    )
    .unwrap();
    std::fs::remove_file(&from).unwrap();
    // The declared child's key goes, or the declarations alone refuse the
    // unlogged partition under it (DEC-1580.1) before the catalog is read.
    let text = std::fs::read_to_string(&child).unwrap();
    let cut = text.find("\nforeign_keys:").expect("the child's key");
    std::fs::write(&child, &text[..=cut]).unwrap();
    let o = d.run(&["plan"]);
    assert_eq!(code(&o), 0, "{}{}", stdout(&o), stderr(&o));
    d.commit();
    let o = d.run(&["plan", "--db", &conn]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains(
            "app.ev_2026 would be created unlogged under app.ev3, which ext.r's foreign key \
             `r_ev_fk` references"
        ),
        "{}",
        stderr(&o)
    );
}

/// A standing range-partitioned parent's indexes change through the CLI
/// (#1688), on a tree holding rows: an index added, renamed (a drop and an
/// add) and dropped, and a unique one over the key column, each reaching
/// every partition as the engine's clone, verifying and replanning empty, the
/// cost estimate naming the recursion. Refused at plan time by name, nothing
/// changed: `strategy: online`, and a new index that would take a
/// partition's own as its clone.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitioned_parents_indexes_change_through_the_cli() {
    parent_indexes_flow(&server(), "parent-indexes-1688");
}

/// [`a_partitioned_parents_indexes_change_through_the_cli`] on a pre-17
/// server.
#[test]
#[ignore = "needs PostgreSQL 16; set PBPS_TEST_PG_OLD_DB"]
fn a_partitioned_parents_indexes_change_through_the_cli_before_postgres_17() {
    let server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    on_server(
        &server,
        "DO $$ BEGIN IF current_setting('server_version_num')::integer >= 170000 THEN RAISE EXCEPTION 'this regression needs a pre-17 server'; END IF; END $$",
    );
    parent_indexes_flow(&server, "parent-indexes-1688-old");
}

fn parent_indexes_flow(server: &str, slug: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, n integer, m integer) \
             PARTITION BY RANGE (ts); \
         CREATE TABLE app.ev_2024 PARTITION OF app.ev \
             FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
         CREATE TABLE app.ev_2025 PARTITION OF app.ev \
             FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
         CREATE INDEX ev_2025_n ON app.ev_2025 (n); \
         INSERT INTO app.ev VALUES (1, '2024-06-01', 1, 1), (2, '2025-06-01', 2, 2)",
    );
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let edit = |from: &str, to: &str| {
        let text = std::fs::read_to_string(&path).unwrap();
        assert!(text.contains(from), "{from:?} in {text}");
        std::fs::write(&path, text.replacen(from, to, 1)).unwrap();
    };
    let applied = |name: &str| {
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let planned = stdout(&o);
        succeeds(approved_apply(
            &d,
            &conn,
            &plan,
            &["--allow", "destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        planned
    };
    let refused = |what: &str| {
        let o = d.run(&["plan"]);
        assert_ne!(code(&o), 0, "{}", stdout(&o));
        assert!(stderr(&o).contains(what), "{}", stderr(&o));
    };
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    // The partitions' indexes on `column`, the engine's clones among them.
    let clones_on = |column: &str| {
        holds(&format!(
            "SELECT count(*) FROM pg_index i JOIN pg_inherits h ON h.inhrelid = i.indexrelid \
             JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0] \
             WHERE i.indrelid IN ('app.ev_2024'::regclass, 'app.ev_2025'::regclass) \
             AND a.attname = '{column}'"
        ))
    };

    // Added: a clone on every partition. With it, `ev_2024` gains its own
    // index of the same shape, built after the parent's and so its own
    // (#1737 review).
    edit(
        "\npartition_by:",
        "\nindexes:\n  ev_m:\n    columns: [m]\n\npartition_by:",
    );
    edit(
        "  ev_2024: {from: [\"2024-01-01\"], to: [\"2025-01-01\"]}\n",
        "  ev_2024:\n    from: [\"2024-01-01\"]\n    to: [\"2025-01-01\"]\n    \
         indexes:\n      ev_2024_m:\n        columns: [m]\n",
    );
    let planned = applied("add.json");
    assert_eq!(
        holds("SELECT count(*) FROM pg_inherits WHERE inhrelid = 'app.ev_2024_m'::regclass"),
        0,
        "the partition's own index is its own"
    );
    assert!(
        planned.contains("recurses into its 2 partition(s)"),
        "{planned}"
    );
    assert_eq!(clones_on("m"), 2);
    // Renamed: a drop and an add, and the add would take `ev_2024`'s own,
    // which stands now, as its clone. Refused, then planned with the own
    // one dropped in the same plan, which runs before the add.
    edit("  ev_m:\n", "  ev_m2:\n");
    refused("which can take app.ev_2024's `ev_2024_m`");
    edit("    indexes:\n      ev_2024_m:\n        columns: [m]\n", "");
    applied("rename.json");
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_m2'"),
        1
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_m'"),
        0
    );
    assert_eq!(clones_on("m"), 2);
    // A unique one over the key column, probed over every partition's rows.
    edit(
        "  ev_m2:\n    columns: [m]\n",
        "  ev_m2:\n    columns: [m]\n  ev_id:\n    columns: [id, ts]\n    unique: true\n",
    );
    // A duplicate in one partition refuses the apply before any DDL.
    on_server(&conn, "INSERT INTO app.ev VALUES (2, '2025-06-01', 3, 3)");
    succeeds(d.run(&["plan"]));
    d.commit();
    let collides = d.dir.join("collides.json");
    succeeds(d.run(&["plan", "--db", &conn, "--out", collides.to_str().unwrap()]));
    let o = approved_apply(&d, &conn, &collides, &["--allow", "destructive,constraint"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("would collide under the new unique index ev_id"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT count(*) FROM pg_class WHERE relname = 'ev_id'"),
        0
    );
    on_server(&conn, "DELETE FROM app.ev WHERE n = 3");
    applied("unique.json");
    assert_eq!(clones_on("id"), 2);
    // Dropped: the clones with it.
    edit("  ev_m2:\n    columns: [m]\n", "");
    applied("drop.json");
    assert_eq!(clones_on("m"), 0);

    // Refused by name, nothing changed: `strategy: online`.
    edit(
        "\npartition_by:",
        "\nstrategy: {online: true}\n\npartition_by:",
    );
    edit("  ev_id:\n", "  ev_m:\n    columns: [m]\n  ev_id:\n");
    refused("with `strategy: online`");
    edit("\nstrategy: {online: true}\n", "\n");
    // And a new index the partition `ev_2025`'s own would be taken into.
    edit(
        "  ev_m:\n    columns: [m]\n",
        "  ev_n:\n    columns: [\"n\"]\n",
    );
    refused("which can take app.ev_2025's `ev_2025_n`");
    assert_eq!(clones_on("n"), 0);
    assert_eq!(
        holds("SELECT count(*) FROM pg_inherits WHERE inhrelid = 'app.ev_2025_n'::regclass"),
        0,
        "the partition's own index is still its own"
    );
}

const SETUP_1699: &str = "CREATE SCHEMA app; \
     CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
     CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, k integer, n integer, \
         m integer, z integer, g integer DEFAULT app.f(1)) PARTITION BY RANGE (ts); \
     CREATE TABLE app.ev_2024 PARTITION OF app.ev \
         FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
     CREATE TABLE app.ev_2025 PARTITION OF app.ev \
         FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
     ALTER TABLE app.ev_2024 ALTER COLUMN m SET DEFAULT app.f(7); \
     CREATE INDEX ev_2025_m ON app.ev_2025 (m); \
     INSERT INTO app.ev (id, ts, k, n, m, z) VALUES (1, '2024-06-01', 1, -1, 1, 1), \
         (2, '2024-07-01', 2, -2, 2, 2), (3, '2025-06-01', 3, -3, 3, NULL)";

fn parent_columns_flow(server: &str, slug: &str) {
    let db = OwnDatabase::new(server, slug);
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, n integer NOT NULL, \
             m integer, note text DEFAULT 'p') PARTITION BY RANGE (ts); \
         CREATE TABLE app.ev_2024 PARTITION OF app.ev \
             FOR VALUES FROM ('2024-01-01') TO ('2025-01-01'); \
         ALTER TABLE app.ev_2024 ALTER COLUMN note SET DEFAULT 'own'; \
         CREATE TABLE app.ev_2025 PARTITION OF app.ev \
             FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
         ALTER TABLE app.ev_2025 ALTER COLUMN m SET NOT NULL; \
         CREATE TABLE app.att (id integer NOT NULL, ts date NOT NULL, n integer NOT NULL, \
             m integer, note text DEFAULT 'p'); \
         ALTER TABLE app.ev ATTACH PARTITION app.att \
             FOR VALUES FROM ('2026-01-01') TO ('2027-01-01'); \
         INSERT INTO app.ev VALUES (1, '2024-06-01', 1, 1, 'a'), (2, '2025-06-01', 2, 2, 'b'), \
             (3, '2026-06-01', 3, 3, 'c')",
    );
    let d = Demo::new(slug);
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    let text = std::cell::RefCell::new(std::fs::read_to_string(&path).unwrap());
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let edit = |from: &str, to: &str| {
        let mut text = text.borrow_mut();
        assert!(text.contains(from), "{from:?} in {text}");
        *text = text.replacen(from, to, 1);
        std::fs::write(&path, &*text).unwrap();
    };
    let applied = |name: &str| {
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let planned = stdout(&o);
        succeeds(approved_apply(
            &d,
            &conn,
            &plan,
            &["--allow", "rename,not-null,destructive,constraint"],
        ));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        planned
    };
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let each = |sql: &str| {
        ["app.ev_2024", "app.ev_2025", "app.att"]
            .iter()
            .map(|t| holds(&sql.replace("{t}", t)))
            .collect::<Vec<_>>()
    };
    let not_null = |column: &str| {
        each(&format!(
            "SELECT attnotnull FROM pg_attribute WHERE attrelid = '{{t}}'::regclass \
             AND attname = '{column}'"
        ))
    };
    let default_is = |column: &str, value: &str| {
        each(&format!(
            "SELECT pg_get_expr(adbin, adrelid) IS NOT DISTINCT FROM {value} FROM pg_attribute a \
             LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum \
             WHERE a.attrelid = '{{t}}'::regclass AND a.attname = '{column}'"
        ))
    };

    // Added, with a default every row takes.
    edit(
        "    default: \"'p'::text\"\n",
        "    default: \"'p'::text\"\n  extra:\n    type: integer\n    default: \"3\"\n",
    );
    let planned = applied("add.json");
    assert!(
        planned.contains("recurses into its 3 partition(s) and takes AccessExclusiveLock on each"),
        "{planned}"
    );
    assert_eq!(holds("SELECT count(*) FROM app.ev WHERE extra = 3"), 3);
    // Retyped.
    edit("  m:\n    type: integer\n", "  m:\n    type: bigint\n");
    applied("retype.json");
    assert_eq!(
        each(
            "SELECT format_type(atttypid, atttypmod) = 'bigint' FROM pg_attribute \
             WHERE attrelid = '{t}'::regclass AND attname = 'm'"
        ),
        [1, 1, 1]
    );
    // Renamed, the key column with it; the partitions' own follow.
    edit("  m:\n", "  m2:\n");
    edit("      m: {nullable: false}", "      m2: {nullable: false}");
    succeeds(d.run(&["rename", "app.ev.m", "m2"]));
    edit("  ts:\n", "  at:\n");
    edit("partition_by: [ts]", "partition_by: [at]");
    succeeds(d.run(&["rename", "app.ev.ts", "at"]));
    applied("rename.json");
    assert_eq!(
        holds("SELECT pg_get_partkeydef('app.ev'::regclass) = 'RANGE (at)'"),
        1
    );
    assert_eq!(not_null("m2"), [0, 1, 0]);
    // A default changed on the parent: `ev_2024` keeps its own.
    edit(
        "    default: \"'p'::text\"\n",
        "    default: \"'q'::text\"\n",
    );
    applied("default.json");
    assert_eq!(default_is("note", "'''q''::text'"), [0, 1, 1]);
    assert_eq!(default_is("note", "'''own''::text'"), [1, 0, 0]);
    // The parent's default dropped, which the engine takes off every
    // partition too: `ev_2024`'s own is set again after it.
    edit("    default: \"'q'::text\"\n", "");
    applied("undefault.json");
    assert_eq!(default_is("note", "NULL"), [0, 1, 1]);
    assert_eq!(default_is("note", "'''own''::text'"), [1, 0, 0]);
    // NOT NULL dropped on the parent: `ev_2024` declares its own, and the
    // attached table's own, which 18 would keep, goes.
    edit(
        "  \"n\":\n    type: integer\n    nullable: false\n",
        "  \"n\":\n    type: integer\n",
    );
    edit(
        "      note: {default: \"'own'::text\"}",
        "      \"n\": {nullable: false}\n      note: {default: \"'own'::text\"}",
    );
    applied("loosen.json");
    assert_eq!(not_null("n"), [1, 0, 0]);
    // NOT NULL set on the parent: `ev_2025`'s own is left to it.
    edit(
        "  m2:\n    type: bigint\n",
        "  m2:\n    type: bigint\n    nullable: false\n",
    );
    edit("    columns:\n      m2: {nullable: false}\n", "");
    applied("tighten.json");
    assert_eq!(not_null("m2"), [1, 1, 1]);
    // And dropped again: `ev_2025`'s own NOT NULL, from before the parent's,
    // is one 18 keeps through the parent's drop, and the plan takes it off.
    edit(
        "  m2:\n    type: bigint\n    nullable: false\n",
        "  m2:\n    type: bigint\n",
    );
    applied("loosen-again.json");
    assert_eq!(not_null("m2"), [0, 0, 0]);
    // A partition's own default in a spelling the engine rewrites, then its
    // column renamed on the parent: the recorded spelling follows the rename
    // into the partition, so the next plan has nothing to do (#1692 review).
    edit(
        "      note: {default: \"'own'::text\"}",
        "      note: {default: \"'own2'\"}",
    );
    applied("own-spelling.json");
    edit("  note:\n", "  label:\n");
    edit(
        "      note: {default: \"'own2'\"}",
        "      label: {default: \"'own2'\"}",
    );
    succeeds(d.run(&["rename", "app.ev.note", "label"]));
    applied("rename-own.json");
    assert_eq!(default_is("label", "'''own2''::text'"), [1, 0, 0]);
    // Dropped.
    edit("  extra:\n    type: integer\n    default: \"3\"\n", "");
    succeeds(d.run(&["drop", "app.ev.extra", "--reason", "gone"]));
    applied("drop.json");
    assert_eq!(
        holds(
            "SELECT count(*) FROM pg_attribute WHERE attname = 'extra' AND NOT attisdropped \
             AND attrelid IN ('app.ev'::regclass, 'app.ev_2024'::regclass, \
             'app.ev_2025'::regclass, 'app.att'::regclass)"
        ),
        0
    );
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.ev"), 3);

    // Refused by name: a key column retyped, then dropped.
    edit("  at:\n    type: date\n", "  at:\n    type: timestamp\n");
    let o = d.run(&["plan"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("which is in its partition key"),
        "{}",
        stderr(&o)
    );
    edit("  at:\n    type: timestamp\n", "  at:\n    type: date\n");
    edit("  at:\n    type: date\n    nullable: false\n", "");
    succeeds(d.run(&["drop", "app.ev.at", "--reason", "gone"]));
    let o = d.run(&["plan"]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("which is in its partition key"),
        "{}",
        stderr(&o)
    );
    assert_eq!(
        holds("SELECT pg_get_partkeydef('app.ev'::regclass) = 'RANGE (at)'"),
        1
    );
}

/// A standing partition's own properties change through the CLI, each on a
/// partition holding rows (#1581): its own index and CHECK added and
/// dropped, its own default changed and then dropped back to its parent's,
/// its own NOT NULL added and dropped, and its persistence and storage
/// parameters switched. Each saved plan applies, verifies and replans empty.
/// A NOT NULL over a NULL the partition holds is refused before the apply's
/// first statement, and an index added to the parent stays refused by name
/// (#1688).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_standing_partitions_own_properties_change_through_the_cli() {
    let server = server();
    let db = OwnDatabase::new(&server, "parts-1581");
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer NOT NULL, ts date NOT NULL, \
             note text DEFAULT 'p', k integer) PARTITION BY RANGE (ts); \
         CREATE TABLE app.ev_2025 PARTITION OF app.ev \
             FOR VALUES FROM ('2025-01-01') TO ('2026-01-01'); \
         CREATE TABLE app.ev_rest PARTITION OF app.ev DEFAULT; \
         ALTER TABLE app.ev_rest ALTER COLUMN note SET DEFAULT 'rest', \
             ALTER COLUMN note SET NOT NULL; \
         ALTER TABLE app.ev_rest SET UNLOGGED; \
         ALTER TABLE app.ev_rest SET (fillfactor = 70); \
         INSERT INTO app.ev VALUES (1, '2025-06-01', 'a', 1), (2, '2025-07-01', 'b', 2), \
             (3, '2030-01-01', 'c', NULL)",
    );
    let d = Demo::new("parts-1581");
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let pulled = "partitions:\n  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n  \
                  ev_rest:\n    default: true\n    columns:\n      \
                  note: {default: \"'rest'::text\", nullable: false}\n    unlogged: true\n    \
                  storage_parameters:\n      fillfactor: 70\n";
    assert!(text.ends_with(pulled), "{text}");
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let declare = |partitions: &str| {
        std::fs::write(&path, text.replace(pulled, partitions)).unwrap();
        d.commit();
    };
    let applied = |name: &str, allow: &[&str]| {
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let planned = stdout(&o);
        succeeds(approved_apply(&d, &conn, &plan, allow));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        planned
    };
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let not_null = |table: &str, column: &str| {
        holds(&format!(
            "SELECT attnotnull FROM pg_attribute \
              WHERE attrelid = '{table}'::regclass AND attname = '{column}'"
        ))
    };
    let default_of = |table: &str| {
        format!(
            "SELECT pg_get_expr(adbin, adrelid) FROM pg_attrdef d JOIN pg_attribute a \
               ON a.attrelid = d.adrelid AND a.attnum = d.adnum \
              WHERE d.adrelid = '{table}'::regclass AND a.attname = 'note'"
        )
    };

    // Added and changed: an index, a CHECK and a NOT NULL of its own on the
    // range partition; a new default of its own, logged and new storage
    // parameters on the DEFAULT one.
    declare(
        "partitions:\n  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n    \
         checks:\n      ev_2025_k_ck: k > 0\n    indexes:\n      ev_2025_k:\n        \
         columns: [k]\n    columns:\n      k: {nullable: false}\n  ev_rest:\n    \
         default: true\n    columns:\n      note: {default: \"'other'\", nullable: false}\n    \
         storage_parameters:\n      fillfactor: 80\n",
    );
    let planned = applied(
        "own.json",
        &["--allow", "constraint", "--allow", "not-null"],
    );
    assert!(
        planned.contains("~ note default -> 'other'") && planned.contains("~ k becomes NOT NULL"),
        "{planned}"
    );
    assert_eq!(holds("SELECT to_regclass('app.ev_2025_k') IS NOT NULL"), 1);
    assert_eq!(
        holds(
            "SELECT EXISTS (SELECT FROM pg_constraint WHERE conname = 'ev_2025_k_ck' \
             AND conrelid = 'app.ev_2025'::regclass)"
        ),
        1
    );
    assert_eq!(not_null("app.ev_2025", "k"), 1);
    assert_eq!(
        holds(&format!(
            "({}) = '''other''::text'",
            default_of("app.ev_rest")
        )),
        1
    );
    assert_eq!(
        holds(
            "SELECT relpersistence = 'p' AND reloptions = '{fillfactor=80}' \
               FROM pg_class WHERE oid = 'app.ev_rest'::regclass"
        ),
        1
    );
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.ev"), 3);

    // Dropped: each back to its parent's, the default taken back from it
    // rather than dropped, and unlogged again with no parameters.
    declare(
        "partitions:\n  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n  \
         ev_rest:\n    default: true\n    unlogged: true\n",
    );
    let planned = applied("back.json", &["--allow", "destructive"]);
    assert!(
        planned.contains("~ note default -> its parent's"),
        "{planned}"
    );
    assert_eq!(holds("SELECT to_regclass('app.ev_2025_k') IS NULL"), 1);
    assert_eq!(
        holds("SELECT NOT EXISTS (SELECT FROM pg_constraint WHERE conname = 'ev_2025_k_ck')"),
        1
    );
    assert_eq!(not_null("app.ev_2025", "k"), 0);
    assert_eq!(not_null("app.ev_rest", "note"), 0);
    assert_eq!(
        holds(&format!(
            "({}) = ({})",
            default_of("app.ev_rest"),
            default_of("app.ev")
        )),
        1
    );
    assert_eq!(
        holds(
            "SELECT relpersistence = 'u' AND reloptions IS NULL \
               FROM pg_class WHERE oid = 'app.ev_rest'::regclass"
        ),
        1
    );
    // A row written to it directly takes its parent's default again.
    on_server(
        &conn,
        "INSERT INTO app.ev_rest (id, ts) VALUES (4, '2031-01-01')",
    );
    assert_eq!(
        scalar(&conn, "SELECT count(*) FROM app.ev WHERE note = 'p'"),
        1
    );

    // Negative: a NOT NULL over the NULLs the partition holds, refused
    // before the apply's first statement.
    declare(
        "partitions:\n  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n  \
         ev_rest:\n    default: true\n    columns:\n      k: {nullable: false}\n    \
         unlogged: true\n",
    );
    let plan = d.dir.join("null.json");
    succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
    let refused = approved_apply(&d, &conn, &plan, &["--allow", "not-null"]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    assert!(
        stderr(&refused).contains("2 existing NULLs in app.ev_rest.k"),
        "{}",
        stderr(&refused)
    );
    assert_eq!(not_null("app.ev_rest", "k"), 0, "nothing ran");

    // An index added to the parent is the parent's change, planned since
    // #1688: the partition's own index on `k` is gone by now, so none is
    // adopted.
    std::fs::write(
        &path,
        text.replace(
            "partition_by: [ts]\n",
            "indexes:\n  ev_k: {columns: [k]}\npartition_by: [ts]\n",
        ),
    )
    .unwrap();
    d.commit();
    let o = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&o).contains("+ index ev_k"), "{}", stdout(&o));
}

/// A function rebuilt under a partition tree's defaults (#1588). The
/// parent's default calls `app.f`, which one partition inherits and another
/// overrides with its own call; a third overrides it with a call to `app.g`
/// alone. Every partition's default row that calls `app.f` is taken off
/// before its drop and put back after its create, and each partition's own,
/// `ev_g`'s too, is set again after the parent's, which reaches every
/// partition. The plan applies, verifies and replans empty, and each
/// partition keeps its default. The same tree, `app.f` new, is created by one
/// plan and by a bootstrap, its partitions reading back their own. A
/// partition's own default calling a function the plan drops for good is
/// still refused by name.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_function_rebuilt_under_partition_defaults_keeps_each_partitions_own() {
    let server = server();
    let own = OwnDatabase::new(&server, "parts-1588");
    let conn = own.connection().to_owned();
    let tree = "CREATE SCHEMA app; \
         CREATE FUNCTION app.f(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
         CREATE FUNCTION app.g(x integer) RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT x $$; \
         CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT app.f(1)) \
             PARTITION BY RANGE (k); \
         CREATE TABLE app.ev_inh PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
         CREATE TABLE app.ev_own PARTITION OF app.ev FOR VALUES FROM (10) TO (20); \
         CREATE TABLE app.ev_g PARTITION OF app.ev FOR VALUES FROM (20) TO (30); \
         ALTER TABLE app.ev_own ALTER COLUMN v SET DEFAULT app.f(2); \
         ALTER TABLE app.ev_g ALTER COLUMN v SET DEFAULT app.g(5)";
    on_server(
        &conn,
        &format!("{tree}; INSERT INTO app.ev (k) VALUES (1), (11), (21)"),
    );
    let d = Demo::new("parts-1588");
    succeeds(d.run(&["pull", "--db", &conn]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    let defaults = |connection: &str| {
        scalar(
            connection,
            "SELECT (string_agg(c.relname || '=' || pg_get_expr(d.adbin, d.adrelid), ' ' \
                                ORDER BY c.relname) = \
                     'ev=app.f(1) ev_g=app.g(5) ev_inh=app.f(1) ev_own=app.f(2)')::int::int8 \
               FROM pg_attrdef d JOIN pg_class c ON c.oid = d.adrelid \
              WHERE c.relnamespace = 'app'::regnamespace",
        )
    };
    // A row written straight to each partition takes that partition's
    // default; one written through the parent takes the parent's.
    let written = |connection: &str| {
        on_server(
            connection,
            "DELETE FROM app.ev; \
             INSERT INTO app.ev (k) VALUES (2); INSERT INTO app.ev_inh (k) VALUES (3); \
             INSERT INTO app.ev_own (k) VALUES (12); INSERT INTO app.ev_g (k) VALUES (22)",
        );
        scalar(
            connection,
            "SELECT (string_agg(k || ':' || v, ' ' ORDER BY k) = '2:1 3:1 12:2 22:5')::int::int8 \
               FROM app.ev",
        )
    };

    let function = d.dir.join("schema/app.f%28integer%29.function.yml");
    let text = std::fs::read_to_string(&function).unwrap();
    let edited = text.replace("SELECT x", "SELECT x * 10");
    assert_ne!(edited, text);
    std::fs::write(&function, edited).unwrap();
    let (plan, script) = connected_plan(&d, &conn);
    let at = |needle: &str| {
        script
            .find(needle)
            .unwrap_or_else(|| panic!("`{needle}` missing from:\n{script}"))
    };
    let parents = at("ALTER TABLE \"app\".\"ev\" ALTER COLUMN \"v\" SET DEFAULT");
    assert!(at("CREATE FUNCTION \"app\".\"f\"") < parents, "{script}");
    for partition in ["ev_own", "ev_g"] {
        assert!(
            parents
                < at(&format!(
                    "ALTER TABLE \"app\".\"{partition}\" ALTER COLUMN \"v\" SET DEFAULT"
                )),
            "{script}"
        );
    }
    succeeds(approved_apply(&d, &conn, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(defaults(&conn), 1);
    assert_eq!(written(&conn), 0, "app.f now multiplies");
    assert_eq!(
        scalar(
            &conn,
            "SELECT (string_agg(k || ':' || v, ' ' ORDER BY k) = '2:10 3:10 12:20 22:5')::int::int8 \
               FROM app.ev"
        ),
        1
    );

    // The same tree, `app.f` new: created by one plan, and by a bootstrap.
    std::fs::write(&function, &text).unwrap();
    let fresh = OwnDatabase::new(&server, "parts-1588-plan");
    on_server(fresh.connection(), "CREATE SCHEMA app");
    succeeds(d.run(&["baseline", "--db", fresh.connection(), "--reason", "empty"]));
    let (plan, _) = connected_plan(&d, fresh.connection());
    succeeds(approved_apply(&d, fresh.connection(), &plan, &[]));
    let booted = OwnDatabase::new(&server, "parts-1588-boot");
    on_server(booted.connection(), "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", booted.connection()]));
    for connection in [fresh.connection(), booted.connection()] {
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        assert_eq!(defaults(connection), 1);
        assert_eq!(written(connection), 1);
    }

    // Negative: `app.g` dropped for good under `ev_g`'s own default.
    std::fs::remove_file(d.dir.join("schema/app.g%28integer%29.function.yml")).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let o = d.run(&["plan", "--db", &conn]);
    assert_eq!(code(&o), 1, "{}{}", stdout(&o), stderr(&o));
    let err = stderr(&o);
    assert!(
        err.contains("app.g(integer)") && err.contains("app.ev_g"),
        "{err}"
    );
}

/// A partition in another schema than its parent takes its parent's default
/// back as the parent's declaration means it (#1607 review): the text is
/// resolved under the parent's schema, so the unqualified `f()` is `app.f`,
/// not the partition schema's `arch.f`. Its own default stays under its own.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitions_default_taken_back_resolves_under_its_parents_schema() {
    let server = server();
    let db = OwnDatabase::new(&server, "parts-1607");
    on_server(
        db.connection(),
        "CREATE SCHEMA app; CREATE SCHEMA arch; \
         CREATE FUNCTION app.f() RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT 1 $$; \
         CREATE FUNCTION arch.f() RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT 2 $$; \
         SET search_path = app; \
         CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT f()) \
             PARTITION BY RANGE (k); \
         RESET search_path; \
         CREATE TABLE arch.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
         ALTER TABLE arch.ev_a ALTER COLUMN v SET DEFAULT 7",
    );
    let d = Demo::new("parts-1607");
    succeeds(d.run(&["pull", "--db", db.connection()]));
    let path = d.dir.join("schema/app.ev.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    let own = "    columns:\n      v: {default: \"7\"}\n";
    assert!(text.contains(own), "{text}");
    // Written unqualified, as a declaration may be: resolved under the
    // parent's schema, it is the `app.f` the database holds.
    let text = text.replace("default: app.f()", "default: f()");
    assert!(text.contains("default: f()"), "{text}");
    std::fs::write(&path, &text).unwrap();
    d.commit();
    // Built from that declaration, which the bootstrap records as written.
    let target = OwnDatabase::new(&server, "parts-1607-target");
    let conn = target.connection().to_owned();
    on_server(&conn, "CREATE SCHEMA app; CREATE SCHEMA arch");
    succeeds(d.run(&["bootstrap", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    std::fs::write(&path, text.replace(own, "")).unwrap();
    d.commit();
    let plan = d.dir.join("back.json");
    let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
    assert!(
        stdout(&o).contains("~ v default -> its parent's"),
        "{}",
        stdout(&o)
    );
    succeeds(approved_apply(&d, &conn, &plan, &[]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    on_server(&conn, "INSERT INTO arch.ev_a (k) VALUES (1)");
    assert_eq!(scalar(&conn, "SELECT v::int8 FROM app.ev WHERE k = 1"), 1);
}

/// A partition's own default the engine stores in its parent's text is
/// refused by name at plan time, before any statement (#1609, DEC-1609.1):
/// `(1)` under a parent's `1` on a standing partition, and `('x'::text)` under
/// a parent's `'x'::text` on one the plan creates. Before, the standing one
/// planned a `SetPartitionDefault` that the apply's closing check refused
/// after it ran, and every plan repeated it. Negative: an own default `2`, and
/// `'other'`, which the engine only respells as `'other'::text`, plan, apply
/// and verify clean. On 16 and 18.
#[test]
#[ignore = "needs both live PostgreSQL versions; see scripts/live-tests-pg.sh"]
fn a_partitions_own_default_stored_as_its_parents_is_refused_before_the_plan() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1609-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; CREATE TABLE app.pbps_1609 (i integer PRIMARY KEY); \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1, b text DEFAULT 'x', \
                 f boolean DEFAULT (false IS NULL), \
                 s bigint DEFAULT ('app.pbps_1609'::regclass)::oid::bigint) PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        // The apply pins `transform_null_equals` off; a probe that inherited
        // this would store the own `false = NULL` below as the parent's
        // `false IS NULL` and refuse it (measured on 18; #1609 review).
        on_server(
            &conn,
            "DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'ALTER DATABASE %I SET transform_null_equals = on', \
                 pg_catalog.current_database()); END $$",
        );
        let d = Demo::new(&format!("parts-1609-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        assert!(pulled.contains(own), "{pulled}");

        // `s` names the parent's table unqualified: under the emitter's path,
        // `pg_temp` last, it is the parent's, not the probe's own
        // `pg_temp.pbps_1609` (#1659).
        let as_parents = pulled.replace(
            own,
            "      v: {default: \"(1)\"}\n      s: {default: \"('pbps_1609'::regclass)::oid::bigint\"}\n",
        ) + "  ev_b:\n    from: [\"10\"]\n    to: [\"20\"]\n    columns:\n      \
               b: {default: \"('x'::text)\"}\n";
        std::fs::write(&path, &as_parents).unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join("refused.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        let err = stderr(&o);
        assert!(
            err.contains(
                "partition app.ev_a column `v`: its own default \"(1)\" is stored as \"1\""
            ) && err.contains(
                "partition app.ev_a column `s`: its own default \"('pbps_1609'::regclass)::oid::bigint\" is \
                 stored as"
            ) && err.contains(
                "partition app.ev_b column `b`: its own default \"('x'::text)\" is stored as"
            ) && err.contains("drop the partition's own default, it is the parent's"),
            "{version}: {err}"
        );
        assert!(
            !plan.exists(),
            "{version}: a refused plan wrote {}",
            plan.display()
        );
        // The probe's temporary table went with its transaction.
        assert_eq!(
            scalar(
                &conn,
                "SELECT count(*) FROM pg_catalog.pg_class \
                 WHERE relname = 'pbps_1609' AND relpersistence = 't'"
            ),
            0,
            "{version}"
        );

        // A declared text cannot end the probe's transaction: the connected
        // plan is read-only (SPEC §9.8), and a batch would have committed
        // the table below (#1609 security review). Unasked, so a warning.
        let escape = pulled.replace(
            own,
            "      v: {default: \"1; COMMIT; CREATE TABLE app.pwned (); COMMIT; BEGIN; \
             SAVEPOINT pbps_1609; SELECT 1\"}\n",
        ) + "  ev_b:\n    from: [\"10\"]\n    to: [\"20\"]\n    columns:\n      \
               b: {default: \"'y'\"}\n";
        std::fs::write(&path, &escape).unwrap();
        d.commit();
        let plan = d.dir.join("escape.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(
            scalar(
                &conn,
                "SELECT count(*) FROM pg_catalog.pg_class WHERE relname = 'pwned'"
            ),
            0,
            "{version}: the plan committed a declared text's SQL"
        );
        assert!(
            stderr(&o).contains(
                "warning: not checked before the plan whether the engine stores it as the \
                 parent's default: partition app.ev_a column `v`"
            ),
            "{version}: {}{}",
            stdout(&o),
            stderr(&o)
        );

        // Negative: a default of its own, and one the engine only respells.
        let own_defaults = pulled.replace(
            own,
            "      v: {default: \"2\"}\n      b: {default: \"'other'\"}\n      \
             f: {default: \"(false = NULL)\"}\n",
        ) + "  ev_b:\n    from: [\"10\"]\n    to: [\"20\"]\n    columns:\n      \
               b: {default: \"'y'\"}\n";
        std::fs::write(&path, &own_defaults).unwrap();
        d.commit();
        let plan = d.dir.join("own.json");
        succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        succeeds(approved_apply(&d, &conn, &plan, &[]));
        succeeds(d.run(&["verify", "--db", &conn]));
        on_server(&conn, "INSERT INTO app.ev_a (k) VALUES (1)");
        assert_eq!(
            scalar(&conn, "SELECT v::int8 FROM app.ev_a WHERE k = 1"),
            2,
            "{version}"
        );
    }
}

/// The partition-default probe runs no DDL while the target has an enabled
/// DDL event trigger: a rollback would not take back what the trigger did
/// outside its transaction, and a connected plan is read-only (SPEC §9.8;
/// #1669, DEC-1609.1). The pair is left to the apply's closing check, with a
/// warning naming the trigger. On 18 and 16. Negative: with the trigger
/// disabled the pair is asked, and refused as the parent's.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn a_ddl_event_trigger_leaves_the_partition_default_probe_unrun() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1669-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1) \
                 PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        let d = Demo::new(&format!("parts-1669-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        // Outside the managed schema, so the plan does not declare it away.
        on_server(
            &conn,
            "CREATE SCHEMA watch; CREATE SEQUENCE watch.fired; \
             CREATE FUNCTION watch.on_ddl() RETURNS event_trigger LANGUAGE plpgsql AS \
                 $$ BEGIN PERFORM pg_catalog.nextval('watch.fired'); END $$; \
             CREATE EVENT TRIGGER pbps_1669_watch ON ddl_command_end \
                 EXECUTE FUNCTION watch.on_ddl()",
        );
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        assert!(pulled.contains(own), "{pulled}");
        std::fs::write(&path, pulled.replace(own, "      v: {default: \"(1)\"}\n")).unwrap();
        d.commit();

        let fired = "SELECT CASE WHEN is_called THEN last_value ELSE 0 END FROM watch.fired";
        let before = scalar(&conn, fired);
        let plan = d.dir.join("unasked.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(
            scalar(&conn, fired),
            before,
            "{version}: the plan fired the event trigger"
        );
        let err = stderr(&o);
        assert!(
            err.contains(
                "warning: not checked before the plan whether the engine stores it as the \
                 parent's default: partition app.ev_a column `v`: the target has the enabled \
                 DDL event trigger(s) `pbps_1669_watch`"
            ),
            "{version}: {}{err}",
            stdout(&o)
        );

        // Negative: disabled, the pair is asked and refused as the parent's.
        on_server(&conn, "ALTER EVENT TRIGGER pbps_1669_watch DISABLE");
        let plan = d.dir.join("asked.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        assert!(
            stderr(&o).contains(
                "partition app.ev_a column `v`: its own default \"(1)\" is stored as \"1\""
            ),
            "{version}: {}",
            stderr(&o)
        );
        on_server(&conn, "DROP EVENT TRIGGER pbps_1669_watch");
    }
}

/// A partition default left unasked keeps its warning when another declared
/// spelling refuses the plan: in JSON it is a `plan.partition-default-unasked`
/// finding in the one `plan.failed` envelope, with no warning line on
/// stderr; in human mode its line stays beside the refusal (#1702). On 18
/// and 16.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn an_unasked_partition_default_stays_in_the_envelope_beside_a_spelling_refusal() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1702-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1) \
                 PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        let d = Demo::new(&format!("parts-1702-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        // An enabled DDL event trigger leaves the pair unasked (#1669), and a
        // bound the engine spells otherwise refuses the plan (#1170).
        on_server(
            &conn,
            "CREATE FUNCTION public.pbps_1702_noop() RETURNS event_trigger LANGUAGE plpgsql AS \
                 $$ BEGIN END $$; \
             CREATE EVENT TRIGGER pbps_1702_watch ON ddl_command_end \
                 EXECUTE FUNCTION public.pbps_1702_noop()",
        );
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        let bound = "[\"10\"]";
        assert!(pulled.contains(own) && pulled.contains(bound), "{pulled}");
        std::fs::write(
            &path,
            pulled
                .replace(own, "      v: {default: \"8\"}\n")
                .replace(bound, "[\"010\"]"),
        )
        .unwrap();
        d.commit();
        let refused = "partition app.ev_a bound on `k` is written \"010\"";
        let warned = "not checked before the plan whether the engine stores it as the parent's \
                      default: partition app.ev_a column `v`";

        let o = d.run(&["plan", "--db", &conn, "--format", "json"]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        assert!(
            !stderr(&o).contains("warning:"),
            "{version}: {}",
            stderr(&o)
        );
        let report = json_output(o);
        let findings = report["findings"]
            .as_array()
            .unwrap_or_else(|| panic!("no findings: {report}"));
        let failed: Vec<_> = findings
            .iter()
            .filter(|f| f["id"] == "plan.failed")
            .collect();
        assert_eq!(failed.len(), 1, "{version}: {report}");
        assert!(
            failed[0]["message"].as_str().unwrap().contains(refused),
            "{version}: {report}"
        );
        let unasked: Vec<_> = findings
            .iter()
            .filter(|f| f["id"] == "plan.partition-default-unasked")
            .collect();
        assert_eq!(unasked.len(), 1, "{version}: {report}");
        assert_eq!(unasked[0]["severity"], "warning", "{version}: {report}");
        let message = unasked[0]["message"].as_str().unwrap();
        assert!(
            message.contains(warned) && message.contains("`pbps_1702_watch`"),
            "{version}: {message}"
        );

        // Negative: human mode keeps the warning line beside the refusal.
        let o = d.run(&["plan", "--db", &conn]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        let err = stderr(&o);
        assert!(
            err.contains(&format!("warning: {warned}")) && err.contains(refused),
            "{version}: {err}"
        );
        assert_eq!(err.matches("warning: ").count(), 1, "{version}: {err}");
        on_server(&conn, "DROP EVENT TRIGGER pbps_1702_watch");
    }
}

/// A partition default left unasked keeps its warning when a later planning
/// step fails, here the drift check: in JSON it is a
/// `plan.partition-default-unasked` finding in the one `plan.failed`
/// envelope, with no warning line on stderr; in human mode its line is printed
/// once, beside the refusal (#1703). On 18 and 16.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn an_unasked_partition_default_stays_in_the_envelope_when_a_later_step_fails() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1703-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1) \
                 PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        let d = Demo::new(&format!("parts-1703-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        // Drift on a recorded fact refuses the plan after the probe has run,
        // and an enabled DDL event trigger leaves its pair unasked (#1669).
        on_server(
            &conn,
            "ALTER TABLE app.ev ALTER COLUMN v SET DEFAULT 2; \
             CREATE FUNCTION public.pbps_1703_noop() RETURNS event_trigger LANGUAGE plpgsql AS \
                 $$ BEGIN END $$; \
             CREATE EVENT TRIGGER pbps_1703_watch ON ddl_command_end \
                 EXECUTE FUNCTION public.pbps_1703_noop()",
        );
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        assert!(pulled.contains(own), "{pulled}");
        std::fs::write(&path, pulled.replace(own, "      v: {default: \"8\"}\n")).unwrap();
        d.commit();
        let refused = "has drifted from the state recorded";
        let warned = "not checked before the plan whether the engine stores it as the parent's \
                      default: partition app.ev_a column `v`";

        let o = d.run(&["plan", "--db", &conn, "--format", "json"]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        // The catalog's own warnings (a superuser here) go to stderr on every
        // connected plan; the unasked one must not.
        assert!(
            !stderr(&o).contains("not checked before the plan"),
            "{version}: {}",
            stderr(&o)
        );
        let report = json_output(o);
        let findings = report["findings"]
            .as_array()
            .unwrap_or_else(|| panic!("no findings: {report}"));
        let failed: Vec<_> = findings
            .iter()
            .filter(|f| f["id"] == "plan.failed")
            .collect();
        assert_eq!(failed.len(), 1, "{version}: {report}");
        assert!(
            failed[0]["message"].as_str().unwrap().contains(refused),
            "{version}: {report}"
        );
        let unasked: Vec<_> = findings
            .iter()
            .filter(|f| f["id"] == "plan.partition-default-unasked")
            .collect();
        assert_eq!(unasked.len(), 1, "{version}: {report}");
        assert_eq!(unasked[0]["severity"], "warning", "{version}: {report}");
        let message = unasked[0]["message"].as_str().unwrap();
        assert!(
            message.contains(warned) && message.contains("`pbps_1703_watch`"),
            "{version}: {message}"
        );

        // Negative: human mode prints the warning line once, beside the
        // refusal, and not again from the error.
        let o = d.run(&["plan", "--db", &conn]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        let err = stderr(&o);
        assert!(
            err.contains(&format!("warning: {warned}")) && err.contains(refused),
            "{version}: {err}"
        );
        assert_eq!(
            err.matches(&format!("warning: {warned}")).count(),
            1,
            "{version}: {err}"
        );
        on_server(&conn, "DROP EVENT TRIGGER pbps_1703_watch");
    }
}

/// Shared warnings retain raw names in JSON and escape them once at both
/// human writers. A default the engine can ask about emits no warning.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn partition_default_warnings_show_names_once_in_json_and_human_output() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let partition = "ev\nline\\tail";
        let column = "v\nline\r\u{1b}[31m\u{9b}\\\u{202e}名前";
        let db = OwnDatabase::new(&server, &format!("parts-2084-{version}"));
        let conn = db.connection();
        on_server(
            conn,
            &format!(
                "CREATE SCHEMA app;
                 CREATE TABLE app.ev (k integer NOT NULL, \"{column}\" integer DEFAULT 1)
                     PARTITION BY RANGE (k);
                 CREATE TABLE app.\"{partition}\" PARTITION OF app.ev FOR VALUES FROM (0) TO (10);
                 ALTER TABLE app.\"{partition}\" ALTER COLUMN \"{column}\" SET DEFAULT 7"
            ),
        );
        let d = Demo::new(&format!("parts-2084-{version}"));
        succeeds(d.run(&["pull", "--db", conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", conn, "--reason", "adopt"]));
        // JSON leaves C1 characters literal; YAML requires them escaped even in quotes.
        let column_yaml = serde_json::to_string(column)
            .unwrap()
            .replace('\u{9b}', "\\u009b");
        let partition_yaml = serde_json::to_string(partition).unwrap();
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev
columns:
  k: {{type: integer, nullable: false}}
  {column_yaml}: {{type: integer, default: \"1\"}}
partition_by: [k]
partitions:
  {partition_yaml}:
    from: [\"0\"]
    to: [\"10\"]
    columns:
      {column_yaml}: {{default: \"8\"}}
"
            ),
        )
        .unwrap();
        d.commit();
        let unasked = |report: &serde_json::Value| -> Vec<serde_json::Value> {
            report["findings"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|finding| finding["id"] == "plan.partition-default-unasked")
                .cloned()
                .collect()
        };
        // Negative: a pair the engine can ask about emits no warning.
        let report = json_output(succeeds(d.run(&["plan", "--db", conn, "--format", "json"])));
        assert!(unasked(&report).is_empty(), "{version}: {report}");

        let trigger =
            "CREATE FUNCTION public.pbps_2084_noop() RETURNS event_trigger LANGUAGE plpgsql AS
                           $$ BEGIN END $$;
                       CREATE EVENT TRIGGER pbps_2084_watch ON ddl_command_end
                           EXECUTE FUNCTION public.pbps_2084_noop()";
        on_server(conn, trigger);
        let prefix =
            "not checked before the plan whether the engine stores it as the parent's default: ";
        let reason = "the target has the enabled DDL event trigger(s) `pbps_2084_watch`, which this check's temporary table would fire";
        let raw = format!("{prefix}partition app.{partition} column `{column}`: {reason}");
        let shown = format!(
            "{prefix}partition app.ev\\nline\\\\tail column `v\\nline\\r\\u{{1b}}[31m\\u{{9b}}\\\\\\u{{202e}}名前`: {reason}"
        );
        let report = json_output(succeeds(d.run(&["plan", "--db", conn, "--format", "json"])));
        let warnings = unasked(&report);
        assert_eq!(warnings.len(), 1, "{version}: {report}");
        assert_eq!(warnings[0]["message"], shown, "{version}: {report}");
        assert_ne!(warnings[0]["message"], raw, "{version}: {report}");
        let check_human = |output: Output| {
            let error = stderr(&succeeds(output));
            let lines: Vec<_> = error
                .lines()
                .filter(|line| line.starts_with("warning: not checked before the plan"))
                .collect();
            assert_eq!(lines, [format!("warning: {shown}")], "{version}: {error}");
        };
        check_human(d.run(&["plan", "--db", conn]));
        // Bootstrap uses the direct warning printer rather than the plan envelope.
        let empty = OwnDatabase::new(&server, &format!("parts-2084-boot-{version}"));
        on_server(empty.connection(), &format!("CREATE SCHEMA app; {trigger}"));
        let sql = d.dir.join("bootstrap.sql");
        check_human(d.run(&[
            "bootstrap",
            "--db",
            empty.connection(),
            "--sql",
            sql.to_str().unwrap(),
        ]));
    }
}

/// A partition's own default the probe could not ask about is a typed
/// warning in a JSON plan's one envelope, with nothing beside it on stderr
/// (SPEC §9.8; #1660). Human output keeps the warning line. Negative: a pair
/// that was asked adds no such finding. On 18 and 16.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn an_unasked_partition_default_is_a_warning_in_the_json_plan() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1660-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1) \
                 PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        let d = Demo::new(&format!("parts-1660-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        assert!(pulled.contains(own), "{pulled}");
        std::fs::write(&path, pulled.replace(own, "      v: {default: \"8\"}\n")).unwrap();
        d.commit();
        let unasked = |report: &serde_json::Value| -> Vec<serde_json::Value> {
            report["findings"]
                .as_array()
                .unwrap_or_else(|| panic!("no findings: {report}"))
                .iter()
                .filter(|f| f["id"] == "plan.partition-default-unasked")
                .cloned()
                .collect()
        };

        // Negative first: asked, so no such finding.
        let report = json_output(succeeds(
            d.run(&["plan", "--db", &conn, "--format", "json"]),
        ));
        assert!(unasked(&report).is_empty(), "{version}: {report}");

        // An enabled DDL event trigger leaves the pair unasked (#1669).
        on_server(
            &conn,
            "CREATE FUNCTION public.pbps_1660_noop() RETURNS event_trigger LANGUAGE plpgsql AS \
                 $$ BEGIN END $$; \
             CREATE EVENT TRIGGER pbps_1660_watch ON ddl_command_end \
                 EXECUTE FUNCTION public.pbps_1660_noop()",
        );
        let o = succeeds(d.run(&["plan", "--db", &conn, "--format", "json"]));
        assert!(
            !stderr(&o).contains("not checked before the plan"),
            "{version}: {}",
            stderr(&o)
        );
        let report = json_output(o);
        let found = unasked(&report);
        assert_eq!(found.len(), 1, "{version}: {report}");
        assert_eq!(found[0]["severity"], "warning", "{version}: {report}");
        let message = found[0]["message"].as_str().unwrap();
        assert!(
            message.contains("partition app.ev_a column `v`")
                && message.contains("`pbps_1660_watch`"),
            "{version}: {message}"
        );

        // Human output keeps the line.
        let o = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(
            stderr(&o).contains(
                "warning: not checked before the plan whether the engine stores it as the \
                 parent's default: partition app.ev_a column `v`"
            ),
            "{version}: {}",
            stderr(&o)
        );
        on_server(&conn, "DROP EVENT TRIGGER pbps_1660_watch");
    }
}

/// Operators a user who may create in a schema could add, each raising when
/// it is called. Every one has a built-in that pbps's own SQL reaches only
/// through a cast or a polymorphic argument, and an operator whose argument
/// types match exactly is chosen over that built-in even with `pg_catalog`
/// searched first (measured on 16 and 18; #1564).
fn trap_operators(schema: &str) -> String {
    let mut sql = format!(
        "CREATE FUNCTION {schema}.pbps_trap() RETURNS boolean LANGUAGE plpgsql AS $$
             BEGIN RAISE EXCEPTION 'pbps-trap: an operator in {schema} was called'; END $$;"
    );
    let traps = [
        ("=", "oid", "regclass"),
        ("<>", "oid", "regclass"),
        ("=", "oid", "integer"),
        ("<>", "oid", "integer"),
        ("||", "text", "name"),
        ("||", "name", "text"),
        ("||", "text", "oid"),
        ("||", "text", "\"char\""),
        ("||", "text", "bigint"),
        ("||", "text", "smallint"),
        ("=", "smallint[]", "smallint[]"),
        // A row write's key: `varchar` has no `=` of its own, so the
        // built-in one is reached through `text` (DEC-1564.2).
        ("=", "character varying", "character varying"),
    ];
    for (i, (op, left, right)) in traps.iter().enumerate() {
        let returns = if *op == "||" { "text" } else { "boolean" };
        sql.push_str(&format!(
            "CREATE FUNCTION {schema}.pbps_trap_{i}({left}, {right}) RETURNS {returns}
                 LANGUAGE plpgsql AS $$ BEGIN PERFORM {schema}.pbps_trap(); RETURN NULL; END $$;
             CREATE OPERATOR {schema}.{op} (leftarg = {left}, rightarg = {right},
                 function = {schema}.pbps_trap_{i});"
        ));
    }
    sql
}

/// pbps's own SQL calls no operator a schema user could add (#1564,
/// DEC-1564.1). Traps sit in `public`, on the deployer's default path, and in
/// the managed schema, the path an apply's batches carry. A pull, a connected
/// plan with its probes, an apply that drops a key the declaration never
/// named, deletes a declared row a child could still reference, and updates
/// and deletes rows by a `varchar` key, grants a declared INSERT's serial
/// sequence USAGE (#1892) and explicit SELECT (#2199), and `doctor` all run
/// without springing one. On 16 and 18. Before, the apply's key lookup compared
/// `conrelid` with a `regclass` on `app`'s path and the trap there refused
/// the plan, and a row write's `"k" = E'a'` called the `varchar` trap.
#[test]
#[ignore = "needs both live PostgreSQL versions; see scripts/live-tests-pg.sh"]
fn pbps_sql_calls_no_operator_a_schema_user_could_add() {
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let slug = format!("operator_traps_{version}");
        let own = OwnDatabase::new(&server, &slug);
        let connection = own.connection();
        on_server(connection, "CREATE SCHEMA app");
        let d = Demo::new(&slug);
        let write = |name: &str, body: &str| {
            std::fs::write(d.dir.join(format!("schema/app.{name}.yml")), body).unwrap();
        };
        let keyed = |fillfactor: u8, identity: &str| {
            format!(
                "table: app.k\ncolumns:\n  id: {{type: integer, nullable: false}}\n\
                 primary_key: {{columns: [id], storage_parameters: {{fillfactor: {fillfactor}}}}}\n\
                 {identity}"
            )
        };
        write("k", &keyed(80, ""));
        let parent = "table: app.p\ncolumns:\n  id: {type: integer, nullable: false}\n  \
                      n: {type: integer}\nprimary_key: {name: pk_p, columns: [id]}\n";
        write(
            "p",
            &format!("{parent}data:\n  mode: exact\n  rows:\n    1: {{}}\n    2: {{}}\n"),
        );
        write(
            "c",
            "table: app.c\ncolumns:\n  id: {type: integer}\nforeign_keys:\n  fk_c:\n    \
             columns: [id]\n    references: app.p(id)\n",
        );
        let coded = "table: app.v\ncolumns:\n  k: {type: varchar(10), nullable: false}\n  \
                     n: {type: integer}\nprimary_key: {columns: [k]}\ndata:\n  mode: exact\n  rows:\n";
        write("v", &format!("{coded}    a: {{n: 1}}\n    b: {{n: 2}}\n"));
        // A serial whose sequence a declared INSERT grants USAGE on: the
        // grant's catalog read is pbps's own (#1892).
        write(
            "s",
            "table: app.s\ncolumns:\n  id: {type: serial}\nprimary_key: {columns: [id]}\n",
        );
        let writer = format!("pbps_trap_writer_{}", std::process::id());
        on_server(
            connection,
            &format!("DROP ROLE IF EXISTS {writer}; CREATE ROLE {writer}"),
        );
        succeeds(d.run(&["plan"]));
        d.commit();
        succeeds(d.run(&["bootstrap", "--db", connection]));
        on_server(connection, "INSERT INTO app.c (id) VALUES (1)");
        on_server(connection, &trap_operators("public"));
        on_server(connection, &trap_operators("app"));
        // The traps spring where nothing guards against them.
        let sprung = try_on_server(
            connection,
            "SET search_path = app; \
             SELECT count(*) FROM pg_catalog.pg_class WHERE oid = 'app.k'::pg_catalog.regclass",
        );
        assert!(
            sprung.as_ref().is_err_and(|e| e.contains("pbps-trap")),
            "{version}: {sprung:?}"
        );

        let clean = |what: &str, out: Output| {
            let all = format!("{}{}", stdout(&out), stderr(&out));
            assert!(
                !all.contains("pbps-trap"),
                "{version}: {what} called a trap:\n{all}"
            );
            assert_eq!(code(&out), 0, "{version}: {what}:\n{all}");
        };
        let pulled = Demo::new(&format!("{slug}_pull"));
        clean("pull", pulled.run(&["pull", "--db", connection]));

        // Finds the key's index by asking the catalog, twice, deletes row 2
        // under the guard that looks for a child still pointing at it, and
        // adds a check the probes count violations of. Updates row `a` and
        // deletes row `b` by their `varchar` key.
        write("k", &keyed(70, "replica_identity: primary_key\n"));
        write("v", &format!("{coded}    a: {{n: 5}}\n"));
        std::fs::write(
            d.dir.join(format!("schema/{writer}.yml")),
            format!("role: {writer}\ngrants:\n  schema::app: [usage]\n  app.s: [insert]\n  sequence::app.s.id: [select]\n"),
        )
        .unwrap();
        write(
            "p",
            &format!(
                "{parent}checks:\n  ck_n: n IS NULL OR n > 0\ndata:\n  mode: exact\n  rows:\n    1: {{}}\n"
            ),
        );
        succeeds(d.run(&["plan"]));
        d.commit();
        let plan = d.dir.join("plan.json");
        let planned = d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]);
        clean("plan --db", planned);
        clean(
            "apply",
            approved_apply(
                &d,
                connection,
                &plan,
                &["--allow", "destructive,constraint,data-update,data-delete"],
            ),
        );
        assert_eq!(
            text_of(
                connection,
                "SELECT pg_catalog.array_to_string(i.reloptions, ',') || ' ' || c.relreplident::text \
                 FROM pg_catalog.pg_class c \
                 JOIN pg_catalog.pg_constraint k ON k.conrelid = c.oid AND k.contype = 'p' \
                 JOIN pg_catalog.pg_class i ON i.oid = k.conindid \
                 WHERE c.oid = 'app.k'::regclass::oid"
            ),
            "fillfactor=70 i",
            "{version}: the key's index and the replica identity changed"
        );
        assert_eq!(
            scalar(connection, "SELECT count(*) FROM app.p"),
            1,
            "{version}"
        );
        assert_eq!(
            text_of(
                connection,
                "SELECT pg_catalog.string_agg(k::text || ':' || n::text, ',') FROM app.v"
            ),
            "a:5",
            "{version}: row a updated and row b deleted by their key"
        );
        clean("doctor", d.run(&["doctor", "--db", connection]));
        on_server(
            connection,
            &format!(
                "SET ROLE {writer}; INSERT INTO app.s DEFAULT VALUES; RESET ROLE; \
                 DROP OWNED BY {writer}; DROP ROLE {writer}"
            ),
        );
    }
}

/// An unlogged partition under a parent that a table outside the
/// declarations references through a permanent key is refused by name
/// (#1595, DEC-1595.1): at `plan --db`, and again at the apply of a plan
/// made before that key arrived, before its first statement. The engine
/// takes the partition all the same, so nothing else would. A partitioned
/// referencing table is named by the key it declares. Not refused: an
/// unlogged referencing table, which a crash empties too, and a permanent
/// partition.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_unlogged_partition_under_an_undeclared_permanent_key_is_refused() {
    let server = server();
    let db = OwnDatabase::new(&server, "parts-1595");
    let conn = db.connection().to_owned();
    on_server(
        &conn,
        "CREATE SCHEMA app; \
         CREATE TABLE app.ev (id integer PRIMARY KEY) PARTITION BY RANGE (id); \
         CREATE TABLE app.ev_1 PARTITION OF app.ev FOR VALUES FROM (0) TO (10)",
    );
    let d = Demo::new("parts-1595");
    succeeds(d.run(&["pull", "--db", &conn]));
    let path = d.dir.join("schema/app.ev.yml");
    let text = std::fs::read_to_string(&path).unwrap();
    d.commit();
    succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
    // Outside the declarations: a permanent table and an unlogged one, each
    // with a key to the parent.
    on_server(
        &conn,
        "CREATE SCHEMA ext; \
         CREATE TABLE ext.r (id integer REFERENCES app.ev); \
         CREATE UNLOGGED TABLE ext.u (id integer REFERENCES app.ev)",
    );
    let declare = |unlogged: bool| {
        let partition = if unlogged {
            "  ev_2:\n    from: [\"10\"]\n    to: [\"20\"]\n    unlogged: true\n"
        } else {
            "  ev_2: {from: [\"10\"], to: [\"20\"]}\n"
        };
        std::fs::write(&path, format!("{text}{partition}")).unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    let named = "app.ev_2 would be created unlogged under app.ev, which ext.r's foreign key \
                 `r_id_fkey` references";
    let absent = || scalar(&conn, "SELECT (to_regclass('app.ev_2') IS NULL)::int::int8");

    declare(true);
    let refused = d.run(&["plan", "--db", &conn]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    assert!(stderr(&refused).contains(named), "{}", stderr(&refused));
    assert!(!stderr(&refused).contains("ext.u"), "{}", stderr(&refused));

    // Planned while only the unlogged table held a key, then the permanent
    // one arrives: the apply refuses before its first statement.
    on_server(&conn, "DROP TABLE ext.r");
    let plan = d.dir.join("unlogged.json");
    succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
    on_server(&conn, "CREATE TABLE ext.r (id integer REFERENCES app.ev)");
    let refused = approved_apply(&d, &conn, &plan, &[]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    assert!(stderr(&refused).contains(named), "{}", stderr(&refused));
    assert_eq!(absent(), 1, "nothing ran");

    // A partitioned referencing table is named by the key it declares,
    // through the leaf that holds a copy under a name of its own (#1612
    // review).
    on_server(
        &conn,
        "DROP TABLE ext.r; \
         CREATE TABLE ext.rp (id integer, CONSTRAINT rp_k FOREIGN KEY (id) REFERENCES app.ev) \
             PARTITION BY RANGE (id); \
         CREATE TABLE ext.rp_1 (id integer, \
             CONSTRAINT own_name FOREIGN KEY (id) REFERENCES app.ev); \
         ALTER TABLE ext.rp ATTACH PARTITION ext.rp_1 FOR VALUES FROM (0) TO (10)",
    );
    let refused = d.run(&["plan", "--db", &conn]);
    assert_ne!(code(&refused), 0, "{}", stdout(&refused));
    assert!(
        stderr(&refused).contains(
            "which ext.rp's foreign key `rp_k` (on its partition ext.rp_1 as `own_name`) \
             references"
        ),
        "{}",
        stderr(&refused)
    );
    on_server(
        &conn,
        "DROP TABLE ext.rp; CREATE TABLE ext.r (id integer REFERENCES app.ev)",
    );

    // Negative: a permanent partition under the same key plans and applies.
    declare(false);
    let plan = d.dir.join("permanent.json");
    succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(&d, &conn, &plan, &[]));
    assert_eq!(absent(), 0);
    succeeds(d.run(&["verify", "--db", &conn]));
}

/// A role other than the deployer or a superuser that can change the
/// database's catalog leaves every partition default pair unasked, naming the
/// role: storing a literal of a composite over its domain runs the domain's
/// check as the deployer, and its function could read and raise what only
/// the deployer can (#1663). Its function never runs, and nothing it would
/// have read reaches the output. So does each way it could change the
/// catalog before the store: types it owns with no check yet, `CREATE` on the
/// database, `ADMIN` on the deploying role, or inheriting it without `SET`
/// (#1707). A text naming another session's temporary schema is left unasked
/// whoever holds it, its check unrun (#1706). Negatives: without it, the pair
/// is asked and refused as the
/// parent's, a domain the deployer owns calling only built-ins does not stop
/// it, and a text the engine refuses is told by its SQLSTATE alone. On 18
/// and 16.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn an_untrusted_domain_check_leaves_the_partition_default_probe_unrun() {
    const LOW: &str = "partition app.ev_a column `v`: the role(s) `pbps_1663_low`, neither \
                       a superuser nor able to become this one, can change this database's \
                       catalog";
    let old = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (version, server) in [("18", server()), ("16", old)] {
        let db = OwnDatabase::new(&server, &format!("parts-1663-{version}"));
        let conn = db.connection().to_owned();
        on_server(
            &conn,
            "CREATE SCHEMA app; \
             CREATE TABLE app.ev (k integer NOT NULL, v integer DEFAULT 1) \
                 PARTITION BY RANGE (k); \
             CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES FROM (0) TO (10); \
             ALTER TABLE app.ev_a ALTER COLUMN v SET DEFAULT 7",
        );
        let d = Demo::new(&format!("parts-1663-{version}"));
        succeeds(d.run(&["pull", "--db", &conn]));
        d.commit();
        succeeds(d.run(&["baseline", "--db", &conn, "--reason", "adopt"]));
        // A role with CREATE in a schema of its own writes a check that
        // counts its runs and raises what only the deployer can read.
        on_server(
            &conn,
            "DO $$ BEGIN CREATE ROLE pbps_1663_low; \
                 EXCEPTION WHEN duplicate_object THEN NULL; END $$; \
             CREATE TABLE public.pbps_1663_secret (s text); \
             INSERT INTO public.pbps_1663_secret VALUES ('pbps-1663-secret'); \
             CREATE SCHEMA evil; CREATE SEQUENCE evil.ran; \
             GRANT CREATE, USAGE ON SCHEMA evil TO pbps_1663_low; \
             SET ROLE pbps_1663_low; \
             CREATE FUNCTION evil.peek(integer) RETURNS boolean LANGUAGE plpgsql AS \
                 $$ BEGIN PERFORM pg_catalog.nextval('evil.ran'); \
                    RAISE EXCEPTION 'leaked %', \
                        (SELECT pg_catalog.string_agg(s, ',') FROM public.pbps_1663_secret); \
                 END $$; \
             CREATE DOMAIN evil.d AS integer CHECK (evil.peek(VALUE)); \
             CREATE TYPE evil.c AS (v evil.d); \
             RESET ROLE",
        );
        let path = d.dir.join("schema/app.ev.yml");
        let pulled = std::fs::read_to_string(&path).unwrap();
        let own = "      v: {default: \"7\"}\n";
        assert!(pulled.contains(own), "{pulled}");
        let declare = |text: &str| {
            std::fs::write(
                &path,
                pulled.replace(own, &format!("      v: {{default: {text:?}}}\n")),
            )
            .unwrap();
            d.commit();
        };
        declare("pg_catalog.length((('(5)')::evil.c)::text)");

        let ran = "SELECT CASE WHEN is_called THEN last_value ELSE 0 END FROM evil.ran";
        let plan = d.dir.join("unasked.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(scalar(&conn, ran), 0, "{version}: the plan ran the check");
        let (out, err) = (stdout(&o), stderr(&o));
        assert!(
            !out.contains("pbps-1663-secret") && !err.contains("pbps-1663-secret"),
            "{version}: {out}{err}"
        );
        assert!(
            err.contains(
                "warning: not checked before the plan whether the engine stores it as the \
                 parent's default: partition app.ev_a column `v`: the role(s) \
                 `pbps_1663_low`, neither a superuser nor able to become this one, can \
                 change this database's catalog, and storing a default can run a check \
                 written there as this role"
            ),
            "{version}: {out}{err}"
        );

        // A type another role owns holds no check yet, and no schema lets it
        // create one: it can still add a `NOT VALID` CHECK to its domain, or a
        // column of a new domain to its composite or table, between the read
        // and the store, so the pair stays unasked all the same (#1706). A
        // membership in the deploying role granted without SET or INHERIT
        // does not make it the deployer.
        on_server(
            &conn,
            "DROP SCHEMA evil CASCADE; CREATE SCHEMA held; \
             DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'GRANT %I TO pbps_1663_low WITH INHERIT FALSE, SET FALSE', \
                 CURRENT_USER); END $$; \
             GRANT CREATE, USAGE ON SCHEMA held TO pbps_1663_low; \
             SET ROLE pbps_1663_low; \
             CREATE DOMAIN held.nc AS integer; \
             CREATE TYPE held.c AS (v integer); \
             CREATE TABLE held.t (a integer); \
             RESET ROLE; \
             REVOKE CREATE ON SCHEMA held FROM pbps_1663_low",
        );
        declare("(2)");
        let plan = d.dir.join("held.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let err = stderr(&o);
        assert!(err.contains(LOW), "{version}: {}{err}", stdout(&o));

        // A role that can create a schema in the database can create the type
        // a declared text names, in a schema no read could have seen (#1706).
        on_server(
            &conn,
            "DROP SCHEMA held CASCADE; \
             DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'GRANT CREATE ON DATABASE %I TO pbps_1663_low', \
                 pg_catalog.current_database()); END $$",
        );
        declare("(3)");
        let plan = d.dir.join("creator.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let err = stderr(&o);
        assert!(err.contains(LOW), "{version}: {}{err}", stdout(&o));

        // Negative: without them, and beside a domain the deployer owns that
        // calls only built-ins, the pair is asked and refused as the parent's.
        // A role holding ADMIN on the deploying role, though it can act as
        // neither, can grant it with SET to a role of its own before the store,
        // which could then change the deployer's own types (#1706).
        on_server(
            &conn,
            "DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'REVOKE CREATE ON DATABASE %I FROM pbps_1663_low', \
                 pg_catalog.current_database()); \
             EXECUTE pg_catalog.format( \
                 'GRANT %I TO pbps_1663_low WITH ADMIN TRUE', CURRENT_USER); END $$",
        );
        declare("(4)");
        let plan = d.dir.join("admin.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let err = stderr(&o);
        assert!(err.contains(LOW), "{version}: {}{err}", stdout(&o));

        // A member that inherits the deploying role's privileges but cannot
        // SET to it is not the deployer: `current_user` tells them apart, so
        // a check it writes would see what a row policy hides from it (#1706).
        on_server(
            &conn,
            "DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'GRANT %I TO pbps_1663_low WITH ADMIN FALSE, INHERIT TRUE', \
                 CURRENT_USER); END $$",
        );
        declare("(5)");
        let plan = d.dir.join("inherit.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let err = stderr(&o);
        assert!(err.contains(LOW), "{version}: {}{err}", stdout(&o));

        on_server(
            &conn,
            "DO $$ BEGIN EXECUTE pg_catalog.format( \
                 'REVOKE %I FROM pbps_1663_low', CURRENT_USER); END $$; \
             CREATE DOMAIN public.pbps_1663_ok AS integer CHECK (VALUE > 0)",
        );
        declare("(1)");
        let plan = d.dir.join("asked.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        assert_eq!(code(&o), 1, "{version}: {}{}", stdout(&o), stderr(&o));
        assert!(
            stderr(&o).contains(
                "partition app.ev_a column `v`: its own default \"(1)\" is stored as \"1\""
            ),
            "{version}: {}",
            stderr(&o)
        );

        // Another session's temporary schema is open to any role with TEMP,
        // PUBLIC's by default, so a check there can appear after the read;
        // a superuser reaches it by naming it. Held here by the deployer, so
        // only the text leaves the pair unasked, and the check never runs
        // (#1706).
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let mut held = rt
            .block_on(pbps_db::Conn::connect(pbps_db::Driver::Postgres, &conn))
            .unwrap();
        on_server(&conn, "CREATE SEQUENCE public.pbps_1663_temp_ran");
        rt.block_on(held.execute(
            "CREATE FUNCTION pg_temp.bump(integer) RETURNS boolean LANGUAGE sql AS \
                 $$ SELECT pg_catalog.nextval('public.pbps_1663_temp_ran') > 0 $$; \
             CREATE DOMAIN pg_temp.d AS integer CHECK (pg_temp.bump(VALUE)); \
             CREATE TYPE pg_temp.c AS (v pg_temp.d)",
        ))
        .unwrap();
        let temp = text_of(
            &conn,
            "SELECT n.nspname::text FROM pg_catalog.pg_type t \
               JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace \
              WHERE t.typname = 'c' AND n.nspname LIKE 'pg\\_temp\\_%'",
        );
        declare(&format!("pg_catalog.length((('(6)')::{temp}.c)::text)"));
        let plan = d.dir.join("temporary.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let temp_ran = "SELECT CASE WHEN is_called THEN last_value ELSE 0 END \
                        FROM public.pbps_1663_temp_ran";
        assert_eq!(
            scalar(&conn, temp_ran),
            0,
            "{version}: the plan ran the check"
        );
        assert!(
            stderr(&o).contains(
                "partition app.ev_a column `v`: its declared text may name a temporary \
                 schema, whose objects another session can change"
            ),
            "{version}: {}{}",
            stdout(&o),
            stderr(&o)
        );
        drop(held);
        drop(rt);

        // A text the engine refuses is told by its SQLSTATE, not its words.
        declare("('pbps-1663-text')::integer");
        let plan = d.dir.join("refused.json");
        let o = d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]);
        let err = stderr(&o);
        assert!(
            err.contains("partition app.ev_a column `v`: the engine refused it (SQLSTATE 22P02)")
                && !err.contains("invalid input syntax"),
            "{version}: {}{err}",
            stdout(&o)
        );
        on_server(
            &conn,
            "DROP OWNED BY pbps_1663_low; DROP ROLE pbps_1663_low",
        );
    }
}

