/// A date or time written otherwise than the engine spells it is the value
/// the engine reads (DEC-1883.1): a row's cell, its key and a partition bound written `2026-02-01` for a `timestamp` plan, apply,
/// bootstrap, verify and plan clean, are stored as that value, and plan clean
/// again written the engine's way; `pull --data` writes the engine's spelling.
/// Two keys that read as one stay refused (DECISIONS 106), as do a `numeric`
/// spelling (DECISIONS 101 outside the date and time types), a text with two
/// readings (DEC-1756.1) and one the engine cannot read at all, and so are two
/// partitions' list values the key's type takes as one (#1632).
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_date_or_time_is_taken_as_the_value_the_engine_reads() {
    let server = server();
    let own = OwnDatabase::new(&server, "temporal-1883");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("temporal-1883");
    let ev = d.dir.join("schema/app.ev.yml");
    let p = d.dir.join("schema/app.p.yml");
    let declare = |key: &str, at: &str, amount: &str, bound: &str, extra: &str| {
        std::fs::write(
            &ev,
            format!(
                "table: app.ev\ncolumns:\n  k: {{type: timestamp without time zone, \
                 nullable: false}}\n  at: {{type: timestamp without time zone}}\n  \
                 tz: {{type: timestamp with time zone}}\n  \
                 amount: {{type: \"numeric(5,2)\"}}\n\
                 primary_key: {{name: ev_pkey, columns: [k]}}\n\
                 data:\n  mode: exact\n  rows:\n    \
                 \"{key}\": {{at: \"{at}\", tz: \"2026-02-01 00:00:00Z\", \
                 amount: \"{amount}\"}}\n{extra}"
            ),
        )
        .unwrap();
        std::fs::write(
            &p,
            format!(
                "table: app.p\ncolumns:\n  ts: {{type: timestamp without time zone, \
                 nullable: false}}\npartition_by: [ts]\npartitions:\n  p_a:\n    \
                 from: [\"{bound}\"]\n    to: [\"2026-06-01\"]\n"
            ),
        )
        .unwrap();
        d.commit();
    };
    let stored = |connection: &str| {
        scalar(
            connection,
            "SELECT count(*) FROM app.ev WHERE k = '2026-02-01 00:00:00' \
               AND at = '2026-02-01 00:00:00' AND tz = '2026-02-01 00:00:00+00'",
        )
    };
    let bound = |connection: &str| {
        scalar(
            connection,
            "SELECT count(*) FROM pg_class WHERE oid = 'app.p_a'::regclass \
               AND pg_get_expr(relpartbound, oid) \
                   = 'FOR VALUES FROM (''2026-02-01 00:00:00'') TO (''2026-06-01 00:00:00'')'",
        )
    };
    declare("2026-02-01", "2026-02-01", "1.50", "2026-02-01", "");
    // Identities for what is declared, as an author's offline plan mints.
    // Only here: offline, a bound written another way is a changed bound, as
    // it always was — only the engine can say the two are one value.
    succeeds(d.run(&["plan"]));
    d.commit();

    // Planned, applied, verified and planned again: nothing left to say.
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
    let plan = d.dir.join("plan.json");
    succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(&d, connection, &plan, &[]));
    succeeds(d.run(&["verify", "--db", connection]));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(stored(connection), 1);
    assert_eq!(bound(connection), 1);

    // Bootstrapped into an empty database, the same.
    let fresh = OwnDatabase::new(&server, "temporal-1883-boot");
    on_server(fresh.connection(), "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", fresh.connection()]));
    succeeds(d.run(&["verify", "--db", fresh.connection()]));
    let next = succeeds(d.run(&["plan", "--db", fresh.connection()]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(stored(fresh.connection()), 1);
    assert_eq!(bound(fresh.connection()), 1);

    // Written the engine's way, the same values: nothing to change.
    declare(
        "2026-02-01 00:00:00",
        "2026-02-01 00:00:00",
        "1.50",
        "2026-02-01 00:00:00",
        "",
    );
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // `pull --data` writes what the engine reads, in its spelling.
    let pulled = Demo::new("temporal-1883-pull");
    succeeds(pulled.run(&["pull", "--db", connection, "--data", "app.ev"]));
    let text = std::fs::read_to_string(pulled.dir.join("schema/app.ev.yml")).unwrap();
    for needle in [
        "\"2026-02-01 00:00:00\": {",
        "at: \"2026-02-01 00:00:00\"",
        "tz: \"2026-02-01 00:00:00+00\"",
    ] {
        assert!(text.contains(needle), "missing {needle:?} in:\n{text}");
    }

    // Still refused, each by name, and nothing changes.
    for (extra, at, amount, needle) in [
        (
            "    \"2026-02-01 00:00:00\": {}\n",
            "2026-02-01",
            "1.50",
            "are the same row to the database",
        ),
        ("", "2026-02-01", "1.5", "`amount` is written \"1.5\""),
        (
            "",
            "01/02/2026",
            "1.50",
            "`at` \"01/02/2026\" is read as 2026-01-02 00:00:00 under this tool's settings",
        ),
        (
            "",
            "2026-02-30",
            "1.50",
            "`at` = \"2026-02-30\" cannot be read as timestamp without time zone",
        ),
    ] {
        declare("2026-02-01", at, amount, "2026-02-01", extra);
        let o = d.run(&["plan", "--db", connection]);
        assert_ne!(code(&o), 0, "{needle}: {}", stdout(&o));
        assert!(stderr(&o).contains(needle), "{needle}: {}", stderr(&o));
    }
    assert_eq!(stored(connection), 1);

    // Two list values in two partitions that the key's type takes as one
    // value: validation compares text and sees two, the engine would refuse
    // the second partition, so the connected plan names the pair by the
    // type's own equality (#1632). A timestamp spelt two ways, and a numeric
    // whose two spellings are each the engine's own.
    declare("2026-02-01", "2026-02-01", "1.50", "2026-02-01", "");
    let list = |table: &str, ty: &str, first: &str, second: &str| {
        std::fs::write(
            d.dir.join(format!("schema/app.{table}.yml")),
            format!(
                "table: app.{table}\ncolumns:\n  k: {{type: {ty}, nullable: false}}\n\
                 partition_by: {{list: [k]}}\npartitions:\n  \
                 {table}_a:\n    in: [\"{first}\"]\n  {table}_b:\n    in: [\"{second}\"]\n"
            ),
        )
        .unwrap();
        // Offline the two are two values, so the author's plan mints them.
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    // Negative: values the engine reads apart plan as written, and one
    // partition may list two spellings of one value.
    list(
        "m",
        "timestamp without time zone",
        "2026-02-01",
        "2026-03-01",
    );
    list("o", "numeric", "1.0\", \"1.00", "2");
    succeeds(d.run(&["plan", "--db", connection]));
    list(
        "l",
        "timestamp without time zone",
        "2026-02-01",
        "2026-02-01 00:00:00",
    );
    list("n", "numeric", "1.0", "1.00");
    let o = d.run(&["plan", "--db", connection]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    for needle in [
        "2 pair(s) of list values are one value of the partition key's type",
        "`app.l_a` takes \"2026-02-01\" and `app.l_b` takes \"2026-02-01 00:00:00\" of `app.l`",
        "`app.n_a` takes \"1.0\" and `app.n_b` takes \"1.00\" of `app.n`",
    ] {
        assert!(stderr(&o).contains(needle), "{needle}: {}", stderr(&o));
    }
    assert!(!stderr(&o).contains("app.o"), "{}", stderr(&o));
}

/// A date/time literal the engine reads two ways is refused by a connected
/// plan and a connected bootstrap, each naming both readings and what to write
/// instead: a row's cell, a column default and a partition bound, and a value
/// read as the moment the statement runs (#1756). A `text` column holding the
/// same characters is not one, and offline planning is unchanged. Nor is an
/// offset-less `timestamptz`: it is read in the target's own zone, which no
/// setting contrasts, and is taken as read (DEC-1916.1). Written the one way
/// they can be read, the same values plan, apply, verify and plan clean.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn an_ambiguous_date_or_time_literal_is_refused_with_both_readings() {
    let server = server();
    let own = OwnDatabase::new(&server, "ambiguous-1756");
    let connection = own.connection();
    on_server(connection, "CREATE SCHEMA app");
    let d = Demo::new("ambiguous-1756");
    let ev = d.dir.join("schema/app.ev.yml");
    let p = d.dir.join("schema/app.p.yml");
    let declare = |date: &str, default: &str, ts: &str, span: &str, clock: &str, bound: &str| {
        std::fs::write(
            &ev,
            format!(
                "table: app.ev\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 d: {{type: date, default: \"'{default}'::date\"}}\n  \
                 ts: {{type: timestamp with time zone}}\n  span: {{type: interval}}\n  \
                 label: {{type: text, default: \"'01/02/2026'::text\"}}\n\
                 primary_key: {{name: ev_pkey, columns: [id]}}\n\
                 data:\n  mode: exact\n  rows:\n    \
                 1: {{d: \"2026-01-02\", ts: \"2026-01-02 09:00:00+00\", span: \"1 day\", \
                 label: \"01/02/2026\"}}\n    \
                 2: {{d: \"{date}\"}}\n    3: {{ts: \"{ts}\"}}\n    4: {{span: \"{span}\"}}\n    \
                 5: {{d: \"{clock}\"}}\n"
            ),
        )
        .unwrap();
        std::fs::write(
            &p,
            format!(
                "table: app.p\ncolumns:\n  d: {{type: date, nullable: false}}\n\
                 partition_by: [d]\npartitions:\n  p_a:\n    from: [\"{bound}\"]\n    \
                 to: [\"2026-06-01\"]\n"
            ),
        )
        .unwrap();
        d.commit();
    };
    declare(
        "01/02/2026",
        "01/02/2026",
        "2026-01-02 09:00",
        "-1 2:03:04",
        "today",
        "01/02/2026",
    );

    // Offline there is nothing to ask, and nothing changes (#1756 scope).
    succeeds(d.run(&["plan"]));

    for args in [
        vec!["bootstrap", "--db", connection],
        vec!["plan", "--db", connection],
    ] {
        if args[0] == "plan" {
            // A plan needs a recorded state: the empty schema, adopted.
            succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));
        }
        let o = d.run(&args);
        assert_ne!(code(&o), 0, "{args:?}: {}", stdout(&o));
        let said = format!("{}{}", stdout(&o), stderr(&o));
        for needle in [
            "5 declared date/time value(s) can be read more than one way",
            "app.ev row `2`: `d` \"01/02/2026\" is read as 2026-01-02 under this tool's \
             settings, but as 2026-02-01 under DateStyle DMY",
            "app.ev row `4`: `span` \"-1 2:03:04\" is read as 0 months -1 days 7384",
            "app.ev row `5`: `d` \"today\" is a date decided by the moment the statement runs",
            "app.ev column `d` default \"'01/02/2026'::date\" is read as 2026-01-02",
            "partition app.p_a bound on `d` \"01/02/2026\" is read as 2026-01-02",
        ] {
            assert!(
                said.contains(needle),
                "{args:?} missing {needle:?} in:\n{said}"
            );
        }
        // The same characters in a `text` column mean one thing, and the
        // pinned reading is not offered as the spelling to write.
        assert!(!said.contains("label"), "{said}");
        assert!(!said.contains("would not come back as written"), "{said}");
        // The offset-less instant has one reading, the target's zone.
        assert!(!said.contains("app.ev row `3`"), "{said}");
    }
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_tables WHERE schemaname = 'app'"
        ),
        0,
        "nothing was created"
    );

    // The one reading each can have, written so: the engine's own spelling.
    declare(
        "2026-02-01",
        "2026-02-01",
        "2026-01-02 01:00:00+00",
        "-1 days -02:03:04",
        "2026-03-01",
        "2026-02-01",
    );
    let plan = d.dir.join("plan.json");
    succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    succeeds(approved_apply(&d, connection, &plan, &[]));
    succeeds(d.run(&["verify", "--db", connection]));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        scalar(
            connection,
            "SELECT (d = DATE '2026-02-01')::int::int8 FROM app.ev WHERE id = 2"
        ),
        1
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT extract(epoch FROM ts)::int8 FROM app.ev WHERE id = 3"
        ),
        1_767_315_600
    );
}

/// An offset-less date/time value is read in the target database's own time
/// zone, which `plan --db` records and names and every write pins (#1916,
/// DEC-1916.1): a row's cell, a column default and a partition bound written
/// without an offset are stored at that zone's instant, then verify and plan
/// clean, and `pull` writes the offset the database renders. A role's setting
/// for its database wins over the database's own. A plan applied after the
/// zone moved is refused before its first statement — transactional, staged
/// and resumed — and the ledger's own times stay UTC. On 16 and 18.
#[test]
#[ignore = "needs PostgreSQL 16 and 18; set PBPS_TEST_PG_DB and PBPS_TEST_PG_OLD_DB"]
fn an_offset_less_value_is_read_in_the_target_databases_own_zone() {
    let old_server = std::env::var("PBPS_TEST_PG_OLD_DB").expect("PBPS_TEST_PG_OLD_DB");
    for (k, server) in [old_server, server()].iter().enumerate() {
        an_offset_less_value_is_read_in_the_target_databases_own_zone_on(server, k);
    }
}

fn an_offset_less_value_is_read_in_the_target_databases_own_zone_on(server: &str, k: usize) {
    let own = OwnDatabase::new(server, &format!("zone_1916_{k}"));
    let connection = own.connection();
    let role_zone = |zone: &str| {
        on_server(
            connection,
            &format!(
                "ALTER ROLE CURRENT_USER IN DATABASE \"{}\" SET timezone = '{zone}'",
                own.name
            ),
        );
    };
    // The database says New York; the role, for this database, Taipei. The
    // role's setting is the one a fresh session gets.
    on_server(
        connection,
        &format!(
            "CREATE SCHEMA app; ALTER DATABASE \"{}\" SET timezone = 'America/New_York'",
            own.name
        ),
    );
    role_zone("Asia/Taipei");

    let d = Demo::new(&format!("zone-1916-{k}"));
    std::fs::write(
        d.dir.join("schema/app.ev.yml"),
        "table: app.ev\ncolumns:\n  id: {type: integer, nullable: false}\n  \
         at: {type: timestamp with time zone, default: \"'2026-02-01'::timestamp with time zone\"}\n\
         primary_key: {name: ev_pkey, columns: [id]}\n\
         data:\n  mode: exact\n  rows:\n    1: {at: \"2026-03-01 09:00\"}\n",
    )
    .unwrap();
    std::fs::write(
        d.dir.join("schema/app.p.yml"),
        "table: app.p\ncolumns:\n  ts: {type: timestamp with time zone, nullable: false}\n\
         partition_by: [ts]\npartitions:\n  p_a:\n    from: [\"2026-02-01\"]\n    \
         to: [\"2026-03-01\"]\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["baseline", "--db", connection, "--reason", "adopt"]));

    // Recorded, and named, in the zone the role's session starts in.
    let plan = d.dir.join("plan.json");
    let planned = succeeds(d.run(&["plan", "--db", connection, "--out", plan.to_str().unwrap()]));
    assert!(
        stdout(&planned).contains("Offset-less date/time values read in Asia/Taipei"),
        "{}",
        stdout(&planned)
    );
    let saved: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
    assert_eq!(saved["baseline"]["time_zone"], "Asia/Taipei");
    let json = json_output(d.run(&["plan", "--db", connection, "--format", "json"]));
    assert_eq!(json["data"]["time_zone"], "Asia/Taipei", "{json}");

    succeeds(approved_apply(&d, connection, &plan, &[]));
    succeeds(d.run(&["verify", "--db", connection]));
    let next = succeeds(d.run(&["plan", "--db", connection]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));

    // Stored at Taipei's instants, asked in UTC so no session zone answers.
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM app.ev WHERE at = TIMESTAMPTZ '2026-03-01 01:00:00+00'"
        ),
        1
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_attrdef \
              WHERE adrelid = 'app.ev'::regclass \
                AND pg_get_expr(adbin, adrelid)::text LIKE '%2026-02-01 00:00:00+08%'"
        ),
        1,
        "the default is Taipei's midnight, rendered in the role's zone"
    );
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_class WHERE oid = 'app.p_a'::regclass \
               AND pg_get_expr(relpartbound, oid) = 'FOR VALUES FROM (''2026-02-01 00:00:00+08'') \
                   TO (''2026-03-01 00:00:00+08'')'"
        ),
        1
    );
    // The ledger's own time is UTC whatever the zone (DECISIONS 287).
    assert_eq!(
        scalar(
            connection,
            "SELECT (abs(extract(epoch FROM (now() AT TIME ZONE 'UTC') - max(applied_at))) \
                     < 600)::int::int8 FROM public.__pbps_state"
        ),
        1
    );

    // `pull` writes the offset the database renders.
    let pulled = Demo::new(&format!("zone-1916-pull-{k}"));
    succeeds(pulled.run(&["pull", "--db", connection, "--data", "app.ev"]));
    let ev = std::fs::read_to_string(pulled.dir.join("schema/app.ev.yml")).unwrap();
    for needle in ["2026-02-01 00:00:00+08", "at: \"2026-03-01 09:00:00+08\""] {
        assert!(ev.contains(needle), "missing {needle:?} in:\n{ev}");
    }
    let p = std::fs::read_to_string(pulled.dir.join("schema/app.p.yml")).unwrap();
    assert!(p.contains("2026-02-01 00:00:00+08"), "{p}");

    // The zone is no contrast any more, the date order still is: a value
    // `DateStyle` decides is refused in Taipei as anywhere (DEC-1756.1).
    let ev = d.dir.join("schema/app.ev.yml");
    let declared = std::fs::read_to_string(&ev).unwrap();
    std::fs::write(
        &ev,
        declared.replace("2026-03-01 09:00", "01/02/2026 09:00"),
    )
    .unwrap();
    let o = d.run(&["plan", "--db", connection]);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    assert!(
        stderr(&o).contains("\"01/02/2026 09:00\" is read as"),
        "{}",
        stderr(&o)
    );
    std::fs::write(&ev, declared).unwrap();

    // Planned in Taipei, applied after the zone moved: refused before the
    // first statement, transactional, staged and resumed.
    std::fs::write(
        d.dir.join("schema/app.u.yml"),
        "table: app.u\ncolumns:\n  id: {type: integer, nullable: false}\n  \
         at: {type: timestamp with time zone}\nprimary_key: [id]\nchecks:\n  \
         b_at: \"at >= '2026-01-01'\"\n  c_at: \"at < '2027-01-01'\"\n",
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    let transactional = d.dir.join("transactional.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        connection,
        "--out",
        transactional.to_str().unwrap(),
    ]));
    let staged = d.dir.join("staged.json");
    succeeds(d.run(&[
        "plan",
        "--db",
        connection,
        "--staged",
        "--out",
        staged.to_str().unwrap(),
    ]));
    let entries = scalar(connection, "SELECT count(*) FROM public.__pbps_state");
    let refused = |o: Output| {
        assert_ne!(code(&o), 0, "{}", stdout(&o));
        assert!(
            stderr(&o).contains(
                "reads offset-less date/time values in `America/New_York` now, and this plan \
                 was computed in `Asia/Taipei`"
            ),
            "{}",
            stderr(&o)
        );
    };
    role_zone("America/New_York");
    refused(approved_apply(&d, connection, &transactional, &[]));
    refused(approved_apply(&d, connection, &staged, &["--staged"]));
    assert_eq!(
        scalar(
            connection,
            "SELECT count(*) FROM pg_class WHERE oid = to_regclass('app.u')"
        ),
        0
    );
    // Each recorded as a failure, as any refused apply is; nothing applied.
    assert_eq!(
        scalar(connection, "SELECT count(*) FROM public.__pbps_state"),
        entries + 2
    );
    assert_eq!(
        latest_snapshot(connection).kind,
        pbps_model::StateKind::Failed
    );

    // Stopped partway in Taipei, resumed in New York: refused too.
    role_zone("Asia/Taipei");
    on_server(
        connection,
        r#"
CREATE SCHEMA witness;
CREATE FUNCTION witness.stop_after_first() RETURNS event_trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='app.u'::regclass AND conname='b_at') THEN
    RAISE EXCEPTION 'stop before the first check commits';
  END IF;
END $$;
CREATE EVENT TRIGGER stop_after_first ON ddl_command_end WHEN TAG IN ('ALTER TABLE') EXECUTE FUNCTION witness.stop_after_first();
"#,
    );
    let stopped = approved_apply(&d, connection, &staged, &["--staged"]);
    assert_eq!(
        code(&stopped),
        1,
        "{}{}",
        stdout(&stopped),
        stderr(&stopped)
    );
    on_server(connection, "DROP EVENT TRIGGER stop_after_first");
    role_zone("America/New_York");
    refused(approved_apply(
        &d,
        connection,
        &staged,
        &["--staged", "--resume"],
    ));
    assert_eq!(
        latest_snapshot(connection)
            .staged
            .as_ref()
            .unwrap()
            .completed,
        1
    );

    // Back in the zone it was planned in, it finishes.
    role_zone("Asia/Taipei");
    succeeds(approved_apply(
        &d,
        connection,
        &staged,
        &["--staged", "--resume"],
    ));
    succeeds(d.run(&["verify", "--db", connection]));
}

/// `pbps resolver externals` drafts what the deployed managed view reads,
/// lists the routine it does not write, and never replaces a file the
/// project uses (#1778).
#[test]
#[ignore = "needs live PostgreSQL; set PBPS_TEST_PG_DB"]
fn resolver_externals_drafts_what_a_managed_view_reads_and_never_replaces_the_externals_file() {
    let db = OwnDatabase::new(&server(), "externals1778");
    let view = "SELECT id, ext.f(id) AS f, mood FROM ext.t";
    on_server(
        db.connection(),
        &format!(
            "CREATE SCHEMA app; CREATE SCHEMA ext; \
             CREATE TYPE ext.mood AS ENUM ('ok'); \
             CREATE TABLE ext.t (id integer PRIMARY KEY, mood ext.mood); \
             CREATE TABLE ext.later (id integer); \
             CREATE FUNCTION ext.f(integer) RETURNS integer LANGUAGE sql IMMUTABLE RETURN $1; \
             CREATE VIEW app.v AS {view}"
        ),
    );
    let d = Demo::new("externals1778");
    std::fs::write(
        d.dir.join("schema/app.v.yml"),
        format!("view: app.v\ndefinition: {view}\n"),
    )
    .unwrap();
    std::fs::write(
        d.dir.join("pbps.yml"),
        "dialect: postgres\nresolvers:\n  scratch:\n    kind: server\n    url_env: PBPS_FLOW_PG_UNUSED\n    externals: db/externals.sql\n",
    )
    .unwrap();
    let printed = succeeds(d.run(&["resolver", "externals", "--db", db.connection()]));
    let sql = stdout(&printed);
    assert!(
        sql.contains("CREATE TYPE ext.mood AS ENUM ('ok');"),
        "{sql}"
    );
    assert!(
        sql.contains("CREATE TABLE ext.t (\n    id integer"),
        "{sql}"
    );
    assert!(
        stderr(&printed).contains("listed: function ext.f(integer): listed, never written"),
        "{}",
        stderr(&printed)
    );
    // Negative: no routine source, and nothing the managed view does not read.
    assert!(!sql.contains("RETURN $1"), "{sql}");
    assert!(!sql.contains("ext.later"), "{sql}");
    // `--schema` adds every unmanaged object of a schema.
    let widened = succeeds(d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--schema",
        "ext",
    ]));
    assert!(
        stdout(&widened).contains("CREATE TABLE ext.later"),
        "{}",
        stdout(&widened)
    );
    // An absent schema is refused by name; an empty one is not.
    let absent = d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--schema",
        "nosuch",
    ]);
    assert_ne!(code(&absent), 0);
    assert!(
        stderr(&absent).contains("--schema nosuch: the target has no schema of that name"),
        "{}",
        stderr(&absent)
    );
    on_server(db.connection(), "CREATE SCHEMA empty");
    succeeds(d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--schema",
        "empty",
    ]));
    // `--out` writes a new file and refuses an existing one without `--force`.
    let out = d.dir.join("draft.sql");
    let out_arg = out.to_str().unwrap();
    succeeds(d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        out_arg,
    ]));
    assert_eq!(std::fs::read_to_string(&out).unwrap(), sql);
    std::fs::write(&out, "-- edited\n").unwrap();
    let refused = d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        out_arg,
    ]);
    assert_ne!(code(&refused), 0);
    assert!(
        stderr(&refused).contains("exists; pass --force"),
        "{}",
        stderr(&refused)
    );
    assert_eq!(std::fs::read_to_string(&out).unwrap(), "-- edited\n");
    succeeds(d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        out_arg,
        "--force",
    ]));
    assert_eq!(std::fs::read_to_string(&out).unwrap(), sql);
    // Nor a declaration file, even one that does not exist yet.
    let declaration = d.dir.join("schema/app.new.yml");
    let refused = d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        declaration.to_str().unwrap(),
    ]);
    assert_ne!(code(&refused), 0);
    assert!(
        stderr(&refused).contains("is a declaration file under"),
        "{}",
        stderr(&refused)
    );
    assert!(!declaration.exists());
    // Negative: a file there the loader does not read is written.
    let beside = d.dir.join("schema/externals.sql");
    succeeds(d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        beside.to_str().unwrap(),
    ]));
    assert_eq!(std::fs::read_to_string(&beside).unwrap(), sql);
    // Nor through a link, dangling or not, `--force` or not.
    #[cfg(unix)]
    {
        let link = d.dir.join("draft-link.sql");
        std::os::unix::fs::symlink(&declaration, &link).unwrap();
        let refused = d.run(&[
            "resolver",
            "externals",
            "--db",
            db.connection(),
            "--out",
            link.to_str().unwrap(),
            "--force",
        ]);
        assert_ne!(code(&refused), 0);
        assert!(
            stderr(&refused).contains("is a symbolic link"),
            "{}",
            stderr(&refused)
        );
        assert!(!declaration.exists());
    }
    // The file a resolver entry names is never replaced, `--force` or not.
    std::fs::create_dir_all(d.dir.join("db")).unwrap();
    let named = d.dir.join("db/externals.sql");
    std::fs::write(&named, "-- reviewed\n").unwrap();
    let refused = d.run(&[
        "resolver",
        "externals",
        "--db",
        db.connection(),
        "--out",
        named.to_str().unwrap(),
        "--force",
    ]);
    assert_ne!(code(&refused), 0);
    assert!(
        stderr(&refused).contains("is the externals file resolver `scratch` names"),
        "{}",
        stderr(&refused)
    );
    assert_eq!(std::fs::read_to_string(&named).unwrap(), "-- reviewed\n");
}

/// A partition tree's triggers go the whole way through the CLI (#1632):
/// pulled as modules on the parent and on a partition, never the clones of
/// the parent's row and constraint triggers, which a bootstrap makes again
/// from the parent's, and which go and come with them when the routine they
/// run is rebuilt.
/// A clone in another mode than its parent's leaves the tree out, named. A
/// partition's own trigger is added and dropped as a table's, and kept
/// through a detach and an attach, where a trigger under a clone's name is
/// created after the detach and dropped before the attach; one named as
/// the parent's row trigger, which the engine refuses as already existing,
/// is refused by name by `validate` and by a connected plan. A
/// reference-data delete that cascades into the tree fires the clone, which
/// is authenticated as the parent's trigger.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partition_trees_triggers_go_through_the_cli() {
    let server = server();
    let source = OwnDatabase::new(&server, "part-tg-1632");
    let target = OwnDatabase::new(&server, "part-tg-1632-target");
    let (src, tgt) = (
        source.connection().to_owned(),
        target.connection().to_owned(),
    );
    on_server(
        &src,
        "CREATE SCHEMA app; \
         CREATE FUNCTION app.f() RETURNS trigger LANGUAGE plpgsql \
             AS $$BEGIN RETURN COALESCE(NEW, OLD); END$$; \
         CREATE TABLE app.kinds (code text NOT NULL PRIMARY KEY, label text); \
         CREATE TABLE app.ev (kind text NOT NULL PRIMARY KEY \
             REFERENCES app.kinds (code) ON DELETE CASCADE, label text) \
             PARTITION BY LIST (kind); \
         CREATE TABLE app.ev_a PARTITION OF app.ev FOR VALUES IN ('a'); \
         CREATE TABLE app.ev_b PARTITION OF app.ev FOR VALUES IN ('b'); \
         CREATE TRIGGER ev_row BEFORE INSERT OR UPDATE OR DELETE ON app.ev \
             FOR EACH ROW EXECUTE FUNCTION app.f(); \
         CREATE TRIGGER ev_stmt AFTER INSERT ON app.ev \
             FOR EACH STATEMENT EXECUTE FUNCTION app.f(); \
         CREATE CONSTRAINT TRIGGER ev_ct AFTER INSERT ON app.ev \
             FOR EACH ROW EXECUTE FUNCTION app.f(); \
         CREATE TRIGGER ev_a_own BEFORE UPDATE ON app.ev_a \
             FOR EACH ROW EXECUTE FUNCTION app.f()",
    );
    // A clone disabled on one partition is a fact no declaration holds: the
    // tree is left out, named.
    on_server(&src, "ALTER TABLE app.ev_b DISABLE TRIGGER ev_row");
    let left = Demo::new("part-tg-1632-left");
    let o = succeeds(left.run(&["pull", "--db", &src]));
    assert!(!left.dir.join("schema/app.ev.yml").exists());
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains("`app.ev_b` is a partition")
            && said.contains("a clone of its parent's trigger in another mode"),
        "{said}"
    );
    on_server(&src, "ALTER TABLE app.ev_b ENABLE TRIGGER ev_row");

    let d = Demo::new("part-tg-1632");
    succeeds(d.run(&["pull", "--db", &src]));
    let triggers = || {
        let mut found = Vec::new();
        for entry in std::fs::read_dir(d.dir.join("schema")).unwrap() {
            let path = entry.unwrap().path();
            let text = std::fs::read_to_string(&path).unwrap_or_default();
            let line = |key: &str| {
                text.lines()
                    .find_map(|l| l.strip_prefix(key))
                    .map(str::to_owned)
            };
            if let (Some(name), Some(on)) = (line("trigger: "), line("on: ")) {
                found.push((name, on, path));
            }
        }
        found.sort();
        found
    };
    let names: Vec<(String, String)> = triggers().into_iter().map(|(n, on, _)| (n, on)).collect();
    assert_eq!(
        names,
        [
            ("app.ev_a_own".to_owned(), "app.ev_a".to_owned()),
            ("app.ev_ct".to_owned(), "app.ev".to_owned()),
            ("app.ev_row".to_owned(), "app.ev".to_owned()),
            ("app.ev_stmt".to_owned(), "app.ev".to_owned()),
        ],
        "the clones of `ev_row` and `ev_ct` are the engine's, not the partitions'"
    );
    succeeds(d.run(&["fmt", "--check"]));
    d.commit();

    on_server(&tgt, "CREATE SCHEMA app");
    succeeds(d.run(&["bootstrap", "--db", &tgt]));
    succeeds(d.run(&["verify", "--db", &tgt]));
    let next = succeeds(d.run(&["plan", "--db", &tgt]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    let triggers_on = |table: &str, clone: bool| {
        scalar(
            &tgt,
            &format!(
                "SELECT count(*) FROM pg_trigger WHERE tgrelid = '{table}'::regclass \
                   AND NOT tgisinternal AND (tgparentid <> 0) = {clone}"
            ),
        )
    };
    assert_eq!(
        (
            triggers_on("app.ev_a", true),
            triggers_on("app.ev_a", false)
        ),
        (2, 1)
    );
    assert_eq!(
        (
            triggers_on("app.ev_b", true),
            triggers_on("app.ev_b", false)
        ),
        (2, 0)
    );

    let applied = |name: &str, allow: &[&str]| {
        let plan = d.dir.join(name);
        succeeds(d.run(&["plan", "--db", &tgt, "--out", plan.to_str().unwrap()]));
        succeeds(approved_apply(&d, &tgt, &plan, allow));
        succeeds(d.run(&["verify", "--db", &tgt]));
        let next = succeeds(d.run(&["plan", "--db", &tgt]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    };
    // A partition to drop with the rebuild below.
    let ev_path = d.dir.join("schema/app.ev.yml");
    let entry_of = |text: &str, name: &str| {
        let mut entry = Vec::new();
        for line in text
            .lines()
            .skip_while(|l| !l.starts_with(&format!("  {name}")))
        {
            if !entry.is_empty() && !line.starts_with("    ") {
                break;
            }
            entry.push(line.to_owned());
        }
        format!("{}\n", entry.join("\n"))
    };
    let before_z = std::fs::read_to_string(&ev_path).unwrap();
    let a_entry = entry_of(&before_z, "ev_a");
    let z_entry = a_entry
        .replace("ev_a", "ev_z")
        .replace("[a]", "[z]")
        .replace("\"a\"", "\"z\"");
    assert_ne!(z_entry, a_entry, "{a_entry}");
    std::fs::write(
        &ev_path,
        before_z.replace(&a_entry, &format!("{a_entry}{z_entry}")),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    applied("z.json", &[]);

    // The routine the triggers run is rebuilt: the parent's triggers are its
    // dependents, dropped and created again around it, and their clones go
    // and come with them. The same plan drops `ev_z`.
    std::fs::write(&ev_path, &before_z).unwrap();
    succeeds(d.run(&["drop-table", "app.ev_z", "--reason", "retired"]));
    let routine = std::fs::read_dir(d.dir.join("schema"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .find(|p| {
            std::fs::read_to_string(p)
                .unwrap_or_default()
                .contains("function: app.f")
        })
        .unwrap();
    let body = std::fs::read_to_string(&routine).unwrap();
    assert!(body.contains("COALESCE(NEW, OLD)"), "{body}");
    std::fs::write(
        &routine,
        body.replace("COALESCE(NEW, OLD)", "COALESCE(OLD, NEW)"),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    // A comment on one clone is the clone's own, which the parent's rebuild
    // would lose: the connected plan refuses it by name (#1632 review).
    on_server(
        &tgt,
        "COMMENT ON TRIGGER ev_row ON app.ev_a IS 'kept by hand'",
    );
    let o = d.run(&["plan", "--db", &tgt]);
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        code(&o) != 0
            && said.contains("on its clone on `app.ev_a`")
            && said.contains("kept by hand"),
        "{said}"
    );
    on_server(&tgt, "COMMENT ON TRIGGER ev_row ON app.ev_a IS NULL");
    // So is one on the constraint a constraint trigger's clone has.
    on_server(
        &tgt,
        "COMMENT ON CONSTRAINT ev_ct ON app.ev_a IS 'kept by hand too'",
    );
    let o = d.run(&["plan", "--db", &tgt]);
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        code(&o) != 0
            && said.contains("on its clone on `app.ev_a`")
            && said.contains("kept by hand too"),
        "{said}"
    );
    on_server(&tgt, "COMMENT ON CONSTRAINT ev_ct ON app.ev_a IS NULL");
    // One on a clone of the partition the plan drops goes with the partition,
    // before the rebuild, and refuses nothing.
    on_server(
        &tgt,
        "COMMENT ON TRIGGER ev_row ON app.ev_z IS 'goes with it'",
    );
    applied("routine.json", &["--allow", "destructive"]);
    assert_eq!(
        scalar(
            &tgt,
            "SELECT count(*) FROM pg_class WHERE oid = to_regclass('app.ev_z')"
        ),
        0
    );
    assert_eq!(
        (triggers_on("app.ev_a", true), triggers_on("app.ev_b", true)),
        (2, 2)
    );

    // A partition's own trigger moves from one partition to the other.
    let own = triggers()
        .into_iter()
        .find(|(n, _, _)| n == "app.ev_a_own")
        .unwrap()
        .2;
    let text = std::fs::read_to_string(&own).unwrap();
    std::fs::remove_file(&own).unwrap();
    std::fs::write(
        d.dir.join("schema/app.ev_b_own.trigger.yml"),
        text.replace("ev_a_own", "ev_b_own")
            .replace("app.ev_a", "app.ev_b"),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    applied("own.json", &["--allow", "destructive"]);
    assert_eq!(
        (
            triggers_on("app.ev_a", false),
            triggers_on("app.ev_b", false)
        ),
        (0, 1)
    );

    // Refused by name before a plan exists: an own trigger under the name
    // the parent's row trigger gives its clones.
    let clash = d.dir.join("schema/app.ev_a_clash.trigger.yml");
    std::fs::write(&clash, text.replace("ev_a_own", "ev_row")).unwrap();
    let needle = "trigger `ev_row` on `app.ev_a` is named as its parent's row trigger";
    for args in [&["validate"][..], &["plan", "--db", &tgt][..]] {
        let o = d.run(args);
        assert_ne!(code(&o), 0, "{}", stdout(&o));
        let said = format!("{}{}", stdout(&o), stderr(&o));
        assert!(said.contains(needle), "{args:?}: {said}");
    }
    std::fs::remove_file(&clash).unwrap();

    // Detached with its shape, the table keeps its own trigger and loses the
    // clones; a trigger declared on it under the name of a clone it had is
    // created after the detach, which frees the name (DEC-1632.3).
    let tree_path = d.dir.join("schema/app.ev.yml");
    let whole = std::fs::read_to_string(&tree_path).unwrap();
    let mut without_b = String::new();
    let mut skipping = false;
    for line in whole.lines() {
        if line.starts_with("  ev_b") {
            skipping = true;
            continue;
        }
        if skipping && line.starts_with("    ") {
            continue;
        }
        skipping = false;
        without_b.push_str(line);
        without_b.push('\n');
    }
    assert_ne!(without_b, whole, "{whole}");
    let shape = whole
        .split("\npartition_by:")
        .next()
        .unwrap()
        .replace("table: app.ev\n", "table: app.ev_b\n")
        // Its key is the parent's clone, under the engine's name for it.
        .replace("ev_pkey", "ev_b_pkey");
    let row = triggers()
        .into_iter()
        .find(|(n, _, _)| n == "app.ev_row")
        .unwrap()
        .2;
    let row_text = std::fs::read_to_string(&row).unwrap();
    let row_on_b = d.dir.join("schema/app.ev_b.ev_row.trigger.yml");
    std::fs::write(&tree_path, &without_b).unwrap();
    std::fs::write(d.dir.join("schema/app.ev_b.yml"), format!("{shape}\n")).unwrap();
    std::fs::write(
        &row_on_b,
        row_text
            .replace("on: app.ev\n", "on: app.ev_b\n")
            .replace("ON app.ev ", "ON app.ev_b "),
    )
    .unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    applied("detach.json", &["--allow", "destructive"]);
    assert_eq!(
        scalar(
            &tgt,
            "SELECT relispartition::int::int8 FROM pg_class WHERE oid = 'app.ev_b'::regclass"
        ),
        0
    );
    assert_eq!(
        (
            triggers_on("app.ev_b", true),
            triggers_on("app.ev_b", false)
        ),
        (0, 2)
    );

    // Attached again: the trigger under a parent's row trigger's name is
    // dropped before the attach, which the engine would refuse over it, the
    // table's own stays its own, and the parent's clones come back.
    std::fs::remove_file(&row_on_b).unwrap();
    std::fs::remove_file(d.dir.join("schema/app.ev_b.yml")).unwrap();
    std::fs::write(&tree_path, &whole).unwrap();
    succeeds(d.run(&["plan"]));
    d.commit();
    applied("attach.json", &["--allow", "destructive,constraint"]);
    assert_eq!(
        (
            triggers_on("app.ev_b", true),
            triggers_on("app.ev_b", false)
        ),
        (2, 1)
    );

    // A reference-data delete whose foreign-key action cascades into the tree
    // reaches the clone of `ev_row` on each partition, which the guard
    // authenticates, rows or none, as the parent's trigger.
    let kinds = d.dir.join("schema/app.kinds.yml");
    let declared = std::fs::read_to_string(&kinds).unwrap();
    let rows = |rows: &str| {
        std::fs::write(
            &kinds,
            format!("{declared}\ndata:\n  mode: exact\n  rows:\n{rows}"),
        )
        .unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    rows("    a: {label: A}\n    b: {label: B}\n");
    applied("rows.json", &[]);
    rows("    a: {label: A}\n");
    applied("cascade.json", &["--allow", "data-delete"]);
    assert_eq!(scalar(&tgt, "SELECT count(*) FROM app.kinds"), 1);

    // A partition the same plan adds before the delete gets its clones under
    // oids that did not exist when the guard authenticated the write; they
    // are accepted as the parent's trigger, which it did (#1632 review).
    rows("    a: {label: A}\n    c: {label: C}\n");
    applied("c.json", &[]);
    let tree_now = std::fs::read_to_string(&tree_path).unwrap();
    let mut entry = Vec::new();
    for line in tree_now.lines().skip_while(|l| !l.starts_with("  ev_a")) {
        if !entry.is_empty() && !line.starts_with("    ") {
            break;
        }
        entry.push(line);
    }
    let entry = format!("{}\n", entry.join("\n"));
    let added = entry
        .replace("ev_a", "ev_c")
        .replace("[a]", "[c]")
        .replace("\"a\"", "\"c\"");
    assert_ne!(added, entry, "{entry}");
    std::fs::write(
        &tree_path,
        tree_now.replace(&entry, &format!("{entry}{added}")),
    )
    .unwrap();
    rows("    a: {label: A}\n");
    applied("partition_and_cascade.json", &["--allow", "data-delete"]);
    assert_eq!(
        (
            triggers_on("app.ev_c", true),
            scalar(&tgt, "SELECT count(*) FROM app.kinds")
        ),
        (2, 1)
    );
}

/// A partition's own foreign keys round-trip through the CLI (#1632): created
/// with the tree beside the parent's clone, pulled back under the partition's
/// entry and never the clone, added and dropped on a standing partition,
/// kept under their names when the partition is detached, and kept when the
/// table is attached again, where the one equal to the parent's becomes its
/// clone, and dropped with the partition. Each saved plan
/// applies, verifies and replans empty. One equal to the parent's, which the
/// engine may take for its clone, and one under the name the parent's clone
/// keeps are refused by name by `validate` and by a connected plan.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitions_own_foreign_keys_change_through_the_cli() {
    let server = server();
    let own = OwnDatabase::new(&server, "part-fk-1632");
    let conn = own.connection().to_owned();
    on_server(&conn, "CREATE SCHEMA app");
    let d = Demo::new("part-fk-1632");
    let referenced = |name: &str| {
        std::fs::write(
            d.dir.join(format!("schema/app.{name}.yml")),
            format!(
                "table: app.{name}\ncolumns:\n  id: {{type: integer, nullable: false}}\n\
                 primary_key: [id]\n"
            ),
        )
        .unwrap();
    };
    referenced("r");
    referenced("s");
    let columns = "columns:\n  id: {type: integer, nullable: false}\n  \
                   ts: {type: date, nullable: false}\n  r: {type: integer}\n  \
                   s: {type: integer}\n";
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\n{columns}foreign_keys:\n  ev_r_fk:\n    columns: [r]\n    \
                 references: app.r(id)\npartition_by: [ts]\npartitions:\n{partitions}"
            ),
        )
        .unwrap();
        succeeds(d.run(&["plan"]));
        d.commit();
    };
    let own_fk = |name: &str, extra: &str| {
        format!(
            "    foreign_keys:\n      {name}:\n        columns: [s]\n        \
             references: app.s(id)\n{extra}"
        )
    };
    let p2025 = format!(
        "  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n{}",
        own_fk("ev_2025_s_fk", "")
    );
    let p2026 = "  ev_2026: {from: [\"2026-01-01\"], to: [\"2027-01-01\"]}\n";
    tree(&format!("{p2025}{p2026}"));
    succeeds(d.run(&["bootstrap", "--db", &conn]));
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    let holds = |sql: &str| scalar(&conn, &format!("SELECT ({sql})::int::int8"));
    let fk_on = |table: &str, name: &str, clone: bool| {
        holds(&format!(
            "SELECT EXISTS (SELECT FROM pg_constraint WHERE contype = 'f' \
               AND conrelid = '{table}'::regclass AND conname = '{name}' \
               AND (conparentid <> 0) = {clone})"
        ))
    };
    assert_eq!(fk_on("app.ev_2025", "ev_2025_s_fk", false), 1);
    assert_eq!(fk_on("app.ev_2025", "ev_r_fk", true), 1);

    // Pulled back under the partition's entry, the clone left to the parent.
    let pulled = Demo::new("part-fk-1632-pull");
    succeeds(pulled.run(&["pull", "--db", &conn]));
    let text = std::fs::read_to_string(pulled.dir.join("schema/app.ev.yml")).unwrap();
    assert!(
        text.contains(&format!(
            "  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n{}",
            own_fk("ev_2025_s_fk", "")
        )) && text.contains(p2026)
            && text.matches("ev_r_fk").count() == 1,
        "{text}"
    );

    let applied = |name: &str, allow: &[&str]| {
        let plan = d.dir.join(name);
        let o = succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        succeeds(approved_apply(&d, &conn, &plan, allow));
        succeeds(d.run(&["verify", "--db", &conn]));
        let next = succeeds(d.run(&["plan", "--db", &conn]));
        assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
        stdout(&o)
    };
    on_server(
        &conn,
        "INSERT INTO app.r VALUES (1); INSERT INTO app.s VALUES (1); \
         INSERT INTO app.ev VALUES (1, '2025-06-01', 1, 1), (2, '2026-06-01', 1, 1)",
    );
    // Added to a standing partition holding rows, and dropped from another.
    let p2026_own = format!(
        "  ev_2026:\n    from: [\"2026-01-01\"]\n    to: [\"2027-01-01\"]\n{}",
        own_fk("ev_2026_s_fk", "        on_delete: cascade\n")
    );
    tree(&format!(
        "  ev_2025: {{from: [\"2025-01-01\"], to: [\"2026-01-01\"]}}\n{p2026_own}"
    ));
    applied(
        "own.json",
        &["--allow", "constraint", "--allow", "destructive"],
    );
    assert_eq!(fk_on("app.ev_2026", "ev_2026_s_fk", false), 1);
    assert_eq!(fk_on("app.ev_2025", "ev_2025_s_fk", false), 0);
    assert_eq!(fk_on("app.ev_2025", "ev_r_fk", true), 1);

    // Refused by name before a plan exists: one equal to the parent's, and
    // one under the name the parent's clone keeps.
    for (entry, needle) in [
        (
            "  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n    \
             foreign_keys:\n      ev_2025_r:\n        columns: [r]\n        \
             references: app.r(id)\n"
                .to_owned(),
            "foreign key `ev_2025_r` is its parent's `ev_r_fk` again",
        ),
        (
            format!(
                "  ev_2025:\n    from: [\"2025-01-01\"]\n    to: [\"2026-01-01\"]\n{}",
                own_fk("ev_r_fk", "")
            ),
            "foreign key `ev_r_fk` is named as its parent's foreign key",
        ),
    ] {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\n{columns}foreign_keys:\n  ev_r_fk:\n    columns: [r]\n    \
                 references: app.r(id)\npartition_by: [ts]\npartitions:\n{entry}{p2026_own}"
            ),
        )
        .unwrap();
        // By `validate`, the CI check, and by the connected plan, which
        // refuses invalid declarations before it reads the target; the
        // offline preview leaves validity to `validate`.
        for args in [&["validate"][..], &["plan", "--db", &conn][..]] {
            let o = d.run(args);
            assert_ne!(code(&o), 0, "{needle}: {}", stdout(&o));
            let said = format!("{}{}", stdout(&o), stderr(&o));
            assert!(said.contains(needle), "{args:?} {needle}: {said}");
        }
    }

    // Detached and kept: its own foreign key keeps its name beside the
    // parent's, which the detach makes the table's own.
    std::fs::write(
        d.dir.join("schema/app.ev_2026.yml"),
        format!(
            "table: app.ev_2026\n{columns}foreign_keys:\n  arch_r:\n    columns: [r]\n    \
             references: app.r(id)\n  ev_2026_s_fk:\n    columns: [s]\n    \
             references: app.s(id)\n    on_delete: cascade\n"
        ),
    )
    .unwrap();
    tree("  ev_2025: {from: [\"2025-01-01\"], to: [\"2026-01-01\"]}\n");
    let planned = applied("detach.json", &["--allow", "destructive"]);
    assert!(
        planned.contains("~ detach table app.ev_2026 from app.ev, keeping its rows"),
        "{planned}"
    );
    assert_eq!(
        holds("SELECT NOT relispartition FROM pg_class WHERE oid = 'app.ev_2026'::regclass"),
        1
    );
    assert_eq!(fk_on("app.ev_2026", "ev_2026_s_fk", false), 1);
    assert_eq!(fk_on("app.ev_2026", "arch_r", false), 1);
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.ev_2026"), 1);

    // Attached again: the foreign key equal to the parent's would become its
    // clone under its own name `arch_r`, measured on 16 and 18, which the
    // partition declares again for one of its own: dropped before the
    // attach, the engine clones the parent's as `ev_r_fk`, and the own one is
    // added after (#1632 review). The other stays the partition's own.
    std::fs::remove_file(d.dir.join("schema/app.ev_2026.yml")).unwrap();
    tree(&format!(
        "  ev_2025: {{from: [\"2025-01-01\"], to: [\"2026-01-01\"]}}\n{p2026_own}      \
         arch_r:\n        columns: [r]\n        references: app.r(id)\n        \
         on_delete: cascade\n"
    ));
    let planned = applied(
        "attach.json",
        &["--allow", "constraint", "--allow", "destructive"],
    );
    assert!(planned.contains("attach"), "{planned}");
    assert_eq!(fk_on("app.ev_2026", "ev_2026_s_fk", false), 1);
    assert_eq!(fk_on("app.ev_2026", "arch_r", false), 1);
    assert_eq!(fk_on("app.ev_2026", "ev_r_fk", true), 1);
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.ev"), 2);

    // Dropped under its standing parent with drop intent, its own foreign
    // keys first (#1632 review).
    std::fs::write(
        d.dir.join("schema/app.ev.yml"),
        format!(
            "table: app.ev\n{columns}foreign_keys:\n  ev_r_fk:\n    columns: [r]\n    \
             references: app.r(id)\npartition_by: [ts]\npartitions:\n  \
             ev_2025: {{from: [\"2025-01-01\"], to: [\"2026-01-01\"]}}\n"
        ),
    )
    .unwrap();
    succeeds(d.run(&["drop-table", "app.ev_2026", "--reason", "retired"]));
    succeeds(d.run(&["plan"]));
    d.commit();
    applied("drop.json", &["--allow", "destructive"]);
    assert_eq!(holds("SELECT to_regclass('app.ev_2026') IS NULL"), 1);
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.ev"), 1);
}

/// A revision that deletes or repoints the declared rows referencing a
/// partition and drops that partition applies through the CLI (#1553): the
/// drop runs after the row changes, and the pre-flight counts each row as it
/// will be, so the deleted one and the repointed one are not counted. The
/// next plan is empty. Negative: with a referencing row kept, the pre-flight
/// still refuses the drop by name, and nothing changes.
#[test]
#[ignore = "needs a live PostgreSQL; set PBPS_TEST_PG_DB"]
fn a_partitions_drop_follows_the_row_changes_that_stop_referencing_it() {
    let server = server();
    let own = OwnDatabase::new(&server, "part-rows-1553");
    let conn = own.connection().to_owned();
    on_server(&conn, "CREATE SCHEMA app");
    let d = Demo::new("part-rows-1553");
    let tree = |partitions: &str| {
        std::fs::write(
            d.dir.join("schema/app.ev.yml"),
            format!(
                "table: app.ev\ncolumns:\n  id: {{type: integer, nullable: false}}\n\
                 primary_key: [id]\npartition_by: [id]\npartitions:\n{partitions}"
            ),
        )
        .unwrap();
    };
    let ev_1 = "  ev_1: {from: [1], to: [10]}\n";
    let ev_2 = "  ev_2: {from: [10], to: [20]}\n";
    let referencing = |data: &str| {
        std::fs::write(
            d.dir.join("schema/app.r.yml"),
            format!(
                "table: app.r\ncolumns:\n  id: {{type: integer, nullable: false}}\n  \
                 ev_id: {{type: integer}}\nprimary_key: [id]\nforeign_keys:\n  r_ev:\n    \
                 columns: [ev_id]\n    references: app.ev(id)\n{data}"
            ),
        )
        .unwrap();
    };
    tree(&format!("{ev_1}{ev_2}"));
    referencing("");
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(d.run(&["bootstrap", "--db", &conn]));
    on_server(
        &conn,
        "INSERT INTO app.ev VALUES (5), (6), (15); \
         INSERT INTO app.r VALUES (1, 5), (2, 15), (3, 6)",
    );
    let applied = |name: &str, allow: &[&str]| {
        let plan = d.dir.join(name);
        succeeds(d.run(&["plan", "--db", &conn, "--out", plan.to_str().unwrap()]));
        let o = approved_apply(&d, &conn, &plan, allow);
        (plan, o)
    };
    referencing(
        "data:\n  mode: exact\n  rows:\n    1: {ev_id: 5}\n    2: {ev_id: 15}\n    \
         3: {ev_id: 6}\n",
    );
    succeeds(d.run(&["plan"]));
    d.commit();
    succeeds(applied("adopt.json", &[]).1);

    // Row 1 deleted and row 3 repointed, ev_1 dropped, in one revision; the
    // negative first: row 3 kept on ev_1, which the pre-flight still counts.
    let allow = ["--allow", "destructive,data-update,data-delete"];
    tree(ev_2);
    succeeds(d.run(&["drop-table", "app.ev_1", "--reason", "retired"]));
    referencing("data:\n  mode: exact\n  rows:\n    2: {ev_id: 15}\n    3: {ev_id: 6}\n");
    succeeds(d.run(&["plan"]));
    d.commit();
    let (_, o) = applied("kept.json", &allow);
    assert_ne!(code(&o), 0, "{}", stdout(&o));
    let said = format!("{}{}", stdout(&o), stderr(&o));
    assert!(
        said.contains("1 rows that reference app.ev_1 through a foreign key to app.ev")
            && said.contains("nothing has been changed"),
        "{said}"
    );
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.r"), 3);
    assert_eq!(
        scalar(
            &conn,
            "SELECT (to_regclass('app.ev_1') IS NOT NULL)::int::int8"
        ),
        1
    );

    referencing("data:\n  mode: exact\n  rows:\n    2: {ev_id: 15}\n    3: {ev_id: 15}\n");
    succeeds(d.run(&["plan"]));
    d.commit();
    let (plan, o) = applied("leave.json", &allow);
    succeeds(o);
    // The drop runs after the row changes that stop referencing it.
    let text = std::fs::read_to_string(&plan).unwrap();
    let at = |needle: &str| {
        text.find(needle)
            .unwrap_or_else(|| panic!("{needle} not in the plan: {text}"))
    };
    assert!(at("\"delete_row\"") < at("\"drop_table\""), "{text}");
    assert!(at("\"update_row\"") < at("\"drop_table\""), "{text}");
    succeeds(d.run(&["verify", "--db", &conn]));
    let next = succeeds(d.run(&["plan", "--db", &conn]));
    assert!(stdout(&next).contains("No changes"), "{}", stdout(&next));
    assert_eq!(
        scalar(&conn, "SELECT (to_regclass('app.ev_1') IS NULL)::int::int8"),
        1
    );
    assert_eq!(
        scalar(&conn, "SELECT count(*) FROM app.r WHERE ev_id = 15"),
        2
    );
    assert_eq!(scalar(&conn, "SELECT count(*) FROM app.r"), 2);
}

#[test]
#[ignore = "needs both live PostgreSQL versions"]
fn row_security_adoption_preserves_policies_during_an_unrelated_column_migration() {
    for variable in ["PBPS_TEST_PG_OLD_DB", "PBPS_TEST_PG_DB"] {
        let base = std::env::var(variable).expect("live PostgreSQL fixture setting");
        let own = OwnDatabase::new(&base, "rls1172");
        let connection = own.connection();
        on_server(
            connection,
            "CREATE SCHEMA app;
            CREATE TABLE app.t (id bigint NOT NULL PRIMARY KEY);
            INSERT INTO app.t VALUES (1);
            CREATE TABLE app.enabled (id integer);
            ALTER TABLE app.enabled ENABLE ROW LEVEL SECURITY;
            CREATE TABLE app.forced (id integer);
            ALTER TABLE app.forced FORCE ROW LEVEL SECURITY;
            CREATE TABLE app.disabled (id integer);
            CREATE POLICY bare ON app.disabled;",
        );
        let catalog = "SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(
            c.relname,c.relrowsecurity,c.relforcerowsecurity,p.polname,p.polcmd,
            p.polpermissive,p.polroles,pg_catalog.pg_get_expr(p.polqual,p.polrelid),
            pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY c.relname,p.polname)::text
            FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
            LEFT JOIN pg_catalog.pg_policy p ON p.polrelid=c.oid
            WHERE n.nspname='app' AND c.relname IN ('enabled','forced','disabled')";
        let before = text_of(connection, catalog);
        let d = Demo::new("rls1172");
        let pulled = succeeds(d.run(&["pull", "--db", connection]));
        assert!(
            !stderr(&pulled).contains("#1172's later PRs"),
            "{}",
            stderr(&pulled)
        );
        let loaded = pbps_load::load_schema_dir(&d.dir.join("schema"))
            .unwrap()
            .schema;
        for name in ["enabled", "forced", "disabled"] {
            assert!(d.dir.join(format!("schema/app.{name}.yml")).exists());
            assert!(loaded.tables[&pbps_model::TableName::new("app", name)].has_row_security());
        }
        d.commit();
        succeeds(d.run(&[
            "baseline",
            "--db",
            connection,
            "--reason",
            "adopt ordinary and row-security tables",
        ]));
        let path = d.dir.join("schema/app.t.yml");
        let original = std::fs::read_to_string(&path).unwrap();
        let edited = original.replace("columns:\n", "columns:\n  label: {type: text}\n");
        assert_ne!(edited, original);
        std::fs::write(path, edited).unwrap();
        let plan = connected_artifact(&d, connection, false);
        let saved: pbps_model::SavedPlan =
            serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
        assert!(
            matches!(&saved.changes.changes[..], [step] if matches!(&step.change, pbps_model::Change::AddColumn { table, name, .. } if table == &pbps_model::TableName::new("app", "t") && name.raw() == "label"))
        );
        succeeds(approved_apply(&d, connection, &plan, &[]));
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection, "--format", "json"]));
        let next: serde_json::Value = serde_json::from_str(&stdout(&next)).unwrap();
        assert_eq!(next["data"]["changes"], 0, "{next}");
        assert_eq!(text_of(connection, catalog), before);
        let snapshot = latest_snapshot(connection);
        assert_eq!(snapshot.schema.tables.len(), 4);
        for name in ["enabled", "forced", "disabled"] {
            let name = pbps_model::TableName::new("app", name);
            assert_eq!(snapshot.schema.tables[&name], loaded.tables[&name]);
        }
        // A standing flag transition now uses the same transactional delivery.
        let path = d.dir.join("schema/app.disabled.yml");
        let mut text = std::fs::read_to_string(&path).unwrap();
        text.push_str("\nrow_security: {enabled: true}\n");
        std::fs::write(path, text).unwrap();
        let plan = connected_artifact(&d, connection, false);
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "revoke"],
        ));
        succeeds(d.run(&["verify", "--db", connection]));
        let next = succeeds(d.run(&["plan", "--db", connection, "--format", "json"]));
        let next: serde_json::Value = serde_json::from_str(&stdout(&next)).unwrap();
        assert_eq!(next["data"]["changes"], 0, "{next}");
        assert_eq!(
            scalar(
                connection,
                "SELECT relrowsecurity::int::bigint FROM pg_class WHERE oid='app.disabled'::regclass"
            ),
            1
        );
    }
}

#[test]
#[ignore = "needs both live PostgreSQL versions"]
fn row_security_created_policies_follow_routines_and_converge_after_apply_and_bootstrap() {
    for variable in ["PBPS_TEST_PG_OLD_DB", "PBPS_TEST_PG_DB"] {
        let base = std::env::var(variable).unwrap();
        let own = OwnDatabase::new(&base, "rls_create1172");
        let connection = own.connection();
        on_server(connection, "CREATE SCHEMA app");
        let d = Demo::new("rls-create1172");
        d.keyed(connection);
        d.table("table: app.t\ncolumns:\n  id: {type: integer, nullable: false}\nprimary_key: [id]\ndata: {mode: ensure, rows: {1: {}}}\n");
        succeeds(d.run(&["plan"]));
        d.commit();
        succeeds(d.run(&["bootstrap", "--db", connection]));
        declare_function(&d, "visible", "SELECT x");
        let path = d.dir.join("schema/app.docs.yml");
        let declaration = "table: app.docs\ncolumns:\n  id: {type: integer, nullable: false}\n  extra: {type: integer, generated: {expression: 'app.visible(id)', stored: true}}\nprimary_key: [id]\nchecks: {tenant_rows: 'id > 0'}\nrow_security: {enabled: true, forced: true}\nrow_policies:\n  tenant_rows:\n    using: 'app.visible(id) > 0 AND extra > 0'\n";
        std::fs::write(&path, declaration).unwrap();
        let plan = connected_artifact(&d, connection, false);
        let saved: pbps_model::SavedPlan =
            serde_json::from_str(&std::fs::read_to_string(&plan).unwrap()).unwrap();
        let at = |check: fn(&pbps_model::Change) -> bool| {
            saved
                .changes
                .changes
                .iter()
                .position(|p| check(&p.change))
                .unwrap()
        };
        assert!(
            at(|c| matches!(c, pbps_model::Change::CreateModule { .. }))
                < at(|c| matches!(c, pbps_model::Change::CreatePolicy { .. }))
        );
        assert!(
            at(
                |c| matches!(c, pbps_model::Change::AddColumn { name, .. } if name.raw() == "extra")
            ) < at(|c| matches!(c, pbps_model::Change::CreatePolicy { .. }))
        );
        assert!(
            at(|c| matches!(c, pbps_model::Change::CreatePolicy { .. }))
                < at(|c| matches!(c, pbps_model::Change::SetRowSecurity { .. }))
        );
        succeeds(approved_apply(
            &d,
            connection,
            &plan,
            &["--allow", "grant-widen"],
        ));
        succeeds(d.run(&["verify", "--db", connection]));
        let noop = succeeds(d.run(&["plan", "--db", connection, "--format", "json"]));
        let json: serde_json::Value = serde_json::from_str(&stdout(&noop)).unwrap();
        assert_eq!(json["data"]["changes"], 0, "{json}");
        assert!(json["findings"].to_string().contains("#595"), "{json}");
        let snapshot = latest_snapshot(connection);
        let docs = &snapshot.schema.tables[&pbps_model::TableName::new("app", "docs")];
        assert_eq!(
            docs.row_security,
            pbps_model::RowSecurity {
                enabled: true,
                forced: true
            }
        );
        assert!(docs.row_policies["tenant_rows"].using.is_some());
        assert!(docs.row_policies["tenant_rows"].with_check.is_none());

        // The same declarations bootstrap on a second empty target. Its data
        // inserts precede policy setup as well as every routine creation.
        let fresh = OwnDatabase::new(&base, "rls_bootstrap1172");
        on_server(fresh.connection(), "CREATE SCHEMA app");
        let other = Demo::new("rls-bootstrap1172");
        other.keyed(fresh.connection());
        for entry in std::fs::read_dir(d.dir.join("schema")).unwrap() {
            let entry = entry.unwrap();
            std::fs::copy(
                entry.path(),
                other.dir.join("schema").join(entry.file_name()),
            )
            .unwrap();
        }
        std::fs::copy(
            d.dir.join("schema.ids.json"),
            other.dir.join("schema.ids.json"),
        )
        .unwrap();
        other.commit();
        let script = other.dir.join("bootstrap.sql");
        succeeds(other.run(&[
            "bootstrap",
            "--db",
            fresh.connection(),
            "--sql",
            script.to_str().unwrap(),
        ]));
        let sql = std::fs::read_to_string(script).unwrap();
        let policy_at = sql.find("CREATE POLICY").unwrap();
        assert!(sql.find("CREATE FUNCTION").unwrap() < policy_at, "{sql}");
        assert!(sql.find("INSERT INTO").unwrap() < policy_at, "{sql}");
        assert!(
            policy_at < sql.find("ENABLE ROW LEVEL SECURITY").unwrap(),
            "{sql}"
        );
        let noop = succeeds(other.run(&["plan", "--db", fresh.connection(), "--format", "json"]));
        let json: serde_json::Value = serde_json::from_str(&stdout(&noop)).unwrap();
        assert_eq!(json["data"]["changes"], 0, "{json}");

        // The connected retype and routine rebuild are refused by policy name.
        std::fs::write(
            &path,
            declaration.replace("id: {type: integer", "id: {type: bigint"),
        )
        .unwrap();
        let refused = d.run(&["plan", "--db", connection]);
        assert_ne!(code(&refused), 0);
        assert!(
            stderr(&refused).contains("tenant_rows")
                && stderr(&refused).contains("explicitly remove or replace"),
            "{}",
            stderr(&refused)
        );
        std::fs::write(&path, declaration).unwrap();
        declare_function(&d, "visible", "SELECT x + 1");
        let refused = d.run(&["plan", "--db", connection]);
        assert_ne!(code(&refused), 0);
        assert!(
            stderr(&refused).contains("tenant_rows")
                && stderr(&refused).contains("explicitly remove or replace"),
            "{}",
            stderr(&refused)
        );
    }
}

#[test]
#[ignore = "needs both live PostgreSQL versions and the scratch cluster"]
